{
  "timeline": [
    {
      "headline": "YouTube Founded",
      "text": "YouTube was founded on February 14, 2005, by Steve Chen, Chad Hurley, and Jawed Karim, three former employees of PayPal.",
      "date": "2005-02-14"
    },
    {
      "headline": "First Video Uploaded",
      "text": "The first video, titled 'Me at the zoo', was uploaded by co-founder Jawed Karim on April 23, 2005.",
      "date": "2005-04-23"
    },
    {
      "headline": "YouTube Launches Public Beta",
      "text": "YouTube launched its public beta in May 2005, allowing users to upload and share videos.",
      "date": "2005-05"
    },
    {
      "headline": "Official Launch",
      "text": "YouTube officially launched in November 2005 after securing funding from Sequoia Capital.",
      "date": "2005-11"
    },
    {
      "headline": "Google Acquires YouTube",
      "text": "Google announced the acquisition of YouTube for $1.65 billion in stock on November 13, 2006.",
      "date": "2006-11-13"
    },
    {
      "headline": "YouTube Partners Program",
      "text": "In May 2007, YouTube launched its Partner Program, allowing content creators to earn revenue from ads.",
      "date": "2007-05"
    },
    {
      "headline": "YouTube Mobile Launch",
      "text": "YouTube launched its mobile site in June 2007, allowing users to watch videos on mobile devices.",
      "date": "2007-06"
    },
    {
      "headline": "YouTube HD",
      "text": "In December 2008, YouTube began offering high-definition video playback.",
      "date": "2008-12"
    },
    {
      "headline": "YouTube Rentals",
      "text": "YouTube introduced a rental service for movies and TV shows in January 2010.",
      "date": "2010-01"
    },
    {
      "headline": "YouTube Live",
      "text": "YouTube launched its live streaming service, YouTube Live, in April 2011.",
      "date": "2011-04"
    },
    {
      "headline": "YouTube Red",
      "text": "YouTube announced YouTube Red, a subscription service offering ad-free content, in October 2015.",
      "date": "2015-10"
    },
    {
      "headline": "YouTube TV",
      "text": "YouTube launched YouTube TV, a streaming television service, in April 2017.",
      "date": "2017-04"
    },
    {
      "headline": "YouTube Music and YouTube Premium",
      "text": "In June 2018, YouTube launched YouTube Music and rebranded YouTube Red as YouTube Premium.",
      "date": "2018-06"
    },
    {
      "headline": "500 Hours of Content Per Minute",
      "text": "As of May 2019, videos were being uploaded to YouTube at a rate of more than 500 hours of content per minute.",
      "date": "2019-05"
    },
    {
      "headline": "14 Billion Videos",
      "text": "By 2023, there were approximately 14 billion videos on YouTube.",
      "date": "2023"
    },
    {
      "headline": "2.7 Billion Monthly Active Users",
      "text": "In January 2024, YouTube had more than 2.7 billion monthly active users.",
      "date": "2024-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of XXXTentacion",
      "text": "Jahseh Dwayne Ricardo Onfroy, known professionally as XXXTentacion, was born on January 23, 1998, in Plantation, Florida, United States.",
      "date": "1998-01-23"
    },
    {
      "headline": "Release of Debut Song",
      "text": "In June 2013, XXXTentacion released his first song, 'News/Flock', on SoundCloud.",
      "date": "2013-06"
    },
    {
      "headline": "Formation of Members Only",
      "text": "In 2014, XXXTentacion and Ski Mask the Slump God formed the group Members Only.",
      "date": "2014"
    },
    {
      "headline": "Release of 'Look at Me!'",
      "text": "In December 2015, XXXTentacion released the song 'Look at Me!' which later became a breakout hit.",
      "date": "2015-12"
    },
    {
      "headline": "Arrest and Legal Issues",
      "text": "On October 8, 2016, XXXTentacion was arrested and charged with robbery and assault with a deadly weapon.",
      "date": "2016-10-08"
    },
    {
      "headline": "Release from Jail",
      "text": "XXXTentacion was released from jail on March 29, 2017, after being granted probation.",
      "date": "2017-03-29"
    },
    {
      "headline": "Release of Debut Album '17'",
      "text": "On August 25, 2017, XXXTentacion released his debut studio album '17', which debuted at number two on the US Billboard 200.",
      "date": "2017-08-25"
    },
    {
      "headline": "Release of Second Album '?'",
      "text": "XXXTentacion released his second studio album '?' on March 16, 2018, which debuted at number one on the Billboard 200.",
      "date": "2018-03-16"
    },
    {
      "headline": "Death of XXXTentacion",
      "text": "XXXTentacion was shot and killed during a robbery at a motorcycle dealership in Deerfield Beach, Florida, on June 18, 2018.",
      "date": "2018-06-18"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Kamala Harris",
      "text": "Kamala Devi Harris was born on October 20, 1964, in Oakland, California.",
      "date": "1964-10-20"
    },
    {
      "headline": "Graduation from Howard University",
      "text": "Kamala Harris graduated from Howard University in 1986 with a degree in political science and economics.",
      "date": "1986"
    },
    {
      "headline": "Graduation from UC Hastings College of the Law",
      "text": "Harris graduated with a Juris Doctor from the University of California, Hastings College of the Law in 1989.",
      "date": "1989"
    },
    {
      "headline": "Deputy District Attorney in Alameda County",
      "text": "Kamala Harris began her career in the Alameda County District Attorney's Office in 1990.",
      "date": "1990"
    },
    {
      "headline": "District Attorney of San Francisco",
      "text": "Kamala Harris was elected as the District Attorney of San Francisco in 2003 and served from 2004 to 2011.",
      "date": "2004"
    },
    {
      "headline": "Attorney General of California",
      "text": "Kamala Harris was elected as the Attorney General of California in 2010 and served from 2011 to 2017.",
      "date": "2011"
    },
    {
      "headline": "U.S. Senator from California",
      "text": "Kamala Harris was elected as the U.S. Senator from California in 2016 and served from 2017 to 2021.",
      "date": "2017"
    },
    {
      "headline": "Vice President of the United States",
      "text": "Kamala Harris was inaugurated as the 49th Vice President of the United States on January 20, 2021.",
      "date": "2021-01-20"
    },
    {
      "headline": "Democratic Nominee for President",
      "text": "Kamala Harris was the Democratic Party's nominee in the 2024 presidential election, becoming the second woman nominated for president by a major U.S. political party.",
      "date": "2024"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of the Indian Premier League",
      "text": "The Indian Premier League (IPL) was founded by the Board of Control for Cricket in India (BCCI) in 2007.",
      "date": "2007"
    },
    {
      "headline": "Inaugural IPL Season",
      "text": "The first season of the Indian Premier League took place from April 18 to June 1, 2008. The Rajasthan Royals won the inaugural title.",
      "date": "2008-04-18"
    },
    {
      "headline": "Introduction of New Teams",
      "text": "In 2011, the IPL expanded to include two new teams, Pune Warriors India and Kochi Tuskers Kerala, increasing the number of franchises to ten.",
      "date": "2011"
    },
    {
      "headline": "Termination of Kochi Tuskers Kerala",
      "text": "The Kochi Tuskers Kerala franchise was terminated by the BCCI due to a breach of contract in September 2011.",
      "date": "2011-09"
    },
    {
      "headline": "Suspension of Chennai Super Kings and Rajasthan Royals",
      "text": "In July 2015, the Chennai Super Kings and Rajasthan Royals were suspended for two years following a spot-fixing and betting scandal.",
      "date": "2015-07"
    },
    {
      "headline": "Return of Chennai Super Kings and Rajasthan Royals",
      "text": "The Chennai Super Kings and Rajasthan Royals returned to the IPL for the 2018 season after serving their two-year suspension.",
      "date": "2018"
    },
    {
      "headline": "Introduction of New Teams",
      "text": "In 2022, the IPL expanded once again to include two new teams, Gujarat Titans and Lucknow Super Giants, bringing the total number of teams to ten.",
      "date": "2022"
    }
  ]
}

