{
  "timeline": [
    {
      "headline": "Establishment of the Electoral College",
      "text": "The United States Electoral College was established by Article Two of the United States Constitution, which was adopted on September 17, 1787. It was created as a compromise between election of the president by a vote in Congress and election of the president by a popular vote of qualified citizens.",
      "date": "1787-09-17"
    },
    {
      "headline": "First Presidential Election",
      "text": "The first use of the Electoral College took place during the presidential election of 1788-1789, which resulted in the election of George Washington as the first President of the United States.",
      "date": "1788"
    },
    {
      "headline": "Twelfth Amendment Ratified",
      "text": "The Twelfth Amendment to the United States Constitution was ratified on June 15, 1804. It provided the procedure for electing the President and Vice President, replacing the original procedure that resulted in the election of the President and Vice President from the same pool of candidates.",
      "date": "1804-06-15"
    },
    {
      "headline": "Twenty-third Amendment Ratified",
      "text": "The Twenty-third Amendment to the United States Constitution was ratified on March 29, 1961. It granted the District of Columbia electors in the Electoral College, allowing its residents to vote for President and Vice President.",
      "date": "1961-03-29"
    },
    {
      "headline": "Contingent Election of 1824",
      "text": "The presidential election of 1824 resulted in no candidate receiving a majority of electoral votes, leading to a contingent election in the House of Representatives. John Quincy Adams was elected President.",
      "date": "1824"
    },
    {
      "headline": "Contingent Election of 1876",
      "text": "The presidential election of 1876 was one of the most disputed in American history. Rutherford B. Hayes was awarded the presidency after a controversial Electoral Commission decision.",
      "date": "1876"
    },
    {
      "headline": "Contingent Election of 1888",
      "text": "In the 1888 presidential election, Benjamin Harrison won the presidency despite losing the popular vote to Grover Cleveland, due to the distribution of electoral votes.",
      "date": "1888"
    },
    {
      "headline": "Contingent Election of 2000",
      "text": "The 2000 presidential election was decided by a Supreme Court decision in Bush v. Gore, which effectively awarded Florida's electoral votes and the presidency to George W. Bush.",
      "date": "2000"
    },
    {
      "headline": "Contingent Election of 2016",
      "text": "In the 2016 presidential election, Donald Trump won the presidency despite losing the popular vote to Hillary Clinton, due to the distribution of electoral votes.",
      "date": "2016"
    }
  ]
}

