      "headline": "Maurya Empire",
      "text": "The Maurya Empire, founded by Chandragupta Maurya, was established around 322 BCE and became one of the largest empires in the Indian subcontinent.",
      "date": "-0322"
    },
    {
      "headline": "Ashoka's Reign",
      "text": "Emperor Ashoka, one of India's greatest rulers, reigned from 268 BCE to 232 BCE and spread Buddhism across Asia.",
      "date": "-0268"
