    {
      "headline": "Mughal Empire",
      "text": "The Mughal Empire was founded by Babur in 1526 CE and became one of the most prominent empires in Indian history, lasting until the mid-19th century.",
      "date": "1526"
    },
    {
      "headline": "British East India Company Rule",
      "text": "The British East India Company began its rule in India in 1757 CE after the Battle of Plassey, marking the start of British colonialism.",
      "date": "1757"
