    {
      "headline": "Inception of the European Cup",
      "text": "The UEFA Champions League was originally known as the European Champion Clubs' Cup, or simply the European Cup. It was conceived in 1955 as a tournament for the champions of European domestic leagues.",
      "date": "1955"
    },
    {
      "headline": "First European Cup Final",
      "text": "The first European Cup final took place on June 13, 1956, at the Parc des Princes in Paris. Real Madrid defeated Stade de Reims 4-3 to become the inaugural champions.",
      "date": "1956-06-13"
    },
    {
      "headline": "Real Madrid's Dominance",
      "text": "Real Madrid won the first five editions of the European Cup from 1956 to 1960, establishing early dominance in the competition.",
      "date": "1960"
    },
    {
      "headline": "Introduction of Group Stage",
      "text": "The competition was rebranded as the UEFA Champions League in the 1992-1993 season, introducing a group stage format for the first time.",
      "date": "1992"
    },
    {
      "headline": "First UEFA Champions League Final",
      "text": "The first final under the new UEFA Champions League format was held on May 26, 1993, at the Olympiastadion in Munich. Olympique de Marseille defeated AC Milan 1-0.",
      "date": "1993-05-26"
    },
    {
      "headline": "Expansion of the Tournament",
      "text": "The tournament expanded in the late 1990s and early 2000s to include more teams from Europe's top leagues, allowing multiple entrants from the strongest leagues.",
      "date": "1997"
    },
    {
      "headline": "Introduction of the Away Goals Rule",
      "text": "The away goals rule was introduced to the competition to determine the winner of a two-legged tie in the event of an aggregate draw.",
      "date": "1965"
    },
    {
      "headline": "Real Madrid's 10th Title",
      "text": "Real Madrid won their 10th UEFA Champions League title, known as 'La Décima', on May 24, 2014, defeating Atlético Madrid 4-1 after extra time.",
      "date": "2014-05-24"
    },
    {
      "headline": "Liverpool's Sixth Title",
      "text": "Liverpool won their sixth UEFA Champions League title on June 1, 2019, defeating Tottenham Hotspur 2-0 in the final held at the Wanda Metropolitano in Madrid.",
      "date": "2019-06-01"
    },
    {
      "headline": "COVID-19 Pandemic Impact",
      "text": "The 2019-2020 UEFA Champions League season was disrupted by the COVID-19 pandemic, leading to a revised format with single-leg knockout matches played in Lisbon, Portugal.",
      "date": "2020"
    }
  ]
}

