{
  "timeline": [
    {
      "headline": "Birth of Napoleon Bonaparte",
      "text": "Napoleon Bonaparte was born on August 15, 1769, in Ajaccio, Corsica, which was then part of the Republic of Genoa.",
      "date": "1769-08-15"
    },
    {
      "headline": "Graduation from Military Academy",
      "text": "In 1785, Napoleon graduated from the École Militaire in Paris, becoming a second lieutenant in an artillery regiment.",
      "date": "1785"
    },
    {
      "headline": "Siege of Toulon",
      "text": "In December 1793, Napoleon played a key role in the French victory at the Siege of Toulon, which led to his promotion to brigadier general.",
      "date": "1793-12"
    },
    {
      "headline": "Italian Campaign",
      "text": "Napoleon led the French army to a series of victories in the Italian Campaign from 1796 to 1797, establishing his reputation as a brilliant military leader.",
      "date": "1796"
    },
    {
      "headline": "Coup of 18 Brumaire",
      "text": "On November 9, 1799, Napoleon staged a coup d'état, known as the Coup of 18 Brumaire, overthrowing the French Directory and establishing the Consulate.",
      "date": "1799-11-09"
    },
    {
      "headline": "First Consul of France",
      "text": "Following the coup, Napoleon became the First Consul of France on December 12, 1799, effectively becoming the leader of the French Republic.",
      "date": "1799-12-12"
    },
    {
      "headline": "Proclaimed Emperor of the French",
      "text": "On May 18, 1804, Napoleon was proclaimed Emperor of the French, marking the beginning of the First French Empire.",
      "date": "1804-05-18"
    },
    {
      "headline": "Coronation as Emperor",
      "text": "Napoleon was crowned Emperor of the French on December 2, 1804, at Notre-Dame Cathedral in Paris.",
      "date": "1804-12-02"
    },
    {
      "headline": "Battle of Austerlitz",
      "text": "On December 2, 1805, Napoleon achieved a decisive victory against the Russian and Austrian armies at the Battle of Austerlitz, also known as the Battle of the Three Emperors.",
      "date": "1805-12-02"
    },
    {
      "headline": "Invasion of Russia",
      "text": "In 1812, Napoleon launched a disastrous invasion of Russia, which ultimately led to the decimation of his Grande Armée.",
      "date": "1812"
    },
    {
      "headline": "Exile to Elba",
      "text": "After his defeat in the War of the Sixth Coalition, Napoleon was forced to abdicate and was exiled to the island of Elba on April 11, 1814.",
      "date": "1814-04-11"
    },
    {
      "headline": "Return to Power (The Hundred Days)",
      "text": "Napoleon escaped from Elba and returned to power in France on March 20, 1815, beginning the period known as the Hundred Days.",
      "date": "1815-03-20"
    },
    {
      "headline": "Battle of Waterloo",
      "text": "On June 18, 1815, Napoleon was defeated at the Battle of Waterloo by the Seventh Coalition, leading to his final abdication.",
      "date": "1815-06-18"
    },
    {
      "headline": "Exile to Saint Helena",
      "text": "Following his defeat at Waterloo, Napoleon was exiled to the remote island of Saint Helena in the South Atlantic Ocean on October 15, 1815.",
      "date": "1815-10-15"
    },
    {
      "headline": "Death of Napoleon Bonaparte",
      "text": "Napoleon Bonaparte died on May 5, 1821, on the island of Saint Helena.",
      "date": "1821-05-05"
    }
  ]
}

