{
  "timeline": [
    {
      "headline": "Assassination of Archduke Franz Ferdinand",
      "text": "On June 28, 1914, Archduke Franz Ferdinand of Austria was assassinated in Sarajevo, Bosnia, by Gavrilo Princip, a member of the nationalist group the Black Hand. This event is widely regarded as the immediate catalyst for World War I.",
      "date": "1914-06-28"
    },
    {
      "headline": "Austria-Hungary Declares War on Serbia",
      "text": "On July 28, 1914, Austria-Hungary declared war on Serbia, marking the beginning of World War I.",
      "date": "1914-07-28"
    },
    {
      "headline": "Germany Declares War on Russia",
      "text": "On August 1, 1914, Germany declared war on Russia, following Russia's mobilization in support of Serbia.",
      "date": "1914-08-01"
    },
    {
      "headline": "Germany Declares War on France",
      "text": "On August 3, 1914, Germany declared war on France, as part of its strategy to quickly defeat France before turning to Russia.",
      "date": "1914-08-03"
    },
    {
      "headline": "United Kingdom Declares War on Germany",
      "text": "On August 4, 1914, the United Kingdom declared war on Germany after Germany invaded Belgium, violating Belgian neutrality.",
      "date": "1914-08-04"
    },
    {
      "headline": "First Battle of the Marne",
      "text": "From September 6 to September 12, 1914, the First Battle of the Marne took place, resulting in an Allied victory and halting the German advance into France.",
      "date": "1914-09-06"
    },
    {
      "headline": "Trench Warfare Begins",
      "text": "By the end of 1914, trench warfare had begun to dominate the Western Front, characterized by a stalemate and extensive trench systems.",
      "date": "1914"
    },
    {
      "headline": "Lusitania Sinking",
      "text": "On May 7, 1915, the British ocean liner RMS Lusitania was sunk by a German U-boat, killing 1,198 people, including 128 Americans, which increased tensions between Germany and the United States.",
      "date": "1915-05-07"
    },
    {
      "headline": "Battle of Verdun",
      "text": "The Battle of Verdun, one of the longest and costliest battles in World War I, was fought from February 21 to December 18, 1916, resulting in heavy casualties on both sides.",
      "date": "1916-02-21"
    },
    {
      "headline": "Battle of the Somme",
      "text": "The Battle of the Somme took place from July 1 to November 18, 1916, and was one of the largest battles of World War I, with over one million men wounded or killed.",
      "date": "1916-07-01"
    },
    {
      "headline": "United States Enters the War",
      "text": "On April 6, 1917, the United States declared war on Germany, joining the Allies in World War I.",
      "date": "1917-04-06"
    },
    {
      "headline": "Russian Revolution",
      "text": "In 1917, the Russian Revolution led to the abdication of Tsar Nicholas II and the eventual withdrawal of Russia from World War I.",
      "date": "1917"
    },
    {
      "headline": "Armistice of Compiègne",
      "text": "On November 11, 1918, the Armistice of Compiègne was signed, ending fighting on the Western Front and marking the end of World War I.",
      "date": "1918-11-11"
    },
    {
      "headline": "Treaty of Versailles",
      "text": "On June 28, 1919, the Treaty of Versailles was signed, officially ending World War I and imposing heavy reparations and territorial losses on Germany.",
      "date": "1919-06-28"
    }
  ]
}

