{
  "timeline": [
    {
      "headline": "Foundation of Fascism",
      "text": "Fascism as a political ideology was founded by Benito Mussolini in Italy. It emerged in the early 20th century, particularly after World War I, as a response to the perceived failures of liberal democracy and socialism.",
      "date": "1919"
    },
    {
      "headline": "Formation of the Fasci Italiani di Combattimento",
      "text": "On March 23, 1919, Benito Mussolini founded the Fasci Italiani di Combattimento in Milan, Italy. This organization was the precursor to the National Fascist Party.",
      "date": "1919-03-23"
    },
    {
      "headline": "March on Rome",
      "text": "The March on Rome was a mass demonstration and insurrection by the Fascist Party, which resulted in Benito Mussolini's appointment as Prime Minister of Italy on October 31, 1922.",
      "date": "1922-10-31"
    },
    {
      "headline": "Establishment of the National Fascist Party",
      "text": "In 1921, the Fasci Italiani di Combattimento was transformed into the National Fascist Party, marking the formal establishment of fascism as a political party in Italy.",
      "date": "1921"
    },
    {
      "headline": "Acerbo Law Passed",
      "text": "The Acerbo Law was passed in Italy in 1923, which allowed Mussolini's party to gain a majority in the Italian Parliament, further consolidating fascist power.",
      "date": "1923"
    },
    {
      "headline": "Fascist Italy's Invasion of Ethiopia",
      "text": "In October 1935, Fascist Italy invaded Ethiopia, marking a significant expansion of fascist imperial ambitions.",
      "date": "1935-10"
    },
    {
      "headline": "Spanish Civil War",
      "text": "From 1936 to 1939, fascist regimes in Italy and Germany supported Francisco Franco's Nationalists in the Spanish Civil War, which resulted in a fascist-aligned dictatorship in Spain.",
      "date": "1936"
    },
    {
      "headline": "Formation of the Axis Powers",
      "text": "In 1936, the Rome-Berlin Axis was formed between Fascist Italy and Nazi Germany, later joined by Japan, creating the Axis Powers during World War II.",
      "date": "1936"
    },
    {
      "headline": "Fall of Fascist Italy",
      "text": "In July 1943, Mussolini was deposed, and the Fascist regime in Italy collapsed as Allied forces invaded the country.",
      "date": "1943-07"
    },
    {
      "headline": "End of World War II and Decline of Fascism",
      "text": "With the end of World War II in 1945, fascist regimes in Europe were dismantled, leading to the decline of fascism as a dominant political ideology.",
      "date": "1945"
    }
  ]
}

