{
  "timeline": [
    {
      "headline": "First Nations and Indigenous Peoples",
      "text": "Indigenous peoples have inhabited the area now known as Canada for thousands of years, with diverse cultures and societies established long before European contact.",
      "date": "-10000"
    },
    {
      "headline": "Norse Exploration",
      "text": "Around the year 1000, Norse explorers from Greenland, led by Leif Erikson, reached the shores of what is now Newfoundland, establishing a settlement at L'Anse aux Meadows.",
      "date": "1000"
    },
    {
      "headline": "John Cabot's Voyage",
      "text": "In 1497, John Cabot, an Italian navigator sailing under the English flag, reached the coast of Newfoundland, marking the beginning of European exploration of Canada.",
      "date": "1497"
    },
    {
      "headline": "Jacques Cartier's Exploration",
      "text": "In 1534, French explorer Jacques Cartier made his first voyage to Canada, claiming the land for France and exploring the Gulf of St. Lawrence.",
      "date": "1534"
    },
    {
      "headline": "Founding of Quebec City",
      "text": "In 1608, Samuel de Champlain founded Quebec City, establishing one of the first permanent European settlements in Canada.",
      "date": "1608"
    },
    {
      "headline": "Treaty of Paris",
      "text": "In 1763, the Treaty of Paris ended the Seven Years' War, with France ceding most of its North American territories, including Canada, to Britain.",
      "date": "1763"
    },
    {
      "headline": "Confederation",
      "text": "On July 1, 1867, the British North America Act united the provinces of Ontario, Quebec, New Brunswick, and Nova Scotia into the Dominion of Canada.",
      "date": "1867-07-01"
    },
    {
      "headline": "Statute of Westminster",
      "text": "In 1931, the Statute of Westminster granted Canada legislative independence from the United Kingdom, marking a significant step towards full sovereignty.",
      "date": "1931"
    },
    {
      "headline": "Canada Act",
      "text": "In 1982, the Canada Act was passed, ending the power of the British Parliament to legislate for Canada and patriating the Canadian Constitution.",
      "date": "1982"
    },
    {
      "headline": "Nunavut Established",
      "text": "On April 1, 1999, the territory of Nunavut was officially separated from the Northwest Territories, creating a new territory for the Inuit people.",
      "date": "1999-04-01"
    }
  ]
}

