    {
      "headline": "Birth of Abraham Lincoln",
      "text": "Abraham Lincoln was born on February 12, 1809, in a one-room log cabin on the Sinking Spring Farm in Hardin County, Kentucky.",
      "date": "1809-02-12"
    },
    {
      "headline": "Lincoln's Family Moves to Indiana",
      "text": "In 1816, Lincoln's family moved to southern Indiana, where they settled in what is now Spencer County.",
      "date": "1816"
    },
    {
      "headline": "Death of Lincoln's Mother",
      "text": "Lincoln's mother, Nancy Hanks Lincoln, died of milk sickness on October 5, 1818.",
      "date": "1818-10-05"
    },
    {
      "headline": "Lincoln Moves to Illinois",
      "text": "In March 1830, Lincoln's family moved to Macon County in southern Illinois.",
      "date": "1830-03"
    },
    {
      "headline": "Lincoln's First Election to Illinois General Assembly",
      "text": "In 1834, Lincoln was elected to the Illinois General Assembly as a member of the Whig Party.",
      "date": "1834"
    },
    {
      "headline": "Lincoln Becomes a Lawyer",
      "text": "In 1836, Lincoln was admitted to the bar after teaching himself law, and he began practicing law in Springfield, Illinois.",
      "date": "1836"
    },
    {
      "headline": "Marriage to Mary Todd",
      "text": "Abraham Lincoln married Mary Todd on November 4, 1842, in Springfield, Illinois.",
      "date": "1842-11-04"
    },
    {
      "headline": "Elected to U.S. House of Representatives",
      "text": "Lincoln was elected to the U.S. House of Representatives in 1846, serving a single term from 1847 to 1849.",
      "date": "1846"
    },
    {
      "headline": "Lincoln-Douglas Debates",
      "text": "In 1858, Lincoln engaged in a series of debates with Stephen A. Douglas during the Illinois Senate race, which brought him national attention.",
      "date": "1858"
    },
    {
      "headline": "Elected 16th President of the United States",
      "text": "Abraham Lincoln was elected as the 16th president of the United States on November 6, 1860.",
      "date": "1860-11-06"
    },
    {
      "headline": "Lincoln's First Inauguration",
      "text": "Lincoln was inaugurated as president on March 4, 1861.",
      "date": "1861-03-04"
    },
    {
      "headline": "Emancipation Proclamation Issued",
      "text": "Lincoln issued the Emancipation Proclamation on January 1, 1863, declaring all slaves in Confederate-held territory to be free.",
      "date": "1863-01-01"
    },
    {
      "headline": "Gettysburg Address",
      "text": "On November 19, 1863, Lincoln delivered the Gettysburg Address at the dedication of the Soldiers' National Cemetery in Gettysburg, Pennsylvania.",
      "date": "1863-11-19"
    },
    {
      "headline": "Re-elected as President",
      "text": "Lincoln was re-elected as president on November 8, 1864.",
      "date": "1864-11-08"
    },
    {
      "headline": "Lincoln's Second Inauguration",
      "text": "Lincoln was inaugurated for his second term on March 4, 1865.",
      "date": "1865-03-04"
    },
    {
      "headline": "Assassination of Abraham Lincoln",
      "text": "Abraham Lincoln was assassinated by John Wilkes Booth on April 14, 1865, and died the following day on April 15, 1865.",
      "date": "1865-04-14"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Albert Einstein",
      "text": "Albert Einstein was born on March 14, 1879, in Ulm, in the Kingdom of Württemberg in the German Empire.",
      "date": "1879-03-14"
    },
    {
      "headline": "Einstein's Family Moves to Munich",
      "text": "In 1880, Einstein's family moved to Munich, where his father and uncle founded Elektrotechnische Fabrik J. Einstein & Cie, a company that manufactured electrical equipment based on direct current.",
      "date": "1880"
    },
    {
      "headline": "Einstein Begins Schooling",
      "text": "In 1884, Einstein began his formal education at the Catholic elementary school in Munich.",
      "date": "1884"
    },
    {
      "headline": "Einstein Attends Luitpold Gymnasium",
      "text": "In 1888, Einstein transferred to the Luitpold Gymnasium (now known as the Albert Einstein Gymnasium) in Munich.",
      "date": "1888"
    },
    {
      "headline": "Einstein Moves to Italy",
      "text": "In 1894, Einstein's family moved to Pavia, Italy, but he stayed in Munich to finish his studies. He later joined his family in Italy.",
      "date": "1894"
    },
    {
      "headline": "Einstein Renounces German Citizenship",
      "text": "In 1896, Einstein renounced his German citizenship to avoid military service and enrolled at the Swiss Federal Polytechnic in Zurich.",
      "date": "1896"
    },
    {
      "headline": "Einstein Graduates from Polytechnic",
      "text": "In 1900, Einstein graduated from the Polytechnic with a diploma in mathematics and physics.",
      "date": "1900"
    },
    {
      "headline": "Einstein Marries Mileva Marić",
      "text": "On January 6, 1903, Einstein married Mileva Marić, a fellow student at the Polytechnic.",
      "date": "1903-01-06"
    },
    {
      "headline": "Annus Mirabilis Papers",
      "text": "In 1905, Einstein published four groundbreaking papers, including his theory of special relativity and the famous equation E=mc².",
      "date": "1905"
    },
    {
      "headline": "Einstein Receives PhD",
      "text": "In 1905, Einstein was awarded a PhD by the University of Zurich for his dissertation on the determination of molecular dimensions.",
      "date": "1905"
    },
    {
      "headline": "Einstein Becomes Professor",
      "text": "In 1908, Einstein became a lecturer at the University of Bern, and later a professor at the University of Zurich in 1909.",
      "date": "1908"
    },
    {
      "headline": "Einstein's General Theory of Relativity",
      "text": "In 1915, Einstein completed his general theory of relativity, which provided a new description of gravitation.",
      "date": "1915"
    },
    {
      "headline": "Einstein Divorces Mileva Marić",
      "text": "Einstein and Mileva Marić divorced on February 14, 1919.",
      "date": "1919-02-14"
    },
    {
      "headline": "Einstein Marries Elsa Löwenthal",
      "text": "On June 2, 1919, Einstein married Elsa Löwenthal, his cousin.",
      "date": "1919-06-02"
    },
    {
      "headline": "Nobel Prize in Physics",
      "text": "In 1921, Einstein was awarded the Nobel Prize in Physics for his discovery of the photoelectric effect.",
      "date": "1921"
    },
    {
      "headline": "Einstein Emigrates to the United States",
      "text": "In 1933, Einstein emigrated to the United States to escape the rise of the Nazi regime in Germany.",
      "date": "1933"
    },
    {
      "headline": "Einstein Becomes U.S. Citizen",
      "text": "In 1940, Einstein became a U.S. citizen, while retaining his Swiss citizenship.",
      "date": "1940"
    },
    {
      "headline": "Death of Albert Einstein",
      "text": "Albert Einstein died on April 18, 1955, in Princeton, New Jersey, USA.",
      "date": "1955-04-18"
    }
  ]
}

