    {
      "headline": "Turgut Özal's Economic Reforms",
      "text": "In the 1980s, Prime Minister Turgut Özal implemented significant economic reforms that liberalized the Turkish economy and promoted privatization.",
      "date": "1980s"
    },
    {
      "headline": "Earthquake in İzmit",
      "text": "On August 17, 1999, a devastating earthquake struck the city of İzmit, causing significant loss of life and damage.",
