{
  "timeline": [
    {
      "headline": "Domestication of Cats Begins",
      "text": "The domestication of the cat occurred in the Near East around 7500 BC. This process began when humans started to settle and farm, attracting wild cats to human settlements due to the abundance of rodents.",
      "date": "-7500"
    },
    {
      "headline": "Cats in Ancient Egypt",
      "text": "By around 2000 BC, cats were fully domesticated in Egypt and revered as sacred animals. They were associated with the goddess Bastet and were often depicted in Egyptian art.",
      "date": "-2000"
    },
    {
      "headline": "Spread of Cats to Europe",
      "text": "Cats spread to Europe around 1000 BC, likely brought by traders and travelers. They became valued for their ability to control vermin populations.",
      "date": "-1000"
    },
    {
      "headline": "Cats in the Roman Empire",
      "text": "During the Roman Empire, cats were commonly kept as pets and used for pest control. They spread further across Europe as the Roman Empire expanded.",
      "date": "0000"
    },
    {
      "headline": "Medieval Perceptions of Cats",
      "text": "In medieval Europe, cats were sometimes associated with witchcraft and superstition, leading to their persecution. However, they remained useful for controlling pests.",
      "date": "1300"
    },
    {
      "headline": "Cats in the Age of Exploration",
      "text": "During the Age of Exploration (15th to 17th centuries), cats were brought on ships to control vermin, leading to their spread to new continents.",
      "date": "1500"
    },
    {
      "headline": "Cats in the Modern Era",
      "text": "In the 19th and 20th centuries, cats became increasingly popular as household pets, valued for their companionship and independent nature.",
      "date": "1800"
    },
    {
      "headline": "Genetic Studies on Cat Domestication",
      "text": "Advances in archaeology and genetics in the 21st century have provided more insights into the domestication process of cats, confirming their origins in the Near East.",
      "date": "2000"
    }
  ]
}

