{
  "timeline": [
    {
      "headline": "Establishment of the United States House of Representatives",
      "text": "The United States House of Representatives was established by the United States Constitution, which was adopted on September 17, 1787. It was created as the lower chamber of the United States Congress, with the Senate being the upper chamber.",
      "date": "1787-09-17"
    },
    {
      "headline": "First Session of the United States House of Representatives",
      "text": "The first session of the United States House of Representatives convened on March 4, 1789, in New York City, which was the temporary capital of the United States at that time.",
      "date": "1789-03-04"
    },
    {
      "headline": "First Speaker of the House",
      "text": "Frederick Muhlenberg was elected as the first Speaker of the House on April 1, 1789. He served as the presiding officer of the House.",
      "date": "1789-04-01"
    },
    {
      "headline": "First Impeachment by the House",
      "text": "The House of Representatives conducted its first impeachment proceedings in 1797 against Senator William Blount for conspiring to assist the British in capturing Spanish territory.",
      "date": "1797"
    },
    {
      "headline": "Move to Washington, D.C.",
      "text": "The House of Representatives moved to Washington, D.C., along with the rest of the federal government, in 1800. The first session in the new capital was held in the United States Capitol building.",
      "date": "1800"
    },
    {
      "headline": "Passage of the 13th Amendment",
      "text": "The House of Representatives passed the 13th Amendment to the United States Constitution on January 31, 1865, which abolished slavery in the United States.",
      "date": "1865-01-31"
    },
    {
      "headline": "First Woman Elected to the House",
      "text": "Jeannette Rankin of Montana became the first woman elected to the United States House of Representatives on November 7, 1916.",
      "date": "1916-11-07"
    },
    {
      "headline": "Televised Sessions Begin",
      "text": "The House of Representatives began televising its sessions on January 3, 1947, allowing the public to view the legislative process.",
      "date": "1947-01-03"
    },
    {
      "headline": "First African American Speaker of the House",
      "text": "On January 3, 2023, Hakeem Jeffries was elected as the first African American to serve as Speaker of the House.",
      "date": "2023-01-03"
    }
  ]
}

