{
  "timeline": [
    {
      "headline": "Independence from British Rule",
      "text": "On August 14, 1947, Pakistan gained independence from British rule, following the end of British India. The country was established as a separate nation for Muslims in the Indian subcontinent.",
      "date": "1947-08-14"
    },
    {
      "headline": "First Constitution Adopted",
      "text": "Pakistan adopted its first constitution on March 23, 1956, transitioning from a Dominion to an Islamic Republic.",
      "date": "1956-03-23"
    },
    {
      "headline": "Military Coup by Ayub Khan",
      "text": "On October 7, 1958, General Ayub Khan led a military coup, abrogating the constitution and declaring martial law.",
      "date": "1958-10-07"
    },
    {
      "headline": "Second Constitution Promulgated",
      "text": "The second constitution of Pakistan was promulgated on June 8, 1962, under Ayub Khan's regime, replacing the 1956 constitution.",
      "date": "1962-06-08"
    },
    {
      "headline": "Yahya Khan's Martial Law",
      "text": "On March 25, 1969, General Yahya Khan imposed martial law after Ayub Khan resigned, leading to another period of military rule.",
      "date": "1969-03-25"
    },
    {
      "headline": "Bangladesh Liberation War",
      "text": "The Bangladesh Liberation War began on March 26, 1971, leading to the secession of East Pakistan and the creation of Bangladesh.",
      "date": "1971-03-26"
    },
    {
      "headline": "Third Constitution Enacted",
      "text": "Pakistan's third constitution was enacted on August 14, 1973, under the leadership of Prime Minister Zulfikar Ali Bhutto.",
      "date": "1973-08-14"
    },
    {
      "headline": "Zia-ul-Haq's Military Coup",
      "text": "On July 5, 1977, General Zia-ul-Haq led a military coup, overthrowing Prime Minister Zulfikar Ali Bhutto and imposing martial law.",
      "date": "1977-07-05"
    },
    {
      "headline": "Return to Civilian Rule",
      "text": "In 1988, after the death of Zia-ul-Haq in a plane crash, Pakistan returned to civilian rule with Benazir Bhutto becoming the first female Prime Minister.",
      "date": "1988"
    },
    {
      "headline": "Nuclear Tests Conducted",
