{
  "timeline": [
    {
      "headline": "Geneva Accords",
      "text": "The Geneva Accords were signed in 1954, temporarily dividing Vietnam at the 17th parallel, with the North controlled by the communist Viet Minh and the South by the State of Vietnam.",
      "date": "1954"
    },
    {
      "headline": "Formation of the National Liberation Front",
      "text": "In December 1960, the National Liberation Front (NLF), also known as the Viet Cong, was formed in South Vietnam to oppose the government and reunify the country under communist rule.",
      "date": "1960-12"
    },
    {
      "headline": "Gulf of Tonkin Incident",
      "text": "In August 1964, the Gulf of Tonkin Incident occurred, involving two separate confrontations between North Vietnamese forces and the United States Navy, leading to increased U.S. involvement in Vietnam.",
      "date": "1964-08"
    },
    {
      "headline": "Gulf of Tonkin Resolution",
      "text": "On August 7, 1964, the U.S. Congress passed the Gulf of Tonkin Resolution, granting President Lyndon B. Johnson the authority to assist any Southeast Asian country whose government was considered to be jeopardized by communist aggression.",
      "date": "1964-08-07"
    },
    {
      "headline": "Operation Rolling Thunder",
      "text": "Beginning in March 1965, Operation Rolling Thunder was a sustained bombing campaign conducted by the U.S. against North Vietnam, marking a significant escalation in American involvement in the war.",
      "date": "1965-03"
    },
    {
      "headline": "Tet Offensive",
      "text": "The Tet Offensive was launched by North Vietnamese and Viet Cong forces in January 1968, consisting of a series of surprise attacks against military and civilian commands and control centers throughout South Vietnam.",
      "date": "1968-01"
    },
    {
      "headline": "My Lai Massacre",
      "text": "On March 16, 1968, U.S. Army soldiers killed hundreds of unarmed South Vietnamese civilians in the hamlet of My Lai, sparking international outrage and increasing domestic opposition to the war.",
      "date": "1968-03-16"
    },
    {
      "headline": "Paris Peace Accords",
      "text": "The Paris Peace Accords were signed on January 27, 1973, intended to establish peace in Vietnam and end the Vietnam War, leading to the withdrawal of U.S. troops.",
      "date": "1973-01-27"
    },
    {
      "headline": "Fall of Saigon",
      "text": "On April 30, 1975, North Vietnamese forces captured Saigon, the capital of South Vietnam, effectively marking the end of the Vietnam War and leading to the reunification of Vietnam under communist control.",
      "date": "1975-04-30"
    }
  ]
}

