      "headline": "Start of the American Civil War",
      "text": "The American Civil War began on April 12, 1861, when Confederate forces fired upon Fort Sumter in South Carolina.",
      "date": "1861-04-12"
    },
    {
      "headline": "First Battle of Bull Run",
      "text": "The First Battle of Bull Run, also known as the First Battle of Manassas, was fought on July 21, 1861, and was the first major battle of the American Civil War.",
      "date": "1861-07-21"
    },
    {
      "headline": "Battle of Antietam",
      "text": "The Battle of Antietam, fought on September 17, 1862, was the bloodiest single-day battle in American history, with about 22,717 dead, wounded, or missing.",
      "date": "1862-09-17"
    },
    {
      "headline": "Emancipation Proclamation Issued",
      "text": "President Abraham Lincoln issued the Emancipation Proclamation on January 1, 1863, declaring all slaves in Confederate-held territory to be free.",
      "date": "1863-01-01"
    },
    {
      "headline": "Battle of Gettysburg",
      "text": "The Battle of Gettysburg was fought from July 1 to July 3, 1863, and is considered the turning point of the American Civil War.",
      "date": "1863-07-01"
    },
    {
      "headline": "Gettysburg Address",
      "text": "President Abraham Lincoln delivered the Gettysburg Address on November 19, 1863, at the dedication of the Soldiers' National Cemetery in Gettysburg, Pennsylvania.",
      "date": "1863-11-19"
    },
    {
      "headline": "Sherman's March to the Sea",
      "text": "Union General William Tecumseh Sherman led his troops on a destructive march from Atlanta to Savannah, Georgia, from November 15 to December 21, 1864.",
      "date": "1864-11-15"
    },
    {
      "headline": "Surrender at Appomattox Court House",
      "text": "Confederate General Robert E. Lee surrendered to Union General Ulysses S. Grant at Appomattox Court House on April 9, 1865, effectively ending the American Civil War.",
      "date": "1865-04-09"
    },
    {
      "headline": "Assassination of Abraham Lincoln",
      "text": "President Abraham Lincoln was assassinated by John Wilkes Booth on April 14, 1865, and died the following day.",
      "date": "1865-04-14"
    },
    {
      "headline": "End of the American Civil War",
      "text": "The American Civil War officially ended on May 9, 1865, when the last Confederate army surrendered.",
      "date": "1865-05-09"
    }
  ]
}

