    {
      "headline": "Burgundian Netherlands",
      "text": "In 1433, the Burgundian Netherlands was formed, uniting various Dutch territories under the rule of the Dukes of Burgundy.",
      "date": "1433"
    },
    {
      "headline": "Habsburg Netherlands",
      "text": "In 1482, the Habsburg Netherlands was established after the marriage of Mary of Burgundy and Maximilian I of Austria.",
      "date": "1482"
    },
    {
      "headline": "Eighty Years' War Begins",
      "text": "In 1568, the Eighty Years' War began as the Dutch sought independence from Spanish rule.",
      "date": "1568"
    },
    {
      "headline": "Union of Utrecht",
      "text": "In 1579, the Union of Utrecht was signed, uniting the northern provinces in their struggle against Spain.",
      "date": "1579"
    },
    {
      "headline": "Dutch Republic Established",
      "text": "In 1581, the Dutch Republic was established following the Act of Abjuration, declaring independence from Spain.",
      "date": "1581"
    },
    {
      "headline": "Peace of Westphalia",
      "text": "In 1648, the Peace of Westphalia ended the Eighty Years' War, recognizing the independence of the Dutch Republic.",
      "date": "1648"
    },
    {
      "headline": "Batavian Republic",
      "text": "In 1795, the Batavian Republic was established after the French Revolutionary forces invaded the Netherlands.",
      "date": "1795"
    },
    {
      "headline": "Kingdom of the Netherlands",
      "text": "In 1815, the Kingdom of the Netherlands was established following the defeat of Napoleon.",
      "date": "1815"
    },
    {
      "headline": "Belgian Revolution",
      "text": "In 1830, the Belgian Revolution led to the secession of Belgium from the Kingdom of the Netherlands.",
      "date": "1830"
    },
    {
      "headline": "World War II Occupation",
      "text": "In 1940, the Netherlands was occupied by Nazi Germany during World War II.",
      "date": "1940"
    },
    {
      "headline": "Liberation of the Netherlands",
      "text": "In 1945, the Netherlands was liberated from Nazi occupation by Allied forces.",
      "date": "1945"
    },
    {
      "headline": "Founding Member of NATO",
      "text": "In 1949, the Netherlands became a founding member of the North Atlantic Treaty Organization (NATO).",
      "date": "1949"
    },
    {
      "headline": "Founding Member of the European Economic Community",
      "text": "In 1957, the Netherlands was one of the founding members of the European Economic Community, a precursor to the European Union.",
      "date": "1957"
