{
  "timeline": [
    {
      "headline": "Birth of B. R. Ambedkar",
      "text": "Bhimrao Ramji Ambedkar was born on April 14, 1891, in Mhow, Central Provinces, British India (now in Madhya Pradesh, India).",
      "date": "1891-04-14"
    },
    {
      "headline": "Graduation from Elphinstone College",
      "text": "In 1912, Ambedkar obtained his degree in economics and political science from Bombay University, becoming one of the first Dalits to achieve this milestone.",
      "date": "1912"
    },
    {
      "headline": "Studies at Columbia University",
      "text": "In 1913, Ambedkar moved to the United States to study at Columbia University on a Baroda State Scholarship. He completed his MA in 1915.",
      "date": "1913"
    },
    {
      "headline": "PhD from Columbia University",
      "text": "Ambedkar was awarded a PhD in Economics from Columbia University in 1927 for his thesis on 'The Evolution of Provincial Finance in British India'.",
      "date": "1927"
    },
    {
      "headline": "Return to India and Public Service",
      "text": "After completing his studies abroad, Ambedkar returned to India in 1923 and began working as a professor and public servant.",
      "date": "1923"
    },
    {
      "headline": "Founding of the Bahishkrit Hitakarini Sabha",
      "text": "In 1924, Ambedkar founded the Bahishkrit Hitakarini Sabha to promote education and socio-economic improvement for the untouchables.",
      "date": "1924"
    },
    {
      "headline": "Participation in the Round Table Conferences",
      "text": "Ambedkar attended the Round Table Conferences in London in 1930, 1931, and 1932, representing the interests of the untouchables.",
      "date": "1930"
    },
    {
      "headline": "Poona Pact",
      "text": "In 1932, Ambedkar signed the Poona Pact with Mahatma Gandhi, which provided reserved seats for untouchables in the provincial legislatures within the general electorate.",
      "date": "1932"
    },
    {
      "headline": "Founding of the Independent Labour Party",
      "text": "In 1936, Ambedkar founded the Independent Labour Party, which contested the 1937 Bombay elections and won 15 seats.",
      "date": "1936"
    },
    {
      "headline": "Drafting the Indian Constitution",
      "text": "Ambedkar was appointed as the Chairman of the Drafting Committee of the Indian Constitution in 1947, playing a pivotal role in its creation.",
      "date": "1947"
    },
    {
      "headline": "First Law and Justice Minister of India",
      "text": "In 1947, Ambedkar became the first Law and Justice Minister of independent India in Jawaharlal Nehru's cabinet.",
      "date": "1947"
    },
    {
      "headline": "Conversion to Buddhism",
      "text": "On October 14, 1956, Ambedkar converted to Buddhism in a public ceremony in Nagpur, inspiring the Dalit Buddhist movement.",
      "date": "1956-10-14"
    },
    {
      "headline": "Death of B. R. Ambedkar",
      "text": "B. R. Ambedkar passed away on December 6, 1956, in Delhi, India.",
      "date": "1956-12-06"
    }
  ]
}

