{
  "timeline": [
    {
      "headline": "Birth of Joseph Stalin",
      "text": "Joseph Vissarionovich Stalin was born on December 18, 1878, in Gori, Tiflis Governorate, Russian Empire (now Georgia).",
      "date": "1878-12-18"
    },
    {
      "headline": "Joins Russian Social Democratic Labour Party",
      "text": "In 1901, Stalin joined the Russian Social Democratic Labour Party, marking the beginning of his political career.",
      "date": "1901"
    },
    {
      "headline": "Exile to Siberia",
      "text": "Stalin was arrested multiple times and was exiled to Siberia in 1902, 1908, 1910, and 1913 due to his revolutionary activities.",
      "date": "1902"
    },
    {
      "headline": "Escape from Siberian Exile",
      "text": "Stalin escaped from his Siberian exile in 1904, demonstrating his determination to continue his revolutionary activities.",
      "date": "1904"
    },
    {
      "headline": "Bolshevik Revolution",
      "text": "Stalin played a role in the Bolshevik Revolution of October 1917, which led to the overthrow of the Provisional Government and the establishment of Bolshevik rule.",
      "date": "1917-10"
    },
    {
      "headline": "Appointed General Secretary of the Communist Party",
      "text": "On April 3, 1922, Stalin was appointed General Secretary of the Communist Party, a position that allowed him to consolidate power.",
      "date": "1922-04-03"
    },
    {
      "headline": "Death of Vladimir Lenin",
      "text": "Vladimir Lenin died on January 21, 1924, leading to a power struggle within the Communist Party, which Stalin eventually won.",
      "date": "1924-01-21"
    },
    {
      "headline": "Launch of the First Five-Year Plan",
      "text": "In 1928, Stalin launched the First Five-Year Plan, aiming to rapidly industrialize the Soviet Union and collectivize agriculture.",
      "date": "1928"
    },
    {
      "headline": "Great Purge",
      "text": "The Great Purge, a campaign of political repression, began in 1936 and lasted until 1938, resulting in the execution and imprisonment of millions.",
      "date": "1936"
    },
    {
      "headline": "World War II and the Battle of Stalingrad",
      "text": "During World War II, the Battle of Stalingrad (1942-1943) was a turning point in the war, with Soviet forces defeating the German army.",
      "date": "1942"
    },
    {
      "headline": "Chairman of the Council of Ministers",
      "text": "Stalin became Chairman of the Council of Ministers on May 6, 1941, further consolidating his control over the Soviet government.",
      "date": "1941-05-06"
    },
    {
      "headline": "Death of Joseph Stalin",
      "text": "Joseph Stalin died on March 5, 1953, in Kuntsevo Dacha, near Moscow, Soviet Union, ending his nearly three-decade rule.",
      "date": "1953-03-05"
    }
  ]
}

