{
  "timeline": [
    {
      "headline": "Dmitri Mendeleev's First Periodic Table",
      "text": "In 1869, Dmitri Mendeleev presented the first version of the periodic table to the Russian Chemical Society. He arranged the 63 known elements into a table based on atomic mass, leaving gaps for elements yet to be discovered.",
      "date": "1869"
    },
    {
      "headline": "Lothar Meyer's Periodic Table",
      "text": "In 1869, Lothar Meyer independently developed a periodic table similar to Mendeleev's, also based on atomic mass and periodic properties of elements.",
      "date": "1869"
    },
    {
      "headline": "Discovery of Gallium",
      "text": "In 1875, the element gallium was discovered by Paul-Émile Lecoq de Boisbaudran. Its properties matched Mendeleev's predictions for the then-unknown element 'eka-aluminum'.",
      "date": "1875"
    },
    {
      "headline": "Discovery of Scandium",
      "text": "In 1879, Lars Fredrik Nilson discovered scandium, which matched Mendeleev's predictions for the element 'eka-boron'.",
      "date": "1879"
    },
    {
      "headline": "Discovery of Germanium",
      "text": "In 1886, Clemens Winkler discovered germanium, which confirmed Mendeleev's predictions for the element 'eka-silicon'.",
      "date": "1886"
    },
    {
      "headline": "Henry Moseley's Atomic Number Concept",
      "text": "In 1913, Henry Moseley demonstrated that the atomic number, not atomic mass, is the correct basis for the organization of the periodic table. This led to the modern definition of the periodic law.",
      "date": "1913"
    },
    {
      "headline": "Glenn T. Seaborg's Actinide Series",
      "text": "In 1945, Glenn T. Seaborg proposed the actinide series, which led to the current layout of the periodic table with the lanthanides and actinides placed below the main body.",
      "date": "1945"
    },
    {
      "headline": "Discovery of Element 101, Mendelevium",
      "text": "In 1955, element 101 was discovered and named mendelevium in honor of Dmitri Mendeleev.",
      "date": "1955"
    },
    {
      "headline": "Completion of the 7th Period",
      "text": "In 2016, the International Union of Pure and Applied Chemistry (IUPAC) confirmed the names of elements 113 (Nihonium), 114 (Flerovium), 115 (Moscovium), 116 (Livermorium), 117 (Tennessine), and 118 (Oganesson), completing the 7th period of the periodic table.",
      "date": "2016"
    }
  ]
}

