{
  "timeline": [
    {
      "headline": "Birth of Mohandas Karamchand Gandhi",
      "text": "Mohandas Karamchand Gandhi was born on October 2, 1869, in Porbandar, which is in present-day Gujarat, India.",
      "date": "1869-10-02"
    },
    {
      "headline": "Marriage to Kasturba Gandhi",
      "text": "In May 1883, at the age of 13, Gandhi was married to Kasturba Makhanji in an arranged marriage.",
      "date": "1883-05"
    },
    {
      "headline": "Departure to London for Law Studies",
      "text": "In September 1888, Gandhi left for London to study law at University College London.",
      "date": "1888-09"
    },
    {
      "headline": "Return to India",
      "text": "Gandhi returned to India in 1891 after completing his studies in law.",
      "date": "1891"
    },
    {
      "headline": "Move to South Africa",
      "text": "In 1893, Gandhi moved to South Africa to work as a legal representative for the Muslim Indian Traders based in the city of Pretoria.",
      "date": "1893"
    },
    {
      "headline": "Formation of Natal Indian Congress",
      "text": "In 1894, Gandhi founded the Natal Indian Congress to fight discrimination against Indians in South Africa.",
      "date": "1894"
    },
    {
      "headline": "First Satyagraha Campaign",
      "text": "In 1906, Gandhi organized his first mass civil disobedience campaign, known as Satyagraha, in response to the Transvaal government's new restrictions on the rights of Indians.",
      "date": "1906"
    },
    {
      "headline": "Return to India from South Africa",
      "text": "Gandhi returned to India in 1915 after spending over 20 years in South Africa, where he developed his political and ethical views.",
      "date": "1915"
    },
    {
      "headline": "Champaran Satyagraha",
      "text": "In 1917, Gandhi led the Champaran Satyagraha, his first significant political campaign in India, to address the grievances of farmers in the Champaran district of Bihar.",
      "date": "1917"
    },
    {
      "headline": "Kheda Satyagraha",
      "text": "In 1918, Gandhi organized the Kheda Satyagraha to support farmers in the Kheda district of Gujarat, who were unable to pay taxes due to crop failure.",
      "date": "1918"
    },
    {
      "headline": "Non-Cooperation Movement",
      "text": "In 1920, Gandhi launched the Non-Cooperation Movement, urging Indians to boycott British goods and institutions.",
      "date": "1920"
    },
    {
      "headline": "Salt March",
      "text": "On March 12, 1930, Gandhi began the Salt March, a 240-mile march to the Arabian Sea to protest the British salt tax.",
      "date": "1930-03-12"
    },
    {
      "headline": "Quit India Movement",
      "text": "In August 1942, Gandhi launched the Quit India Movement, demanding an end to British rule in India.",
      "date": "1942-08"
    },
    {
      "headline": "India's Independence",
      "text": "On August 15, 1947, India gained independence from British rule, a movement significantly influenced by Gandhi's leadership and philosophy.",
      "date": "1947-08-15"
    },
    {
      "headline": "Assassination of Mahatma Gandhi",
      "text": "Mahatma Gandhi was assassinated on January 30, 1948, by Nathuram Godse in New Delhi, India.",
      "date": "1948-01-30"
    }
  ]
}

