      "headline": "Birth of Alexander the Great",
      "text": "Alexander the Great was born in Pella, the ancient capital of Macedonia, in July 356 BCE.",
      "date": "-0356-07"
    },
    {
      "headline": "Alexander Becomes King of Macedon",
      "text": "In 336 BCE, Alexander ascended to the throne of Macedon after the assassination of his father, King Philip II.",
      "date": "-0336"
    },
    {
      "headline": "Battle of Granicus",
      "text": "In May 334 BCE, Alexander won his first major battle against the Persian Empire at the Battle of Granicus.",
      "date": "-0334-05"
    },
    {
      "headline": "Battle of Issus",
      "text": "In November 333 BCE, Alexander defeated Darius III of Persia at the Battle of Issus.",
      "date": "-0333-11"
    },
    {
      "headline": "Siege of Tyre",
      "text": "In 332 BCE, Alexander successfully besieged and captured the heavily fortified city of Tyre after a seven-month siege.",
      "date": "-0332"
    },
    {
      "headline": "Founding of Alexandria",
      "text": "In 331 BCE, Alexander founded the city of Alexandria in Egypt, which would become a major center of Hellenistic culture.",
      "date": "-0331"
    },
    {
      "headline": "Battle of Gaugamela",
      "text": "On October 1, 331 BCE, Alexander achieved a decisive victory over Darius III at the Battle of Gaugamela, leading to the fall of the Achaemenid Empire.",
      "date": "-0331-10-01"
    },
    {
      "headline": "Conquest of Persepolis",
      "text": "In 330 BCE, Alexander captured and burned the Persian capital of Persepolis.",
      "date": "-0330"
    },
    {
      "headline": "Campaign in India",
      "text": "In 326 BCE, Alexander crossed into India and fought the Battle of the Hydaspes against King Porus.",
      "date": "-0326"
    },
    {
      "headline": "Return to Babylon",
      "text": "In 324 BCE, Alexander returned to Babylon, where he began planning further military campaigns.",
      "date": "-0324"
    },
    {
      "headline": "Death of Alexander the Great",
      "text": "Alexander the Great died on June 10 or 11, 323 BCE, in the palace of Nebuchadnezzar II in Babylon, at the age of 32.",
      "date": "-0323-06-10"
    }
  ]
}

