{
  "timeline": [
    {
      "headline": "First Human Habitation",
      "text": "The region now known as South Africa has been inhabited by humans for thousands of years. Evidence of early human habitation dates back to around 170,000 years ago.",
      "date": "-170000"
    },
    {
      "headline": "Arrival of Bantu-speaking Peoples",
      "text": "Around 500 CE, Bantu-speaking peoples began migrating into the region, bringing with them new technologies and farming practices.",
      "date": "0500"
    },
    {
      "headline": "Portuguese Exploration",
      "text": "In 1488, Portuguese explorer Bartolomeu Dias became the first European to reach the southern tip of Africa, which he named the Cape of Storms, later renamed the Cape of Good Hope.",
      "date": "1488"
    },
    {
      "headline": "Dutch Settlement at Cape of Good Hope",
      "text": "In 1652, the Dutch East India Company established a supply station at the Cape of Good Hope, marking the beginning of European colonization in South Africa.",
      "date": "1652"
    },
    {
      "headline": "British Control of the Cape",
      "text": "In 1806, the British took control of the Cape Colony from the Dutch during the Napoleonic Wars.",
      "date": "1806"
    },
    {
      "headline": "Great Trek",
      "text": "Between 1835 and 1846, the Great Trek occurred, during which thousands of Boers (Dutch settlers) migrated inland to escape British rule.",
      "date": "1835"
    },
    {
      "headline": "Discovery of Diamonds",
      "text": "In 1867, diamonds were discovered in Kimberley, leading to a diamond rush and increased British interest in the region.",
      "date": "1867"
    },
    {
      "headline": "First Boer War",
      "text": "The First Boer War took place from 1880 to 1881, as the Boers resisted British attempts to annex the Transvaal Republic.",
      "date": "1880"
    },
    {
      "headline": "Discovery of Gold",
      "text": "In 1886, gold was discovered on the Witwatersrand, leading to a gold rush and further economic development.",
      "date": "1886"
    },
    {
      "headline": "Second Boer War",
      "text": "The Second Boer War occurred from 1899 to 1902, resulting in British victory and the annexation of the Boer republics.",
      "date": "1899"
    },
    {
      "headline": "Union of South Africa",
      "text": "On May 31, 1910, the Union of South Africa was established, uniting the Cape Colony, Natal, Transvaal, and the Orange Free State under British dominion.",
      "date": "1910-05-31"
    },
    {
      "headline": "Apartheid Legislation Begins",
      "text": "In 1948, the National Party came to power and began implementing apartheid, a policy of racial segregation and discrimination.",
      "date": "1948"
    },
    {
      "headline": "Sharpeville Massacre",
      "text": "On March 21, 1960, police opened fire on a peaceful protest in Sharpeville, killing 69 people and leading to increased international condemnation of apartheid.",
      "date": "1960-03-21"
    },
    {
      "headline": "Republic of South Africa",
      "text": "On May 31, 1961, South Africa became a republic and left the Commonwealth of Nations.",
      "date": "1961-05-31"
    },
    {
      "headline": "Soweto Uprising",
      "text": "On June 16, 1976, the Soweto Uprising began as students protested against the imposition of Afrikaans as a medium of instruction, leading to widespread unrest.",
      "date": "1976-06-16"
    },
    {
      "headline": "Nelson Mandela Released",
      "text": "On February 11, 1990, Nelson Mandela was released from prison after 27 years, marking a significant step towards the end of apartheid.",
      "date": "1990-02-11"
    },
    {
      "headline": "End of Apartheid",
      "text": "In 1994, apartheid officially ended, and South Africa held its first multiracial elections, resulting in Nelson Mandela becoming the country's first black president.",
      "date": "1994"
    },
    {
      "headline": "Adoption of New Constitution",
      "text": "In 1996, South Africa adopted a new constitution, enshrining equal rights for all citizens.",
      "date": "1996"
    }
  ]
}

