}

{
  "timeline": [
    {
      "headline": "Case Filed",
      "text": "The case of Roe v. Wade was filed in 1970 by 'Jane Roe', an alias for Norma McCorvey, who challenged the Texas laws that criminalized abortion.",
      "date": "1970"
    },
    {
      "headline": "Supreme Court Decision",
      "text": "On January 22, 1973, the U.S. Supreme Court issued its decision in Roe v. Wade, ruling that the Constitution of the United States protects a pregnant woman's liberty to choose to have an abortion without excessive government restriction.",
      "date": "1973-01-22"
    },
    {
      "headline": "Impact on Abortion Laws",
      "text": "The decision in Roe v. Wade struck down many federal and state abortion laws, and it sparked an ongoing national debate in the United States about abortion.",
      "date": "1973"
    },
    {
      "headline": "Subsequent Legal Challenges",
      "text": "In the years following the Roe v. Wade decision, numerous legal challenges and cases were brought forth that sought to overturn or limit the scope of the ruling.",
      "date": "1973 onwards"
    },
    {
      "headline": "Planned Parenthood v. Casey",
      "text": "In 1992, the Supreme Court case Planned Parenthood v. Casey reaffirmed the central holding of Roe v. Wade but allowed states to impose certain restrictions on abortion.",
      "date": "1992"
    },
    {
      "headline": "Dobbs v. Jackson Women's Health Organization",
      "text": "On June 24, 2022, the Supreme Court overturned Roe v. Wade in the case of Dobbs v. Jackson Women's Health Organization, ending the federal constitutional right to an abortion.",
      "date": "2022-06-24"
    }
  ]
}

