    {
      "headline": "Aztec Empire Established",
      "text": "The Aztec Empire was established in 1428 through the Triple Alliance of Tenochtitlan, Texcoco, and Tlacopan, dominating central Mexico.",
      "date": "1428"
    },
    {
      "headline": "Spanish Conquest of the Aztec Empire",
      "text": "In 1521, Hernán Cortés and his Spanish forces, along with indigenous allies, conquered the Aztec Empire, marking the beginning of Spanish rule in Mexico.",
      "date": "1521"
    },
    {
      "headline": "Mexican War of Independence Begins",
      "text": "The Mexican War of Independence began on September 16, 1810, with Miguel Hidalgo's call to arms, known as the Grito de Dolores.",
      "date": "1810-09-16"
    },
    {
      "headline": "Independence from Spain",
      "text": "Mexico gained independence from Spain on September 27, 1821, following the signing of the Treaty of Córdoba.",
      "date": "1821-09-27"
    },
    {
      "headline": "First Mexican Empire Established",
      "text": "The First Mexican Empire was established in 1821, with Agustín de Iturbide as Emperor, but it was short-lived, ending in 1823.",
      "date": "1821"
    },
    {
      "headline": "Mexican-American War",
      "text": "The Mexican-American War took place from 1846 to 1848, resulting in Mexico losing about half of its territory to the United States.",
      "date": "1846"
    },
    {
      "headline": "Benito Juárez Becomes President",
      "text": "Benito Juárez became President of Mexico in 1858, known for his liberal reforms and resistance against the French intervention.",
      "date": "1858"
    },
    {
      "headline": "French Intervention and Second Mexican Empire",
      "text": "The French intervention in Mexico led to the establishment of the Second Mexican Empire under Emperor Maximilian I from 1864 to 1867.",
      "date": "1864"
    },
    {
      "headline": "Porfirio Díaz's Presidency",
      "text": "Porfirio Díaz served as President of Mexico from 1876 to 1911, a period known as the Porfiriato, marked by modernization and economic growth but also political repression.",
      "date": "1876"
    },
    {
      "headline": "Mexican Revolution Begins",
      "text": "The Mexican Revolution began on November 20, 1910, as a response to the long-standing dictatorship of Porfirio Díaz, leading to significant social and political changes.",
      "date": "1910-11-20"
    },
    {
      "headline": "Constitution of 1917",
      "text": "The Constitution of 1917 was enacted on February 5, 1917, establishing a framework for land reform, labor rights, and the separation of church and state.",
      "date": "1917-02-05"
    },
    {
      "headline": "PRI Dominance Begins",
      "text": "The Institutional Revolutionary Party (PRI) began its long-standing dominance in Mexican politics in 1929, ruling for most of the 20th century.",
      "date": "1929"
    },
    {
      "headline": "Tlatelolco Massacre",
      "text": "On October 2, 1968, the Tlatelolco Massacre occurred in Mexico City, where government forces killed hundreds of student protesters.",
      "date": "1968-10-02"
    },
    {
      "headline": "NAFTA Agreement",
      "text": "The North American Free Trade Agreement (NAFTA) between Mexico, the United States, and Canada came into effect on January 1, 1994, boosting trade and economic integration.",
      "date": "1994-01-01"
    },
    {
      "headline": "Election of Vicente Fox",
      "text": "Vicente Fox was elected President in 2000, marking the end of 71 years of PRI rule and the beginning of a new era in Mexican politics.",
