{
  "timeline": [
    {
      "headline": "Creation of the United States Senate",
      "text": "The United States Senate was established as part of the United States Constitution, which was signed on September 17, 1787. The Senate was created as the upper chamber of the United States Congress, with the authority to pass or defeat federal legislation, confirm presidential appointments, approve treaties, and try impeachment cases.",
      "date": "1787-09-17"
    },
    {
      "headline": "First United States Senate Session",
      "text": "The first session of the United States Senate was held on March 4, 1789, in New York City, which was the temporary capital of the United States at the time. This marked the official beginning of the Senate's legislative activities.",
      "date": "1789-03-04"
    },
    {
      "headline": "Ratification of the Seventeenth Amendment",
      "text": "The Seventeenth Amendment to the United States Constitution was ratified on April 8, 1913. This amendment established the direct election of United States Senators by popular vote, replacing the previous system of election by state legislatures.",
      "date": "1913-04-08"
    },
    {
      "headline": "First Televised Senate Session",
      "text": "On January 3, 1947, the United States Senate held its first televised session. This event marked a significant step in making Senate proceedings more accessible to the American public.",
      "date": "1947-01-03"
    },
    {
      "headline": "Senate Watergate Hearings",
      "text": "The Senate Watergate hearings began on May 17, 1973. These hearings were conducted by the Senate Watergate Committee to investigate the Watergate scandal, which ultimately led to the resignation of President Richard Nixon.",
      "date": "1973-05-17"
    },
    {
      "headline": "First Female Senate Majority Leader",
      "text": "On January 3, 2021, Senator Mitch McConnell was succeeded by Senator Chuck Schumer as the Senate Majority Leader, marking the first time a woman, Kamala Harris, served as Vice President and thus as President of the Senate.",
      "date": "2021-01-03"
    }
  ]
}

