{
  "timeline": [
    {
      "headline": "First Opium War",
      "text": "The First Opium War between the British Empire and the Qing dynasty of China began in 1839 and ended in 1842.",
      "date": "1839"
    },
    {
      "headline": "Treaty of Nanking",
      "text": "On August 29, 1842, the Treaty of Nanking was signed, ending the First Opium War. As part of the treaty, Hong Kong Island was ceded to the British Empire.",
