{
  "timeline": [
    {
      "headline": "Discovery of Brazil",
      "text": "On April 22, 1500, Portuguese navigator Pedro Álvares Cabral officially discovered Brazil, landing on the coast near present-day Porto Seguro.",
      "date": "1500-04-22"
    },
    {
      "headline": "Establishment of the First Permanent Settlement",
      "text": "In 1532, the Portuguese established the first permanent settlement in Brazil at São Vicente.",
      "date": "1532"
    },
    {
      "headline": "Creation of the Governorate General of Brazil",
      "text": "In 1549, the Portuguese crown created the Governorate General of Brazil to centralize the administration of the colony, with Tomé de Sousa as the first governor-general.",
      "date": "1549"
    },
    {
      "headline": "Dutch Occupation of Brazil",
      "text": "From 1630 to 1654, the Dutch occupied parts of northeastern Brazil, establishing a colony in Pernambuco.",
      "date": "1630"
    },
    {
      "headline": "End of Dutch Occupation",
      "text": "In 1654, the Portuguese successfully expelled the Dutch from Brazil, regaining control over the occupied territories.",
      "date": "1654"
    },
    {
      "headline": "Inconfidência Mineira",
      "text": "In 1789, the Inconfidência Mineira, a failed independence movement, took place in Minas Gerais, inspired by the American and French revolutions.",
      "date": "1789"
    },
    {
      "headline": "Transfer of the Portuguese Court to Brazil",
      "text": "In 1808, the Portuguese royal family and court fled to Brazil to escape Napoleon's invasion of Portugal, making Rio de Janeiro the de facto capital of the Portuguese Empire.",
      "date": "1808"
    },
    {
      "headline": "Brazil Becomes a Kingdom",
      "text": "In 1815, Brazil was elevated to the status of a kingdom, united with Portugal as the United Kingdom of Portugal, Brazil, and the Algarves.",
      "date": "1815"
    },
    {
      "headline": "Independence of Brazil",
      "text": "On September 7, 1822, Prince Dom Pedro declared Brazil's independence from Portugal, becoming Emperor Pedro I of Brazil.",
      "date": "1822-09-07"
    },
    {
      "headline": "Abolition of Slavery",
      "text": "On May 13, 1888, Brazil abolished slavery with the signing of the Lei Áurea (Golden Law) by Princess Isabel.",
      "date": "1888-05-13"
    },
    {
      "headline": "Proclamation of the Republic",
      "text": "On November 15, 1889, Brazil transitioned from an empire to a republic following a military coup that deposed Emperor Pedro II.",
      "date": "1889-11-15"
    },
    {
      "headline": "Vargas Era Begins",
      "text": "In 1930, Getúlio Vargas came to power after a coup d'état, marking the beginning of the Vargas Era, which lasted until 1945.",
      "date": "1930"
    },
    {
      "headline": "Military Dictatorship",
      "text": "In 1964, a military coup overthrew President João Goulart, leading to a military dictatorship that lasted until 1985.",
      "date": "1964"
    },
    {
      "headline": "Return to Democracy",
      "text": "In 1985, Brazil returned to civilian rule with the election of Tancredo Neves, although he died before taking office, and José Sarney became president.",
      "date": "1985"
    },
    {
      "headline": "New Constitution",
      "text": "In 1988, Brazil adopted a new constitution, establishing a democratic government and guaranteeing civil rights.",
      "date": "1988"
    },
    {
      "headline": "First Direct Presidential Election Since 1960",
      "text": "In 1989, Brazil held its first direct presidential election since 1960, resulting in the election of Fernando Collor de Mello.",
      "date": "1989"
    },
    {
      "headline": "Impeachment of President Collor",
      "text": "In 1992, President Fernando Collor de Mello resigned amid corruption charges, becoming the first Brazilian president to be impeached.",
      "date": "1992"
    },
    {
      "headline": "Election of Luiz Inácio Lula da Silva",
      "text": "In 2002, Luiz Inácio Lula da Silva was elected president, becoming the first working-class president of Brazil.",
      "date": "2002"
    },
    {
      "headline": "Impeachment of President Dilma Rousseff",
      "text": "In 2016, President Dilma Rousseff was impeached and removed from office over charges of fiscal mismanagement.",
      "date": "2016"
    }
  ]
}

