{
  "timeline": [
    {
      "headline": "Earliest Known Reference to Freemasonry",
      "text": "The Regius Manuscript, dating from approximately 1390, is the earliest known document that refers to Freemasonry. It is a poem that outlines the duties of a mason.",
      "date": "1390"
    },
    {
      "headline": "Formation of the Premier Grand Lodge of England",
      "text": "On June 24, 1717, the Premier Grand Lodge of England, the first Grand Lodge in the world, was formed in London when four existing lodges gathered at the Goose and Gridiron Ale-house.",
      "date": "1717-06-24"
    },
    {
      "headline": "Publication of Anderson's Constitutions",
      "text": "In 1723, James Anderson published the first edition of the Constitutions of the Free-Masons, which became a foundational document for Freemasonry.",
      "date": "1723"
    },
    {
      "headline": "Establishment of the Grand Lodge of Ireland",
      "text": "The Grand Lodge of Ireland was established in 1725, making it the second oldest Grand Lodge in the world.",
      "date": "1725"
    },
    {
      "headline": "Formation of the Grand Lodge of Scotland",
      "text": "The Grand Lodge of Scotland was formed on November 30, 1736, further solidifying the organizational structure of Freemasonry in the British Isles.",
      "date": "1736-11-30"
    },
    {
      "headline": "Union of the Two Grand Lodges in England",
      "text": "On December 27, 1813, the Premier Grand Lodge of England and the Antient Grand Lodge of England united to form the United Grand Lodge of England.",
      "date": "1813-12-27"
    },
    {
      "headline": "Establishment of Prince Hall Freemasonry",
      "text": "Prince Hall Freemasonry was established in the late 18th century, with African Lodge No. 459 receiving its charter from the Grand Lodge of England on September 29, 1784.",
      "date": "1784-09-29"
    },
