{
  "timeline": [
    {
      "headline": "Explosion of Reactor No. 4",
      "text": "On April 26, 1986, the No. 4 reactor at the Chernobyl Nuclear Power Plant exploded near the city of Pripyat in northern Ukraine, then part of the Soviet Union. This event marked the beginning of the Chernobyl disaster.",
      "date": "1986-04-26"
    },
    {
      "headline": "Immediate Response and Firefighting",
      "text": "In the immediate aftermath of the explosion, firefighters and plant workers attempted to control the fires and contain the damage. Many of these first responders were exposed to high levels of radiation.",
      "date": "1986-04-26"
    },
    {
      "headline": "Evacuation of Pripyat",
      "text": "On April 27, 1986, the city of Pripyat, located near the Chernobyl plant, was evacuated. Approximately 49,000 residents were relocated due to the dangerous levels of radiation.",
      "date": "1986-04-27"
    },
    {
      "headline": "Soviet Government Acknowledges Disaster",
      "text": "On April 28, 1986, the Soviet government publicly acknowledged the disaster after increased radiation levels were detected in Sweden, prompting international concern.",
      "date": "1986-04-28"
    },
    {
      "headline": "Construction of the Sarcophagus",
      "text": "In May 1986, efforts began to construct a concrete sarcophagus to encase the damaged reactor and contain the release of radioactive materials. This structure was completed in November 1986.",
      "date": "1986-11"
    },
    {
      "headline": "International Nuclear Event Scale Rating",
      "text": "The Chernobyl disaster was rated at the maximum severity level of 7 on the International Nuclear Event Scale, indicating a major accident with widespread health and environmental effects.",
      "date": "1986"
    },
    {
      "headline": "Formation of the Chernobyl Exclusion Zone",
      "text": "In 1986, the Chernobyl Exclusion Zone was established, covering an area of approximately 2,600 square kilometers around the plant to restrict access and minimize radiation exposure.",
      "date": "1986"
    },
    {
      "headline": "Liquidation Efforts",
      "text": "Between 1986 and 1991, more than 500,000 personnel, known as 'liquidators,' were involved in cleanup operations, including decontamination and construction of the sarcophagus.",
      "date": "1986-1991"
    },
    {
      "headline": "Closure of Chernobyl Nuclear Power Plant",
      "text": "The Chernobyl Nuclear Power Plant continued to operate until December 15, 2000, when the last functioning reactor, Reactor No. 3, was shut down.",
      "date": "2000-12-15"
    },
    {
      "headline": "Completion of the New Safe Confinement",
      "text": "In November 2016, the New Safe Confinement structure was completed and slid into place over the original sarcophagus to further contain radioactive materials and facilitate future dismantling efforts.",
      "date": "2016-11"
    }
  ]
}

