    },
    {
      "headline": "Assassination of Justice Minister Rodrigo Lara",
      "text": "On April 30, 1984, Colombian Justice Minister Rodrigo Lara Bonilla was assassinated, an act attributed to the Medellín Cartel, leading to increased government action against Escobar.",
      "date": "1984-04-30"
    },
    {
      "headline": "La Catedral Prison",
      "text": "In 1991, Escobar surrendered to Colombian authorities and was imprisoned in his self-designed prison, La Catedral, which included luxurious amenities.",
      "date": "1991"
    },
