    },
    {
      "headline": "Restoration to the Line of Succession",
      "text": "In 1544, Elizabeth was restored to the line of succession by the Third Succession Act, after her half-brother Edward VI and half-sister Mary I.",
      "date": "1544"
    },
    {
      "headline": "Accession to the Throne",
      "text": "Elizabeth became Queen of England and Ireland on November 17, 1558, following the death of her half-sister Mary I.",
      "date": "1558-11-17"
    },
    {
      "headline": "Elizabethan Religious Settlement",
      "text": "In 1559, Elizabeth established the Elizabethan Religious Settlement, which set the foundation for the Church of England.",
      "date": "1559"
    },
    {
      "headline": "Defeat of the Spanish Armada",
      "text": "In 1588, the English navy defeated the Spanish Armada, marking a significant military victory during Elizabeth's reign.",
      "date": "1588"
    },
    {
      "headline": "Execution of Mary, Queen of Scots",
      "text": "On February 8, 1587, Mary, Queen of Scots, was executed after being implicated in a plot to assassinate Elizabeth.",
      "date": "1587-02-08"
    },
    {
      "headline": "Death of Elizabeth I",
      "text": "Elizabeth I died on March 24, 1603, at Richmond Palace, ending the Tudor dynasty.",
      "date": "1603-03-24"
    }
  ]
}

