{
  "timeline": [
    {
      "headline": "Establishment of Văn Lang",
      "text": "The first known Vietnamese state, Văn Lang, was established by the Hồng Bàng dynasty around 2879 BCE.",
      "date": "-2879"
    },
    {
      "headline": "Nanyue Kingdom",
      "text": "In 207 BCE, the Nanyue Kingdom was established by Zhao Tuo, which included parts of modern-day Vietnam.",
      "date": "-0207"
    },
    {
      "headline": "Han Conquest",
      "text": "In 111 BCE, the Han dynasty of China conquered Nanyue, incorporating Vietnam into the Han Empire.",
      "date": "-0111"
    },
    {
      "headline": "Trưng Sisters' Rebellion",
      "text": "In 40 CE, the Trưng Sisters led a rebellion against Chinese rule, temporarily establishing an independent state.",
      "date": "0040"
    },
    {
      "headline": "Ngô Dynasty",
      "text": "In 939, Ngô Quyền defeated the Southern Han at the Battle of Bạch Đằng River, marking the end of Chinese domination and the beginning of the Ngô Dynasty.",
      "date": "0939"
    },
    {
      "headline": "Lý Dynasty",
      "text": "In 1009, the Lý Dynasty was established, marking a period of prosperity and cultural development in Vietnam.",
      "date": "1009"
    },
    {
      "headline": "Trần Dynasty",
      "text": "In 1225, the Trần Dynasty was established, known for repelling Mongol invasions and fostering economic growth.",
      "date": "1225"
    },
    {
      "headline": "Ming Occupation",
      "text": "In 1407, the Ming dynasty of China invaded and occupied Vietnam, leading to a period of Chinese rule.",
      "date": "1407"
    },
    {
      "headline": "Lê Lợi's Rebellion",
      "text": "In 1428, Lê Lợi successfully led a rebellion against the Ming, establishing the Lê Dynasty and restoring Vietnamese independence.",
      "date": "1428"
    },
    {
      "headline": "Nguyễn Dynasty",
      "text": "In 1802, the Nguyễn Dynasty was established, unifying Vietnam under Emperor Gia Long.",
      "date": "1802"
    },
    {
      "headline": "French Colonization",
      "text": "In 1887, Vietnam became part of French Indochina, marking the beginning of French colonial rule.",
      "date": "1887"
    },
    {
      "headline": "August Revolution",
      "text": "In August 1945, the Viet Minh led by Ho Chi Minh launched the August Revolution, declaring independence from France.",
      "date": "1945-08"
    },
    {
      "headline": "First Indochina War",
      "text": "From 1946 to 1954, Vietnam fought the First Indochina War against French colonial forces, ending with the Geneva Accords.",
      "date": "1946"
    },
    {
      "headline": "Vietnam War",
      "text": "From 1955 to 1975, the Vietnam War took place between North Vietnam, supported by communist allies, and South Vietnam, supported by the United States.",
      "date": "1955"
    },
    {
      "headline": "Fall of Saigon",
      "text": "On April 30, 1975, North Vietnamese forces captured Saigon, leading to the reunification of Vietnam under communist control.",
      "date": "1975-04-30"
    },
    {
      "headline": "Socialist Republic of Vietnam",
      "text": "On July 2, 1976, the Socialist Republic of Vietnam was officially established, unifying North and South Vietnam.",
      "date": "1976-07-02"
    },
    {
      "headline": "Doi Moi Reforms",
      "text": "In 1986, Vietnam initiated the Đổi Mới economic reforms, transitioning from a centrally planned economy to a socialist-oriented market economy.",
      "date": "1986"
    },
    {
      "headline": "Vietnam Joins WTO",
      "text": "On January 11, 2007, Vietnam became a member of the World Trade Organization (WTO), marking its integration into the global economy.",
      "date": "2007-01-11"
    }
  ]
}

