{
  "timeline": [
    {
      "headline": "Birth of Julius Caesar",
      "text": "Gaius Julius Caesar was born on July 12 or 13, 100 BCE in Rome.",
      "date": "-0100-07"
    },
    {
      "headline": "Marriage to Cornelia",
      "text": "In 84 BCE, Caesar married Cornelia, the daughter of Lucius Cornelius Cinna, an influential politician.",
      "date": "-0084"
    },
    {
      "headline": "Military Service in Asia",
      "text": "In 81 BCE, Caesar served in Asia Minor and distinguished himself in battle, earning the Civic Crown for saving a fellow soldier's life.",
      "date": "-0081"
    },
    {
      "headline": "Capture by Pirates",
      "text": "In 75 BCE, Caesar was captured by Cilician pirates and held for ransom. He later raised a naval force, captured the pirates, and had them executed.",
      "date": "-0075"
    },
    {
      "headline": "Elected Pontifex Maximus",
      "text": "In 63 BCE, Caesar was elected as Pontifex Maximus, the chief priest of the Roman state religion.",
      "date": "-0063"
    },
    {
      "headline": "First Triumvirate Formation",
      "text": "In 60 BCE, Caesar formed the First Triumvirate with Pompey and Crassus, a political alliance that dominated Roman politics.",
      "date": "-0060"
    },
    {
      "headline": "Consulship",
      "text": "In 59 BCE, Caesar was elected consul, the highest elected political office of the Roman Republic.",
      "date": "-0059"
    },
    {
      "headline": "Gallic Wars",
      "text": "From 58 BCE to 50 BCE, Caesar led military campaigns known as the Gallic Wars, expanding Roman territory to the English Channel and the Rhine.",
      "date": "-0058"
    },
    {
      "headline": "Crossing the Rubicon",
      "text": "On January 10, 49 BCE, Caesar crossed the Rubicon River with his army, igniting a civil war against Pompey and the Senate.",
      "date": "-0049-01-10"
    },
    {
      "headline": "Battle of Pharsalus",
      "text": "On August 9, 48 BCE, Caesar defeated Pompey's forces at the Battle of Pharsalus in Greece.",
      "date": "-0048-08-09"
    },
    {
      "headline": "Appointed Dictator",
      "text": "In 49 BCE, Caesar was appointed dictator, a position he held multiple times, eventually becoming dictator perpetuo (dictator in perpetuity) in 44 BCE.",
      "date": "-0049"
    },
    {
      "headline": "Assassination",
      "text": "On March 15, 44 BCE, Julius Caesar was assassinated by a group of Roman senators led by Brutus and Cassius, an event known as the Ides of March.",
      "date": "-0044-03-15"
    }
  ]
}

