{
  "timeline": [
    {
      "headline": "Founding of DuckDuckGo",
      "text": "DuckDuckGo was founded by Gabriel Weinberg in 2008. The company was established with a focus on privacy and providing a search engine that does not track its users.",
      "date": "2008"
    },
    {
      "headline": "Launch of DuckDuckGo Search Engine",
      "text": "In 2008, DuckDuckGo launched its search engine, offering users a privacy-focused alternative to other search engines by not tracking search history or personal information.",
      "date": "2008"
    },
    {
      "headline": "DuckDuckGo Gains Popularity",
      "text": "By 2011, DuckDuckGo's popularity began to grow, reaching 1 million searches per day. This was partly due to increased awareness of online privacy issues.",
      "date": "2011"
    },
    {
      "headline": "DuckDuckGo's First Major Funding",
      "text": "In 2011, DuckDuckGo received its first major funding of $3 million from Union Square Ventures, which helped the company expand its operations.",
      "date": "2011"
    },
    {
      "headline": "Introduction of !Bang Commands",
      "text": "In 2012, DuckDuckGo introduced !bang commands, allowing users to search directly on other websites from the DuckDuckGo search bar.",
      "date": "2012"
    },
    {
      "headline": "Traffic Milestone",
      "text": "In 2013, DuckDuckGo reached a significant milestone of 3 million searches per day, reflecting its growing user base.",
      "date": "2013"
    },
    {
      "headline": "Inclusion in Apple's Safari",
      "text": "In 2014, DuckDuckGo was included as a search engine option in Apple's Safari browser, increasing its visibility and accessibility to users.",
      "date": "2014"
    },
    {
      "headline": "DuckDuckGo Reaches 10 Million Searches Per Day",
      "text": "In 2015, DuckDuckGo reached 10 million searches per day, marking a significant growth in its user base and popularity.",
      "date": "2015"
    },
    {
      "headline": "Launch of Privacy Browser Extensions",
      "text": "In 2018, DuckDuckGo launched privacy-focused browser extensions and a mobile app, expanding its product offerings beyond just a search engine.",
      "date": "2018"
    },
    {
      "headline": "DuckDuckGo Reaches 30 Million Searches Per Day",
      "text": "In 2019, DuckDuckGo reached 30 million searches per day, demonstrating continued growth and user trust in its privacy-focused services.",
      "date": "2019"
    },
    {
      "headline": "DuckDuckGo's Funding Round",
      "text": "In 2021, DuckDuckGo raised $100 million in a funding round, which was used to further develop its privacy-focused products and services.",
      "date": "2021"
    },
    {
      "headline": "Launch of DuckDuckGo Web Browser",
      "text": "In 2022, DuckDuckGo launched its own web browser, further expanding its suite of privacy-focused tools and services.",
      "date": "2022"
    }
  ]
}

