{
  "timeline": [
    {
      "headline": "Invention of HTTP Cookies",
      "text": "HTTP cookies were invented by Lou Montulli, a programmer at Netscape Communications, in March 1994. The purpose was to create a mechanism for websites to store stateful information on the user's computer.",
      "date": "1994-03"
    },
    {
      "headline": "First Use of Cookies",
      "text": "The first use of cookies was for an e-commerce application for Netscape's website in 1994. This allowed the website to remember the contents of a user's shopping cart.",
      "date": "1994"
    },
    {
      "headline": "Introduction of Cookies in Netscape Navigator",
      "text": "Cookies were first implemented in Netscape Navigator 0.9 beta in October 1994, which was one of the earliest web browsers.",
      "date": "1994-10"
    },
    {
      "headline": "Public Awareness and Privacy Concerns",
      "text": "In February 1996, the Financial Times published an article that raised public awareness about cookies and privacy concerns, leading to a broader discussion about user privacy on the internet.",
      "date": "1996-02"
    },
    {
      "headline": "Standardization of Cookies",
      "text": "In 1997, the Internet Engineering Task Force (IETF) published RFC 2109, which was the first attempt to standardize the use of cookies.",
      "date": "1997"
    },
    {
      "headline": "EU Cookie Law",
      "text": "In May 2011, the European Union's ePrivacy Directive came into effect, requiring websites to obtain informed consent from users before storing cookies on their devices.",
      "date": "2011-05"
    },
    {
      "headline": "GDPR and Cookie Consent",
      "text": "On May 25, 2018, the General Data Protection Regulation (GDPR) was enforced, further strengthening the requirements for cookie consent and user data protection in the European Union.",
      "date": "2018-05-25"
    }
  ]
}

