      "headline": "Alexander the Great's Conquest",
      "text": "In 330 BCE, Alexander the Great conquered the region during his campaign against the Achaemenid Empire.",
      "date": "-0330"
    },
    {
      "headline": "Maurya Empire Control",
      "text": "The Maurya Empire, under Ashoka, controlled parts of Afghanistan around 250 BCE.",
      "date": "-0250"
    },
    {
      "headline": "Kushan Empire Establishment",
      "text": "The Kushan Empire, which included Afghanistan, was established around 30 CE.",
      "date": "0030"
