      "date": "2014-06-29"
    },
    {
      "headline": "Capture of Mosul",
      "text": "ISIS captured the city of Mosul in Iraq on June 10, 2014, marking a significant territorial gain for the group.",
      "date": "2014-06-10"
    },
    {
      "headline": "Battle of Kobani",
      "text": "The Battle of Kobani, a major conflict between ISIS and Kurdish forces, took place from September 2014 to January 2015, resulting in a Kurdish victory.",
