{
  "timeline": [
    {
      "headline": "Founding of the Polish State",
      "text": "The Polish state is traditionally dated to 966, when Mieszko I, the first ruler of the Polans, converted to Christianity and was baptized, marking the beginning of the Christianization of Poland.",
      "date": "0966"
    },
    {
      "headline": "Coronation of Bolesław I the Brave",
      "text": "In 1025, Bolesław I the Brave was crowned the first King of Poland, establishing the Kingdom of Poland.",
      "date": "1025"
    },
    {
      "headline": "Union of Krewo",
      "text": "In 1385, the Union of Krewo was signed, marking the beginning of the Polish-Lithuanian union, which eventually led to the formation of the Polish-Lithuanian Commonwealth.",
      "date": "1385"
    },
    {
      "headline": "Establishment of the Polish-Lithuanian Commonwealth",
      "text": "The Polish-Lithuanian Commonwealth was officially established in 1569 with the Union of Lublin, creating one of the largest and most populous countries in 16th- and 17th-century Europe.",
      "date": "1569"
    },
    {
      "headline": "Partitions of Poland",
      "text": "The first partition of Poland occurred in 1772, followed by the second in 1793 and the third in 1795, which resulted in the complete division and disappearance of Poland from the map of Europe.",
      "date": "1795"
    },
    {
      "headline": "Regaining Independence",
      "text": "Poland regained its independence on November 11, 1918, following World War I and the collapse of the occupying powers.",
      "date": "1918-11-11"
    },
    {
      "headline": "Invasion of Poland",
      "text": "On September 1, 1939, Nazi Germany invaded Poland, marking the beginning of World War II.",
      "date": "1939-09-01"
    },
    {
      "headline": "End of World War II and Communist Era",
      "text": "In 1945, World War II ended, and Poland fell under Soviet influence, leading to the establishment of a communist government.",
      "date": "1945"
    },
    {
      "headline": "Solidarity Movement",
      "text": "In 1980, the Solidarity movement, led by Lech Wałęsa, emerged as a major social movement advocating for workers' rights and political reform.",
      "date": "1980"
    },
    {
      "headline": "Fall of Communism",
      "text": "In 1989, Poland transitioned from a communist state to a democratic republic, marking the end of communist rule.",
      "date": "1989"
    },
    {
      "headline": "Joining the European Union",
      "text": "Poland became a member of the European Union on May 1, 2004, integrating further into European political and economic structures.",
      "date": "2004-05-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Establishment of the Swazi Kingdom",
      "text": "The Swazi Kingdom was established in the mid-18th century by King Ngwane III, who is considered the first King of modern Swaziland. The kingdom was formed as Ngwane III led his people to settle in the area now known as Eswatini.",
      "date": "1750"
    },
    {
      "headline": "British Protectorate Established",
      "text": "In 1903, after the Anglo-Boer War, Swaziland became a British protectorate. This marked the beginning of British colonial rule in the region.",
      "date": "1903"
    },
    {
      "headline": "Independence from British Rule",
      "text": "Eswatini gained independence from British rule on September 6, 1968. This marked the end of colonial rule and the beginning of self-governance for the nation.",
      "date": "1968-09-06"
    },
    {
      "headline": "King Mswati III's Reign Begins",
      "text": "King Mswati III ascended to the throne on April 25, 1986, following the death of his father, King Sobhuza II. He became one of the youngest reigning monarchs in the world.",
      "date": "1986-04-25"
    },
    {
      "headline": "Constitutional Reform",
      "text": "In 2005, a new constitution was adopted in Eswatini, which came into effect on February 8, 2006. This constitution was intended to modernize the legal framework of the country while maintaining the monarchy.",
      "date": "2006-02-08"
    },
    {
      "headline": "Name Change to Eswatini",
      "text": "On April 19, 2018, King Mswati III announced that the country's name would change from Swaziland to Eswatini. This change was made to mark the 50th anniversary of independence and to reflect the country's cultural heritage.",
      "date": "2018-04-19"
    }
  ]
}

