{
  "timeline": [
    {
      "headline": "Establishment of the Kamakura Shogunate",
      "text": "In 1185, Minamoto no Yoritomo established the Kamakura Shogunate, marking the beginning of the shogunate system in Japan. This system would last until 1868.",
      "date": "1185"
    },
    {
      "headline": "Minamoto no Yoritomo Appointed as Shogun",
      "text": "In 1192, Minamoto no Yoritomo was officially appointed as the first shogun by the Emperor, solidifying his power and the shogunate's role in Japanese governance.",
      "date": "1192"
    },
    {
      "headline": "End of the Kamakura Shogunate",
      "text": "The Kamakura Shogunate ended in 1333 when it was overthrown by Emperor Go-Daigo, leading to the brief Kenmu Restoration.",
      "date": "1333"
    },
    {
      "headline": "Establishment of the Ashikaga Shogunate",
      "text": "In 1336, Ashikaga Takauji established the Ashikaga Shogunate, also known as the Muromachi Shogunate, after defeating Emperor Go-Daigo.",
      "date": "1336"
    },
    {
      "headline": "Onin War",
      "text": "The Onin War, which lasted from 1467 to 1477, was a major civil war that led to the weakening of the Ashikaga Shogunate and the beginning of the Sengoku period.",
      "date": "1467"
    },
    {
      "headline": "End of the Ashikaga Shogunate",
      "text": "The Ashikaga Shogunate effectively ended in 1573 when Oda Nobunaga expelled the last shogun, Ashikaga Yoshiaki, from Kyoto.",
      "date": "1573"
    },
    {
      "headline": "Establishment of the Tokugawa Shogunate",
      "text": "In 1603, Tokugawa Ieyasu was appointed shogun, establishing the Tokugawa Shogunate, which would rule Japan for over 250 years.",
      "date": "1603"
    },
    {
      "headline": "Sakoku Edict",
      "text": "In 1639, the Tokugawa Shogunate issued the Sakoku Edict, enforcing Japan's policy of national isolation, which lasted until 1853.",
      "date": "1639"
    },
    {
      "headline": "End of the Tokugawa Shogunate",
      "text": "The Tokugawa Shogunate ended in 1868 with the Meiji Restoration, which restored imperial rule under Emperor Meiji.",
      "date": "1868"
    }
  ]
}

