      "date": "2010-12"
    },
    {
      "headline": "First BRICS Summit with South Africa",
      "text": "The third BRICS summit and the first with South Africa as a member was held in Sanya, China, on April 14, 2011.",
      "date": "2011-04-14"
    },
    {
      "headline": "Establishment of the New Development Bank",
      "text": "During the 6th BRICS summit in Fortaleza, Brazil, on July 15, 2014, the BRICS countries signed an agreement to establish the New Development Bank (NDB) to finance infrastructure and sustainable development projects.",
      "date": "2014-07-15"
    },
    {
      "headline": "BRICS Contingent Reserve Arrangement",
      "text": "The BRICS countries signed an agreement to create a Contingent Reserve Arrangement (CRA) during the 6th BRICS summit in 2014, aimed at providing protection against global liquidity pressures.",
      "date": "2014-07-15"
    },
    {
      "headline": "BRICS Expansion",
      "text": "In 2023, BRICS announced the inclusion of six new countries: Iran, Egypt, Ethiopia, Argentina, Saudi Arabia, and the United Arab Emirates, expanding the group's geopolitical influence.",
      "date": "2023"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Los Angeles",
      "text": "Los Angeles was founded on September 4, 1781, by Spanish governor Felipe de Neve. It was originally named 'El Pueblo de Nuestra Señora la Reina de los Ángeles de Porciúncula'.",
      "date": "1781-09-04"
    },
    {
      "headline": "Mexican Independence",
      "text": "In 1821, Los Angeles became part of Mexico following the Mexican War of Independence from Spain.",
      "date": "1821"
    },
    {
      "headline": "American Conquest",
      "text": "Los Angeles was conquered by American forces during the Mexican-American War in 1847.",
      "date": "1847"
    },
    {
      "headline": "California Statehood",
      "text": "California was admitted to the United States as the 31st state on September 9, 1850, and Los Angeles became part of the state.",
      "date": "1850-09-09"
    },
    {
      "headline": "Completion of the Transcontinental Railroad",
      "text": "In 1876, the completion of the Southern Pacific Railroad connected Los Angeles to the rest of the United States, spurring growth and development.",
      "date": "1876"
    },
    {
      "headline": "Incorporation as a City",
      "text": "Los Angeles was incorporated as a city on April 4, 1850.",
      "date": "1850-04-04"
    },
    {
      "headline": "Discovery of Oil",
      "text": "In 1892, oil was discovered in Los Angeles, leading to a boom in the local economy.",
      "date": "1892"
    },
    {
      "headline": "Opening of the Los Angeles Aqueduct",
      "text": "The Los Angeles Aqueduct was completed in 1913, providing the city with a reliable water supply and enabling further growth.",
      "date": "1913"
    },
    {
      "headline": "Hollywood Becomes Part of Los Angeles",
      "text": "In 1910, Hollywood merged with Los Angeles, eventually becoming the center of the American film industry.",
      "date": "1910"
    },
    {
      "headline": "Summer Olympics",
      "text": "Los Angeles hosted the Summer Olympics for the first time in 1932.",
      "date": "1932"
    },
    {
      "headline": "Second Summer Olympics",
      "text": "Los Angeles hosted the Summer Olympics again in 1984.",
      "date": "1984"
    },
    {
      "headline": "Rodney King Riots",
      "text": "In 1992, the city experienced major riots following the acquittal of police officers involved in the beating of Rodney King.",
      "date": "1992"
    },
    {
      "headline": "Northridge Earthquake",
      "text": "A major earthquake struck Los Angeles on January 17, 1994, causing widespread damage and loss of life.",
      "date": "1994-01-17"
    }
  ]
}

