{
  "timeline": [
    {
      "headline": "Foundation of Monaco",
      "text": "Monaco was founded as a colony by the Phocaeans of Massalia (modern-day Marseille) in 600 BCE.",
      "date": "-0600"
    },
    {
      "headline": "Monaco under Roman Control",
      "text": "Monaco became part of the Roman Empire in 122 BCE.",
      "date": "-0122"
    },
    {
      "headline": "Monaco under Genoese Control",
      "text": "In 1191, the Holy Roman Emperor Henry VI granted sovereignty over Monaco to the city of Genoa.",
      "date": "1191"
    },
    {
      "headline": "Grimaldi Family Seizes Control",
      "text": "On January 8, 1297, François Grimaldi, disguised as a monk, seized the fortress of Monaco, establishing the Grimaldi family's rule.",
      "date": "1297-01-08"
    },
    {
      "headline": "Monaco Becomes a Principality",
      "text": "In 1612, Honoré II began to style himself 'Prince' of Monaco, marking the beginning of Monaco as a principality.",
      "date": "1612"
    },
    {
      "headline": "Treaty of Peronne",
      "text": "In 1641, the Treaty of Peronne was signed, placing Monaco under the protection of France.",
      "date": "1641"
    },
    {
      "headline": "Monaco Annexed by France",
      "text": "In 1793, Monaco was annexed by France during the French Revolution.",
      "date": "1793"
    },
    {
      "headline": "Monaco Restored to Grimaldi Rule",
      "text": "In 1814, following the fall of Napoleon, the Grimaldi family was restored to the throne of Monaco.",
      "date": "1814"
    },
    {
      "headline": "Monaco's Independence Recognized",
      "text": "In 1861, the Franco-Monegasque Treaty was signed, recognizing Monaco's independence.",
      "date": "1861"
    },
    {
      "headline": "Opening of the Monte Carlo Casino",
      "text": "In 1863, the Monte Carlo Casino was opened, significantly boosting Monaco's economy.",
      "date": "1863"
    },
    {
      "headline": "Monaco's Constitution Established",
      "text": "In 1911, Monaco adopted its first constitution, limiting the powers of the prince.",
      "date": "1911"
    },
    {
      "headline": "Monaco Joins the United Nations",
      "text": "On May 28, 1993, Monaco became a member of the United Nations.",
      "date": "1993-05-28"
    },
    {
      "headline": "Monaco's New Constitution",
      "text": "In 2002, a new constitution was adopted, further democratizing the government structure.",
      "date": "2002"
    }
  ]
}

