{
  "timeline": [
    {
      "headline": "Arrival of Buddhism",
      "text": "In 247 BCE, Buddhism was introduced to Sri Lanka by Mahinda, the son of the Indian Emperor Ashoka, marking a significant cultural and religious transformation.",
      "date": "-0247"
    },
    {
      "headline": "Anuradhapura Kingdom",
      "text": "The Anuradhapura Kingdom was established around 377 BCE and became a major center of Theravada Buddhism and a significant political power in the region.",
      "date": "-0377"
    },
    {
      "headline": "Chola Invasion",
      "text": "In 993 CE, the Chola dynasty from South India invaded Sri Lanka, marking the beginning of a period of Chola rule over the island.",
      "date": "0993"
    },
    {
      "headline": "Polonnaruwa Period",
      "text": "The Polonnaruwa period began in 1070 CE when King Vijayabahu I defeated the Chola invaders and established Polonnaruwa as the capital.",
      "date": "1070"
    },
    {
      "headline": "Portuguese Arrival",
      "text": "In 1505, the Portuguese arrived in Sri Lanka, marking the beginning of European colonial influence on the island.",
      "date": "1505"
    },
    {
      "headline": "Dutch Control",
      "text": "The Dutch took control of coastal areas of Sri Lanka from the Portuguese in 1658, establishing the Dutch Ceylon.",
      "date": "1658"
    },
    {
      "headline": "British Rule",
      "text": "In 1815, the British took control of the entire island, marking the beginning of British colonial rule in Sri Lanka.",
      "date": "1815"
    },
    {
      "headline": "Independence from Britain",
      "text": "Sri Lanka gained independence from British rule on February 4, 1948, becoming a dominion within the British Commonwealth.",
      "date": "1948-02-04"
    },
    {
      "headline": "Republic of Sri Lanka",
      "text": "On May 22, 1972, Sri Lanka became a republic and changed its name from Ceylon to the Republic of Sri Lanka.",
      "date": "1972-05-22"
    },
    {
      "headline": "Civil War Begins",
      "text": "The Sri Lankan Civil War began on July 23, 1983, between the government and the Liberation Tigers of Tamil Eelam (LTTE).",
      "date": "1983-07-23"
    },
    {
      "headline": "End of Civil War",
      "text": "The Sri Lankan Civil War ended on May 18, 2009, with the defeat of the LTTE by the Sri Lankan military.",
      "date": "2009-05-18"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Recorded Observation",
      "text": "In 1802, the British began the Great Trigonometric Survey of India to determine the location and names of the world's highest mountains. Mount Everest was first identified as a peak of interest during this survey.",
      "date": "1802"
    },
    {
      "headline": "Peak XV Identified",
      "text": "In 1847, the British surveyors identified Peak XV, which would later be known as Mount Everest, as the highest point on Earth.",
      "date": "1847"
    },
    {
      "headline": "Official Naming of Mount Everest",
      "text": "In 1865, the mountain was officially named Mount Everest by the Royal Geographical Society upon a recommendation by Andrew Waugh, the British Surveyor General of India. It was named after Sir George Everest, Waugh's predecessor.",
      "date": "1865"
    },
    {
      "headline": "First Successful Ascent",
      "text": "On May 29, 1953, Sir Edmund Hillary from New Zealand and Tenzing Norgay, a Sherpa of Nepal, became the first climbers confirmed to have reached the summit of Mount Everest.",
      "date": "1953-05-29"
    },
    {
      "headline": "First American Ascent",
      "text": "On May 1, 1963, James Whittaker became the first American to reach the summit of Mount Everest.",
      "date": "1963-05-01"
    },
    {
      "headline": "First Solo Ascent",
      "text": "On August 20, 1980, Reinhold Messner made the first solo ascent of Mount Everest without supplemental oxygen.",
      "date": "1980-08-20"
    },
    {
      "headline": "First Ascent by a Woman",
      "text": "On May 16, 1975, Junko Tabei from Japan became the first woman to reach the summit of Mount Everest.",
      "date": "1975-05-16"
    },
    {
      "headline": "Deadliest Day on Everest",
      "text": "On April 25, 2015, an earthquake in Nepal triggered an avalanche on Mount Everest, resulting in the deadliest day on the mountain with 22 people killed.",
      "date": "2015-04-25"
    },
    {
      "headline": "Revised Elevation Announced",
      "text": "In December 2020, China and Nepal jointly announced a new official height for Mount Everest of 8,848.86 meters, following a survey conducted by both countries.",
      "date": "2020-12"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of the Indian National Congress",
      "text": "The Indian National Congress was founded on 28 December 1885 in Bombay. It was the first modern nationalist movement to emerge in the British Empire in Asia and Africa.",
      "date": "1885-12-28"
    },
    {
      "headline": "Adoption of Swaraj",
      "text": "In 1906, the Indian National Congress adopted the goal of Swaraj, or self-rule, as its objective.",
      "date": "1906"
    },
    {
      "headline": "Split into Moderates and Extremists",
      "text": "In 1907, the Congress split into two factions: the Moderates, led by Gopal Krishna Gokhale, and the Extremists, led by Bal Gangadhar Tilak.",
      "date": "1907"
    },
    {
      "headline": "Lucknow Pact",
      "text": "In 1916, the Congress and the All-India Muslim League signed the Lucknow Pact, agreeing to work together for Indian self-government.",
      "date": "1916"
    },
    {
      "headline": "Non-Cooperation Movement",
      "text": "In 1920, under the leadership of Mahatma Gandhi, the Congress launched the Non-Cooperation Movement against British rule.",
      "date": "1920"
    },
    {
      "headline": "Civil Disobedience Movement",
      "text": "In 1930, the Congress initiated the Civil Disobedience Movement, marked by the Salt March led by Gandhi.",
      "date": "1930"
    },
    {
      "headline": "Quit India Movement",
      "text": "In 1942, the Congress launched the Quit India Movement, demanding an end to British rule in India.",
      "date": "1942"
    },
    {
      "headline": "Indian Independence",
      "text": "On 15 August 1947, India gained independence from British rule, with the Congress playing a leading role in the freedom struggle.",
      "date": "1947-08-15"
    },
    {
      "headline": "First General Elections",
      "text": "In 1951-52, the first general elections were held in India, and the Congress won a majority, forming the government.",
      "date": "1951"
    },
    {
      "headline": "Split in the Congress Party",
      "text": "In 1969, the Congress party split into two factions: Congress (O) led by K. Kamaraj and Congress (R) led by Indira Gandhi.",
      "date": "1969"
    },
    {
      "headline": "Emergency Period",
      "text": "From 1975 to 1977, India was under a state of emergency declared by Prime Minister Indira Gandhi, during which civil liberties were suspended.",
      "date": "1975"
    },
    {
      "headline": "Return to Power",
      "text": "In 1980, the Congress party, led by Indira Gandhi, returned to power in the general elections.",
      "date": "1980"
    },
    {
      "headline": "Assassination of Indira Gandhi",
      "text": "On 31 October 1984, Prime Minister Indira Gandhi was assassinated by her bodyguards, leading to a period of political turmoil.",
      "date": "1984-10-31"
    },
