{
  "timeline": [
    {
      "headline": "First Ku Klux Klan Founded",
      "text": "The first Ku Klux Klan was founded in Pulaski, Tennessee, in December 1865 by six Confederate veterans. It was initially a social club but quickly evolved into a violent organization targeting African Americans and their allies during the Reconstruction era.",
      "date": "1865-12"
    },
    {
      "headline": "First Klan's Peak and Decline",
      "text": "The first Klan reached its peak in the late 1860s, using terror and violence to oppose Reconstruction efforts and suppress African American civil rights. By the early 1870s, federal enforcement acts and internal divisions led to its decline.",
      "date": "1870"
    },
    {
      "headline": "Second Ku Klux Klan Founded",
      "text": "The second Ku Klux Klan was founded in 1915 in Atlanta, Georgia, by William J. Simmons. Inspired by the film 'The Birth of a Nation,' this iteration expanded its targets to include immigrants, Catholics, Jews, and others.",
      "date": "1915"
    },
    {
      "headline": "Second Klan's Peak Membership",
      "text": "The second Klan reached its peak in the mid-1920s, with an estimated 4 to 5 million members across the United States. It wielded significant political influence, particularly in the Midwest and South.",
      "date": "1924"
    },
    {
      "headline": "Decline of the Second Klan",
      "text": "By the late 1920s, the second Klan began to decline due to internal scandals, financial mismanagement, and public backlash against its violent activities.",
      "date": "1929"
    },
    {
      "headline": "Third Ku Klux Klan Emerges",
      "text": "The third Ku Klux Klan emerged in the late 1940s and 1950s, in response to the Civil Rights Movement. This iteration focused on opposing desegregation and civil rights for African Americans.",
      "date": "1946"
    },
    {
      "headline": "Civil Rights Era Violence",
      "text": "During the 1960s, the third Klan was involved in numerous acts of violence and intimidation against civil rights activists, including bombings, beatings, and murders.",
      "date": "1960"
    },
    {
      "headline": "Federal Crackdown on the Klan",
      "text": "In the late 1960s and 1970s, federal investigations and prosecutions, along with civil lawsuits, significantly weakened the Klan's influence and membership.",
      "date": "1970"
    },
    {
      "headline": "Modern-Day Klan Activity",
      "text": "In the 21st century, the Ku Klux Klan remains a small, fragmented group with limited influence. It continues to promote white supremacist ideologies, though its membership is significantly reduced.",
      "date": "2000"
    }
  ]
}

{
