{
  "timeline": [
    {
      "headline": "Treaty of Paris",
      "text": "The Treaty of Paris was signed on April 18, 1951, establishing the European Coal and Steel Community (ECSC), which laid the foundation for future European integration.",
      "date": "1951-04-18"
    },
    {
      "headline": "Treaty of Rome",
      "text": "On March 25, 1957, the Treaty of Rome was signed, establishing the European Economic Community (EEC) and the European Atomic Energy Community (Euratom).",
      "date": "1957-03-25"
    },
    {
      "headline": "Merger Treaty",
      "text": "The Merger Treaty, signed on April 8, 1965, came into force on July 1, 1967, merging the executive bodies of the ECSC, EEC, and Euratom into a single Commission and a single Council.",
      "date": "1967-07-01"
    },
    {
      "headline": "Single European Act",
      "text": "The Single European Act was signed on February 17, 1986, and came into effect on July 1, 1987, aiming to create a single market within the European Community by 1992.",
      "date": "1987-07-01"
    },
    {
      "headline": "Treaty of Maastricht",
      "text": "The Treaty of Maastricht was signed on February 7, 1992, and came into force on November 1, 1993, establishing the European Union and paving the way for the creation of the euro currency.",
      "date": "1993-11-01"
    },
    {
      "headline": "Treaty of Amsterdam",
      "text": "The Treaty of Amsterdam was signed on October 2, 1997, and came into force on May 1, 1999, amending the Treaty of Maastricht and the Treaty of Rome.",
      "date": "1999-05-01"
    },
    {
      "headline": "Treaty of Nice",
      "text": "The Treaty of Nice was signed on February 26, 2001, and came into force on February 1, 2003, reforming the institutional structure of the European Union to withstand eastward expansion.",
      "date": "2003-02-01"
    },
    {
      "headline": "Enlargement of the EU",
      "text": "On May 1, 2004, the European Union underwent its largest single expansion, with ten new member states joining: Cyprus, the Czech Republic, Estonia, Hungary, Latvia, Lithuania, Malta, Poland, Slovakia, and Slovenia.",
      "date": "2004-05-01"
    },
    {
      "headline": "Treaty of Lisbon",
      "text": "The Treaty of Lisbon was signed on December 13, 2007, and came into force on December 1, 2009, amending the Maastricht Treaty and the Treaty of Rome, and enhancing the efficiency and democratic legitimacy of the Union.",
      "date": "2009-12-01"
    },
    {
      "headline": "Brexit",
      "text": "On January 31, 2020, the United Kingdom officially left the European Union, marking the first time a member state has departed from the EU.",
      "date": "2020-01-31"
    }
  ]
}

