      "text": "Mary married Francis, the Dauphin of France, on April 24, 1558, in Notre Dame Cathedral, Paris.",
      "date": "1558-04-24"
    },
    {
      "headline": "Queen Consort of France",
      "text": "Mary became Queen Consort of France on July 10, 1559, when her husband Francis became King Francis II of France.",
      "date": "1559-07-10"
    },
    {
      "headline": "Widowhood and Return to Scotland",
      "text": "Mary returned to Scotland in August 1561 after the death of her husband, King Francis II, on December 5, 1560.",
      "date": "1561-08"
    },
    {
      "headline": "Marriage to Henry Stuart, Lord Darnley",
      "text": "Mary married her cousin Henry Stuart, Lord Darnley, on July 29, 1565, at the Palace of Holyroodhouse, Edinburgh.",
      "date": "1565-07-29"
    },
    {
      "headline": "Birth of James VI and I",
      "text": "Mary gave birth to her only child, James VI of Scotland and I of England, on June 19, 1566, at Edinburgh Castle.",
      "date": "1566-06-19"
    },
    {
      "headline": "Murder of Lord Darnley",
      "text": "Mary's husband, Lord Darnley, was murdered on February 10, 1567, at Kirk o' Field, Edinburgh.",
      "date": "1567-02-10"
    },
    {
      "headline": "Marriage to James Hepburn, 4th Earl of Bothwell",
      "text": "Mary married James Hepburn, 4th Earl of Bothwell, on May 15, 1567, at Holyrood Palace.",
      "date": "1567-05-15"
    },
    {
      "headline": "Forced Abdication",
      "text": "Mary was forced to abdicate the Scottish throne in favor of her son, James VI, on July 24, 1567.",
      "date": "1567-07-24"
    },
    {
      "headline": "Imprisonment in England",
      "text": "Mary fled to England in 1568 seeking protection from her cousin, Queen Elizabeth I, but was imprisoned for 19 years.",
      "date": "1568"
    },
    {
      "headline": "Execution",
      "text": "Mary, Queen of Scots was executed on February 8, 1587, at Fotheringhay Castle, Northamptonshire, England.",
      "date": "1587-02-08"
