{
  "timeline": [
    {
      "headline": "Birth of Nelson Mandela",
      "text": "Nelson Rolihlahla Mandela was born on July 18, 1918, in Mvezo, Umtata, then part of South Africa's Cape Province.",
      "date": "1918-07-18"
    },
    {
      "headline": "Mandela Joins the African National Congress",
      "text": "In 1943, Nelson Mandela joined the African National Congress (ANC), beginning his long career in anti-apartheid activism.",
      "date": "1943"
    },
    {
      "headline": "Co-founds the ANC Youth League",
      "text": "In 1944, Mandela co-founded the African National Congress Youth League (ANCYL) with other young leaders to invigorate the ANC.",
      "date": "1944"
    },
    {
      "headline": "Defiance Campaign",
      "text": "In 1952, Mandela was appointed National Volunteer-in-Chief of the Defiance Campaign against unjust apartheid laws, which was a pivotal moment in his activism.",
      "date": "1952"
    },
    {
      "headline": "Mandela Opens Law Firm",
      "text": "In 1952, Mandela and Oliver Tambo opened the first black law firm in South Africa, Mandela and Tambo, providing affordable legal counsel to black people.",
      "date": "1952"
    },
    {
      "headline": "Arrest and Treason Trial",
      "text": "In 1956, Mandela was arrested and charged with treason, along with 155 others. The trial lasted until 1961, ending with an acquittal.",
      "date": "1956"
    },
    {
      "headline": "Formation of Umkhonto we Sizwe",
      "text": "In 1961, Mandela co-founded Umkhonto we Sizwe, the armed wing of the ANC, to carry out sabotage against government targets.",
      "date": "1961"
    },
    {
      "headline": "Rivonia Trial and Imprisonment",
      "text": "In 1962, Mandela was arrested and sentenced to five years in prison. In 1964, during the Rivonia Trial, he was sentenced to life imprisonment for sabotage and conspiracy to overthrow the government.",
      "date": "1964"
    },
    {
      "headline": "Release from Prison",
      "text": "On February 11, 1990, Nelson Mandela was released from Victor Verster Prison after 27 years of imprisonment.",
      "date": "1990-02-11"
    },
    {
      "headline": "Elected President of the ANC",
      "text": "In 1991, Mandela was elected President of the African National Congress, leading the party in negotiations to end apartheid.",
      "date": "1991"
    },
    {
      "headline": "Nobel Peace Prize",
      "text": "In 1993, Nelson Mandela was awarded the Nobel Peace Prize alongside F.W. de Klerk for their efforts to peacefully end apartheid and establish multiracial elections.",
      "date": "1993"
    },
    {
      "headline": "Elected President of South Africa",
      "text": "On May 10, 1994, Nelson Mandela was inaugurated as South Africa's first black president after the country's first fully representative democratic election.",
      "date": "1994-05-10"
    },
    {
      "headline": "Steps Down as ANC President",
      "text": "In 1997, Mandela stepped down as President of the ANC, succeeded by Thabo Mbeki.",
      "date": "1997"
    },
    {
      "headline": "Retirement from Politics",
      "text": "In 1999, Mandela retired from active politics, focusing on charitable work and conflict resolution.",
      "date": "1999"
    },
    {
      "headline": "Death of Nelson Mandela",
      "text": "Nelson Mandela passed away on December 5, 2013, at the age of 95, in Johannesburg, South Africa.",
      "date": "2013-12-05"
    }
  ]
}

