  "timeline": [
    {
      "headline": "Kazakhstan becomes part of the Russian Empire",
      "text": "In the 18th century, Kazakhstan became part of the Russian Empire. The process began with the annexation of the Junior Zhuz in 1731 and continued with the Middle Zhuz in 1822 and the Senior Zhuz in 1848.",
      "date": "1731"
    },
    {
      "headline": "Kazakhstan under Soviet rule",
      "text": "Following the Russian Revolution of 1917, Kazakhstan became part of the Soviet Union. It was initially part of the Kirghiz Autonomous Socialist Soviet Republic within the Russian Soviet Federative Socialist Republic (RSFSR) in 1920.",
      "date": "1920"
    },
    {
      "headline": "Kazakh Autonomous Socialist Soviet Republic established",
      "text": "The Kazakh Autonomous Socialist Soviet Republic was established on August 26, 1920, as part of the RSFSR.",
      "date": "1920-08-26"
    },
    {
      "headline": "Kazakh Soviet Socialist Republic",
      "text": "On December 5, 1936, the Kazakh Autonomous Socialist Soviet Republic was reorganized into the Kazakh Soviet Socialist Republic, becoming a full union republic of the Soviet Union.",
      "date": "1936-12-05"
    },
    {
      "headline": "Virgin Lands Campaign",
      "text": "In 1953, the Soviet Union launched the Virgin Lands Campaign, which aimed to increase agricultural production by cultivating previously unused land in Kazakhstan.",
      "date": "1953"
    },
    {
      "headline": "Kazakhstan declares independence",
      "text": "Kazakhstan declared its independence from the Soviet Union on December 16, 1991, becoming the last Soviet republic to do so.",
      "date": "1991-12-16"
    },
    {
      "headline": "Nursultan Nazarbayev becomes President",
      "text": "Nursultan Nazarbayev became the first President of Kazakhstan on December 1, 1991, following the country's independence.",
      "date": "1991-12-01"
    },
    {
      "headline": "Capital moved to Astana",
      "text": "In 1997, the capital of Kazakhstan was moved from Almaty to Astana (now Nur-Sultan), as part of a strategic move to develop the northern part of the country.",
      "date": "1997"
    },
    {
      "headline": "Kazakhstan joins the Eurasian Economic Union",
      "text": "On January 1, 2015, Kazakhstan became a founding member of the Eurasian Economic Union, an economic union of states located in central and northern Eurasia.",
      "date": "2015-01-01"
    }
  ]
}

