    {
      "headline": "Birth of A. P. J. Abdul Kalam",
      "text": "A. P. J. Abdul Kalam was born on October 15, 1931, in Rameswaram, Tamil Nadu, India.",
      "date": "1931-10-15"
    },
    {
      "headline": "Graduation in Physics",
      "text": "In 1954, Kalam graduated with a degree in Physics from Saint Joseph's College, Tiruchirappalli.",
      "date": "1954"
    },
    {
      "headline": "Studied Aerospace Engineering",
      "text": "In 1960, Kalam completed his studies in aerospace engineering at the Madras Institute of Technology.",
      "date": "1960"
    },
    {
      "headline": "Joined DRDO",
      "text": "In 1960, Kalam joined the Defence Research and Development Organisation (DRDO) as a scientist.",
      "date": "1960"
    },
    {
      "headline": "Joined ISRO",
      "text": "In 1969, Kalam transferred to the Indian Space Research Organisation (ISRO) where he was the project director of India's first Satellite Launch Vehicle (SLV-III).",
      "date": "1969"
    },
    {
      "headline": "First Satellite Launch Vehicle",
      "text": "In 1980, under Kalam's leadership, India's first Satellite Launch Vehicle (SLV-III) successfully deployed the Rohini satellite in near-earth orbit.",
      "date": "1980"
    },
    {
      "headline": "Integrated Guided Missile Development Program",
      "text": "In 1983, Kalam returned to DRDO to lead the Integrated Guided Missile Development Program, which resulted in the development of missiles like Agni and Prithvi.",
      "date": "1983"
    },
    {
      "headline": "Pokhran-II Nuclear Tests",
      "text": "In 1998, Kalam played a crucial role in the Pokhran-II nuclear tests, which established India as a nuclear power.",
      "date": "1998"
    },
    {
      "headline": "Elected President of India",
      "text": "On July 25, 2002, A. P. J. Abdul Kalam was sworn in as the 11th President of India.",
      "date": "2002-07-25"
    },
    {
      "headline": "End of Presidential Term",
      "text": "Kalam's term as President ended on July 25, 2007.",
      "date": "2007-07-25"
