    {
      "headline": "First Nobel Prize in Physics",
      "text": "In 1903, Marie Curie, along with Pierre Curie and Henri Becquerel, was awarded the Nobel Prize in Physics for their joint research on radiation phenomena.",
      "date": "1903"
    },
    {
      "headline": "Death of Pierre Curie",
      "text": "Pierre Curie died in a street accident on April 19, 1906.",
      "date": "1906-04-19"
    },
    {
      "headline": "First Woman Professor at the University of Paris",
      "text": "In 1906, Marie Curie became the first woman to become a professor at the University of Paris.",
      "date": "1906"
    },
    {
      "headline": "Second Nobel Prize in Chemistry",
      "text": "In 1911, Marie Curie was awarded the Nobel Prize in Chemistry for her services to the advancement of chemistry by the discovery of the elements radium and polonium, by the isolation of radium and the study of the nature and compounds of this remarkable element.",
      "date": "1911"
    },
    {
      "headline": "Establishment of the Radium Institute",
