{
  "timeline": [
    {
      "headline": "Birth of Charlie Chaplin",
      "text": "Charlie Chaplin was born on April 16, 1889, in London, England.",
      "date": "1889-04-16"
    },
    {
      "headline": "First Stage Performance",
      "text": "In 1894, at the age of five, Chaplin made his first stage appearance, filling in for his mother at a music hall performance.",
      "date": "1894"
    },
    {
      "headline": "Joined Fred Karno Company",
      "text": "In 1908, Chaplin joined the Fred Karno Company, a popular British music hall troupe, where he honed his comedic skills.",
      "date": "1908"
    },
    {
      "headline": "First Film Appearance",
      "text": "Chaplin made his first film appearance in 1914 in the short film 'Making a Living'.",
      "date": "1914"
    },
    {
      "headline": "Debut of the Tramp Character",
      "text": "In 1914, Chaplin debuted his iconic character, the Tramp, in the film 'Kid Auto Races at Venice'.",
      "date": "1914"
    },
    {
      "headline": "Founded United Artists",
      "text": "In 1919, Chaplin co-founded United Artists with Mary Pickford, Douglas Fairbanks, and D.W. Griffith to gain control over his films.",
      "date": "1919"
    },
    {
      "headline": "Release of 'The Kid'",
      "text": "In 1921, Chaplin released 'The Kid', one of his most famous films, which was a major success.",
      "date": "1921"
    },
    {
      "headline": "Release of 'The Gold Rush'",
      "text": "In 1925, Chaplin released 'The Gold Rush', which he considered the film he wanted to be remembered for.",
      "date": "1925"
    },
    {
      "headline": "Release of 'City Lights'",
      "text": "In 1931, Chaplin released 'City Lights', a silent film with a synchronized musical score, which was a critical and commercial success.",
      "date": "1931"
    },
    {
      "headline": "Release of 'Modern Times'",
      "text": "In 1936, Chaplin released 'Modern Times', a film that satirized the industrialization of the modern world.",
      "date": "1936"
    },
    {
      "headline": "Release of 'The Great Dictator'",
      "text": "In 1940, Chaplin released 'The Great Dictator', his first true sound film, which was a satirical take on Adolf Hitler.",
      "date": "1940"
    },
    {
      "headline": "Exile from the United States",
      "text": "In 1952, Chaplin was effectively exiled from the United States due to political controversies and accusations of communist sympathies.",
      "date": "1952"
    },
    {
      "headline": "Received Honorary Academy Award",
      "text": "In 1972, Chaplin returned to the United States to receive an Honorary Academy Award for his contributions to the film industry.",
      "date": "1972"
    },
    {
      "headline": "Death of Charlie Chaplin",
