{
  "timeline": [
    {
      "headline": "Pyu City-States",
      "text": "The Pyu city-states, the earliest recorded civilization in Myanmar, thrived from around 200 BCE to 900 CE. They were known for their trade and cultural exchanges with India and China.",
      "date": "-0200"
    },
    {
      "headline": "Rise of the Pagan Kingdom",
      "text": "The Pagan Kingdom, considered the first Burmese empire, was founded in 849 CE. It unified the regions that make up modern Myanmar.",
      "date": "0849"
    },
    {
      "headline": "Anawrahta's Reign",
      "text": "King Anawrahta, who reigned from 1044 to 1077, is credited with founding the Pagan Empire and introducing Theravada Buddhism to the region.",
      "date": "1044"
    },
    {
      "headline": "Fall of Pagan Kingdom",
      "text": "The Pagan Kingdom fell in 1287 due to Mongol invasions and internal strife, leading to a period of fragmentation.",
      "date": "1287"
    },
    {
      "headline": "Toungoo Dynasty",
      "text": "The Toungoo Dynasty, established in 1510, reunified Myanmar and expanded its territory, becoming one of the largest empires in Southeast Asia.",
      "date": "1510"
    },
    {
      "headline": "Konbaung Dynasty",
      "text": "The Konbaung Dynasty, founded in 1752, was the last dynasty of Myanmar. It continued to expand the empire until it faced British colonization.",
      "date": "1752"
    },
    {
      "headline": "First Anglo-Burmese War",
      "text": "The First Anglo-Burmese War took place from 1824 to 1826, resulting in the British annexation of parts of Myanmar.",
      "date": "1824"
    },
    {
      "headline": "British Annexation",
      "text": "Following the Third Anglo-Burmese War in 1885, the British fully annexed Myanmar, making it a province of British India.",
      "date": "1885"
    },
    {
      "headline": "Independence from Britain",
      "text": "Myanmar gained independence from British rule on January 4, 1948, becoming the Union of Burma.",
      "date": "1948-01-04"
    },
    {
      "headline": "Military Coup",
      "text": "On March 2, 1962, General Ne Win led a military coup, establishing a military government and initiating socialist policies.",
      "date": "1962-03-02"
    },
    {
      "headline": "8888 Uprising",
      "text": "The 8888 Uprising, a series of nationwide protests against the military government, began on August 8, 1988, leading to a violent crackdown.",
      "date": "1988-08-08"
    },
    {
      "headline": "Saffron Revolution",
      "text": "In September 2007, the Saffron Revolution occurred, led by monks protesting against the military regime's economic policies.",
      "date": "2007-09"
    },
    {
      "headline": "Transition to Civilian Government",
      "text": "In 2011, Myanmar began transitioning to a civilian government, ending decades of military rule.",
      "date": "2011"
    },
    {
      "headline": "Military Coup",
      "text": "On February 1, 2021, the military seized power in a coup, detaining elected leaders and declaring a state of emergency.",
      "date": "2021-02-01"
    }
  ]
}

