{
  "timeline": [
    {
      "headline": "Foundation of the Kingdom of Sweden",
      "text": "The Kingdom of Sweden is traditionally dated to the early Middle Ages, around the 12th century, when it emerged as a unified kingdom.",
      "date": "1100"
    },
    {
      "headline": "Kalmar Union",
      "text": "In 1397, Sweden entered into the Kalmar Union with Denmark and Norway, a series of personal unions that lasted until 1523.",
      "date": "1397"
    },
    {
      "headline": "Gustav Vasa's Reign",
      "text": "Gustav Vasa was elected king in 1523, marking the end of the Kalmar Union and the beginning of Sweden as an independent nation.",
      "date": "1523"
    },
    {
      "headline": "Thirty Years' War",
      "text": "Sweden entered the Thirty Years' War in 1630, significantly expanding its territories and influence in Europe.",
      "date": "1630"
    },
    {
      "headline": "Treaty of Westphalia",
      "text": "In 1648, the Treaty of Westphalia ended the Thirty Years' War, with Sweden gaining territories and recognition as a major European power.",
      "date": "1648"
    },
    {
      "headline": "Great Northern War",
      "text": "The Great Northern War (1700-1721) saw Sweden fighting against a coalition led by Russia, resulting in the loss of its status as a major power.",
      "date": "1700"
    },
    {
      "headline": "End of the Great Northern War",
      "text": "The Treaty of Nystad in 1721 ended the Great Northern War, with Sweden ceding significant territories to Russia.",
      "date": "1721"
    },
    {
      "headline": "Swedish Constitution of 1809",
      "text": "In 1809, a new constitution was adopted, establishing a separation of powers and a constitutional monarchy.",
      "date": "1809"
    },
    {
      "headline": "Union with Norway",
      "text": "In 1814, Sweden entered into a union with Norway, which lasted until 1905.",
      "date": "1814"
    },
    {
      "headline": "Dissolution of the Union with Norway",
      "text": "The union between Sweden and Norway was peacefully dissolved in 1905, leading to Norway's independence.",
      "date": "1905"
    },
    {
      "headline": "Sweden's Neutrality in World Wars",
      "text": "Sweden maintained a policy of neutrality during both World War I (1914-1918) and World War II (1939-1945).",
      "date": "1914"
