{
  "timeline": [
    {
      "headline": "Birth of Leonardo da Vinci",
      "text": "Leonardo di ser Piero da Vinci was born on April 15, 1452, in Vinci, Republic of Florence, which is now in Italy.",
      "date": "1452-04-15"
    },
    {
      "headline": "Apprenticeship with Andrea del Verrocchio",
      "text": "In 1466, at the age of 14, Leonardo was apprenticed to the artist Andrea del Verrocchio in Florence, where he learned a wide range of technical skills.",
      "date": "1466"
    },
    {
      "headline": "Completion of The Baptism of Christ",
      "text": "Around 1475-1476, Leonardo collaborated with Verrocchio on 'The Baptism of Christ', painting the young angel holding Jesus' robe in a manner that was so much superior to his master's that Verrocchio reportedly resolved never to paint again.",
      "date": "1476"
    },
    {
      "headline": "Leonardo's First Independent Commission",
      "text": "In 1478, Leonardo received his first independent commission to paint an altarpiece for the Chapel of St. Bernard in the Palazzo Vecchio, Florence.",
      "date": "1478"
    },
    {
      "headline": "The Adoration of the Magi",
      "text": "In 1481, Leonardo began work on 'The Adoration of the Magi' for the Monks of San Donato a Scopeto, but he left it unfinished when he moved to Milan.",
      "date": "1481"
    },
    {
      "headline": "Move to Milan",
      "text": "In 1482, Leonardo moved to Milan to work in the service of Ludovico Sforza, the Duke of Milan, where he worked on various projects including painting, sculpture, and engineering.",
      "date": "1482"
    },
    {
      "headline": "Completion of The Last Supper",
      "text": "Between 1495 and 1498, Leonardo painted 'The Last Supper' in the Convent of Santa Maria delle Grazie in Milan, which became one of his most famous works.",
      "date": "1498"
    },
    {
      "headline": "Return to Florence",
      "text": "In 1500, after the fall of Ludovico Sforza, Leonardo returned to Florence where he was received as a renowned artist.",
      "date": "1500"
    },
    {
      "headline": "Mona Lisa",
      "text": "Between 1503 and 1506, Leonardo worked on the 'Mona Lisa', which is now one of the most famous paintings in the world.",
      "date": "1506"
    },
    {
      "headline": "Move to Rome",
      "text": "In 1513, Leonardo moved to Rome, where he worked for the Pope and continued his scientific studies.",
      "date": "1513"
    },
    {
      "headline": "Move to France",
      "text": "In 1516, Leonardo moved to France at the invitation of King Francis I, who offered him the title of 'Premier Painter and Engineer and Architect to the King'.",
      "date": "1516"
    },
    {
      "headline": "Death of Leonardo da Vinci",
      "text": "Leonardo da Vinci died on May 2, 1519, at the age of 67, in Amboise, Kingdom of France.",
      "date": "1519-05-02"
    }
  ]
}

