{
  "timeline": [
    {
      "headline": "Formation of Nok Culture",
      "text": "The Nok culture, one of the earliest known civilizations in Nigeria, emerged around 1500 BCE. It is known for its terracotta sculptures and advanced ironworking.",
      "date": "-1500"
    },
    {
      "headline": "Rise of the Hausa City-States",
      "text": "By the 7th century CE, the Hausa city-states began to emerge in northern Nigeria, becoming important centers of trade and culture.",
      "date": "0700"
    },
    {
      "headline": "Kanem-Bornu Empire",
      "text": "The Kanem-Bornu Empire, a powerful African state, dominated the region from the 9th century until the 19th century.",
      "date": "0900"
    },
    {
      "headline": "Oyo Empire",
      "text": "The Oyo Empire, a Yoruba state, rose to prominence in the 14th century, becoming a major political and military power in West Africa.",
      "date": "1300"
    },
    {
      "headline": "Fulani Jihad",
      "text": "In 1804, the Fulani Jihad led by Usman dan Fodio began, resulting in the establishment of the Sokoto Caliphate, which became a major Islamic state in the region.",
      "date": "1804"
    },
    {
      "headline": "British Colonial Rule",
      "text": "In 1901, Nigeria became a British protectorate, and in 1914, the Northern and Southern protectorates were amalgamated to form the Colony and Protectorate of Nigeria.",
      "date": "1914"
    },
    {
      "headline": "Independence from Britain",
      "text": "Nigeria gained independence from Britain on October 1, 1960, becoming a sovereign nation.",
      "date": "1960-10-01"
    },
    {
      "headline": "First Republic",
      "text": "The First Republic was established in 1963 when Nigeria became a republic with Nnamdi Azikiwe as its first President.",
      "date": "1963"
    },
    {
      "headline": "Nigerian Civil War",
      "text": "The Nigerian Civil War, also known as the Biafran War, occurred from July 6, 1967, to January 15, 1970, following the secession of the southeastern region of Nigeria as the Republic of Biafra.",
      "date": "1967-07-06"
    },
    {
      "headline": "Second Republic",
      "text": "The Second Republic was established in 1979, following a new constitution and the election of Shehu Shagari as President.",
      "date": "1979"
    },
    {
      "headline": "Return to Civilian Rule",
      "text": "Nigeria returned to civilian rule on May 29, 1999, with the election of Olusegun Obasanjo as President, marking the beginning of the Fourth Republic.",
      "date": "1999-05-29"
    }
  ]
}

