{
  "timeline": [
    {
      "headline": "First Serbian State",
      "text": "The first Serbian state, known as the Principality of Serbia, was established in the early 7th century.",
      "date": "0600"
    },
    {
      "headline": "Formation of the Serbian Kingdom",
      "text": "In 1217, Stefan Nemanjić was crowned as the first King of Serbia, marking the formation of the Serbian Kingdom.",
      "date": "1217"
    },
    {
      "headline": "Establishment of the Serbian Empire",
      "text": "In 1346, Stefan Dušan proclaimed himself Emperor, establishing the Serbian Empire.",
      "date": "1346"
    },
    {
      "headline": "Battle of Kosovo",
      "text": "On June 28, 1389, the Battle of Kosovo took place between the Serbian army and the Ottoman Empire, resulting in significant losses for both sides.",
      "date": "1389-06-28"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "In 1459, the Ottoman Empire conquered the Serbian Despotate, bringing Serbia under Ottoman rule.",
      "date": "1459"
    },
    {
      "headline": "First Serbian Uprising",
      "text": "The First Serbian Uprising against Ottoman rule began in 1804, led by Karađorđe Petrović.",
      "date": "1804"
    },
    {
      "headline": "Second Serbian Uprising",
      "text": "In 1815, the Second Serbian Uprising was led by Miloš Obrenović, leading to the establishment of the semi-independent Principality of Serbia.",
      "date": "1815"
    },
    {
      "headline": "Recognition of Serbian Independence",
      "text": "In 1878, the Congress of Berlin recognized Serbia as an independent state.",
      "date": "1878"
    },
    {
      "headline": "Formation of the Kingdom of Serbs, Croats, and Slovenes",
      "text": "On December 1, 1918, Serbia became part of the Kingdom of Serbs, Croats, and Slovenes, later known as Yugoslavia.",
      "date": "1918-12-01"
    },
    {
      "headline": "Axis Invasion of Yugoslavia",
      "text": "In April 1941, Axis powers invaded Yugoslavia, leading to its occupation during World War II.",
      "date": "1941-04"
    },
    {
      "headline": "Formation of Socialist Federal Republic of Yugoslavia",
      "text": "In 1945, after World War II, the Socialist Federal Republic of Yugoslavia was established, with Serbia as one of its republics.",
      "date": "1945"
    },
    {
      "headline": "Breakup of Yugoslavia",
      "text": "In the early 1990s, Yugoslavia began to break apart, leading to the independence of several republics.",
      "date": "1991"
    },
    {
      "headline": "Federal Republic of Yugoslavia",
      "text": "In 1992, Serbia and Montenegro formed the Federal Republic of Yugoslavia after the breakup of the Socialist Federal Republic of Yugoslavia.",
      "date": "1992"
    },
    {
      "headline": "Serbia and Montenegro",
      "text": "In 2003, the Federal Republic of Yugoslavia was reconstituted as the State Union of Serbia and Montenegro.",
      "date": "2003"
    },
    {
      "headline": "Independence of Montenegro",
      "text": "On June 3, 2006, Montenegro declared independence, leading to the dissolution of the State Union of Serbia and Montenegro.",
      "date": "2006-06-03"
    },
    {
      "headline": "Declaration of Independence by Kosovo",
      "text": "On February 17, 2008, Kosovo declared independence from Serbia, a move not recognized by Serbia.",
      "date": "2008-02-17"
    }
  ]
}

