{
  "timeline": [
    {
      "headline": "Unification of Upper and Lower Egypt",
      "text": "Around 3100 BCE, King Narmer (also known as Menes) is traditionally credited with uniting Upper and Lower Egypt, marking the beginning of the First Dynasty and the start of the Early Dynastic Period.",
      "date": "-3100"
    },
    {
      "headline": "Construction of the Great Pyramid of Giza",
      "text": "The Great Pyramid of Giza was constructed during the reign of Pharaoh Khufu (Cheops) around 2580–2560 BCE. It is the largest of the three pyramids on the Giza plateau and one of the Seven Wonders of the Ancient World.",
      "date": "-2580"
    },
    {
      "headline": "Reign of Pharaoh Hatshepsut",
      "text": "Hatshepsut, one of the few female pharaohs, ruled Egypt from approximately 1479 to 1458 BCE. Her reign was marked by significant building projects and trade expeditions.",
      "date": "-1479"
    },
    {
      "headline": "Reign of Pharaoh Akhenaten",
      "text": "Akhenaten ruled from 1353 to 1336 BCE and is known for abandoning traditional Egyptian polytheism and introducing worship centered on the Aten, the sun disk.",
      "date": "-1353"
    },
    {
      "headline": "Reign of Pharaoh Tutankhamun",
      "text": "Tutankhamun, also known as King Tut, reigned from 1332 to 1323 BCE. His nearly intact tomb was discovered in 1922, sparking worldwide interest in ancient Egypt.",
      "date": "-1332"
    },
    {
      "headline": "Battle of Kadesh",
      "text": "In 1274 BCE, the Battle of Kadesh took place between the forces of the Egyptian Empire under Ramesses II and the Hittite Empire. It is one of the earliest battles in recorded history for which details of tactics and formations are known.",
      "date": "-1274"
    },
    {
      "headline": "Reign of Pharaoh Ramesses II",
      "text": "Ramesses II, also known as Ramesses the Great, reigned from 1279 to 1213 BCE. He is often regarded as the most powerful and celebrated pharaoh of the New Kingdom.",
      "date": "-1279"
    },
    {
      "headline": "Conquest by Alexander the Great",
      "text": "In 332 BCE, Alexander the Great conquered Egypt, marking the end of Persian rule and the beginning of the Hellenistic period.",
      "date": "-0332"
    },
    {
      "headline": "Founding of Alexandria",
      "text": "In 331 BCE, Alexander the Great founded the city of Alexandria, which became a major center of Hellenistic culture and trade.",
      "date": "-0331"
    },
    {
      "headline": "Cleopatra VII's Reign",
      "text": "Cleopatra VII ruled from 51 to 30 BCE. She was the last active ruler of the Ptolemaic Kingdom of Egypt, known for her relationships with Roman leaders Julius Caesar and Mark Antony.",
      "date": "-0051"
    },
    {
      "headline": "Egypt becomes a Roman Province",
      "text": "In 30 BCE, following the defeat of Mark Antony and Cleopatra at the Battle of Actium, Egypt became a province of the Roman Empire.",
      "date": "-0030"
    },
    {
      "headline": "Arab Conquest of Egypt",
      "text": "In 641 CE, the Arab forces led by Amr ibn al-As conquered Egypt, marking the beginning of Islamic rule.",
      "date": "0641"
    },
    {
      "headline": "Construction of the Al-Azhar Mosque",
      "text": "The Al-Azhar Mosque was founded in 970 CE in Cairo by the Fatimid Caliphate. It became a center of Islamic learning and is one of the oldest universities in the world.",
      "date": "0970"
    },
    {
      "headline": "Napoleon's Campaign in Egypt",
      "text": "In 1798, Napoleon Bonaparte led a French campaign in Egypt, which marked the beginning of modern European interest in Egyptology.",
      "date": "1798"
    },
    {
      "headline": "British Occupation of Egypt",
      "text": "In 1882, British forces occupied Egypt, establishing control over the country while it remained nominally part of the Ottoman Empire.",
      "date": "1882"
    },
    {
      "headline": "Egyptian Revolution of 1952",
      "text": "The Egyptian Revolution of 1952, led by the Free Officers Movement, resulted in the overthrow of King Farouk and the establishment of a republic.",
      "date": "1952"
    },
    {
      "headline": "Suez Crisis",
      "text": "In 1956, Egypt nationalized the Suez Canal, leading to a military intervention by Israel, the United Kingdom, and France. The crisis ended with a United Nations-brokered ceasefire.",
      "date": "1956"
    },
    {
      "headline": "Camp David Accords",
      "text": "In 1978, Egypt and Israel signed the Camp David Accords, leading to the Egypt-Israel Peace Treaty in 1979. Egypt became the first Arab country to officially recognize Israel.",
      "date": "1978"
    },
    {
      "headline": "Egyptian Revolution of 2011",
      "text": "In 2011, mass protests led to the resignation of President Hosni Mubarak, ending his 30-year rule and marking a significant moment in the Arab Spring.",
      "date": "2011"
    }
  ]
}

