{
  "timeline": [
    {
      "headline": "Observation of Solar Flare",
      "text": "On September 1, 1859, British astronomer Richard Carrington observed a massive solar flare. This was the first time a solar flare was observed and recorded.",
      "date": "1859-09-01"
    },
    {
      "headline": "Peak of the Geomagnetic Storm",
      "text": "The geomagnetic storm, known as the Carrington Event, peaked on September 1–2, 1859. It was the most intense geomagnetic storm in recorded history.",
      "date": "1859-09-02"
    },
    {
      "headline": "Global Auroral Displays",
      "text": "During the peak of the storm on September 1–2, 1859, strong auroral displays were reported globally, even at latitudes much closer to the equator than usual.",
      "date": "1859-09-02"
    },
    {
      "headline": "Impact on Telegraph Systems",
      "text": "The geomagnetic storm caused sparking and even fires in telegraph stations. Telegraph systems all over Europe and North America failed, in some cases giving telegraph operators electric shocks.",
      "date": "1859-09-02"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Helen Keller",
      "text": "Helen Adams Keller was born on June 27, 1880, in Tuscumbia, Alabama.",
      "date": "1880-06-27"
    },
    {
      "headline": "Illness and Loss of Sight and Hearing",
      "text": "In February 1882, at 19 months old, Helen Keller contracted an illness, possibly scarlet fever or meningitis, which left her both deaf and blind.",
      "date": "1882-02"
    },
    {
      "headline": "Meeting Anne Sullivan",
      "text": "On March 3, 1887, Anne Sullivan arrived at the Keller home to become Helen's teacher, marking the beginning of a 49-year-long relationship.",
      "date": "1887-03-03"
    },
    {
      "headline": "Breakthrough in Communication",
      "text": "In April 1887, Helen Keller learned to communicate through the use of sign language, starting with the word 'water' at a water pump.",
      "date": "1887-04"
    },
    {
      "headline": "Education at Perkins Institute",
      "text": "In 1888, Helen Keller began her formal education at the Perkins Institute for the Blind in Boston.",
      "date": "1888"
    },
    {
      "headline": "Enrollment at Radcliffe College",
      "text": "In 1900, Helen Keller was admitted to Radcliffe College of Harvard University.",
      "date": "1900"
    },
    {
      "headline": "Graduation from Radcliffe College",
      "text": "In 1904, Helen Keller graduated from Radcliffe College, becoming the first deafblind person to earn a Bachelor of Arts degree.",
      "date": "1904"
    },
    {
      "headline": "Publication of 'The Story of My Life'",
      "text": "In 1903, Helen Keller published her autobiography, 'The Story of My Life', which detailed her early life, education, and experiences with Anne Sullivan.",
      "date": "1903"
    },
    {
      "headline": "Co-founding the ACLU",
      "text": "In 1920, Helen Keller was a founding member of the American Civil Liberties Union (ACLU), advocating for civil rights.",
      "date": "1920"
    },
    {
      "headline": "Death of Anne Sullivan",
      "text": "Anne Sullivan, Helen Keller's teacher and companion, passed away on October 20, 1936.",
      "date": "1936-10-20"
    },
    {
      "headline": "Death of Helen Keller",
      "text": "Helen Keller passed away on June 1, 1968, at her home in Easton, Connecticut.",
      "date": "1968-06-01"
    }
  ]
}

