{
  "timeline": [
    {
      "headline": "Foundation of the County of Portugal",
      "text": "The County of Portugal was established as a semi-independent county in the Kingdom of León in 868.",
      "date": "0868"
    },
    {
      "headline": "Battle of São Mamede",
      "text": "On June 24, 1128, Afonso I defeated his mother, Teresa of León, at the Battle of São Mamede, securing his control over the County of Portugal.",
      "date": "1128-06-24"
    },
    {
      "headline": "Proclamation of the Kingdom of Portugal",
      "text": "Afonso I declared himself King of Portugal in 1139 after his victory at the Battle of Ourique.",
      "date": "1139"
    },
    {
      "headline": "Recognition of Portuguese Independence",
      "text": "The Treaty of Zamora was signed on October 5, 1143, recognizing Portugal as an independent kingdom.",
      "date": "1143-10-05"
    },
    {
      "headline": "Treaty of Alcañices",
      "text": "In 1297, the Treaty of Alcañices was signed, establishing the borders between Portugal and the Kingdom of León.",
      "date": "1297"
    },
    {
      "headline": "Beginning of the Age of Discovery",
      "text": "In the early 15th century, Prince Henry the Navigator began sponsoring exploratory voyages along the West African coast.",
      "date": "1415"
    },
    {
      "headline": "Discovery of Brazil",
      "text": "On April 22, 1500, Pedro Álvares Cabral discovered Brazil, claiming it for Portugal.",
      "date": "1500-04-22"
    },
    {
      "headline": "Union of the Crowns",
      "text": "In 1580, the Iberian Union was formed when Philip II of Spain also became Philip I of Portugal, uniting the two crowns.",
      "date": "1580"
    },
    {
      "headline": "Restoration of Independence",
      "text": "On December 1, 1640, Portugal regained its independence from Spain, ending the Iberian Union.",
      "date": "1640-12-01"
    },
    {
      "headline": "Lisbon Earthquake",
      "text": "On November 1, 1755, a massive earthquake struck Lisbon, causing widespread destruction and loss of life.",
      "date": "1755-11-01"
    },
    {
      "headline": "Portuguese Republic Established",
      "text": "On October 5, 1910, the Portuguese monarchy was overthrown, and the First Portuguese Republic was established.",
      "date": "1910-10-05"
    },
    {
      "headline": "Carnation Revolution",
      "text": "On April 25, 1974, a military coup known as the Carnation Revolution ended the Estado Novo regime, leading to democratic reforms.",
      "date": "1974-04-25"
    },
    {
      "headline": "Portugal Joins the European Union",
      "text": "On January 1, 1986, Portugal became a member of the European Economic Community, now the European Union.",
      "date": "1986-01-01"
    }
  ]
}

