{
  "timeline": [
    {
      "headline": "Ottoman Rule",
      "text": "The Gaza Strip was part of the Ottoman Empire from 1517 until the end of World War I in 1917.",
      "date": "1517"
    },
    {
      "headline": "British Mandate",
      "text": "Following the defeat of the Ottoman Empire in World War I, the Gaza Strip came under British control as part of the British Mandate for Palestine from 1920 to 1948.",
      "date": "1920"
    },
    {
      "headline": "1948 Arab-Israeli War",
      "text": "During the 1948 Arab-Israeli War, the Gaza Strip was occupied by Egypt. This occupation lasted until 1967.",
      "date": "1948"
    },
    {
      "headline": "Six-Day War",
      "text": "In June 1967, during the Six-Day War, Israel captured the Gaza Strip from Egypt and began its military occupation.",
      "date": "1967-06"
    },
    {
      "headline": "Oslo Accords",
      "text": "The Oslo Accords, signed in 1993, led to the establishment of the Palestinian Authority and partial self-governance in the Gaza Strip.",
      "date": "1993"
    },
    {
      "headline": "Israeli Disengagement",
      "text": "In 2005, Israel unilaterally disengaged from the Gaza Strip, withdrawing its military forces and dismantling its settlements.",
      "date": "2005"
    },
    {
      "headline": "Hamas Takeover",
      "text": "In June 2007, Hamas took control of the Gaza Strip after a conflict with Fatah, leading to a political and territorial split with the West Bank.",
      "date": "2007-06"
    },
    {
      "headline": "Gaza War (Operation Cast Lead)",
      "text": "From December 2008 to January 2009, Israel launched a military operation in the Gaza Strip, known as Operation Cast Lead, in response to rocket fire from Gaza.",
      "date": "2008-12"
    },
    {
      "headline": "Gaza War (Operation Protective Edge)",
      "text": "In July and August 2014, another major conflict occurred between Israel and Hamas in the Gaza Strip, known as Operation Protective Edge.",
      "date": "2014-07"
    },
    {
      "headline": "Great March of Return",
      "text": "Beginning in March 2018, Palestinians in the Gaza Strip organized weekly protests along the Gaza-Israel border, known as the Great March of Return.",
      "date": "2018-03"
    }
  ]
}

