{
  "timeline": [
    {
      "headline": "Outbreak of the Korean War",
      "text": "The Korean War began on June 25, 1950, when North Korean forces crossed the 38th parallel and invaded South Korea.",
      "date": "1950-06-25"
    },
    {
      "headline": "United Nations Security Council Resolution 82",
      "text": "On June 27, 1950, the United Nations Security Council passed Resolution 82, calling for North Korea to cease hostilities and withdraw to the 38th parallel.",
      "date": "1950-06-27"
    },
    {
      "headline": "Battle of Osan",
      "text": "The first significant engagement between American and North Korean forces occurred on July 5, 1950, at the Battle of Osan.",
      "date": "1950-07-05"
    },
    {
      "headline": "Incheon Landing",
      "text": "On September 15, 1950, United Nations forces led by General Douglas MacArthur launched a successful amphibious assault at Incheon, turning the tide of the war.",
      "date": "1950-09-15"
    },
    {
      "headline": "Recapture of Seoul",
      "text": "Seoul was recaptured by United Nations forces on September 28, 1950, following the successful Incheon Landing.",
      "date": "1950-09-28"
    },
    {
      "headline": "Chinese Intervention",
      "text": "In late October 1950, Chinese forces entered the Korean War, launching a series of offensives against United Nations forces.",
      "date": "1950-10"
    },
    {
      "headline": "Battle of Chosin Reservoir",
      "text": "From November 27 to December 13, 1950, United Nations forces, primarily U.S. Marines, fought a brutal battle against Chinese forces at the Chosin Reservoir.",
      "date": "1950-11-27"
    },
    {
      "headline": "Stalemate and Armistice Talks",
      "text": "By mid-1951, the war had reached a stalemate, and armistice talks began in July 1951, continuing intermittently for two years.",
      "date": "1951-07"
    },
    {
      "headline": "Signing of the Korean Armistice Agreement",
      "text": "The Korean Armistice Agreement was signed on July 27, 1953, effectively ending hostilities but not officially ending the war.",
      "date": "1953-07-27"
    }
  ]
}

