    {
      "headline": "Unification of Denmark",
      "text": "The unification of Denmark is traditionally dated to the reign of King Gorm the Old, who ruled from around 936 to 958. He is considered the first historically recognized king of Denmark.",
      "date": "0936"
    },
    {
      "headline": "Christianization of Denmark",
      "text": "Harald Bluetooth, who ruled from approximately 958 to 986, is credited with the Christianization of Denmark. He erected the Jelling stones, which are considered Denmark's 'birth certificate'.",
      "date": "0965"
    },
    {
      "headline": "Kalmar Union",
      "text": "The Kalmar Union was formed in 1397, uniting the kingdoms of Denmark, Norway, and Sweden under a single monarch. This union lasted until 1523.",
      "date": "1397"
    },
    {
      "headline": "Reformation in Denmark",
      "text": "In 1536, Denmark officially became a Lutheran state, marking the end of Catholicism as the state religion.",
      "date": "1536"
    },
    {
      "headline": "Treaty of Roskilde",
      "text": "The Treaty of Roskilde was signed in 1658, ceding significant territories to Sweden, including Scania, Halland, and Blekinge.",
      "date": "1658"
    },
    {
      "headline": "Constitution of Denmark",
      "text": "The first Danish constitution was signed on June 5, 1849, establishing a constitutional monarchy and a parliamentary system.",
      "date": "1849-06-05"
    },
    {
      "headline": "Second Schleswig War",
      "text": "The Second Schleswig War occurred in 1864, resulting in Denmark's defeat and the loss of the duchies of Schleswig, Holstein, and Lauenburg to Prussia and Austria.",
      "date": "1864"
    },
    {
      "headline": "Reunification of Southern Jutland",
      "text": "Following a plebiscite, Southern Jutland was reunited with Denmark in 1920 after being lost in the Second Schleswig War.",
      "date": "1920"
    },
    {
      "headline": "Occupation during World War II",
      "text": "Denmark was occupied by Nazi Germany from April 9, 1940, until May 5, 1945, during World War II.",
      "date": "1940-04-09"
    },
    {
      "headline": "Joining the European Economic Community",
      "text": "Denmark joined the European Economic Community, now the European Union, on January 1, 1973.",
      "date": "1973-01-01"
    },
    {
      "headline": "Greenland's Home Rule",
      "text": "Greenland was granted home rule on May 1, 1979, allowing it greater autonomy within the Kingdom of Denmark.",
      "date": "1979-05-01"
    },
    {
      "headline": "Faroe Islands' Home Rule",
      "text": "The Faroe Islands were granted home rule on April 1, 1948, allowing them greater autonomy within the Kingdom of Denmark.",
      "date": "1948-04-01"
    }
  ]
}

