{
  "timeline": [
    {
      "headline": "Minoan Civilization",
      "text": "The Minoan civilization, considered the first advanced civilization in Europe, flourished on the island of Crete from approximately 3000 BCE to 1450 BCE.",
      "date": "-3000"
    },
    {
      "headline": "Mycenaean Civilization",
      "text": "The Mycenaean civilization developed on mainland Greece from around 1600 BCE to 1100 BCE, known for its palatial states, art, and writing system.",
      "date": "-1600"
    },
    {
      "headline": "Greek Dark Ages",
      "text": "Following the collapse of the Mycenaean civilization, Greece entered a period known as the Greek Dark Ages, lasting from about 1100 BCE to 800 BCE.",
      "date": "-1100"
    },
    {
      "headline": "Archaic Period",
      "text": "The Archaic period in Greece, from approximately 800 BCE to 480 BCE, saw the rise of city-states (poleis) and the development of Greek culture and politics.",
      "date": "-0800"
    },
    {
      "headline": "Classical Greece",
      "text": "The Classical period, from 480 BCE to 323 BCE, was marked by great political and cultural achievements, including the rise of Athens and the development of democracy.",
      "date": "-0480"
    },
    {
      "headline": "Peloponnesian War",
      "text": "The Peloponnesian War, a conflict between Athens and Sparta, lasted from 431 BCE to 404 BCE, ending with the defeat of Athens.",
      "date": "-0431"
    },
    {
      "headline": "Hellenistic Period",
      "text": "Following the death of Alexander the Great in 323 BCE, the Hellenistic period began, characterized by the spread of Greek culture across the Mediterranean and Near East.",
      "date": "-0323"
    },
    {
      "headline": "Roman Greece",
      "text": "Greece became part of the Roman Republic in 146 BCE after the Roman conquest, leading to a period of Roman influence and integration.",
      "date": "-0146"
    },
    {
      "headline": "Byzantine Greece",
      "text": "After the division of the Roman Empire, Greece became part of the Byzantine Empire, lasting from approximately 330 CE to 1453 CE.",
      "date": "0330"
    },
    {
      "headline": "Ottoman Greece",
      "text": "Greece fell under Ottoman rule in the mid-15th century, following the fall of Constantinople in 1453, and remained so until the 19th century.",
      "date": "1453"
    },
    {
      "headline": "Greek War of Independence",
      "text": "The Greek War of Independence began in 1821 and resulted in the establishment of an independent Greek state in 1830.",
      "date": "1821"
    },
    {
      "headline": "Establishment of the Kingdom of Greece",
      "text": "The Kingdom of Greece was formally established in 1832, with Otto of Bavaria as its first king.",
      "date": "1832"
    },
    {
      "headline": "Balkan Wars",
      "text": "Greece participated in the Balkan Wars from 1912 to 1913, expanding its territory significantly.",
      "date": "1912"
    },
    {
      "headline": "World War I and the Asia Minor Catastrophe",
      "text": "Greece joined the Allies in World War I in 1917. The subsequent Greco-Turkish War (1919-1922) ended in defeat for Greece, leading to the Asia Minor Catastrophe.",
      "date": "1917"
    },
    {
      "headline": "World War II and Axis Occupation",
      "text": "Greece was invaded by Axis powers in 1941 and occupied until 1944, during which time a significant resistance movement developed.",
      "date": "1941"
    },
    {
      "headline": "Greek Civil War",
      "text": "The Greek Civil War took place from 1946 to 1949 between government forces and communist insurgents, ending in a government victory.",
      "date": "1946"
    },
    {
      "headline": "Military Junta",
      "text": "A military junta ruled Greece from 1967 to 1974, a period known as the Regime of the Colonels.",
      "date": "1967"
    },
    {
      "headline": "Restoration of Democracy",
      "text": "Democracy was restored in Greece in 1974 following the fall of the military junta.",
      "date": "1974"
    },
    {
      "headline": "Greece Joins the European Union",
      "text": "Greece became a member of the European Union on January 1, 1981.",
      "date": "1981-01-01"
    },
    {
      "headline": "Eurozone Membership",
      "text": "Greece adopted the euro as its currency on January 1, 2001, becoming a member of the Eurozone.",
      "date": "2001-01-01"
    },
    {
      "headline": "Greek Financial Crisis",
      "text": "Greece faced a severe financial crisis starting in 2009, leading to austerity measures and international bailouts.",
      "date": "2009"
    }
  ]
}

