    {
      "headline": "Tesla Develops the Induction Motor",
      "text": "In 1887, Tesla developed the induction motor and began working on alternating current (AC) systems.",
      "date": "1887"
    },
    {
      "headline": "Tesla Patents the Polyphase AC System",
      "text": "In 1888, Tesla patented his polyphase alternating current system, which included the induction motor and transformer.",
      "date": "1888"
    },
    {
      "headline": "Tesla Sells Patents to George Westinghouse",
      "text": "In 1888, Tesla sold his alternating current patents to George Westinghouse, which led to the widespread adoption of AC power.",
      "date": "1888"
