    {
      "headline": "Tesla Opens Laboratory in New York",
      "text": "In 1899, Tesla opened a laboratory in Colorado Springs, where he conducted experiments with high-voltage electricity and wireless transmission.",
      "date": "1899"
    },
    {
      "headline": "Tesla's Wardenclyffe Tower Project",
      "text": "In 1901, Tesla began construction of the Wardenclyffe Tower on Long Island, New York, intended for wireless transmission of electricity.",
