      "headline": "Creation of the Mona Lisa",
      "text": "Leonardo da Vinci began painting the Mona Lisa in Florence, Italy. The work is believed to have been started in 1503.",
      "date": "1503"
    },
    {
      "headline": "Completion of the Mona Lisa",
      "text": "Leonardo da Vinci completed the Mona Lisa, although some art historians believe he continued to work on it until 1517.",
      "date": "1517"
    },
    {
      "headline": "Acquisition by King Francis I of France",
      "text": "The Mona Lisa was acquired by King Francis I of France and placed in the Palace of Fontainebleau. This occurred after Leonardo's death in 1519.",
      "date": "1519"
    },
    {
      "headline": "Relocation to the Louvre Museum",
      "text": "The Mona Lisa was moved to the Louvre Museum in Paris after the French Revolution, where it remains today.",
      "date": "1797"
    },
    {
      "headline": "Theft of the Mona Lisa",
      "text": "The Mona Lisa was stolen from the Louvre on August 21, 1911, by Italian handyman Vincenzo Peruggia, who believed the painting should be returned to Italy.",
      "date": "1911-08-21"
    },
    {
      "headline": "Recovery of the Mona Lisa",
      "text": "The Mona Lisa was recovered in Florence, Italy, in December 1913, and returned to the Louvre Museum.",
      "date": "1913-12"
    },
    {
      "headline": "Vandalism Incident",
      "text": "The Mona Lisa was damaged by a vandal who threw acid at it in 1956, and later that year, another vandal threw a rock at it, damaging the painting.",
      "date": "1956"
    },
    {
      "headline": "Protective Measures",
      "text": "In response to vandalism, the Mona Lisa was placed behind bulletproof glass to protect it from further damage.",
      "date": "1956"
    }
  ]
}

