    {
      "headline": "Birth of Malcolm X",
      "text": "Malcolm X was born on May 19, 1925, in Omaha, Nebraska, as Malcolm Little.",
      "date": "1925-05-19"
    },
    {
      "headline": "Father's Death",
      "text": "In 1931, Malcolm X's father, Earl Little, died in what was officially ruled a streetcar accident, though his family believed he was murdered by white supremacists.",
      "date": "1931"
    },
    {
      "headline": "Mother's Institutionalization",
      "text": "In 1938, Malcolm X's mother, Louise Little, was committed to a mental institution, and the children were split up among various foster homes.",
      "date": "1938"
    },
    {
      "headline": "Move to Boston",
      "text": "In 1941, Malcolm moved to Boston to live with his half-sister, Ella Little-Collins.",
      "date": "1941"
    },
    {
      "headline": "Imprisonment",
      "text": "In 1946, Malcolm X was sentenced to 8 to 10 years in prison for larceny and breaking and entering.",
      "date": "1946"
    },
    {
      "headline": "Conversion to Islam",
      "text": "While in prison, Malcolm X converted to Islam and joined the Nation of Islam, adopting the name Malcolm X in 1948.",
      "date": "1948"
    },
    {
      "headline": "Release from Prison",
      "text": "Malcolm X was released from prison in 1952 and became a minister and national spokesman for the Nation of Islam.",
      "date": "1952"
    },
    {
      "headline": "Establishment of Mosque No. 7",
      "text": "In 1954, Malcolm X established Mosque No. 7 in Harlem, New York, and became a prominent leader in the Nation of Islam.",
      "date": "1954"
    },
    {
      "headline": "Hajj and Sunni Islam Conversion",
      "text": "In April 1964, Malcolm X made a pilgrimage to Mecca, known as Hajj, and converted to Sunni Islam, adopting the name El-Hajj Malik El-Shabazz.",
      "date": "1964-04"
    },
    {
      "headline": "Founding of the Organization of Afro-American Unity",
      "text": "In June 1964, Malcolm X founded the Organization of Afro-American Unity, advocating for human rights and African American unity.",
      "date": "1964-06"
    },
    {
      "headline": "Assassination",
      "text": "Malcolm X was assassinated on February 21, 1965, while giving a speech at the Audubon Ballroom in New York City.",
      "date": "1965-02-21"
    }
  ]
}

