    {
      "headline": "Foundation of Luxembourg",
      "text": "Luxembourg was founded in 963 when Count Siegfried acquired a rocky promontory and its Roman-era fortifications, known as Lucilinburhuc, from the Abbey of St. Maximin in Trier.",
      "date": "0963"
    },
    {
      "headline": "County of Luxembourg",
      "text": "In 1354, the County of Luxembourg was elevated to a duchy by Emperor Charles IV.",
      "date": "1354"
    },
    {
      "headline": "Burgundian Rule",
      "text": "In 1443, Luxembourg came under the rule of the Burgundian Netherlands.",
      "date": "1443"
    },
    {
      "headline": "Spanish Rule",
      "text": "After the death of Charles the Bold in 1477, Luxembourg became part of the Spanish Netherlands.",
      "date": "1477"
    },
    {
      "headline": "Austrian Rule",
      "text": "In 1715, following the War of the Spanish Succession, Luxembourg became part of the Austrian Netherlands.",
      "date": "1715"
    },
    {
      "headline": "French Annexation",
      "text": "Luxembourg was annexed by France in 1795 during the French Revolutionary Wars.",
      "date": "1795"
    },
    {
      "headline": "Congress of Vienna",
      "text": "In 1815, the Congress of Vienna established Luxembourg as a Grand Duchy in personal union with the Netherlands under King William I.",
      "date": "1815"
    },
    {
      "headline": "Luxembourg Crisis",
      "text": "In 1867, the Luxembourg Crisis nearly led to war between France and Prussia, but was resolved by the Treaty of London, which reaffirmed Luxembourg's independence and neutrality.",
      "date": "1867"
    },
    {
      "headline": "German Occupation in WWI",
      "text": "Luxembourg was occupied by Germany during World War I from 1914 to 1918.",
      "date": "1914"
    },
    {
      "headline": "German Occupation in WWII",
      "text": "Luxembourg was again occupied by Germany during World War II from 1940 to 1944.",
      "date": "1940"
    },
    {
      "headline": "Founding Member of the United Nations",
      "text": "Luxembourg became a founding member of the United Nations in 1945.",
      "date": "1945"
    },
    {
      "headline": "Founding Member of NATO",
      "text": "Luxembourg became a founding member of NATO in 1949.",
      "date": "1949"
    },
    {
      "headline": "Founding Member of the European Economic Community",
      "text": "Luxembourg was a founding member of the European Economic Community, which later became the European Union, in 1957.",
