{
  "timeline": [
    {
      "headline": "Development Initiation",
      "text": "The development of the Iron Dome system began in response to the rocket threat faced by Israel, particularly from the Gaza Strip. The project was initiated by Rafael Advanced Defense Systems and Israel Aerospace Industries.",
      "date": "2007"
    },
    {
      "headline": "First Successful Interception",
      "text": "The Iron Dome system successfully intercepted a rocket for the first time during a test. This marked a significant milestone in the development of the defense system.",
      "date": "2009"
    },
    {
      "headline": "Operational Deployment",
      "text": "The Iron Dome was declared operational and deployed for the first time near Beersheba, Israel, in response to rocket attacks from Gaza.",
      "date": "2011-03"
    },
    {
      "headline": "First Combat Interception",
      "text": "The Iron Dome system successfully intercepted a Grad rocket fired from Gaza, marking its first interception in combat.",
      "date": "2011-04-07"
    },
    {
      "headline": "U.S. Funding Contribution",
      "text": "From 2011 to 2021, the United States contributed a total of US$1.6 billion to the Iron Dome defense system, supporting its development and deployment.",
      "date": "2011"
    },
    {
      "headline": "Operation Pillar of Defense",
      "text": "During Operation Pillar of Defense, the Iron Dome system intercepted hundreds of rockets fired from Gaza, demonstrating its effectiveness in combat.",
      "date": "2012-11"
    },
    {
      "headline": "Operation Protective Edge",
      "text": "The Iron Dome played a crucial role during Operation Protective Edge, intercepting approximately 90% of the rockets targeted at populated areas in Israel.",
      "date": "2014-07"
    },
    {
      "headline": "Additional U.S. Funding Approved",
      "text": "The U.S. Congress approved an additional US$1 billion in funding for the Iron Dome system, further supporting its capabilities.",
      "date": "2022"
    }
  ]
}

