{
  "timeline": [
    {
      "headline": "Foundation of Constantinople",
      "text": "On May 11, 330, Emperor Constantine the Great dedicated the city of Byzantium as the new capital of the Roman Empire, renaming it Constantinople.",
      "date": "0330-05-11"
    },
    {
      "headline": "Division of the Roman Empire",
      "text": "In 395, the Roman Empire was permanently divided into Eastern and Western halves, with the Eastern Roman Empire centered in Constantinople.",
      "date": "0395"
    },
    {
      "headline": "Reign of Justinian I",
      "text": "From 527 to 565, Emperor Justinian I ruled the Byzantine Empire, known for his ambitious reconquests and the codification of Roman law in the Corpus Juris Civilis.",
      "date": "0527"
    },
    {
      "headline": "Nika Riots",
      "text": "In January 532, the Nika Riots broke out in Constantinople, leading to significant destruction and loss of life before being suppressed by Emperor Justinian I.",
      "date": "0532-01"
    },
    {
      "headline": "Completion of Hagia Sophia",
      "text": "On December 27, 537, the Hagia Sophia was completed under the orders of Emperor Justinian I, becoming an architectural marvel and the central church of the Byzantine Empire.",
      "date": "0537-12-27"
    },
    {
      "headline": "Battle of Yarmouk",
      "text": "In 636, the Byzantine Empire suffered a significant defeat against the Rashidun Caliphate at the Battle of Yarmouk, leading to the loss of Syria.",
      "date": "0636"
    },
    {
      "headline": "Iconoclasm Controversy",
      "text": "Beginning in 726, the Byzantine Empire experienced the Iconoclasm Controversy, a period of religious conflict over the use of icons in worship.",
      "date": "0726"
    },
    {
      "headline": "Reign of Basil II",
      "text": "From 976 to 1025, Basil II ruled the Byzantine Empire, known for his military conquests and the expansion of the empire's territories.",
      "date": "0976"
    },
    {
      "headline": "Battle of Manzikert",
      "text": "On August 26, 1071, the Byzantine Empire suffered a major defeat at the Battle of Manzikert against the Seljuk Turks, leading to the loss of much of Anatolia.",
      "date": "1071-08-26"
    },
    {
      "headline": "Fourth Crusade and Sack of Constantinople",
      "text": "In 1204, during the Fourth Crusade, Constantinople was sacked by Crusader forces, leading to the establishment of the Latin Empire.",
      "date": "1204"
    },
    {
      "headline": "Restoration of the Byzantine Empire",
      "text": "In 1261, the Byzantine Empire was restored under the Palaiologos dynasty after the recapture of Constantinople from the Latin Empire.",
      "date": "1261"
    },
    {
      "headline": "Fall of Constantinople",
      "text": "On May 29, 1453, Constantinople fell to the Ottoman Empire, marking the end of the Byzantine Empire.",
      "date": "1453-05-29"
    }
  ]
}

