    {
      "headline": "Break-in at the Democratic National Committee Headquarters",
      "text": "On June 17, 1972, five men were arrested for breaking into the Democratic National Committee headquarters at the Watergate Office Building in Washington, D.C. They were attempting to plant listening devices.",
      "date": "1972-06-17"
    },
    {
      "headline": "Nixon's Re-election",
      "text": "President Richard Nixon was re-elected in a landslide victory on November 7, 1972, despite the ongoing investigation into the Watergate break-in.",
      "date": "1972-11-07"
    },
    {
      "headline": "Senate Watergate Committee Formed",
      "text": "In February 1973, the United States Senate voted to establish a committee to investigate the Watergate scandal. The committee was chaired by Senator Sam Ervin.",
      "date": "1973-02"
    },
    {
      "headline": "Televised Senate Watergate Hearings Begin",
      "text": "The Senate Watergate Committee began its televised hearings on May 17, 1973, bringing the scandal into the national spotlight.",
      "date": "1973-05-17"
    },
    {
      "headline": "Nixon's Tapes Revealed",
      "text": "On July 16, 1973, it was revealed that President Nixon had a tape-recording system in his offices and had recorded many conversations.",
      "date": "1973-07-16"
    },
    {
      "headline": "Saturday Night Massacre",
      "text": "On October 20, 1973, in what became known as the 'Saturday Night Massacre,' President Nixon ordered the firing of special prosecutor Archibald Cox, leading to the resignations of Attorney General Elliot Richardson and Deputy Attorney General William Ruckelshaus.",
      "date": "1973-10-20"
    },
    {
      "headline": "United States v. Nixon",
      "text": "On July 24, 1974, the Supreme Court ruled unanimously in United States v. Nixon that the president must release the tapes to government investigators.",
      "date": "1974-07-24"
    },
    {
      "headline": "Nixon Resigns",
      "text": "On August 8, 1974, President Richard Nixon announced his resignation from office, effective the next day, becoming the first U.S. president to resign.",
      "date": "1974-08-08"
    },
    {
      "headline": "Gerald Ford Becomes President",
      "text": "Vice President Gerald Ford was sworn in as the 38th President of the United States on August 9, 1974, following Nixon's resignation.",
      "date": "1974-08-09"
    },
    {
      "headline": "Pardon of Richard Nixon",
      "text": "On September 8, 1974, President Gerald Ford granted a full and unconditional pardon to Richard Nixon for any crimes he might have committed against the United States while president.",
      "date": "1974-09-08"
    }
  ]
}

