    {
      "headline": "Creation of C Programming Language",
      "text": "C was created in the early 1970s by Dennis Ritchie at Bell Labs. It was developed as a system programming language for the Unix operating system.",
      "date": "1972"
    },
    {
      "headline": "Publication of 'The C Programming Language'",
      "text": "In 1978, Brian Kernighan and Dennis Ritchie published 'The C Programming Language', which became the definitive reference for the language.",
      "date": "1978"
    },
    {
      "headline": "ANSI C Standardization",
      "text": "In 1989, the American National Standards Institute (ANSI) ratified a standard for C, known as ANSI C, which standardized the language and its library.",
      "date": "1989"
    },
    {
      "headline": "ISO C Standardization",
      "text": "In 1990, the International Organization for Standardization (ISO) adopted the ANSI C standard, further solidifying its status as a global standard.",
      "date": "1990"
    },
    {
      "headline": "C99 Standard",
      "text": "In 1999, the C programming language was updated with the C99 standard, which introduced several new features, including inline functions, variable-length arrays, and new data types.",
      "date": "1999"
    },
    {
      "headline": "C11 Standard",
      "text": "The C11 standard was published in 2011, introducing features such as multi-threading support, improved Unicode support, and additional standard library functions.",
      "date": "2011"
    },
    {
      "headline": "C18 Standard",
      "text": "In 2018, the C18 standard was released, which included bug fixes and improvements to the C11 standard without introducing new features.",
      "date": "2018"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Alan Turing",
      "text": "Alan Mathison Turing was born on June 23, 1912, in Maida Vale, London, England.",
      "date": "1912-06-23"
    },
    {
      "headline": "Education at King's College, Cambridge",
      "text": "In 1931, Turing began studying at King's College, Cambridge, where he graduated with a degree in mathematics in 1934.",
      "date": "1931"
    },
    {
      "headline": "Publication of 'On Computable Numbers'",
      "text": "In 1936, Turing published his paper 'On Computable Numbers, with an Application to the Entscheidungsproblem,' introducing the concept of a Turing machine.",
      "date": "1936"
    },
    {
      "headline": "Ph.D. from Princeton University",
      "text": "Turing received his Ph.D. from Princeton University in 1938, where he studied under Alonzo Church.",
      "date": "1938"
    },
    {
      "headline": "Work at Bletchley Park",
      "text": "During World War II, Turing worked at Bletchley Park, the British codebreaking centre, where he played a crucial role in breaking the German Enigma code.",
      "date": "1939"
    },
    {
      "headline": "Development of the Bombe",
      "text": "In 1940, Turing developed the Bombe, an electromechanical machine used to decipher Enigma-encrypted messages.",
      "date": "1940"
    },
    {
      "headline": "Turing Test Proposal",
      "text": "In 1950, Turing proposed the Turing Test in his paper 'Computing Machinery and Intelligence,' which became a foundational concept in artificial intelligence.",
      "date": "1950"
    },
    {
      "headline": "Conviction for Gross Indecency",
      "text": "In 1952, Turing was convicted of gross indecency due to his homosexual relationship, which was illegal at the time in the UK.",
      "date": "1952"
    },
    {
      "headline": "Death of Alan Turing",
      "text": "Alan Turing died on June 7, 1954, in Wilmslow, Cheshire, England, from cyanide poisoning.",
      "date": "1954-06-07"
    }
  ]
}

