{
  "timeline": [
    {
      "headline": "Jamsetji Tata's Birth",
      "text": "Jamsetji Tata, the founder of the Tata Group, was born on March 3, 1839, in Navsari, Gujarat, India.",
      "date": "1839-03-03"
    },
    {
      "headline": "Establishment of Tata Group",
      "text": "In 1868, Jamsetji Tata founded the Tata Group, which would grow to become one of India's largest and most respected business conglomerates.",
      "date": "1868"
    },
    {
      "headline": "Establishment of Empress Mills",
      "text": "In 1877, Jamsetji Tata established Empress Mills in Nagpur, marking the beginning of the industrialization of India.",
      "date": "1877"
    },
    {
      "headline": "Establishment of Tata Steel",
      "text": "In 1907, Tata Steel was established as India's first steel company, originally known as Tata Iron and Steel Company Limited (TISCO).",
      "date": "1907"
    },
    {
      "headline": "Jamsetji Tata's Death",
      "text": "Jamsetji Tata passed away on May 19, 1904, in Bad Nauheim, Germany, leaving behind a legacy of industrialization and philanthropy.",
      "date": "1904-05-19"
    },
    {
      "headline": "Establishment of Tata Power",
      "text": "In 1911, Tata Power was established, becoming India's largest integrated power company.",
      "date": "1911"
    },
    {
      "headline": "Establishment of Tata Institute of Science",
      "text": "In 1911, the Tata Institute of Science, now known as the Indian Institute of Science, was established in Bangalore, India, with the support of the Tata family.",
      "date": "1911"
    },
    {
      "headline": "Establishment of Tata Airlines",
      "text": "In 1932, Tata Airlines was established, which later became Air India, India's national airline.",
      "date": "1932"
    },
    {
      "headline": "J.R.D. Tata becomes Chairman",
      "text": "In 1938, J.R.D. Tata became the Chairman of Tata Sons, leading the company to new heights.",
      "date": "1938"
    },
    {
      "headline": "Establishment of Tata Motors",
      "text": "In 1945, Tata Motors was established, initially as Tata Engineering and Locomotive Co. Ltd. (TELCO), marking the Tata Group's entry into the automotive industry.",
      "date": "1945"
    },
    {
      "headline": "Ratan Tata becomes Chairman",
      "text": "In 1991, Ratan Tata became the Chairman of Tata Sons, leading the group through a period of globalization and expansion.",
      "date": "1991"
    },
    {
      "headline": "Acquisition of Tetley",
      "text": "In 2000, Tata Tea acquired Tetley, a British tea company, marking one of the first major international acquisitions by an Indian company.",
      "date": "2000"
    },
    {
      "headline": "Acquisition of Corus",
      "text": "In 2007, Tata Steel acquired Corus, a European steel maker, in one of the largest acquisitions by an Indian company.",
      "date": "2007"
    },
    {
      "headline": "Acquisition of Jaguar Land Rover",
      "text": "In 2008, Tata Motors acquired Jaguar Land Rover from Ford, marking a significant expansion into the luxury automotive market.",
      "date": "2008"
    },
    {
      "headline": "Cyrus Mistry becomes Chairman",
      "text": "In 2012, Cyrus Mistry was appointed as the Chairman of Tata Sons, succeeding Ratan Tata.",
      "date": "2012"
    },
    {
      "headline": "Ratan Tata returns as Interim Chairman",
      "text": "In 2016, Ratan Tata returned as the interim Chairman of Tata Sons after the removal of Cyrus Mistry.",
      "date": "2016"
