{
  "timeline": [
    {
      "headline": "Introduction of Horizon IT System",
      "text": "In 1999, the Post Office introduced the Horizon IT system, developed by Fujitsu, to manage accounting and transactions across its branches.",
      "date": "1999"
    },
    {
      "headline": "Start of Prosecutions",
      "text": "Between 1999 and 2015, more than 900 subpostmasters were prosecuted for theft, fraud, and false accounting based on data from the Horizon system.",
      "date": "1999"
    },
    {
      "headline": "First Known Convictions",
      "text": "The first known convictions of subpostmasters based on Horizon data occurred in the early 2000s, with many facing criminal charges and financial ruin.",
      "date": "2000"
    },
    {
      "headline": "Growing Awareness of Issues",
      "text": "Throughout the 2000s, subpostmasters began raising concerns about discrepancies and errors in the Horizon system, leading to increased scrutiny.",
      "date": "2000"
    },
    {
      "headline": "Legal Challenges Begin",
      "text": "In the 2010s, subpostmasters began to legally challenge the Post Office's prosecutions, citing faults in the Horizon system as the cause of financial discrepancies.",
      "date": "2010"
    },
    {
      "headline": "High Court Ruling",
      "text": "In December 2019, the High Court ruled in favor of the subpostmasters, finding that the Horizon system contained significant bugs, errors, and defects.",
      "date": "2019-12"
    },
    {
      "headline": "Convictions Overturned",
      "text": "In 2021, the Court of Appeal overturned the convictions of 39 subpostmasters, acknowledging the miscarriages of justice due to faulty Horizon data.",
      "date": "2021"
    },
    {
      "headline": "Compensation and Inquiry",
      "text": "Following the overturned convictions, the UK government announced compensation schemes and a public inquiry into the scandal.",
      "date": "2021"
    },
    {
      "headline": "Prime Minister's Statement",
      "text": "In 2024, Prime Minister Rishi Sunak described the Post Office scandal as one of the greatest miscarriages of justice in British history.",
      "date": "2024"
    }
  ]
}

