  "timeline": [
    {
      "headline": "Birth of Joan of Arc",
      "text": "Joan of Arc was born in Domrémy, a village in northeastern France, around January 6, 1412.",
      "date": "1412"
    },
    {
      "headline": "Joan's Visions Begin",
      "text": "In 1425, at the age of 13, Joan of Arc began experiencing visions of saints instructing her to support Charles VII and help him reclaim his kingdom from English domination.",
      "date": "1425"
    },
    {
      "headline": "Joan Meets Charles VII",
      "text": "In February 1429, Joan of Arc met Charles VII at Chinon, convincing him of her divine mission to lead France to victory.",
      "date": "1429-02"
    },
    {
      "headline": "Siege of Orléans",
      "text": "On May 8, 1429, Joan of Arc played a crucial role in lifting the Siege of Orléans, marking a turning point in the Hundred Years' War.",
      "date": "1429-05-08"
    },
    {
      "headline": "Coronation of Charles VII",
      "text": "Joan of Arc was present at the coronation of Charles VII in Reims on July 17, 1429, fulfilling part of her divine mission.",
      "date": "1429-07-17"
    },
    {
      "headline": "Capture of Joan of Arc",
      "text": "Joan of Arc was captured by the Burgundians at the Siege of Compiègne on May 23, 1430, and later sold to the English.",
      "date": "1430-05-23"
    },
    {
      "headline": "Trial and Execution",
      "text": "Joan of Arc was tried for heresy and burned at the stake in Rouen on May 30, 1431.",
      "date": "1431-05-30"
    },
    {
      "headline": "Posthumous Retrial and Rehabilitation",
      "text": "In 1456, a posthumous retrial declared Joan of Arc innocent of heresy, restoring her reputation.",
      "date": "1456"
    },
    {
      "headline": "Canonization of Joan of Arc",
      "text": "Joan of Arc was canonized as a saint by the Roman Catholic Church on May 16, 1920.",
      "date": "1920-05-16"
    }
  ]
}

