    {
      "headline": "Battle of Kosovo",
      "text": "The Battle of Kosovo took place on June 28, 1389, between the army led by Serbian Prince Lazar and the invading Ottoman forces led by Sultan Murad I. This battle is one of the most significant events in the history of Kosovo.",
      "date": "1389-06-28"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Kosovo came under Ottoman rule in the late 14th century after the Battle of Kosovo. It remained part of the Ottoman Empire for several centuries.",
      "date": "1455"
    },
    {
      "headline": "First Balkan War",
      "text": "During the First Balkan War in 1912, Kosovo was taken from the Ottoman Empire by the Kingdom of Serbia.",
      "date": "1912"
    },
    {
      "headline": "Kosovo in Yugoslavia",
      "text": "After World War I, Kosovo became part of the Kingdom of Serbs, Croats, and Slovenes, later known as Yugoslavia.",
      "date": "1918"
    },
    {
      "headline": "Autonomous Province of Kosovo and Metohija",
      "text": "In 1946, Kosovo was established as an autonomous region within the Socialist Republic of Serbia, part of the Socialist Federal Republic of Yugoslavia.",
      "date": "1946"
    },
    {
      "headline": "Kosovo War",
      "text": "The Kosovo War occurred from March 5, 1998, to June 11, 1999, involving conflict between Yugoslav forces and the Kosovo Liberation Army, with NATO intervening in 1999.",
      "date": "1998-03-05"
    },
    {
      "headline": "NATO Bombing of Yugoslavia",
      "text": "NATO conducted a bombing campaign against Yugoslavia from March 24, 1999, to June 10, 1999, to stop the humanitarian crisis in Kosovo.",
      "date": "1999-03-24"
    },
    {
      "headline": "UNMIK Administration",
      "text": "Following the Kosovo War, the United Nations Interim Administration Mission in Kosovo (UNMIK) was established to govern the region.",
      "date": "1999-06-10"
    },
    {
      "headline": "Declaration of Independence",
      "text": "Kosovo declared independence from Serbia on February 17, 2008. The declaration was met with mixed international reactions, with some countries recognizing Kosovo as an independent state and others not.",
      "date": "2008-02-17"
    },
    {
      "headline": "ICJ Advisory Opinion",
      "text": "On July 22, 2010, the International Court of Justice issued an advisory opinion stating that Kosovo's declaration of independence did not violate international law.",
      "date": "2010-07-22"
    }
  ]
}

