{
  "timeline": [
    {
      "headline": "Establishment of the Supreme Court",
      "text": "The Supreme Court of the United States was established by the Judiciary Act of 1789, which was signed into law by President George Washington on September 24, 1789.",
      "date": "1789-09-24"
    },
    {
      "headline": "First Session of the Supreme Court",
      "text": "The Supreme Court held its first session on February 2, 1790, in the Merchants Exchange Building in New York City.",
      "date": "1790-02-02"
    },
    {
      "headline": "Marbury v. Madison Decision",
      "text": "In 1803, the Supreme Court, under Chief Justice John Marshall, decided the case of Marbury v. Madison, establishing the principle of judicial review, which allows the Court to strike down laws that violate the Constitution.",
      "date": "1803"
    },
    {
      "headline": "Dred Scott v. Sandford Decision",
      "text": "In 1857, the Supreme Court delivered the Dred Scott v. Sandford decision, ruling that African Americans could not be American citizens and that Congress could not prohibit slavery in the territories.",
      "date": "1857"
    },
    {
      "headline": "Plessy v. Ferguson Decision",
      "text": "In 1896, the Supreme Court decided Plessy v. Ferguson, upholding the constitutionality of racial segregation under the 'separate but equal' doctrine.",
      "date": "1896"
    },
    {
      "headline": "Brown v. Board of Education Decision",
      "text": "In 1954, the Supreme Court ruled in Brown v. Board of Education that racial segregation in public schools was unconstitutional, overturning Plessy v. Ferguson.",
      "date": "1954"
    },
    {
      "headline": "Roe v. Wade Decision",
      "text": "In 1973, the Supreme Court issued its decision in Roe v. Wade, establishing a woman's legal right to an abortion under the right to privacy.",
      "date": "1973"
    },
    {
      "headline": "Bush v. Gore Decision",
      "text": "In 2000, the Supreme Court decided Bush v. Gore, effectively resolving the 2000 presidential election in favor of George W. Bush.",
      "date": "2000"
    },
    {
      "headline": "Obergefell v. Hodges Decision",
      "text": "In 2015, the Supreme Court ruled in Obergefell v. Hodges that same-sex marriage is a constitutional right under the Fourteenth Amendment.",
      "date": "2015"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Murders of Nicole Brown Simpson and Ron Goldman",
      "text": "On June 12, 1994, Nicole Brown Simpson and her friend Ron Goldman were found stabbed to death outside Brown's condominium in Los Angeles.",
      "date": "1994-06-12"
    },
    {
      "headline": "O.J. Simpson Charged with Murder",
      "text": "On June 17, 1994, O.J. Simpson was charged with the murders of Nicole Brown Simpson and Ron Goldman. A low-speed pursuit of Simpson in a white Ford Bronco was broadcast live on television.",
      "date": "1994-06-17"
    },
    {
      "headline": "Preliminary Hearing and Arraignment",
      "text": "On July 22, 1994, O.J. Simpson was arraigned and pleaded not guilty to the murder charges.",
