{
  "timeline": [
    {
      "headline": "Birth of Vincent van Gogh",
      "text": "Vincent Willem van Gogh was born on March 30, 1853, in Zundert, Netherlands.",
      "date": "1853-03-30"
    },
    {
      "headline": "Van Gogh Begins Working at Goupil & Cie",
      "text": "In 1869, Vincent van Gogh began working at the art dealership Goupil & Cie in The Hague.",
      "date": "1869"
    },
    {
      "headline": "Van Gogh Moves to London",
      "text": "In 1873, Van Gogh was transferred to the London branch of Goupil & Cie.",
      "date": "1873"
    },
    {
      "headline": "Van Gogh Dismissed from Goupil & Cie",
      "text": "In 1876, Van Gogh was dismissed from Goupil & Cie due to his lack of interest in the business.",
      "date": "1876"
    },
    {
      "headline": "Van Gogh Becomes a Teacher and Preacher",
      "text": "In 1876, after leaving Goupil & Cie, Van Gogh worked as a teacher and lay preacher in England.",
      "date": "1876"
    },
    {
      "headline": "Van Gogh Studies Theology",
      "text": "In 1877, Van Gogh returned to the Netherlands to study theology in Amsterdam.",
      "date": "1877"
    },
    {
      "headline": "Van Gogh Begins Missionary Work",
      "text": "In 1879, Van Gogh began working as a missionary in the Borinage, a coal-mining region in Belgium.",
      "date": "1879"
    },
    {
      "headline": "Van Gogh Decides to Become an Artist",
      "text": "In 1880, Van Gogh decided to pursue a career as an artist, inspired by his time in the Borinage.",
      "date": "1880"
    },
    {
      "headline": "Van Gogh Moves to Paris",
      "text": "In 1886, Van Gogh moved to Paris, where he was influenced by Impressionism and Post-Impressionism.",
      "date": "1886"
    },
    {
      "headline": "Van Gogh Moves to Arles",
      "text": "In February 1888, Van Gogh moved to Arles in the south of France, seeking inspiration from the rural landscape.",
      "date": "1888-02"
    },
    {
      "headline": "Van Gogh's Ear Incident",
      "text": "On December 23, 1888, Van Gogh famously cut off part of his left ear during a mental breakdown.",
      "date": "1888-12-23"
    },
    {
      "headline": "Van Gogh Admitted to Saint-Paul-de-Mausole Asylum",
      "text": "In May 1889, Van Gogh voluntarily admitted himself to the Saint-Paul-de-Mausole asylum in Saint-Rémy-de-Provence.",
      "date": "1889-05"
    },
    {
      "headline": "Van Gogh Paints 'Starry Night'",
      "text": "In June 1889, while at the asylum, Van Gogh painted one of his most famous works, 'Starry Night'.",
      "date": "1889-06"
    },
    {
      "headline": "Van Gogh Moves to Auvers-sur-Oise",
      "text": "In May 1890, Van Gogh moved to Auvers-sur-Oise to be closer to his brother Theo and to receive care from Dr. Paul Gachet.",
      "date": "1890-05"
    },
    {
      "headline": "Death of Vincent van Gogh",
      "text": "On July 29, 1890, Vincent van Gogh died from a self-inflicted gunshot wound in Auvers-sur-Oise, France.",
      "date": "1890-07-29"
    }
  ]
}

