{
  "timeline": [
    {
      "headline": "Start of the Cold War",
      "text": "The Cold War began in 1947, marked by geopolitical tension between the United States and the Soviet Union, along with their respective allies.",
      "date": "1947"
    },
    {
      "headline": "Berlin Blockade and Airlift",
      "text": "From June 24, 1948, to May 12, 1949, the Soviet Union blocked the Western Allies' railway, road, and canal access to the sectors of Berlin under Western control. In response, the Western Allies organized the Berlin Airlift to carry supplies to the people of West Berlin.",
      "date": "1948-06-24"
    },
    {
      "headline": "Formation of NATO",
      "text": "On April 4, 1949, the North Atlantic Treaty Organization (NATO) was formed as a military alliance among Western countries to counter Soviet expansion.",
      "date": "1949-04-04"
    },
    {
      "headline": "Korean War",
      "text": "The Korean War began on June 25, 1950, when North Korea, supported by China and the Soviet Union, invaded South Korea, which was backed by United Nations forces led by the United States. The war ended with an armistice on July 27, 1953.",
      "date": "1950-06-25"
    },
    {
      "headline": "Cuban Missile Crisis",
      "text": "In October 1962, the Cuban Missile Crisis occurred when the Soviet Union placed nuclear missiles in Cuba, leading to a tense 13-day standoff with the United States, which nearly escalated into a full-scale nuclear war.",
      "date": "1962-10"
    },
    {
      "headline": "Vietnam War",
      "text": "The Vietnam War was a prolonged conflict that lasted from November 1, 1955, to April 30, 1975, involving North Vietnam and its communist allies against South Vietnam and its principal ally, the United States.",
      "date": "1955-11-01"
    },
    {
      "headline": "Soviet Invasion of Afghanistan",
      "text": "On December 24, 1979, the Soviet Union invaded Afghanistan, leading to a decade-long conflict with Afghan insurgents, who were supported by the United States and other countries.",
      "date": "1979-12-24"
    },
    {
      "headline": "Fall of the Berlin Wall",
      "text": "On November 9, 1989, the Berlin Wall fell, symbolizing the weakening of Soviet influence in Eastern Europe and the beginning of the end of the Cold War.",
      "date": "1989-11-09"
    },
    {
      "headline": "Dissolution of the Soviet Union",
      "text": "The Soviet Union was officially dissolved on December 26, 1991, marking the end of the Cold War.",
      "date": "1991-12-26"
    }
  ]
}

