    },
    {
      "headline": "Austro-Hungarian Compromise of 1867",
      "text": "The Austro-Hungarian Compromise of 1867 established the dual monarchy of Austria-Hungary, granting Hungary equal status with Austria. This marked the beginning of the Austro-Hungarian Empire.",
      "date": "1867"
    },
    {
      "headline": "Treaty of Trianon",
      "text": "Signed on June 4, 1920, the Treaty of Trianon formally ended World War I for Hungary and resulted in significant territorial losses, reducing Hungary's size by about two-thirds.",
      "date": "1920-06-04"
    },
    {
      "headline": "Hungarian Revolution of 1956",
      "text": "The Hungarian Revolution of 1956 was a nationwide revolt against the Soviet-imposed policies of the People's Republic of Hungary, lasting from October 23 until November 10, 1956.",
