{
  "timeline": [
    {
      "headline": "Formation of the Kingdom of Kongo",
      "text": "The Kingdom of Kongo was established in the late 14th century, around 1390, in the western part of present-day Democratic Republic of the Congo.",
      "date": "1390"
    },
    {
      "headline": "Arrival of Portuguese Explorers",
      "text": "In 1482, Portuguese explorer Diogo Cão reached the mouth of the Congo River, marking the beginning of European contact with the region.",
      "date": "1482"
    },
    {
      "headline": "Colonization by Belgium",
      "text": "In 1885, King Leopold II of Belgium established the Congo Free State as his private property, leading to significant exploitation and atrocities.",
      "date": "1885"
    },
    {
      "headline": "Annexation as Belgian Congo",
      "text": "In 1908, due to international pressure, the Congo Free State was annexed by Belgium and became the Belgian Congo.",
      "date": "1908"
    },
    {
      "headline": "Independence from Belgium",
      "text": "On June 30, 1960, the Democratic Republic of the Congo gained independence from Belgium, with Patrice Lumumba as its first Prime Minister.",
      "date": "1960-06-30"
    },
    {
      "headline": "Congo Crisis",
      "text": "The Congo Crisis was a period of political upheaval and conflict in the Republic of the Congo between 1960 and 1965.",
      "date": "1960"
    },
    {
      "headline": "Mobutu's Coup",
      "text": "In 1965, Joseph-Désiré Mobutu seized power in a coup and established a one-party state, later renaming the country Zaire in 1971.",
      "date": "1965"
    },
    {
      "headline": "Renaming to Zaire",
      "text": "In 1971, Mobutu renamed the country Zaire as part of his Authenticity campaign.",
      "date": "1971"
    },
    {
      "headline": "First Congo War",
      "text": "The First Congo War began in 1996, leading to the overthrow of Mobutu and the end of the Zaire regime in 1997.",
      "date": "1996"
    },
    {
      "headline": "Renaming to Democratic Republic of the Congo",
      "text": "In 1997, following the First Congo War, the country was renamed the Democratic Republic of the Congo.",
      "date": "1997"
    },
    {
      "headline": "Second Congo War",
      "text": "The Second Congo War, also known as the Great African War, began in 1998 and involved multiple African nations, lasting until 2003.",
      "date": "1998"
    },
    {
      "headline": "End of Second Congo War",
      "text": "The Second Congo War officially ended in 2003, although conflicts continued in the eastern regions.",
      "date": "2003"
    },
    {
      "headline": "First Democratic Elections",
      "text": "In 2006, the Democratic Republic of the Congo held its first multi-party elections in over 40 years.",
      "date": "2006"
    }
  ]
}

