    {
      "headline": "Bus Accident",
      "text": "On September 17, 1925, Frida Kahlo was involved in a serious bus accident that resulted in numerous injuries, including a broken spinal column, collarbone, ribs, pelvis, and fractures in her right leg.",
      "date": "1925-09-17"
    },
    {
      "headline": "First Self-Portrait",
      "text": "In 1926, while recovering from her injuries, Frida Kahlo painted her first self-portrait, 'Self-Portrait in a Velvet Dress'.",
