    {
      "headline": "First Solo Exhibition",
      "text": "Frida Kahlo held her first solo exhibition at the Julien Levy Gallery in New York City in 1938.",
      "date": "1938"
    },
    {
      "headline": "Exhibition in Paris",
      "text": "In 1939, Frida Kahlo exhibited her work in Paris, where she met artists such as Pablo Picasso and Marcel Duchamp.",
      "date": "1939"
    },
    {
      "headline": "Divorce from Diego Rivera",
      "text": "Frida Kahlo and Diego Rivera divorced in 1939, although they remarried a year later in 1940.",
      "date": "1939"
    },
    {
      "headline": "Remarriage to Diego Rivera",
      "text": "Frida Kahlo and Diego Rivera remarried on December 8, 1940.",
      "date": "1940-12-08"
    },
    {
      "headline": "First Solo Exhibition in Mexico",
      "text": "In 1953, Frida Kahlo had her first solo exhibition in Mexico at the Galería Arte Contemporaneo.",
      "date": "1953"
    },
    {
      "headline": "Death of Frida Kahlo",
      "text": "Frida Kahlo died on July 13, 1954, in Coyoacán, Mexico City, Mexico.",
