{
  "timeline": [
    {
      "headline": "Aksumite Empire Established",
      "text": "The Aksumite Empire, one of the great civilizations of the ancient world, was established in what is now northern Ethiopia and Eritrea. It is known for its monumental obelisks, the introduction of Christianity, and its role in ancient trade networks.",
      "date": "-0100"
    },
    {
      "headline": "Conversion to Christianity",
      "text": "In 330 AD, King Ezana of the Aksumite Empire converted to Christianity, making it the official religion of the state. This marked Ethiopia as one of the earliest regions in the world to officially adopt Christianity.",
      "date": "0330"
    },
    {
      "headline": "Zagwe Dynasty Begins",
      "text": "The Zagwe dynasty came to power in the mid-12th century, known for its rock-hewn churches in Lalibela, which are now a UNESCO World Heritage site.",
      "date": "1137"
    },
    {
      "headline": "Solomonic Dynasty Restored",
      "text": "In 1270, the Solomonic dynasty was restored under Emperor Yekuno Amlak, claiming descent from the biblical King Solomon and the Queen of Sheba.",
      "date": "1270"
    },
    {
      "headline": "Battle of Adwa",
      "text": "On March 1, 1896, Ethiopian forces led by Emperor Menelik II defeated the Italian army at the Battle of Adwa, securing Ethiopian sovereignty and marking a significant victory against colonial powers in Africa.",
      "date": "1896-03-01"
    },
    {
      "headline": "Italian Occupation",
      "text": "From 1936 to 1941, Ethiopia was occupied by Italy following the Second Italo-Ethiopian War, becoming part of Italian East Africa.",
      "date": "1936"
    },
    {
      "headline": "Liberation and Return of Haile Selassie",
      "text": "In 1941, Emperor Haile Selassie returned to Ethiopia with the help of British and Ethiopian forces, ending the Italian occupation.",
      "date": "1941"
    },
    {
      "headline": "Ethiopian Revolution",
      "text": "In 1974, a revolution led by the Derg, a Marxist-Leninist military junta, overthrew Emperor Haile Selassie, ending the Solomonic dynasty.",
      "date": "1974"
    },
    {
      "headline": "Fall of the Derg",
      "text": "In 1991, the Derg regime was overthrown by the Ethiopian People's Revolutionary Democratic Front (EPRDF), leading to the establishment of the Federal Democratic Republic of Ethiopia.",
      "date": "1991"
    },
    {
      "headline": "Eritrean Independence",
      "text": "In 1993, Eritrea gained independence from Ethiopia following a referendum, becoming a separate sovereign nation.",
      "date": "1993"
    },
    {
      "headline": "Ethiopian-Eritrean War",
      "text": "From 1998 to 2000, Ethiopia and Eritrea engaged in a border war, resulting in tens of thousands of casualties and a stalemate.",
      "date": "1998"
    },
    {
      "headline": "Peace Agreement with Eritrea",
      "text": "In 2018, Ethiopia and Eritrea signed a peace agreement, officially ending the state of war between the two countries.",
      "date": "2018"
    }
  ]
}

