{
  "timeline": [
    {
      "headline": "First Mention of Bosnia",
      "text": "The first mention of Bosnia as a land (horion Bosona) was in the De Administrando Imperio, a political-geographical handbook written by the Byzantine Emperor Constantine VII in the mid-10th century.",
      "date": "0940"
    },
    {
      "headline": "Kingdom of Bosnia",
      "text": "In 1377, Bosnia became a kingdom under King Tvrtko I, marking the peak of the medieval Bosnian state.",
      "date": "1377"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "The Ottoman Empire conquered Bosnia in 1463, marking the beginning of several centuries of Ottoman rule.",
      "date": "1463"
    },
    {
      "headline": "Austro-Hungarian Annexation",
      "text": "In 1878, Bosnia and Herzegovina was occupied by Austria-Hungary following the Congress of Berlin, and it was formally annexed in 1908.",
      "date": "1908"
    },
    {
      "headline": "Assassination of Archduke Franz Ferdinand",
      "text": "On June 28, 1914, Archduke Franz Ferdinand of Austria was assassinated in Sarajevo, an event that triggered World War I.",
      "date": "1914-06-28"
    },
    {
      "headline": "Formation of Yugoslavia",
      "text": "After World War I, Bosnia and Herzegovina became part of the Kingdom of Serbs, Croats, and Slovenes, later known as Yugoslavia, in 1918.",
      "date": "1918"
    },
    {
      "headline": "World War II and Socialist Yugoslavia",
      "text": "During World War II, Bosnia and Herzegovina was part of the Independent State of Croatia, a Nazi puppet state. After the war, it became one of the six republics of the Socialist Federal Republic of Yugoslavia in 1945.",
      "date": "1945"
    },
    {
      "headline": "Bosnian War",
      "text": "The Bosnian War took place from 1992 to 1995, following Bosnia and Herzegovina's declaration of independence from Yugoslavia.",
      "date": "1992"
    },
    {
      "headline": "Dayton Agreement",
      "text": "The Dayton Agreement was signed on December 14, 1995, ending the Bosnian War and establishing the current political structure of Bosnia and Herzegovina.",
      "date": "1995-12-14"
    }
  ]
}

