{
  "timeline": [
    {
      "headline": "Italian Colonization",
      "text": "In 1890, Eritrea officially became a colony of Italy. This marked the beginning of European colonial rule in the region.",
      "date": "1890"
    },
    {
      "headline": "British Administration",
      "text": "Following Italy's defeat in World War II, Eritrea came under British military administration in 1941.",
      "date": "1941"
    },
    {
      "headline": "Federation with Ethiopia",
      "text": "In 1952, Eritrea was federated with Ethiopia by a United Nations resolution, which granted Eritrea autonomy within the Ethiopian Empire.",
      "date": "1952"
    },
    {
      "headline": "Annexation by Ethiopia",
      "text": "In 1962, Ethiopia annexed Eritrea, dissolving the federation and making Eritrea a province of Ethiopia. This led to the Eritrean War of Independence.",
      "date": "1962"
    },
    {
      "headline": "Eritrean War of Independence",
      "text": "The Eritrean War of Independence began in 1961 and lasted until 1991, when Eritrean forces defeated Ethiopian troops.",
      "date": "1961"
    },
    {
      "headline": "Independence Referendum",
      "text": "In April 1993, a United Nations-supervised referendum was held, and Eritreans overwhelmingly voted for independence from Ethiopia.",
      "date": "1993-04"
    },
    {
      "headline": "Official Independence",
      "text": "Eritrea officially declared its independence on May 24, 1993, following the successful referendum.",
      "date": "1993-05-24"
    },
    {
      "headline": "Eritrean-Ethiopian War",
      "text": "From 1998 to 2000, Eritrea and Ethiopia engaged in a border war, which resulted in tens of thousands of casualties.",
      "date": "1998"
    },
    {
      "headline": "Peace Agreement with Ethiopia",
      "text": "In July 2018, Eritrea and Ethiopia signed a peace agreement, formally ending the state of war between the two countries.",
      "date": "2018-07"
    }
  ]
}

