{
  "timeline": [
    {
      "headline": "Birth of Edgar Allan Poe",
      "text": "Edgar Allan Poe was born on January 19, 1809, in Boston, Massachusetts.",
      "date": "1809-01-19"
    },
    {
      "headline": "Death of Poe's Parents",
      "text": "In 1811, Poe's mother, Elizabeth Arnold Poe, died in Richmond, Virginia. His father, David Poe Jr., had abandoned the family earlier and died shortly thereafter.",
      "date": "1811"
    },
    {
      "headline": "Adoption by the Allan Family",
      "text": "In 1811, after the death of his mother, Poe was taken in by John and Frances Allan of Richmond, Virginia, though they never formally adopted him.",
      "date": "1811"
    },
    {
      "headline": "Enrollment at the University of Virginia",
      "text": "In 1826, Poe enrolled at the University of Virginia to study ancient and modern languages.",
      "date": "1826"
    },
    {
      "headline": "Military Service",
      "text": "In 1827, Poe enlisted in the United States Army under the name 'Edgar A. Perry.'",
      "date": "1827"
    },
    {
      "headline": "Publication of 'Tamerlane and Other Poems'",
      "text": "In 1827, Poe's first book, 'Tamerlane and Other Poems,' was published anonymously.",
      "date": "1827"
    },
    {
      "headline": "Discharge from the Army",
      "text": "In 1829, Poe was honorably discharged from the Army after securing a replacement.",
      "date": "1829"
    },
    {
      "headline": "Publication of 'Al Aaraaf, Tamerlane, and Minor Poems'",
      "text": "In 1829, Poe published his second book, 'Al Aaraaf, Tamerlane, and Minor Poems.'",
      "date": "1829"
    },
    {
      "headline": "Enrollment at West Point",
      "text": "In 1830, Poe entered the United States Military Academy at West Point.",
      "date": "1830"
    },
    {
      "headline": "Dismissal from West Point",
      "text": "In 1831, Poe was dismissed from West Point for neglect of duties.",
      "date": "1831"
    },
    {
      "headline": "Publication of 'Poems'",
      "text": "In 1831, Poe published a third volume of poetry titled 'Poems.'",
      "date": "1831"
    },
    {
      "headline": "Marriage to Virginia Clemm",
      "text": "On May 16, 1836, Poe married his 13-year-old cousin, Virginia Clemm, in Richmond, Virginia.",
      "date": "1836-05-16"
    },
    {
      "headline": "Publication of 'The Narrative of Arthur Gordon Pym of Nantucket'",
      "text": "In 1838, Poe's only complete novel, 'The Narrative of Arthur Gordon Pym of Nantucket,' was published.",
      "date": "1838"
    },
    {
      "headline": "Publication of 'Tales of the Grotesque and Arabesque'",
      "text": "In 1840, Poe published 'Tales of the Grotesque and Arabesque,' a collection of short stories.",
      "date": "1840"
    },
    {
      "headline": "Publication of 'The Raven'",
      "text": "In January 1845, Poe's poem 'The Raven' was published and became an instant success.",
      "date": "1845-01"
    },
    {
      "headline": "Death of Virginia Clemm Poe",
      "text": "On January 30, 1847, Poe's wife, Virginia Clemm Poe, died of tuberculosis.",
      "date": "1847-01-30"
    },
    {
      "headline": "Death of Edgar Allan Poe",
      "text": "Edgar Allan Poe died on October 7, 1849, in Baltimore, Maryland, under mysterious circumstances.",
      "date": "1849-10-07"
    }
  ]
}

