{
  "timeline": [
    {
      "headline": "Early Settlements",
      "text": "The region of modern-day Syria has been inhabited since prehistoric times, with evidence of human settlement dating back to the Neolithic period.",
      "date": "-10000"
    },
    {
      "headline": "Ancient Kingdoms",
      "text": "Syria was home to several ancient kingdoms and empires, including the Eblaite, Amorite, and Aramean kingdoms, from around 3000 BCE.",
      "date": "-3000"
    },
    {
      "headline": "Assyrian and Babylonian Rule",
      "text": "Syria was part of the Assyrian Empire from the 9th century BCE and later the Neo-Babylonian Empire.",
      "date": "-0900"
    },
    {
      "headline": "Persian Empire",
      "text": "In 539 BCE, Syria became part of the Achaemenid Persian Empire under Cyrus the Great.",
      "date": "-0539"
    },
    {
      "headline": "Alexander the Great",
      "text": "Syria was conquered by Alexander the Great in 333 BCE, becoming part of the Hellenistic world.",
      "date": "-0333"
    },
    {
      "headline": "Roman and Byzantine Rule",
      "text": "Syria became a Roman province in 64 BCE and later part of the Byzantine Empire after the division of the Roman Empire.",
      "date": "-0064"
    },
    {
      "headline": "Islamic Conquest",
      "text": "In 637 CE, Syria was conquered by Muslim Arab forces, becoming part of the Umayyad Caliphate with Damascus as its capital.",
      "date": "0637"
    },
    {
      "headline": "Ottoman Empire",
      "text": "Syria became part of the Ottoman Empire in 1516, remaining under Ottoman rule until the end of World War I.",
      "date": "1516"
    },
    {
      "headline": "French Mandate",
      "text": "Following the defeat of the Ottoman Empire in World War I, Syria was placed under French mandate in 1920.",
      "date": "1920"
    },
    {
      "headline": "Independence",
      "text": "Syria gained independence from France on April 17, 1946.",
      "date": "1946-04-17"
    },
    {
      "headline": "Ba'ath Party Coup",
      "text": "The Ba'ath Party came to power in Syria through a coup on March 8, 1963.",
      "date": "1963-03-08"
    },
    {
      "headline": "Hafez al-Assad's Presidency",
      "text": "Hafez al-Assad became President of Syria on March 13, 1971, after a coup in 1970.",
      "date": "1971-03-13"
    },
    {
      "headline": "Bashar al-Assad's Presidency",
      "text": "Bashar al-Assad became President of Syria on July 17, 2000, following the death of his father, Hafez al-Assad.",
      "date": "2000-07-17"
    },
    {
      "headline": "Syrian Civil War",
      "text": "The Syrian Civil War began in March 2011, following nationwide protests against the Assad government.",
      "date": "2011-03"
    }
  ]
}

