{
  "timeline": [
    {
      "headline": "Birth of Jesus",
      "text": "According to Christian tradition, Jesus was born in Bethlehem. The exact date is not known, but it is traditionally celebrated on December 25th.",
      "date": "-0004"
    },
    {
      "headline": "Crucifixion of Jesus",
      "text": "Jesus was crucified under the Roman governor Pontius Pilate. This event is central to Christian belief, as it is followed by the resurrection of Jesus. The crucifixion is estimated to have occurred around 30-33 AD.",
      "date": "0030"
    },
    {
      "headline": "Resurrection of Jesus",
      "text": "Christians believe that Jesus rose from the dead on the third day after his crucifixion, an event celebrated as Easter.",
      "date": "0030"
    },
    {
      "headline": "Council of Jerusalem",
      "text": "Around 50 AD, the Council of Jerusalem was held, which addressed the issue of whether Gentile converts to Christianity needed to follow Jewish law.",
      "date": "0050"
    },
    {
      "headline": "Edict of Milan",
      "text": "In 313 AD, the Edict of Milan was issued by Emperor Constantine, granting religious tolerance for Christianity within the Roman Empire.",
      "date": "0313"
    },
    {
      "headline": "First Council of Nicaea",
      "text": "In 325 AD, the First Council of Nicaea was convened by Emperor Constantine to address the Arian controversy and resulted in the Nicene Creed.",
      "date": "0325"
    },
    {
      "headline": "Christianity becomes the state religion of the Roman Empire",
      "text": "In 380 AD, Emperor Theodosius I declared Christianity as the state religion of the Roman Empire with the Edict of Thessalonica.",
      "date": "0380"
    },
    {
      "headline": "Great Schism",
      "text": "In 1054, the Great Schism occurred, dividing Christianity into the Roman Catholic Church in the West and the Orthodox Church in the East.",
      "date": "1054"
    },
    {
      "headline": "Protestant Reformation",
      "text": "Beginning in 1517, the Protestant Reformation was initiated by Martin Luther's Ninety-Five Theses, leading to the formation of Protestant churches.",
      "date": "1517"
    },
    {
      "headline": "Council of Trent",
      "text": "Held between 1545 and 1563, the Council of Trent was a major Catholic council that addressed issues raised by the Protestant Reformation and reformed church practices.",
      "date": "1545"
    },
    {
      "headline": "Second Vatican Council",
      "text": "The Second Vatican Council, held from 1962 to 1965, was a significant ecumenical council of the Catholic Church that modernized many church practices.",
      "date": "1962"
    }
  ]
}

{
  "timeline": [
