    {
      "headline": "Earliest Known Use of Swastika",
      "text": "The swastika symbol dates back to the Neolithic period, with the earliest known use around 10,000 BCE. It has been found in various archaeological sites across Europe and Asia.",
      "date": "-10000"
    },
    {
      "headline": "Swastika in Ancient Indian Religions",
      "text": "In ancient Indian religions, the swastika has been used as a symbol of divinity and spirituality. It is prominently featured in Hinduism, Buddhism, and Jainism, representing good fortune and auspiciousness.",
      "date": "-1500"
    },
    {
      "headline": "Swastika in Ancient Greece",
      "text": "The swastika was used in Ancient Greece, where it was known as the 'gammadion' or 'tetraskelion'. It appeared in various forms on pottery and architecture.",
      "date": "-800"
    },
    {
      "headline": "Swastika in Early Christian Art",
      "text": "The swastika appeared in early Christian art and architecture, often used as a symbol of Christ or eternity.",
      "date": "0300"
    },
    {
      "headline": "Swastika in Native American Cultures",
      "text": "The swastika was used by various Native American tribes as a symbol of life, sun, power, and strength.",
      "date": "1000"
    },
    {
      "headline": "Adoption by the German Nazi Party",
      "text": "In the early 20th century, the swastika was adopted by the German Nazi Party as a symbol of Aryan identity and German nationalist pride. It became the official emblem of the Nazi Party in 1920.",
      "date": "1920"
    },
    {
      "headline": "Swastika in Nazi Germany",
      "text": "During the Nazi regime (1933-1945), the swastika was used extensively in propaganda, flags, and insignia, becoming a symbol of hate and anti-Semitism.",
      "date": "1933"
    },
    {
      "headline": "Post-World War II Perception",
      "text": "After World War II, the swastika became widely associated with the atrocities of the Nazi regime, leading to its ban in several countries and its perception as a symbol of hate.",
      "date": "1945"
    },
    {
      "headline": "Contemporary Use in Indian Religions",
      "text": "Despite its negative connotations in the West, the swastika continues to be used in Indian religions as a symbol of good fortune and auspiciousness.",
      "date": "2023"
    }
  ]
}

