    },
    {
      "headline": "Viceroyalty of New Granada Established",
      "text": "In 1717, the Viceroyalty of New Granada was established, which included present-day Colombia, Venezuela, Ecuador, and Panama.",
      "date": "1717"
    },
    {
      "headline": "Independence from Spain",
      "text": "Colombia declared independence from Spain on July 20, 1810, marking the beginning of a long struggle for independence.",
      "date": "1810-07-20"
    },
    {
      "headline": "Battle of Boyacá",
      "text": "On August 7, 1819, the Battle of Boyacá took place, leading to a decisive victory for the independence forces under Simón Bolívar.",
      "date": "1819-08-07"
    },
    {
      "headline": "Gran Colombia Established",
      "text": "In 1819, the Republic of Gran Colombia was established, uniting Colombia, Venezuela, Ecuador, and Panama under one government.",
      "date": "1819"
    },
    {
      "headline": "Dissolution of Gran Colombia",
      "text": "In 1831, Gran Colombia was dissolved, leading to the formation of the Republic of New Granada, which later became Colombia.",
      "date": "1831"
    },
    {
      "headline": "Thousand Days' War",
      "text": "From 1899 to 1902, the Thousand Days' War was fought between the Liberal and Conservative parties, resulting in significant loss of life and economic disruption.",
      "date": "1899"
    },
    {
      "headline": "Separation of Panama",
      "text": "On November 3, 1903, Panama seceded from Colombia with the support of the United States.",
      "date": "1903-11-03"
    },
    {
      "headline": "La Violencia",
      "text": "La Violencia was a period of civil conflict in Colombia from 1948 to 1958, resulting in the deaths of an estimated 200,000 people.",
      "date": "1948"
    },
    {
      "headline": "Colombian Constitution of 1991",
      "text": "On July 4, 1991, a new Colombian Constitution was enacted, introducing significant political and social reforms.",
      "date": "1991-07-04"
    },
    {
      "headline": "Peace Agreement with FARC",
      "text": "On November 24, 2016, the Colombian government signed a peace agreement with the FARC, ending over 50 years of conflict.",
      "date": "2016-11-24"
    }
  ]
}

