      "headline": "Battle of Bunker Hill",
      "text": "The Battle of Bunker Hill was fought on June 17, 1775, during the Siege of Boston and was one of the early battles of the American Revolutionary War.",
      "date": "1775-06-17"
    },
    {
      "headline": "Declaration of Independence",
      "text": "The United States Declaration of Independence was adopted by the Continental Congress on July 4, 1776, declaring the thirteen American colonies as independent states, free from British rule.",
      "date": "1776-07-04"
    },
    {
      "headline": "Battle of Saratoga",
      "text": "The Battle of Saratoga was a turning point in the Revolutionary War, fought in two stages on September 19 and October 7, 1777, resulting in a decisive American victory.",
      "date": "1777-09-19"
    },
    {
      "headline": "France Enters the War",
      "text": "On February 6, 1778, France signed a treaty of alliance with the United States, entering the war against Britain.",
      "date": "1778-02-06"
    },
    {
      "headline": "Siege of Yorktown",
      "text": "The Siege of Yorktown, from September 28 to October 19, 1781, was the last major land battle of the American Revolutionary War, resulting in the surrender of British General Cornwallis.",
      "date": "1781-09-28"
    },
    {
      "headline": "Treaty of Paris Signed",
      "text": "The Treaty of Paris was signed on September 3, 1783, officially ending the American Revolutionary War and recognizing the independence of the United States.",
      "date": "1783-09-03"
    }
  ]
}

