{
  "timeline": [
    {
      "headline": "Start of The Troubles",
      "text": "The Troubles began in the late 1960s, marked by civil rights protests by the Catholic minority in Northern Ireland against discrimination by the Protestant majority.",
      "date": "1968"
    },
    {
      "headline": "Battle of the Bogside",
      "text": "The Battle of the Bogside was a major riot that took place in Derry, Northern Ireland, from 12 to 14 August 1969. It was a pivotal event in the escalation of The Troubles.",
      "date": "1969-08-12"
    },
    {
      "headline": "British Army Deployment",
      "text": "The British Army was deployed to Northern Ireland on 14 August 1969 to restore order following the Battle of the Bogside.",
      "date": "1969-08-14"
    },
    {
      "headline": "Bloody Sunday",
      "text": "On 30 January 1972, British soldiers shot 26 unarmed civilians during a protest march in Derry, Northern Ireland. This event became known as Bloody Sunday.",
      "date": "1972-01-30"
    },
    {
      "headline": "Sunningdale Agreement",
      "text": "The Sunningdale Agreement was an attempt to establish a power-sharing Northern Ireland Executive and a cross-border Council of Ireland. It was signed in December 1973 but collapsed in May 1974.",
      "date": "1973-12"
    },
    {
      "headline": "Birmingham Pub Bombings",
      "text": "On 21 November 1974, two bombs exploded in pubs in Birmingham, England, killing 21 people and injuring 182. The IRA was blamed for the attacks.",
      "date": "1974-11-21"
    },
    {
      "headline": "Hunger Strikes",
      "text": "In 1981, Irish republican prisoners in Northern Ireland's Maze Prison went on hunger strike to protest against the removal of Special Category Status. Ten prisoners died, including Bobby Sands.",
      "date": "1981"
    },
    {
      "headline": "Anglo-Irish Agreement",
      "text": "The Anglo-Irish Agreement was signed on 15 November 1985 by the British and Irish governments, giving the Irish government an advisory role in Northern Ireland's affairs.",
      "date": "1985-11-15"
    },
    {
      "headline": "Downing Street Declaration",
      "text": "On 15 December 1993, the British and Irish governments issued the Downing Street Declaration, which affirmed the right of the people of Ireland to self-determination.",
      "date": "1993-12-15"
    },
    {
      "headline": "IRA Ceasefire",
      "text": "The Provisional Irish Republican Army (IRA) declared a ceasefire on 31 August 1994, marking a significant step towards peace.",
      "date": "1994-08-31"
    },
    {
      "headline": "Good Friday Agreement",
      "text": "The Good Friday Agreement, also known as the Belfast Agreement, was signed on 10 April 1998. It was a major political development that helped bring an end to The Troubles.",
      "date": "1998-04-10"
    }
  ]
}

{
