      "headline": "QR Code Popularity Surge",
      "text": "During the COVID-19 pandemic in 2020, QR codes saw a significant increase in usage for contactless transactions, menus, and information sharing to reduce physical contact.",
      "date": "2020"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Hijacking of Indian Airlines Flight 814",
      "text": "On 24 December 1999, Indian Airlines Flight 814, an Airbus A300, was hijacked by five members of Harkat-ul-Mujahideen. The flight was en route from Kathmandu to Delhi when it was taken over shortly after entering Indian airspace at about 16:53 IST.",
      "date": "1999-12-24"
    },
    {
      "headline": "Landing in Amritsar",
      "text": "After being hijacked, Flight 814 landed in Amritsar, India, but was not refueled due to a delay in decision-making by Indian authorities.",
      "date": "1999-12-24"
    },
    {
      "headline": "Landing in Lahore",
      "text": "The hijacked aircraft was diverted to Lahore, Pakistan, where it landed and was refueled.",
      "date": "1999-12-24"
    },
    {
      "headline": "Landing in Dubai",
      "text": "Flight 814 landed in Dubai, United Arab Emirates, where 27 passengers were released, including a critically injured passenger who was stabbed by the hijackers.",
      "date": "1999-12-25"
    },
    {
      "headline": "Landing in Kandahar",
      "text": "The hijacked plane finally landed in Kandahar, Afghanistan, which was under Taliban control at the time.",
      "date": "1999-12-25"
    },
    {
      "headline": "Negotiations and Release",
      "text": "After a week of negotiations, the Indian government agreed to release three militants in exchange for the hostages. The hostages were released on 31 December 1999.",
      "date": "1999-12-31"
    },
    {
      "headline": "Return of Hostages",
      "text": "The hostages returned to India on 31 December 1999, marking the end of the hijacking crisis.",
      "date": "1999-12-31"
    }
  ]
}

