{
  "timeline": [
    {
      "headline": "Adoption of Article 370",
      "text": "Article 370 was adopted in the Indian Constitution on 1949-10-17, granting special autonomy to the state of Jammu and Kashmir.",
      "date": "1949-10-17"
    },
    {
      "headline": "Jammu and Kashmir's Constitution Comes into Effect",
      "text": "On 1957-01-26, the Constitution of Jammu and Kashmir came into effect, further solidifying the state's special status under Article 370.",
      "date": "1957-01-26"
    },
    {
      "headline": "Presidential Order of 1954",
      "text": "On 1954-05-14, a Presidential Order was issued, extending Indian citizenship to the 'permanent residents' of Jammu and Kashmir, among other provisions.",
      "date": "1954-05-14"
    },
    {
      "headline": "Sheikh Abdullah's Dismissal and Arrest",
      "text": "In 1953, Sheikh Abdullah, the then Prime Minister of Jammu and Kashmir, was dismissed and arrested, leading to political instability in the region.",
      "date": "1953"
    },
    {
      "headline": "Indira-Sheikh Accord",
      "text": "In 1975, the Indira-Sheikh Accord was signed, leading to the return of Sheikh Abdullah as the Chief Minister of Jammu and Kashmir.",
      "date": "1975"
    },
    {
      "headline": "Jammu and Kashmir Reorganization Act",
      "text": "On 2019-08-05, the Government of India abrogated Article 370, revoking the special status of Jammu and Kashmir and bifurcating the state into two Union Territories.",
      "date": "2019-08-05"
    },
    {
      "headline": "End of Statehood for Jammu and Kashmir",
      "text": "On 2019-10-31, Jammu and Kashmir ceased to be a state and was reorganized into two Union Territories: Jammu and Kashmir, and Ladakh.",
      "date": "2019-10-31"
    }
  ]
}

