    {
      "headline": "Wilson's Education",
      "text": "Wilson attended Davidson College in 1873 and later transferred to Princeton University, where he graduated in 1879.",
      "date": "1879"
    },
    {
      "headline": "Wilson Earns Ph.D.",
      "text": "Wilson earned his Ph.D. in political science from Johns Hopkins University in 1886, becoming the only U.S. president to hold a doctorate.",
      "date": "1886"
    },
    {
      "headline": "President of Princeton University",
      "text": "Wilson became the president of Princeton University in 1902, where he implemented significant educational reforms.",
      "date": "1902"
    },
    {
      "headline": "Governor of New Jersey",
      "text": "Wilson was elected as the Governor of New Jersey in 1910, where he gained a reputation as a progressive reformer.",
      "date": "1910"
    },
    {
      "headline": "Elected President of the United States",
      "text": "Wilson was elected as the 28th President of the United States in 1912, defeating incumbent President William Howard Taft and former President Theodore Roosevelt.",
      "date": "1912"
    },
    {
      "headline": "Federal Reserve Act",
      "text": "Wilson signed the Federal Reserve Act into law on December 23, 1913, establishing the Federal Reserve System.",
      "date": "1913-12-23"
    },
    {
      "headline": "World War I and U.S. Entry",
      "text": "Wilson led the United States into World War I on April 6, 1917, after initially maintaining a policy of neutrality.",
      "date": "1917-04-06"
    },
    {
      "headline": "Fourteen Points Speech",
      "text": "On January 8, 1918, Wilson delivered his Fourteen Points speech, outlining his vision for post-war peace and the establishment of the League of Nations.",
      "date": "1918-01-08"
    },
    {
      "headline": "Treaty of Versailles",
      "text": "Wilson played a key role in negotiating the Treaty of Versailles, signed on June 28, 1919, which officially ended World War I.",
      "date": "1919-06-28"
    },
    {
      "headline": "Stroke and Decline in Health",
      "text": "Wilson suffered a debilitating stroke on October 2, 1919, which left him partially paralyzed and significantly impaired his ability to govern.",
      "date": "1919-10-02"
    },
    {
      "headline": "End of Presidency",
      "text": "Wilson's presidency ended on March 4, 1921, after serving two terms.",
      "date": "1921-03-04"
    },
    {
      "headline": "Death of Woodrow Wilson",
      "text": "Wilson died on February 3, 1924, in Washington, D.C., at the age of 67.",
      "date": "1924-02-03"
    }
  ]
}

