      "headline": "First Mention of Belarusian Lands",
      "text": "The lands of modern-day Belarus were first mentioned in historical records in the 9th century as part of the Kievan Rus'.",
      "date": "0900"
    },
    {
      "headline": "Grand Duchy of Lithuania",
      "text": "By the 13th century, the territories of modern Belarus were incorporated into the Grand Duchy of Lithuania.",
      "date": "1300"
    },
    {
      "headline": "Union of Lublin",
      "text": "In 1569, the Union of Lublin was signed, creating the Polish-Lithuanian Commonwealth, which included Belarusian lands.",
      "date": "1569"
    },
    {
      "headline": "Partitions of Poland",
      "text": "In the late 18th century, the partitions of Poland resulted in Belarusian territories being annexed by the Russian Empire.",
      "date": "1795"
    },
    {
      "headline": "Belarusian People's Republic",
      "text": "On March 25, 1918, the Belarusian People's Republic was declared, but it was short-lived.",
      "date": "1918-03-25"
    },
    {
      "headline": "Belarusian Soviet Socialist Republic",
      "text": "In 1919, the Belarusian Soviet Socialist Republic was established as part of the Soviet Union.",
      "date": "1919"
    },
    {
      "headline": "Nazi Occupation",
      "text": "During World War II, Belarus was occupied by Nazi Germany from 1941 to 1944.",
      "date": "1941"
    },
    {
      "headline": "Liberation and Soviet Era",
      "text": "Belarus was liberated by Soviet forces in 1944 and remained a part of the Soviet Union until its dissolution.",
      "date": "1944"
    },
    {
      "headline": "Independence from Soviet Union",
      "text": "Belarus declared independence from the Soviet Union on August 25, 1991.",
      "date": "1991-08-25"
    },
