{
  "timeline": [
    {
      "headline": "Composition of the Rigveda",
      "text": "The Rigveda, one of the oldest known Vedic texts, is composed around 1500 BCE. It is a collection of hymns dedicated to various deities and forms the basis of Vedic religion.",
      "date": "-1500"
    },
    {
      "headline": "Composition of the Upanishads",
      "text": "The Upanishads, philosophical texts that explore the concepts of Brahman and Atman, are composed between 800 BCE and 500 BCE. They mark a shift from ritualistic practices to philosophical inquiry.",
      "date": "-0800"
    },
    {
      "headline": "Rise of the Mahajanapadas",
      "text": "Around 600 BCE, the rise of the Mahajanapadas, large kingdoms in ancient India, leads to the development of new religious and philosophical ideas, including those found in Hinduism.",
      "date": "-0600"
    },
    {
      "headline": "Composition of the Bhagavad Gita",
      "text": "The Bhagavad Gita, a 700-verse Hindu scripture that is part of the Indian epic Mahabharata, is composed around 200 BCE. It is a conversation between Prince Arjuna and the god Krishna, who serves as his charioteer.",
      "date": "-0200"
    },
    {
      "headline": "Gupta Empire and the Classical Age",
      "text": "From 320 CE to 550 CE, the Gupta Empire rules over much of India. This period is considered a 'Golden Age' of Hindu culture, with significant developments in art, architecture, and philosophy.",
      "date": "0320"
    },
    {
      "headline": "Composition of the Puranas",
      "text": "The Puranas, a genre of ancient Indian literature encompassing mythological stories, traditions, and legends, are composed between 300 CE and 1000 CE. They play a crucial role in the development of Hindu religious practices.",
      "date": "0300"
    },
    {
      "headline": "Bhakti Movement",
      "text": "Starting around the 7th century CE, the Bhakti movement emerges in South India and spreads northwards. It emphasizes personal devotion to deities and challenges the caste system.",
      "date": "0700"
    },
    {
      "headline": "Establishment of the Vijayanagara Empire",
      "text": "In 1336, the Vijayanagara Empire is established in South India. It becomes a significant center for Hindu culture and religion, promoting temple construction and Sanskrit literature.",
      "date": "1336"
    },
    {
      "headline": "British Colonial Rule",
      "text": "From the 18th century onwards, British colonial rule in India impacts Hindu society and religion, leading to reform movements such as the Brahmo Samaj and Arya Samaj.",
      "date": "1757"
    },
    {
      "headline": "Indian Independence",
      "text": "In 1947, India gains independence from British rule. Hinduism continues to evolve in the modern era, influencing and being influenced by global cultural exchanges.",
      "date": "1947"
    }
  ]
}

