    {
      "headline": "Eisenhower and Nixon Reelected",
      "text": "Incumbent Republican President Dwight D. Eisenhower and his running mate, incumbent Vice President Richard Nixon, were reelected, defeating Democrat Adlai Stevenson II, former Illinois governor, for a second time.",
      "date": "1956-11-06"
    },
    {
      "headline": "Sixth Rematch in American Presidential History",
      "text": "This election was the sixth and most recent rematch in American presidential history. It was the second time in which the winner was the same both times, the first being William McKinley's victories over William Jennings Bryan in 1896 and 1900.",
      "date": "1956-11-06"
    },
    {
      "headline": "Last Election Before Term Limits",
      "text": "This was the last election before term limits established by the Twenty-second Amendment to the United States Constitution, which first applied to Eisenhower, became effective.",
      "date": "1956-11-06"
    }
  ]
}

