{
  "timeline": [
    {
      "headline": "Hijacking of Northwest Orient Airlines Flight 305",
      "text": "On November 24, 1971, an unidentified man known as D. B. Cooper hijacked Northwest Orient Airlines Flight 305, a Boeing 727 aircraft, during its flight from Portland, Oregon, to Seattle, Washington. He informed a flight attendant that he had a bomb and demanded $200,000 in ransom and four parachutes.",
      "date": "1971-11-24"
    },
    {
      "headline": "Ransom and Release of Passengers",
      "text": "Upon landing in Seattle, Cooper received the ransom money and parachutes. He then released the 36 passengers in exchange for the ransom and instructed the flight crew to refuel the aircraft for a second flight to Mexico City, with a planned refueling stop in Reno, Nevada.",
      "date": "1971-11-24"
    },
    {
      "headline": "Parachute Jump",
      "text": "Approximately thirty minutes after taking off from Seattle, Cooper opened the aircraft's aft door and deployed the staircase. He parachuted into the night over southwestern Washington, disappearing without a trace.",
      "date": "1971-11-24"
    },
    {
      "headline": "Investigation and Search",
      "text": "Following the hijacking, a massive manhunt and investigation were launched by the FBI, but Cooper's true identity and whereabouts have never been conclusively determined. The case remains one of the greatest unsolved mysteries in U.S. history.",
      "date": "1971"
    }
  ]
}

