      "headline": "Construction of the First Temple",
      "text": "King Solomon, David's son, built the First Temple in Jerusalem around 957 BCE.",
      "date": "-0957"
    },
    {
      "headline": "Destruction of the First Temple",
      "text": "The First Temple was destroyed by the Babylonians under King Nebuchadnezzar II in 586 BCE.",
      "date": "-0586"
    },
    {
      "headline": "Construction of the Second Temple",
      "text": "The Second Temple was completed in 516 BCE after the return of the Jewish exiles from Babylon.",
      "date": "-0516"
    },
    {
      "headline": "Roman Siege and Destruction of the Second Temple",
      "text": "In 70 CE, the Romans besieged Jerusalem and destroyed the Second Temple.",
      "date": "0070"
    },
    {
      "headline": "Byzantine Period",
      "text": "Jerusalem became a Christian city under Byzantine rule starting in 324 CE.",
      "date": "0324"
    },
    {
      "headline": "Muslim Conquest",
      "text": "In 638 CE, Jerusalem was conquered by Muslim forces under Caliph Umar.",
      "date": "0638"
    },
    {
      "headline": "Crusader Control",
      "text": "The First Crusade captured Jerusalem in 1099 CE, establishing the Kingdom of Jerusalem.",
      "date": "1099"
    },
    {
      "headline": "Ayyubid Recapture",
      "text": "Saladin recaptured Jerusalem from the Crusaders in 1187 CE.",
      "date": "1187"
    },
    {
      "headline": "Ottoman Rule",
      "text": "The Ottoman Empire took control of Jerusalem in 1517 CE and ruled until 1917 CE.",
      "date": "1517"
