    {
      "headline": "Ancient Kingdom of Paeonia",
      "text": "The region now known as North Macedonia was part of the ancient kingdom of Paeonia, inhabited by the Paeonians, a Thracian people.",
      "date": "-0500"
    },
    {
      "headline": "Conquest by Philip II of Macedon",
      "text": "In 356 BCE, the region was conquered by Philip II of Macedon, father of Alexander the Great, and became part of the Macedonian Empire.",
      "date": "-0356"
    },
    {
      "headline": "Roman Conquest",
      "text": "The region was conquered by the Roman Republic in 168 BCE and became part of the Roman province of Macedonia.",
      "date": "-0168"
    },
    {
      "headline": "Byzantine Rule",
      "text": "After the division of the Roman Empire in 395 CE, the region became part of the Byzantine Empire.",
      "date": "0395"
    },
    {
      "headline": "Slavic Settlement",
      "text": "In the 6th and 7th centuries, Slavic tribes settled in the region, significantly influencing its demographic and cultural landscape.",
      "date": "0600"
    },
    {
      "headline": "First Bulgarian Empire",
      "text": "In the late 9th century, the region became part of the First Bulgarian Empire.",
      "date": "0890"
    },
    {
      "headline": "Ottoman Rule",
      "text": "The region fell under Ottoman rule in the late 14th century and remained part of the Ottoman Empire for over five centuries.",
      "date": "1395"
    },
    {
      "headline": "Balkan Wars",
      "text": "During the Balkan Wars of 1912-1913, the region was divided between Serbia, Greece, and Bulgaria.",
      "date": "1912"
    },
    {
      "headline": "Part of Yugoslavia",
      "text": "After World War I, the region became part of the Kingdom of Serbs, Croats, and Slovenes, later known as Yugoslavia.",
      "date": "1918"
    },
    {
      "headline": "Socialist Republic of Macedonia",
      "text": "In 1944, the People's Republic of Macedonia was established as one of the constituent republics of the Socialist Federal Republic of Yugoslavia.",
      "date": "1944"
    },
    {
      "headline": "Independence from Yugoslavia",
      "text": "North Macedonia declared independence from Yugoslavia on September 8, 1991, following a referendum.",
      "date": "1991-09-08"
    },
    {
      "headline": "Ohrid Framework Agreement",
      "text": "In 2001, the Ohrid Framework Agreement was signed, ending the conflict between ethnic Albanian insurgents and Macedonian security forces.",
      "date": "2001"
    },
    {
      "headline": "Name Change to North Macedonia",
      "text": "On June 17, 2018, the Prespa Agreement was signed with Greece, leading to the country's name change to North Macedonia, which took effect on February 12, 2019.",
