      "headline": "Final Landfall in Mississippi",
      "text": "Katrina made its final landfall near the Louisiana-Mississippi border on August 29, 2005.",
      "date": "2005-08-29"
    },
    {
      "headline": "Dissipation",
      "text": "Hurricane Katrina weakened and was downgraded to a tropical depression on August 30, 2005, before dissipating over the Tennessee Valley on August 31, 2005.",
      "date": "2005-08-31"
    },
