{
  "timeline": [
    {
      "headline": "Birth of Pablo Picasso",
      "text": "Pablo Picasso was born on October 25, 1881, in Málaga, Spain.",
      "date": "1881-10-25"
    },
    {
      "headline": "Blue Period Begins",
      "text": "In 1901, Picasso began his Blue Period, characterized by somber paintings rendered in shades of blue and blue-green.",
      "date": "1901"
    },
    {
      "headline": "Rose Period Begins",
      "text": "Around 1904, Picasso's Rose Period began, marked by a lighter palette and featuring circus performers and harlequins.",
      "date": "1904"
    },
    {
      "headline": "Les Demoiselles d'Avignon",
      "text": "In 1907, Picasso painted Les Demoiselles d'Avignon, a proto-Cubist work that challenged traditional representation in art.",
      "date": "1907"
    },
    {
      "headline": "Co-founding of Cubism",
      "text": "Between 1907 and 1914, Picasso, along with Georges Braque, developed Cubism, a revolutionary new style of painting.",
      "date": "1907"
    },
    {
      "headline": "Invention of Constructed Sculpture",
      "text": "In 1912, Picasso invented constructed sculpture, which involved assembling disparate elements to create a three-dimensional work.",
      "date": "1912"
    },
    {
      "headline": "Co-invention of Collage",
      "text": "Picasso co-invented collage in 1912, a technique that involves assembling different forms to create a new whole.",
      "date": "1912"
    },
    {
      "headline": "Creation of Guernica",
      "text": "In 1937, Picasso painted Guernica, a powerful anti-war painting depicting the bombing of Guernica during the Spanish Civil War.",
      "date": "1937"
    },
    {
      "headline": "Death of Pablo Picasso",
      "text": "Pablo Picasso died on April 8, 1973, in Mougins, France.",
      "date": "1973-04-08"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Departure from Independence, Missouri",
      "text": "The Donner Party departed from Independence, Missouri, on May 12, 1846, beginning their journey to California.",
      "date": "1846-05-12"
    },
    {
      "headline": "Decision to Take Hastings Cutoff",
      "text": "In July 1846, the Donner Party decided to take the Hastings Cutoff, a new and untested route that was supposed to shorten the journey to California.",
      "date": "1846-07"
    },
    {
      "headline": "Arrival at Great Salt Lake Desert",
      "text": "In August 1846, the Donner Party arrived at the Great Salt Lake Desert, where they faced significant delays and hardships.",
      "date": "1846-08"
    },
    {
      "headline": "Reaching Truckee Lake",
      "text": "On October 31, 1846, the Donner Party reached Truckee Lake (now Donner Lake) in the Sierra Nevada, where they were trapped by early snowfall.",
      "date": "1846-10-31"
    },
    {
      "headline": "First Attempt to Cross the Pass",
      "text": "On November 4, 1846, the Donner Party made their first attempt to cross the Sierra Nevada pass but were forced to turn back due to heavy snow.",
      "date": "1846-11-04"
    },
    {
      "headline": "The Forlorn Hope Expedition",
      "text": "On December 16, 1846, a group of 15 members, later known as the 'Forlorn Hope,' set out on snowshoes to seek help.",
      "date": "1846-12-16"
    },
    {
      "headline": "Rescue of the First Survivors",
      "text": "The first rescue party reached the Donner Party on February 19, 1847, and began evacuating survivors.",
      "date": "1847-02-19"
    },
    {
      "headline": "Final Rescue of Survivors",
      "text": "The last of the Donner Party survivors were rescued on April 17, 1847, ending the ordeal.",
      "date": "1847-04-17"
    }
  ]
}

