{
  "timeline": [
    {
      "headline": "Formation of the Solar System",
      "text": "The Solar System formed approximately 4.6 billion years ago from the gravitational collapse of a region within a large molecular cloud. This event led to the formation of the Sun and a surrounding protoplanetary disc.",
      "date": "-4600000000"
    },
    {
      "headline": "Formation of the Sun",
      "text": "The Sun formed at the center of the collapsing molecular cloud, becoming a G-type main-sequence star. It maintains equilibrium by fusing hydrogen into helium at its core.",
      "date": "-4600000000"
    },
    {
      "headline": "Formation of the Protoplanetary Disc",
      "text": "Alongside the Sun, a protoplanetary disc formed, consisting of gas and dust. This disc eventually coalesced into the planets, moons, asteroids, and other bodies in the Solar System.",
      "date": "-4600000000"
    },
    {
      "headline": "Differentiation of the Planets",
      "text": "Over millions of years, the protoplanetary disc differentiated into the various planets and other celestial bodies, with rocky planets forming closer to the Sun and gas giants forming further away.",
      "date": "-4500000000"
    },
    {
      "headline": "Stabilization of the Solar System",
      "text": "The Solar System gradually stabilized into its current configuration, with the planets settling into their orbits around the Sun.",
      "date": "-4000000000"
    }
  ]
}

