    {
      "headline": "Conceptualization of HDI",
      "text": "The Human Development Index (HDI) was conceptualized by Pakistani economist Mahbub ul-Haq, who aimed to create a more comprehensive measure of development that goes beyond economic growth.",
      "date": "1980"
    },
    {
      "headline": "First Human Development Report",
      "text": "The first Human Development Report was published by the United Nations Development Programme (UNDP) in 1990, introducing the Human Development Index as a new way to measure and rank countries' levels of social and economic development.",
      "date": "1990"
    },
    {
      "headline": "Introduction of HDI Components",
      "text": "The HDI was introduced as a composite index measuring average achievement in three basic dimensions of human development: life expectancy, education (mean years of schooling and expected years of schooling), and per capita income.",
      "date": "1990"
    },
    {
      "headline": "HDI Revision",
      "text": "In 2010, the HDI was revised to include new indicators and methodologies, such as the geometric mean of normalized indices for each of the three dimensions, to better reflect inequalities in human development.",
      "date": "2010"
    },
    {
      "headline": "Annual Human Development Reports",
      "text": "Since its inception, the HDI has been featured in annual Human Development Reports published by the UNDP, providing updates and insights into global human development trends.",
      "date": "1990"
    }
  ]
}

