    {
      "headline": "Enlightenment of the Buddha",
      "text": "Siddhartha Gautama attained enlightenment under the Bodhi tree in Bodh Gaya, India, at the age of 35, becoming the Buddha.",
      "date": "-0528"
    },
    {
      "headline": "First Sermon at Sarnath",
      "text": "The Buddha delivered his first sermon at Deer Park in Sarnath, India, setting in motion the Wheel of Dharma.",
      "date": "-0528"
    },
    {
      "headline": "Formation of the Sangha",
      "text": "The Buddha established the Sangha, a community of monks and nuns, to spread his teachings.",
      "date": "-0528"
    },
    {
      "headline": "Death of the Buddha",
      "text": "The Buddha passed away at the age of 80 in Kushinagar, India, entering Parinirvana.",
      "date": "-0483"
    },
    {
      "headline": "First Buddhist Council",
      "text": "Held shortly after the Buddha's death, the First Buddhist Council was convened to preserve his teachings.",
      "date": "-0483"
    },
    {
      "headline": "Second Buddhist Council",
      "text": "The Second Buddhist Council was held approximately 100 years after the Buddha's death to address disputes within the Sangha.",
      "date": "-0373"
    },
    {
      "headline": "Reign of Emperor Ashoka",
      "text": "Emperor Ashoka, who ruled much of the Indian subcontinent, converted to Buddhism and helped spread the religion across Asia.",
      "date": "-0268"
    },
    {
      "headline": "Third Buddhist Council",
      "text": "Convened by Emperor Ashoka, the Third Buddhist Council aimed to purify the Sangha and compile the Buddhist teachings.",
      "date": "-0247"
    },
    {
      "headline": "Buddhism spreads to Sri Lanka",
      "text": "Buddhism was introduced to Sri Lanka by Mahinda, the son of Emperor Ashoka, establishing the Theravada tradition.",
      "date": "-0247"
    },
    {
      "headline": "Buddhism enters China",
      "text": "Buddhism began to spread into China during the Han dynasty, gradually becoming a major religious and cultural force.",
      "date": "0001"
