    {
      "headline": "Outbreak of the Black Death",
      "text": "The Black Death began in 1346 in the region of the Black Sea, likely originating in the Central Asian steppes. It spread through trade routes, reaching Europe by 1347.",
      "date": "1346"
    },
    {
      "headline": "Arrival in Europe",
      "text": "In October 1347, the Black Death arrived in Europe when 12 Genoese trading ships docked at the Sicilian port of Messina. Most sailors aboard the ships were dead, and those still alive were gravely ill.",
      "date": "1347-10"
    },
    {
      "headline": "Spread through Italy",
      "text": "By early 1348, the plague had spread rapidly through Italy, affecting major cities such as Genoa, Venice, and Florence.",
      "date": "1348"
    },
    {
      "headline": "Spread to France and Spain",
      "text": "The Black Death reached France and Spain in 1348, devastating cities like Marseille and Barcelona.",
      "date": "1348"
    },
    {
      "headline": "Impact on England",
      "text": "The plague reached England in June 1348, entering through the port of Melcombe Regis in Dorset. It spread quickly across the country.",
      "date": "1348-06"
    },
    {
      "headline": "Spread to Scandinavia and Eastern Europe",
      "text": "By 1349, the Black Death had spread to Scandinavia and Eastern Europe, affecting Norway, Sweden, and Poland.",
      "date": "1349"
    },
    {
      "headline": "Peak of the Black Death",
      "text": "The Black Death reached its peak in 1349-1350, causing widespread mortality across Europe. It is estimated that up to 50% of the population perished.",
      "date": "1349"
    },
    {
      "headline": "End of the First Wave",
      "text": "By 1353, the first wave of the Black Death had largely subsided, although the plague would reoccur in Europe for centuries.",
      "date": "1353"
    },
    {
      "headline": "Long-term Effects",
      "text": "The Black Death had profound long-term effects on European society, including significant population decline, economic disruption, and social upheaval. It also led to changes in religious attitudes and practices.",
      "date": "1353"
    }
  ]
}

