{
  "timeline": [
    {
      "headline": "Emergence of Rastafari",
      "text": "Rastafari emerged in Jamaica during the 1930s as a new religious and social movement. It was influenced by the teachings of Marcus Garvey and the coronation of Haile Selassie I as Emperor of Ethiopia in 1930.",
      "date": "1930"
    },
    {
      "headline": "Coronation of Haile Selassie I",
      "text": "On November 2, 1930, Ras Tafari Makonnen was crowned as Emperor Haile Selassie I of Ethiopia. This event was seen by many as the fulfillment of a prophecy and played a significant role in the development of the Rastafari movement.",
      "date": "1930-11-02"
    },
    {
      "headline": "Marcus Garvey's Influence",
      "text": "Marcus Garvey, a Jamaican political leader, had a significant influence on the Rastafari movement. His teachings on black empowerment and African repatriation inspired early Rastafarians.",
      "date": "1930s"
    },
    {
      "headline": "Leonard Howell's Role",
      "text": "Leonard Howell, often considered one of the first preachers of Rastafari, established the first Rastafarian community, Pinnacle, in Jamaica in the 1940s.",
      "date": "1940s"
    },
    {
      "headline": "Spread of Rastafari",
      "text": "During the 1950s and 1960s, Rastafari began to spread beyond Jamaica, influenced by the global popularity of reggae music and the international recognition of figures like Bob Marley.",
      "date": "1950s-1960s"
    },
    {
      "headline": "Visit of Haile Selassie I to Jamaica",
      "text": "On April 21, 1966, Haile Selassie I visited Jamaica, an event that was monumental for Rastafarians and is celebrated annually as 'Grounation Day'.",
      "date": "1966-04-21"
    },
    {
      "headline": "Bob Marley's Influence",
      "text": "Bob Marley, a prominent reggae musician and Rastafarian, played a crucial role in popularizing Rastafari globally through his music in the 1970s.",
      "date": "1970s"
    },
    {
      "headline": "Recognition and Growth",
      "text": "By the late 20th century, Rastafari had gained recognition as a legitimate religious movement and continued to grow, with followers worldwide.",
      "date": "1980s-1990s"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Unification of Bhutan",
      "text": "In 1616, Ngawang Namgyal, a Tibetan lama, unified Bhutan and established himself as the first Zhabdrung Rinpoche, creating a distinct Bhutanese identity.",
      "date": "1616"
    },
    {
      "headline": "Establishment of the Dual System of Government",
      "text": "In 1651, Ngawang Namgyal established the dual system of government, combining religious and secular leadership.",
      "date": "1651"
    },
    {
      "headline": "Treaty of Sinchula",
      "text": "In 1865, the Treaty of Sinchula was signed between Bhutan and British India, ceding some Bhutanese territories to the British in exchange for an annual subsidy.",
      "date": "1865"
    },
    {
      "headline": "Establishment of the Monarchy",
      "text": "In 1907, Ugyen Wangchuck was elected as the first hereditary King of Bhutan, marking the establishment of the monarchy.",
      "date": "1907"
    },
    {
      "headline": "Treaty of Punakha",
      "text": "In 1910, the Treaty of Punakha was signed, which allowed Bhutan to maintain its independence while ceding control of its foreign relations to British India.",
      "date": "1910"
    },
    {
      "headline": "Independence from British India",
      "text": "In 1949, Bhutan signed a treaty with newly independent India, regaining control over its foreign relations while maintaining a special relationship with India.",
      "date": "1949"
    },
    {
      "headline": "Introduction of Planned Development",
      "text": "In 1961, Bhutan began its first Five-Year Plan, marking the start of planned economic development.",
      "date": "1961"
    },
    {
      "headline": "Membership in the United Nations",
      "text": "In 1971, Bhutan became a member of the United Nations, further establishing its presence on the international stage.",
      "date": "1971"
    },
    {
      "headline": "Coronation of King Jigme Singye Wangchuck",
      "text": "In 1974, Jigme Singye Wangchuck was crowned as the fourth King of Bhutan, continuing the Wangchuck dynasty.",
      "date": "1974"
    },
    {
      "headline": "Introduction of Gross National Happiness",
      "text": "In the 1970s, King Jigme Singye Wangchuck introduced the concept of Gross National Happiness as a measure of the country's development.",
      "date": "1970s"
    },
    {
      "headline": "Transition to Constitutional Monarchy",
      "text": "In 2008, Bhutan transitioned to a constitutional monarchy with the adoption of its first constitution and the first democratic elections.",
      "date": "2008"
    },
    {
      "headline": "Coronation of King Jigme Khesar Namgyel Wangchuck",
      "text": "In 2008, Jigme Khesar Namgyel Wangchuck was crowned as the fifth King of Bhutan, following the abdication of his father.",
      "date": "2008"
    }
  ]
}

