{
  "timeline": [
    {
      "headline": "Project MKUltra Begins",
      "text": "Project MKUltra was officially sanctioned on April 13, 1953, by the director of the Central Intelligence Agency, Allen Dulles. The program aimed to develop mind control techniques for use in interrogations and covert operations.",
      "date": "1953-04-13"
    },
    {
      "headline": "Early Experiments and Techniques",
      "text": "Throughout the 1950s, MKUltra conducted various experiments involving drugs, hypnosis, sensory deprivation, isolation, verbal and sexual abuse, as well as other forms of psychological torture. LSD was one of the primary drugs tested during this period.",
      "date": "1950s"
    },
    {
      "headline": "Expansion of MKUltra",
      "text": "In the late 1950s and early 1960s, the scope of MKUltra expanded to include experiments on unwitting subjects, including U.S. citizens, without their consent. This included experiments conducted in prisons, hospitals, and universities.",
      "date": "1950s-1960s"
    },
    {
      "headline": "Frank Olson Incident",
      "text": "In 1953, Frank Olson, a scientist working with the CIA, died under suspicious circumstances after being unwittingly dosed with LSD. His death was later ruled a suicide, but it raised significant questions about the ethics and legality of MKUltra's activities.",
      "date": "1953"
    },
    {
      "headline": "Project MKUltra Exposed",
      "text": "In 1975, the Church Committee and the Rockefeller Commission investigated the CIA's illegal activities, including MKUltra. These investigations brought the program to public attention and revealed the extent of the CIA's unethical practices.",
      "date": "1975"
    },
    {
      "headline": "Declassification of Documents",
      "text": "In 1977, under a Freedom of Information Act request, the CIA released thousands of documents related to MKUltra, providing further insight into the program's operations and abuses.",
      "date": "1977"
    },
    {
      "headline": "Official Closure of MKUltra",
      "text": "Although MKUltra was officially halted in 1973, the program's closure was confirmed and documented in the late 1970s following the investigations and public outcry.",
      "date": "1973"
    }
  ]
}

