{
  "timeline": [
    {
      "headline": "First European Contact",
      "text": "In 1513, Spanish explorer Juan Ponce de León became the first European to make documented contact with Florida, landing on the east coast near present-day St. Augustine.",
      "date": "1513"
    },
    {
      "headline": "Establishment of St. Augustine",
      "text": "On September 8, 1565, St. Augustine was founded by Spanish admiral Pedro Menéndez de Avilés, making it the oldest continuously inhabited European-established settlement in the contiguous United States.",
      "date": "1565-09-08"
    },
    {
      "headline": "Transfer to British Control",
      "text": "In 1763, Florida was ceded by Spain to Great Britain as part of the Treaty of Paris, which ended the Seven Years' War.",
      "date": "1763"
    },
    {
      "headline": "Return to Spanish Control",
      "text": "In 1783, Florida was returned to Spanish control following the American Revolutionary War as part of the Treaty of Paris.",
      "date": "1783"
    },
    {
      "headline": "Adams-Onís Treaty",
      "text": "In 1819, the Adams-Onís Treaty was signed, in which Spain ceded Florida to the United States. The treaty was ratified in 1821.",
      "date": "1821"
    },
    {
      "headline": "Florida Becomes a U.S. Territory",
      "text": "On March 30, 1822, the United States formally organized the Florida Territory.",
      "date": "1822-03-30"
    },
    {
      "headline": "Statehood",
      "text": "On March 3, 1845, Florida was admitted to the Union as the 27th state.",
      "date": "1845-03-03"
    },
    {
      "headline": "Civil War and Secession",
      "text": "On January 10, 1861, Florida seceded from the Union and joined the Confederate States of America during the American Civil War.",
      "date": "1861-01-10"
    },
    {
      "headline": "Reconstruction and Readmission",
      "text": "On June 25, 1868, Florida was readmitted to the Union after the Civil War during the Reconstruction era.",
      "date": "1868-06-25"
    },
    {
      "headline": "Great Miami Hurricane",
      "text": "In September 1926, the Great Miami Hurricane struck Florida, causing widespread destruction and marking one of the most devastating hurricanes in the state's history.",
      "date": "1926-09"
    },
    {
      "headline": "Disney World Opens",
      "text": "On October 1, 1971, Walt Disney World Resort opened near Orlando, significantly boosting Florida's tourism industry.",
      "date": "1971-10-01"
    },
    {
      "headline": "Hurricane Andrew",
      "text": "In August 1992, Hurricane Andrew made landfall in Florida, causing extensive damage and becoming one of the costliest hurricanes in U.S. history.",
      "date": "1992-08"
    },
    {
