{
  "timeline": [
    {
      "headline": "Origin of the Term 'Teetotalism'",
      "text": "The term 'teetotalism' is believed to have originated in the early 19th century. It was first used by Richard Turner, a member of the Preston Temperance Society, in a speech in 1833.",
      "date": "1833"
    },
    {
      "headline": "Formation of the Preston Temperance Society",
      "text": "The Preston Temperance Society, one of the earliest temperance organizations, was formed in 1832 in Preston, England. It played a significant role in promoting teetotalism.",
      "date": "1832"
    },
    {
      "headline": "Establishment of the American Temperance Society",
      "text": "The American Temperance Society was established in 1826. It was one of the first national organizations to advocate for the abstinence from alcohol, influencing the teetotalism movement in the United States.",
      "date": "1826"
    },
    {
      "headline": "The Washingtonian Movement",
      "text": "In 1840, the Washingtonian movement began in Baltimore, Maryland. It was a fellowship of men who encouraged each other to abstain from alcohol, contributing to the spread of teetotalism.",
      "date": "1840"
    },
    {
      "headline": "The Band of Hope",
      "text": "Founded in Leeds, England, in 1847, the Band of Hope was a temperance organization aimed at teaching children the importance of sobriety and teetotalism.",
      "date": "1847"
    },
    {
      "headline": "Formation of the Good Templars",
      "text": "The Independent Order of Good Templars was founded in 1851 in Utica, New York. It became one of the largest international temperance organizations promoting teetotalism.",
      "date": "1851"
    },
    {
      "headline": "The Women's Christian Temperance Union",
      "text": "The Women's Christian Temperance Union (WCTU) was founded in 1873 in Ohio, USA. It became a powerful advocate for teetotalism and played a significant role in the temperance movement.",
      "date": "1873"
    },
    {
      "headline": "Prohibition in the United States",
      "text": "The 18th Amendment to the United States Constitution, which established the prohibition of alcohol, was ratified in 1919 and went into effect in 1920. It was a significant event influenced by the teetotalism and temperance movements.",
      "date": "1919"
    },
    {
      "headline": "Repeal of Prohibition",
      "text": "The 21st Amendment to the United States Constitution was ratified in 1933, repealing the 18th Amendment and ending Prohibition. This marked a shift in the influence of teetotalism in the United States.",
      "date": "1933"
    }
  ]
}

