{
  "timeline": [
    {
      "headline": "Initial Construction of Walls",
      "text": "The earliest walls were constructed as early as the 7th century BC by various Chinese states to defend against nomadic invasions.",
      "date": "-0700"
    },
    {
      "headline": "Qin Dynasty Unification",
      "text": "During the reign of Qin Shi Huang (220–206 BC), the first emperor of China, various sections of earlier walls were connected to form a unified defense system against northern invaders.",
      "date": "-0220"
    },
    {
      "headline": "Han Dynasty Expansion",
      "text": "The Han dynasty (206 BC–220 AD) extended the Great Wall to protect the Silk Road trade routes and to defend against the Xiongnu.",
      "date": "-0206"
    },
    {
      "headline": "Sui and Tang Dynasties",
      "text": "The Sui (581–618) and Tang (618–907) dynasties conducted repairs and expansions of the Great Wall, although the Tang focused more on military expeditions than wall building.",
      "date": "0581"
    },
    {
      "headline": "Ming Dynasty Reconstruction",
      "text": "The most well-known sections of the Great Wall were built by the Ming dynasty (1368–1644) after the Ming army was defeated by the Oirats in 1449. The Ming constructed walls with stronger materials like bricks and stone.",
      "date": "1368"
    },
    {
      "headline": "End of Major Construction",
      "text": "The construction of the Great Wall largely ceased after the fall of the Ming dynasty in 1644, as the Qing dynasty expanded the empire's borders beyond the wall.",
      "date": "1644"
    }
  ]
}

