{
  "timeline": [
    {
      "headline": "First Human Settlement",
      "text": "The first human settlement in Estonia dates back to around 9000 BCE, following the retreat of the glaciers after the last Ice Age.",
      "date": "-09000"
    },
    {
      "headline": "Estonian Iron Age",
      "text": "The Estonian Iron Age began around 500 BCE, marked by the development of fortified settlements and increased trade.",
      "date": "-0500"
    },
    {
      "headline": "Viking Age",
      "text": "During the Viking Age, from around 800 to 1050 CE, Estonia was a significant area for trade and raids.",
      "date": "0800"
    },
    {
      "headline": "Danish Conquest",
      "text": "In 1219, Denmark conquered northern Estonia, establishing a foothold in the region.",
      "date": "1219"
    },
    {
      "headline": "Livonian Order Rule",
      "text": "By 1346, the Livonian Order had purchased northern Estonia from Denmark, consolidating control over the region.",
      "date": "1346"
    },
    {
      "headline": "Swedish Rule",
      "text": "In 1561, during the Livonian War, northern Estonia came under Swedish control, marking the beginning of Swedish rule.",
      "date": "1561"
    },
    {
      "headline": "Great Northern War",
      "text": "The Great Northern War (1700-1721) resulted in Estonia becoming part of the Russian Empire after Sweden's defeat.",
      "date": "1721"
    },
    {
      "headline": "Estonian National Awakening",
      "text": "The Estonian National Awakening began in the mid-19th century, fostering a sense of national identity and cultural revival.",
      "date": "1850"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On February 24, 1918, Estonia declared independence from Russia amidst the chaos of World War I.",
      "date": "1918-02-24"
    },
    {
      "headline": "Soviet Occupation",
      "text": "In June 1940, Estonia was occupied by the Soviet Union, marking the beginning of Soviet control.",
      "date": "1940-06"
    },
    {
      "headline": "German Occupation",
      "text": "From 1941 to 1944, Estonia was occupied by Nazi Germany during World War II.",
      "date": "1941"
    },
    {
      "headline": "Reoccupation by Soviet Union",
      "text": "In 1944, the Soviet Union reoccupied Estonia, which remained part of the USSR until 1991.",
      "date": "1944"
    },
    {
      "headline": "Restoration of Independence",
      "text": "Estonia restored its independence on August 20, 1991, following the collapse of the Soviet Union.",
      "date": "1991-08-20"
    },
    {
      "headline": "EU and NATO Membership",
      "text": "In 2004, Estonia joined both the European Union and NATO, marking significant integration into Western political and economic structures.",
