{
  "timeline": [
    {
      "headline": "Foundation of the Mughal Empire",
      "text": "The Mughal Empire was founded by Babur after his victory at the First Battle of Panipat on April 21, 1526.",
      "date": "1526-04-21"
    },
    {
      "headline": "Babur's Reign",
      "text": "Babur, the founder of the Mughal Empire, reigned from 1526 until his death in 1530.",
      "date": "1526"
    },
    {
      "headline": "Humayun's Ascension",
      "text": "Humayun, Babur's son, ascended to the throne in 1530 after Babur's death.",
      "date": "1530"
    },
    {
      "headline": "Humayun's Exile",
      "text": "Humayun was defeated by Sher Shah Suri and went into exile in Persia in 1540.",
      "date": "1540"
    },
    {
      "headline": "Restoration of Humayun",
      "text": "Humayun regained the throne of the Mughal Empire in 1555 after defeating the Suri dynasty.",
      "date": "1555"
    },
    {
      "headline": "Akbar's Reign Begins",
      "text": "Akbar, Humayun's son, began his reign in 1556 after Humayun's death.",
      "date": "1556"
    },
    {
      "headline": "Second Battle of Panipat",
      "text": "Akbar defeated Hemu at the Second Battle of Panipat on November 5, 1556, consolidating his rule.",
      "date": "1556-11-05"
    },
    {
      "headline": "Akbar's Religious Reforms",
      "text": "Akbar implemented religious reforms, including the abolition of the jizya tax on non-Muslims, during his reign from 1556 to 1605.",
      "date": "1556"
    },
    {
      "headline": "Jahangir's Reign",
      "text": "Jahangir, Akbar's son, ascended to the throne in 1605 and ruled until his death in 1627.",
      "date": "1605"
    },
    {
      "headline": "Shah Jahan's Reign",
      "text": "Shah Jahan, Jahangir's son, began his reign in 1628 and is known for commissioning the Taj Mahal.",
      "date": "1628"
    },
    {
      "headline": "Construction of the Taj Mahal",
      "text": "The construction of the Taj Mahal, commissioned by Shah Jahan, began in 1632 and was completed in 1648.",
      "date": "1632"
    },
    {
      "headline": "Aurangzeb's Reign",
      "text": "Aurangzeb, Shah Jahan's son, ascended to the throne in 1658 and expanded the empire to its greatest extent.",
      "date": "1658"
    },
    {
      "headline": "Death of Aurangzeb",
      "text": "Aurangzeb died in 1707, marking the beginning of the decline of the Mughal Empire.",
      "date": "1707"
    },
    {
      "headline": "Battle of Plassey",
      "text": "The Battle of Plassey in 1757 marked the beginning of British control over India, significantly weakening the Mughal Empire.",
      "date": "1757"
    },
    {
      "headline": "End of the Mughal Empire",
      "text": "The Mughal Empire effectively ended in 1857 after the Indian Rebellion, when the British deposed the last emperor, Bahadur Shah II.",
      "date": "1857"
    }
  ]
}

