{
  "timeline": [
    {
      "headline": "First Human Settlement",
      "text": "The first human settlement in Papua New Guinea is believed to have occurred around 50,000 years ago.",
      "date": "-48000"
    },
    {
      "headline": "Austronesian Migration",
      "text": "Around 3000 BCE, Austronesian-speaking peoples began to arrive in Papua New Guinea, bringing new agricultural practices.",
      "date": "-3000"
    },
    {
      "headline": "European Contact",
      "text": "In 1526-27, the Portuguese explorer Jorge de Meneses is believed to have been the first European to sight Papua New Guinea.",
      "date": "1526"
    },
    {
      "headline": "British and German Colonization",
      "text": "In 1884, the southeastern part of Papua New Guinea was annexed by Britain as British New Guinea, while the northeastern part was claimed by Germany as German New Guinea.",
      "date": "1884"
    },
    {
      "headline": "Australian Administration",
      "text": "In 1906, the British part of Papua New Guinea was transferred to Australian administration and became known as the Territory of Papua.",
      "date": "1906"
    },
    {
      "headline": "World War II Impact",
      "text": "During World War II, Papua New Guinea was a major battleground in the Pacific theater, with significant battles such as the Kokoda Track campaign occurring between 1942 and 1943.",
      "date": "1942"
    },
    {
      "headline": "United Nations Trusteeship",
      "text": "In 1949, the territories of Papua and New Guinea were combined and placed under Australian administration as a United Nations Trust Territory.",
      "date": "1949"
    },
    {
      "headline": "Self-Government",
      "text": "Papua New Guinea achieved self-government on December 1, 1973.",
      "date": "1973-12-01"
    },
    {
      "headline": "Independence",
      "text": "Papua New Guinea gained full independence from Australia on September 16, 1975.",
      "date": "1975-09-16"
    },
    {
      "headline": "Bougainville Conflict",
      "text": "A civil conflict known as the Bougainville Civil War began in 1988 and lasted until 1998, resulting in significant loss of life and displacement.",
      "date": "1988"
    },
    {
      "headline": "Bougainville Peace Agreement",
      "text": "In 2001, the Bougainville Peace Agreement was signed, granting Bougainville autonomy and the promise of a future independence referendum.",
      "date": "2001"
    },
    {
      "headline": "Bougainville Referendum",
      "text": "In 2019, a non-binding independence referendum was held in Bougainville, with an overwhelming majority voting for independence.",
      "date": "2019"
    }
  ]
}

