{
  "timeline": [
    {
      "headline": "Foundation of the Catholic Church",
      "text": "The Catholic Church traces its origins to the teachings of Jesus Christ and the apostles in the 1st century CE. It is believed to have been founded by Jesus Christ, with the apostle Peter considered the first pope.",
      "date": "0001"
    },
    {
      "headline": "Council of Nicaea",
      "text": "In 325, the First Council of Nicaea was convened by Emperor Constantine I. It was the first ecumenical council of the Christian Church and resulted in the first uniform Christian doctrine, called the Nicene Creed.",
      "date": "0325"
    },
    {
      "headline": "Great Schism",
      "text": "In 1054, the Great Schism occurred, leading to the separation between the Roman Catholic Church and the Eastern Orthodox Church, primarily over issues of papal authority and the filioque clause in the Nicene Creed.",
      "date": "1054"
    },
    {
      "headline": "Fourth Lateran Council",
      "text": "In 1215, the Fourth Lateran Council was convened by Pope Innocent III. It was one of the most important councils in the history of the Catholic Church, establishing key doctrines and reforms.",
      "date": "1215"
    },
    {
      "headline": "Council of Trent",
      "text": "The Council of Trent was held between 1545 and 1563 in response to the Protestant Reformation. It was a major part of the Counter-Reformation, addressing doctrinal and disciplinary issues.",
      "date": "1545"
    },
    {
      "headline": "First Vatican Council",
      "text": "The First Vatican Council was convened by Pope Pius IX in 1869-1870. It is known for its definition of papal infallibility.",
      "date": "1869"
    },
    {
      "headline": "Second Vatican Council",
      "text": "The Second Vatican Council was held from 1962 to 1965 under Popes John XXIII and Paul VI. It aimed to address relations between the Catholic Church and the modern world, resulting in significant changes in church practices.",
      "date": "1962"
    },
    {
      "headline": "Election of Pope Francis",
      "text": "In 2013, Pope Francis was elected as the 266th pope of the Catholic Church. He is the first pope from the Americas and the Southern Hemisphere.",
      "date": "2013"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Coinage Act of 1792",
      "text": "The Coinage Act of 1792 was enacted on April 2, 1792. It established the United States dollar as the country's standard unit of money, at par with the Spanish silver dollar, and divided it into 100 cents. The act also authorized the creation of the United States Mint and the minting of coins denominated in dollars and cents.",
      "date": "1792-04-02"
    },
    {
      "headline": "Introduction of Federal Reserve Notes",
      "text": "Federal Reserve Notes were introduced in 1914 as part of the Federal Reserve Act of 1913. These notes are the current form of U.S. banknotes and are popularly known as greenbacks due to their predominantly green color.",
      "date": "1914"
    },
    {
      "headline": "Bretton Woods Agreement",
      "text": "In 1944, the Bretton Woods Agreement established the U.S. dollar as the world's primary reserve currency, linking it to gold and setting fixed exchange rates with other currencies.",
      "date": "1944"
    },
    {
      "headline": "End of Gold Standard",
      "text": "On August 15, 1971, President Richard Nixon announced the end of the U.S. dollar's convertibility into gold, effectively ending the Bretton Woods system and transitioning to a fiat currency system.",
      "date": "1971-08-15"
    },
    {
      "headline": "Introduction of the Euro",
      "text": "On January 1, 1999, the euro was introduced as the official currency of the Eurozone, challenging the dominance of the U.S. dollar in international markets.",
      "date": "1999-01-01"
    }
  ]
}

