      "headline": "First Proposal of Daylight Saving Time",
      "text": "In 1895, George Hudson, an entomologist from New Zealand, proposed the idea of daylight saving time. He suggested a two-hour shift forward in October and a two-hour shift back in March.",
      "date": "1895"
    },
    {
      "headline": "First Implementation of Daylight Saving Time",
      "text": "Daylight saving time was first implemented by the German Empire and Austria-Hungary on April 30, 1916, during World War I, as a way to conserve coal.",
      "date": "1916-04-30"
    },
    {
      "headline": "United States Adopts Daylight Saving Time",
      "text": "The United States adopted daylight saving time on March 19, 1918, during World War I, but it was repealed after the war ended.",
      "date": "1918-03-19"
    },
    {
      "headline": "Daylight Saving Time Reintroduced in World War II",
      "text": "During World War II, daylight saving time was reintroduced in many countries, including the United States, to save energy.",
      "date": "1942"
    },
    {
      "headline": "Uniform Time Act of 1966",
      "text": "The Uniform Time Act of 1966 was enacted in the United States, establishing a standardized system of daylight saving time across the country.",
      "date": "1966"
    },
    {
      "headline": "Energy Policy Act of 2005",
      "text": "The Energy Policy Act of 2005 extended daylight saving time in the United States by four weeks, starting in 2007.",
      "date": "2005"
    }
  ]
}

