    },
    {
      "headline": "Direct Rule Imposed",
      "text": "The British government imposed direct rule over Northern Ireland on March 30, 1972, suspending the Northern Ireland Parliament.",
      "date": "1972-03-30"
    },
    {
      "headline": "Good Friday Agreement",
      "text": "The Good Friday Agreement, also known as the Belfast Agreement, was signed on April 10, 1998, bringing an end to most of the violence of the Troubles and establishing a devolved government in Northern Ireland.",
      "date": "1998-04-10"
    },
    {
      "headline": "Northern Ireland Assembly Established",
      "text": "The Northern Ireland Assembly was established following the Good Friday Agreement, with its first session held on July 1, 1998.",
      "date": "1998-07-01"
    },
    {
      "headline": "St Andrews Agreement",
      "text": "The St Andrews Agreement was reached on October 13, 2006, leading to the restoration of the Northern Ireland Assembly and Executive.",
      "date": "2006-10-13"
    },
    {
      "headline": "Brexit Referendum",
      "text": "On June 23, 2016, the United Kingdom voted to leave the European Union, with Northern Ireland voting to remain.",
      "date": "2016-06-23"
    },
    {
      "headline": "Northern Ireland Protocol",
      "text": "The Northern Ireland Protocol was agreed upon as part of the Brexit withdrawal agreement, coming into effect on January 1, 2021, to address the unique situation of Northern Ireland post-Brexit.",
