{
  "timeline": [
    {
      "headline": "Pre-Columbian Era",
      "text": "Before 1492, Native American societies thrived across North America with diverse cultures, languages, and social structures. They developed complex societies with trade networks, agriculture, and architecture.",
      "date": "-1492"
    },
    {
      "headline": "Columbian Exchange Begins",
      "text": "In 1492, Christopher Columbus's arrival in the Americas initiated the Columbian Exchange, bringing profound changes to Native American societies through the introduction of new diseases, animals, and plants.",
      "date": "1492"
    },
    {
      "headline": "Jamestown Settlement",
      "text": "In 1607, the establishment of Jamestown, Virginia, marked the beginning of sustained European colonization, leading to significant interactions and conflicts with Native American tribes.",
      "date": "1607"
    },
    {
      "headline": "Trail of Tears",
      "text": "Between 1830 and 1850, the U.S. government forcibly relocated thousands of Native Americans from their ancestral homelands in the southeastern United States to designated Indian Territory west of the Mississippi River, in a series of forced relocations known as the Trail of Tears.",
      "date": "1830"
    },
    {
      "headline": "Indian Citizenship Act",
      "text": "On June 2, 1924, the Indian Citizenship Act was signed into law, granting U.S. citizenship to all Native Americans born in the United States.",
      "date": "1924-06-02"
    },
    {
      "headline": "American Indian Movement Founded",
      "text": "In 1968, the American Indian Movement (AIM) was founded to address issues of sovereignty, treaty rights, and police harassment, becoming a significant force in advocating for Native American rights.",
      "date": "1968"
    },
    {
      "headline": "Occupation of Alcatraz",
      "text": "From November 20, 1969, to June 11, 1971, Native American activists occupied Alcatraz Island to protest federal policies and advocate for Native American rights, drawing national attention to their cause.",
      "date": "1969-11-20"
    },
    {
      "headline": "Indian Self-Determination and Education Assistance Act",
      "text": "In 1975, the Indian Self-Determination and Education Assistance Act was passed, allowing tribes greater control over their own affairs and education systems.",
      "date": "1975"
    },
    {
      "headline": "Native American Graves Protection and Repatriation Act",
      "text": "In 1990, the Native American Graves Protection and Repatriation Act (NAGPRA) was enacted, providing a process for museums and federal agencies to return certain cultural items to lineal descendants and culturally affiliated tribes.",
      "date": "1990"
    }
  ]
}

