{
  "timeline": [
    {
      "headline": "Creation of the Seven Wonders of the Ancient World",
      "text": "The Seven Wonders of the Ancient World were a list of remarkable constructions of classical antiquity. They were originally considered a guidebook for travelers in the Mediterranean region. The list includes the Great Pyramid of Giza, Hanging Gardens of Babylon, Statue of Zeus at Olympia, Temple of Artemis at Ephesus, Mausoleum at Halicarnassus, Colossus of Rhodes, and the Lighthouse of Alexandria.",
      "date": "-00250"
    },
    {
      "headline": "Great Pyramid of Giza",
      "text": "The Great Pyramid of Giza, located in Egypt, is the oldest and only surviving structure of the original Seven Wonders of the Ancient World. It was built around 2560 BCE as a tomb for the Egyptian Pharaoh Khufu.",
      "date": "-02560"
    },
    {
      "headline": "Hanging Gardens of Babylon",
      "text": "The Hanging Gardens of Babylon are said to have been built in the ancient city-state of Babylon, near present-day Hillah, Babil, in Iraq. They are one of the Seven Wonders of the Ancient World, though their existence has not been definitively proven.",
      "date": "-0600"
    },
    {
      "headline": "Statue of Zeus at Olympia",
      "text": "The Statue of Zeus at Olympia was a giant seated figure made by the sculptor Phidias around 435 BCE. It was erected in the Temple of Zeus, Olympia, Greece, and was one of the Seven Wonders of the Ancient World.",
      "date": "-0435"
    },
    {
      "headline": "Temple of Artemis at Ephesus",
      "text": "The Temple of Artemis at Ephesus, located in present-day Turkey, was a large temple dedicated to the goddess Artemis. It was completed around 550 BCE and was one of the Seven Wonders of the Ancient World.",
      "date": "-0550"
    },
    {
      "headline": "Mausoleum at Halicarnassus",
      "text": "The Mausoleum at Halicarnassus was a tomb built for Mausolus, a satrap of the Persian Empire, and his wife, Artemisia II of Caria. It was completed around 350 BCE in present-day Bodrum, Turkey, and was one of the Seven Wonders of the Ancient World.",
      "date": "-0350"
    },
    {
      "headline": "Colossus of Rhodes",
      "text": "The Colossus of Rhodes was a statue of the sun god Helios, erected in the city of Rhodes, Greece, by Chares of Lindos in 280 BCE. It was one of the Seven Wonders of the Ancient World.",
      "date": "-0280"
    },
    {
      "headline": "Lighthouse of Alexandria",
      "text": "The Lighthouse of Alexandria, also known as the Pharos of Alexandria, was a lighthouse built by the Ptolemaic Kingdom between 280 and 247 BCE on the island of Pharos in Alexandria, Egypt. It was one of the Seven Wonders of the Ancient World.",
      "date": "-0280"
    },
    {
      "headline": "New7Wonders of the World",
      "text": "In 2007, the New7Wonders Foundation announced a list of the New7Wonders of the World, which includes the Great Wall of China, Petra, Christ the Redeemer, Machu Picchu, Chichen Itza, Roman Colosseum, and the Taj Mahal.",
      "date": "2007"
    }
  ]
}

