      "headline": "Settlement by Austronesian peoples",
      "text": "The first human settlement on Madagascar by Austronesian peoples from Borneo occurred around 500 CE.",
      "date": "0500"
    },
    {
      "headline": "Bantu migration",
      "text": "Bantu-speaking peoples began to arrive on the island around 1000 CE, bringing with them iron-working technology and agriculture.",
      "date": "1000"
    },
    {
      "headline": "Formation of the Merina Kingdom",
      "text": "The Merina Kingdom was established in the central highlands of Madagascar in the early 16th century.",
      "date": "1500"
    },
    {
      "headline": "Reign of King Andrianampoinimerina",
      "text": "King Andrianampoinimerina reigned from 1787 to 1810 and is credited with unifying the Merina Kingdom and laying the foundation for the modern state of Madagascar.",
      "date": "1787"
    },
    {
      "headline": "Reign of Queen Ranavalona I",
      "text": "Queen Ranavalona I ruled from 1828 to 1861 and is known for her resistance to European influence and efforts to preserve Malagasy culture.",
      "date": "1828"
    },
    {
      "headline": "French colonization",
      "text": "Madagascar became a French colony in 1896 after the Franco-Hova Wars, and it remained under French control until 1960.",
      "date": "1896"
    },
    {
      "headline": "Independence from France",
      "text": "Madagascar gained independence from France on June 26, 1960, becoming the Malagasy Republic.",
      "date": "1960-06-26"
    },
    {
      "headline": "First Republic of Madagascar",
      "text": "The First Republic of Madagascar was established in 1960, following independence, and lasted until 1972.",
      "date": "1960"
    },
    {
      "headline": "Socialist Revolution",
      "text": "In 1975, a socialist revolution led by Didier Ratsiraka established the Democratic Republic of Madagascar.",
      "date": "1975"
    },
    {
      "headline": "Transition to the Third Republic",
      "text": "In 1992, Madagascar transitioned to the Third Republic with a new constitution and democratic elections.",
      "date": "1992"
    },
    {
      "headline": "Political crisis and coup",
      "text": "In 2009, a political crisis led to a coup d'état, and Andry Rajoelina assumed power.",
      "date": "2009"
    },
    {
      "headline": "Return to democracy",
      "text": "In 2013, Madagascar held democratic elections, marking a return to constitutional governance.",
      "date": "2013"
    }
  ]
}

