    {
      "headline": "Formation of Al-Qaeda",
      "text": "Al-Qaeda was formed in 1988 by Osama bin Laden, Abdullah Azzam, and other Arab volunteers during the Soviet–Afghan War. The organization was established to continue the jihad against perceived enemies of Islam.",
      "date": "1988"
    },
    {
      "headline": "First Major Attack: Aden Hotel Bombing",
      "text": "On December 29, 1992, Al-Qaeda conducted its first known terrorist attack, bombing the Gold Mohur Hotel in Aden, Yemen, which was used by U.S. troops en route to Somalia.",
      "date": "1992-12-29"
    },
    {
      "headline": "1993 World Trade Center Bombing",
      "text": "On February 26, 1993, a truck bomb was detonated below the North Tower of the World Trade Center in New York City, killing six people and injuring over a thousand. Al-Qaeda was later linked to the attack.",
      "date": "1993-02-26"
    },
    {
      "headline": "1998 U.S. Embassy Bombings",
      "text": "On August 7, 1998, Al-Qaeda carried out simultaneous bombings of the U.S. embassies in Nairobi, Kenya, and Dar es Salaam, Tanzania, killing 224 people and injuring over 4,500.",
      "date": "1998-08-07"
    },
    {
      "headline": "USS Cole Bombing",
      "text": "On October 12, 2000, Al-Qaeda attacked the USS Cole, a U.S. Navy destroyer, while it was harbored in Aden, Yemen. The attack killed 17 American sailors and injured 39.",
      "date": "2000-10-12"
    },
    {
      "headline": "September 11 Attacks",
      "text": "On September 11, 2001, Al-Qaeda hijacked four commercial airliners, crashing two into the World Trade Center towers in New York City, one into the Pentagon, and the fourth in Pennsylvania. The attacks killed nearly 3,000 people.",
      "date": "2001-09-11"
    },
    {
      "headline": "U.S. Invasion of Afghanistan",
      "text": "Following the September 11 attacks, the United States, with support from allied nations, invaded Afghanistan on October 7, 2001, to dismantle Al-Qaeda and remove the Taliban from power.",
      "date": "2001-10-07"
    },
    {
      "headline": "Death of Osama bin Laden",
      "text": "On May 2, 2011, Osama bin Laden, the founder and leader of Al-Qaeda, was killed by U.S. Navy SEALs in Abbottabad, Pakistan, during a covert operation.",
      "date": "2011-05-02"
    }
  ]
}

