      "date": "1814"
    },
    {
      "headline": "Flag Act of 1818",
      "text": "On April 4, 1818, Congress passed the Flag Act of 1818, which established the design of the flag to have 13 stripes and a star for each state. The act also specified that a new star would be added on the Fourth of July following the admission of each new state.",
      "date": "1818-04-04"
    },
    {
      "headline": "Adoption of the 50-star Flag",
      "text": "On July 4, 1960, the 50-star flag was officially adopted following the admission of Hawaii as the 50th state on August 21, 1959. This is the current design of the flag.",
      "date": "1960-07-04"
    }
  ]
}

