      "headline": "First Description by Hans Asperger",
      "text": "In 1944, Austrian pediatrician Hans Asperger first described the symptoms of Asperger syndrome in children, noting their difficulties in social interaction and nonverbal communication, along with restricted and repetitive behaviors.",
      "date": "1944"
    },
    {
      "headline": "Recognition in English-speaking Countries",
      "text": "Asperger syndrome gained recognition in English-speaking countries in the late 1980s and early 1990s, following the translation of Hans Asperger's work.",
      "date": "1980-1990"
    },
    {
      "headline": "Inclusion in DSM-IV",
      "text": "In 1994, Asperger syndrome was included as a diagnosis in the fourth edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM-IV) by the American Psychiatric Association.",
      "date": "1994"
    },
    {
      "headline": "Inclusion in ICD-10",
      "text": "In 1992, Asperger syndrome was included in the International Classification of Diseases, 10th Revision (ICD-10) by the World Health Organization.",
      "date": "1992"
    },
    {
      "headline": "Removal from DSM-5",
      "text": "In 2013, Asperger syndrome was removed as a separate diagnosis in the DSM-5 and was merged into the broader category of autism spectrum disorder (ASD).",
      "date": "2013"
    },
    {
      "headline": "Removal from ICD-11",
      "text": "In 2019, Asperger syndrome was removed as a separate diagnosis in the ICD-11 and was included under autism spectrum disorder (ASD).",
      "date": "2019"
    }
  ]
}

