    {
      "headline": "Discovery of Mycobacterium tuberculosis",
      "text": "In 1882, Robert Koch discovered the bacterium Mycobacterium tuberculosis, the causative agent of tuberculosis. This was a significant breakthrough in understanding the disease.",
      "date": "1882"
    },
    {
      "headline": "Development of the Tuberculin Skin Test",
      "text": "In 1907, Charles Mantoux developed the tuberculin skin test, which became a standard method for diagnosing tuberculosis infection.",
      "date": "1907"
    },
    {
      "headline": "Introduction of the BCG Vaccine",
      "text": "In 1921, the Bacillus Calmette-Guérin (BCG) vaccine was first used in humans. It was developed by Albert Calmette and Camille Guérin as a vaccine against tuberculosis.",
      "date": "1921"
    },
    {
      "headline": "Discovery of Streptomycin",
      "text": "In 1943, Selman Waksman and Albert Schatz discovered streptomycin, the first antibiotic effective against tuberculosis, marking the beginning of antibiotic treatment for the disease.",
      "date": "1943"
    },
    {
      "headline": "Introduction of Isoniazid",
      "text": "In 1952, isoniazid was introduced as a treatment for tuberculosis. It became a key component of the standard treatment regimen for the disease.",
      "date": "1952"
    },
    {
      "headline": "Development of Directly Observed Therapy (DOT)",
      "text": "In the 1990s, the World Health Organization (WHO) recommended Directly Observed Therapy (DOT) as a strategy to ensure adherence to tuberculosis treatment regimens.",
      "date": "1990"
    },
    {
      "headline": "Declaration of Tuberculosis as a Global Emergency",
      "text": "In 1993, the World Health Organization declared tuberculosis a global health emergency due to its resurgence and the rise of drug-resistant strains.",
      "date": "1993"
    },
    {
      "headline": "Launch of the Stop TB Partnership",
      "text": "In 2000, the Stop TB Partnership was launched to coordinate global efforts to combat tuberculosis and achieve the goal of eliminating the disease as a public health problem.",
      "date": "2000"
    }
  ]
}

