      "text": "The Schengen Agreement was signed on June 14, 1985, by five of the ten member states of the European Economic Community near the village of Schengen in Luxembourg.",
      "date": "1985-06-14"
    },
    {
      "headline": "Schengen Convention Signed",
      "text": "The Schengen Convention was signed on June 19, 1990, which supplemented the Schengen Agreement and proposed the abolition of internal border controls.",
      "date": "1990-06-19"
    },
    {
      "headline": "Schengen Agreement Implemented",
      "text": "The Schengen Agreement was implemented on March 26, 1995, abolishing border controls between the participating countries.",
      "date": "1995-03-26"
    },
    {
      "headline": "Incorporation into EU Law",
      "text": "The Schengen acquis was incorporated into European Union law with the Treaty of Amsterdam, which came into effect on May 1, 1999.",
      "date": "1999-05-01"
    },
    {
      "headline": "Expansion of Schengen Area",
      "text": "On December 21, 2007, the Schengen Area expanded to include nine new countries: Czech Republic, Estonia, Hungary, Latvia, Lithuania, Malta, Poland, Slovakia, and Slovenia.",
      "date": "2007-12-21"
    },
    {
      "headline": "Switzerland Joins Schengen Area",
      "text": "Switzerland joined the Schengen Area on December 12, 2008, allowing for the abolition of border controls with its neighboring countries.",
      "date": "2008-12-12"
    },
    {
      "headline": "Liechtenstein Joins Schengen Area",
      "text": "Liechtenstein became a member of the Schengen Area on December 19, 2011, further expanding the zone of free movement.",
      "date": "2011-12-19"
    }
  ]
}

