  "timeline": [
    {
      "headline": "Foundation of the Druze Faith",
      "text": "The Druze faith was founded in the early 11th century during the reign of the sixth Fatimid caliph, al-Hakim bi-Amr Allah. The movement began in 1017 CE when al-Hakim declared himself the manifestation of God.",
      "date": "1017"
    },
    {
      "headline": "End of Public Proselytization",
      "text": "In 1043 CE, the Druze faith closed its doors to new adherents, ending public proselytization. This decision was made by the Druze leader Hamza ibn Ali ibn Ahmad, marking the faith as a closed community.",
      "date": "1043"
    },
    {
      "headline": "Migration to the Levant",
      "text": "During the 11th century, the Druze community began to migrate to the mountainous regions of the Levant, including present-day Lebanon, Syria, and Israel, where they established a strong presence.",
      "date": "1100"
    },
    {
      "headline": "Druze in the Ottoman Empire",
      "text": "Throughout the Ottoman period, the Druze played a significant role in the politics of the region, particularly in Mount Lebanon, where they were involved in various conflicts and alliances.",
      "date": "1516"
    },
    {
      "headline": "The Ma'an Dynasty",
      "text": "The Ma'an dynasty, a Druze ruling family, governed parts of Lebanon from the 16th to the 17th century, with Fakhr al-Din II being one of the most notable leaders who expanded Druze influence.",
      "date": "1590"
    },
    {
      "headline": "The Battle of Ain Dara",
      "text": "In 1711, the Battle of Ain Dara took place between the Qaysi and Yamani factions, leading to a significant Druze victory and the consolidation of Qaysi dominance in Mount Lebanon.",
      "date": "1711"
    },
    {
      "headline": "Druze-Maronite Conflict",
      "text": "In the mid-19th century, tensions between the Druze and Maronite Christians in Mount Lebanon escalated into violent conflicts, culminating in the 1860 civil war.",
      "date": "1860"
    },
    {
      "headline": "Lebanon's Independence",
      "text": "The Druze community played a role in the political landscape of Lebanon following its independence from France in 1943, participating in the country's complex sectarian politics.",
      "date": "1943"
    },
    {
      "headline": "Druze in Modern Politics",
      "text": "In the late 20th and early 21st centuries, the Druze have continued to be active in the political scenes of Lebanon, Syria, and Israel, often advocating for their rights and autonomy within these states.",
      "date": "2000"
    }
  ]
}

