{
  "timeline": [
    {
      "headline": "Wall Street Stock Market Crash",
      "text": "The Wall Street stock market crash, often considered the beginning of the Great Depression, occurred in October 1929. The crash led to a drastic reduction in consumer wealth and marked the start of a severe global economic downturn.",
      "date": "1929-10"
    },
    {
      "headline": "Bank Failures Begin",
      "text": "In 1930, a wave of bank failures began in the United States, contributing to the economic downturn. Many banks were unable to meet the demands of depositors withdrawing their funds, leading to widespread bank closures.",
      "date": "1930"
    },
    {
      "headline": "Unemployment Reaches High Levels",
      "text": "By 1933, unemployment in the United States had reached approximately 25%, with similar high rates in other countries such as the United Kingdom and Germany. This was one of the most severe impacts of the Great Depression.",
      "date": "1933"
    },
    {
      "headline": "New Deal Initiated",
      "text": "In 1933, U.S. President Franklin D. Roosevelt initiated the New Deal, a series of programs, public work projects, financial reforms, and regulations aimed at providing relief for the unemployed and poor, and recovering the economy.",
      "date": "1933"
    },
    {
      "headline": "Dust Bowl Intensifies Economic Hardship",
      "text": "During the mid-1930s, the Dust Bowl, a period of severe dust storms, greatly damaged the ecology and agriculture of the American and Canadian prairies, exacerbating the economic hardships of the Great Depression.",
      "date": "1934"
    },
    {
      "headline": "Social Security Act Passed",
      "text": "In 1935, the Social Security Act was passed in the United States, establishing a system of old-age benefits for workers, benefits for victims of industrial accidents, unemployment insurance, and aid for dependent mothers and children, the blind, and the physically handicapped.",
      "date": "1935"
    },
    {
      "headline": "Recession of 1937-1938",
      "text": "A second severe economic downturn, known as the Recession of 1937-1938, occurred in the United States, causing a setback in the recovery efforts from the Great Depression.",
      "date": "1937"
    },
    {
      "headline": "World War II Begins",
      "text": "The onset of World War II in 1939 is often considered a major factor in the eventual recovery from the Great Depression, as the war effort led to increased industrial production and employment.",
      "date": "1939"
    }
  ]
}

