      "headline": "Foundation of the Achaemenid Empire",
      "text": "The Achaemenid Empire was founded by Cyrus the Great in 550 BCE after he defeated the Median Empire.",
      "date": "-0550"
    },
    {
      "headline": "Conquest of Lydia",
      "text": "Cyrus the Great conquered the Kingdom of Lydia in 547 BCE, expanding the empire's territory into Asia Minor.",
      "date": "-0547"
    },
