  "timeline": [
    {
      "headline": "Invention of Morse Code",
      "text": "Morse code was developed in the early 1830s and 1840s by Samuel Morse and Alfred Vail. The code was first used in 1844 to send a message over a telegraph line from Washington, D.C., to Baltimore.",
      "date": "1844"
    },
    {
      "headline": "First Public Demonstration",
      "text": "On May 24, 1844, Samuel Morse sent the first long-distance telegraph message, 'What hath God wrought,' from the U.S. Capitol in Washington, D.C., to the old Mt. Clare Depot in Baltimore.",
      "date": "1844-05-24"
    },
    {
      "headline": "International Morse Code Standardized",
      "text": "In 1865, the International Morse Code was standardized at the International Telegraphy Congress in Paris, which modified the original Morse code to include letters with diacritical marks and other symbols.",
      "date": "1865"
    },
    {
      "headline": "Adoption by Maritime Industry",
      "text": "Morse code became widely used in the maritime industry for ship-to-ship and ship-to-shore communication, particularly after the Radio Act of 1912, which mandated its use for distress signals.",
      "date": "1912"
    },
    {
      "headline": "Morse Code in World War II",
      "text": "During World War II, Morse code was extensively used by military forces for secure communication. It was a crucial tool for sending encrypted messages across battlefields.",
      "date": "1939"
    },
    {
      "headline": "End of Commercial Use",
      "text": "The last commercial Morse code transmission in the United States was sent on July 12, 1999, marking the end of an era for this form of communication.",
      "date": "1999-07-12"
    },
    {
      "headline": "Final Maritime Use",
      "text": "The last official Morse code transmission by the French Navy was sent on January 31, 1997, signaling the end of its use in maritime communication.",
      "date": "1997-01-31"
    }
  ]
}

