{
  "timeline": [
    {
      "headline": "Launch of Apollo 11",
      "text": "Apollo 11 was launched by NASA from Kennedy Space Center on July 16, 1969, at 13:32 UTC. It marked the beginning of the first mission to land humans on the Moon.",
      "date": "1969-07-16"
    },
    {
      "headline": "Lunar Module Eagle Lands on the Moon",
      "text": "On July 20, 1969, at 20:17 UTC, the Apollo Lunar Module Eagle, piloted by Neil Armstrong and Buzz Aldrin, successfully landed on the Moon's surface at a site they named Tranquility Base.",
      "date": "1969-07-20"
    },
    {
      "headline": "First Human Steps on the Moon",
      "text": "Neil Armstrong became the first person to step onto the Moon's surface on July 21, 1969, at 02:56 UTC, famously declaring, 'That's one small step for [a] man, one giant leap for mankind.'",
      "date": "1969-07-21"
    },
    {
      "headline": "Buzz Aldrin Joins Armstrong on the Moon",
      "text": "Buzz Aldrin joined Neil Armstrong on the lunar surface 19 minutes after Armstrong's first step, and together they spent about two and a quarter hours exploring the Moon.",
      "date": "1969-07-21"
    },
    {
      "headline": "Lunar Surface Exploration",
      "text": "Armstrong and Aldrin spent approximately 21 hours and 36 minutes on the Moon's surface, collecting 47.5 pounds (21.5 kg) of lunar material to bring back to Earth.",
      "date": "1969-07-21"
    },
    {
      "headline": "Lunar Module Lifts Off from the Moon",
      "text": "The Lunar Module Eagle lifted off from the Moon's surface on July 21, 1969, to rejoin the Command Module Columbia piloted by Michael Collins in lunar orbit.",
      "date": "1969-07-21"
    },
    {
      "headline": "Return to Earth",
      "text": "Apollo 11 safely returned to Earth, splashing down in the Pacific Ocean on July 24, 1969, at 16:50 UTC, marking the successful completion of the mission.",
      "date": "1969-07-24"
    }
  ]
}

{
  "timeline": [
