{
  "timeline": [
    {
      "headline": "Formation of the Somali People",
      "text": "The Somali people are believed to have originated from the Cushitic peoples of the Horn of Africa. They have a rich history of trade and interaction with other cultures, particularly through the ancient city-states along the Somali coast.",
      "date": "-3000"
    },
    {
      "headline": "Rise of the Sultanates",
      "text": "Between the 9th and 13th centuries, several powerful Somali sultanates and city-states emerged, including the Sultanate of Ifat and the Sultanate of Adal.",
      "date": "0900"
    },
    {
      "headline": "Ajuran Sultanate",
      "text": "The Ajuran Sultanate, a Somali Muslim empire, dominated the Indian Ocean trade from the 13th to the 17th century, controlling much of the Horn of Africa.",
      "date": "1300"
    },
    {
      "headline": "Colonial Era Begins",
      "text": "In the late 19th century, European powers began colonizing the Somali territories. The British, Italians, and French established control over different parts of the region.",
      "date": "1884"
    },
    {
      "headline": "Dervish State",
      "text": "From 1899 to 1920, the Dervish State, led by Mohammed Abdullah Hassan, resisted colonial rule in Somalia, particularly against the British.",
      "date": "1899"
    },
    {
      "headline": "Independence and Unification",
      "text": "On July 1, 1960, the territories of British Somaliland and Italian Somaliland united to form the independent Republic of Somalia.",
      "date": "1960-07-01"
    },
    {
      "headline": "Siad Barre's Coup",
      "text": "On October 21, 1969, Major General Mohamed Siad Barre led a coup d'état, establishing a socialist state and ruling until 1991.",
      "date": "1969-10-21"
    },
    {
      "headline": "Civil War Begins",
      "text": "In 1991, the Somali Civil War began following the overthrow of Siad Barre's regime, leading to decades of conflict and instability.",
      "date": "1991"
    },
    {
      "headline": "Transitional Federal Government",
      "text": "In 2004, the Transitional Federal Government (TFG) was established in an attempt to restore national governance.",
      "date": "2004"
    },
    {
      "headline": "Federal Government of Somalia",
      "text": "In 2012, the Federal Government of Somalia was established, marking the end of the transitional period and the beginning of a new federal system.",
      "date": "2012"
    }
  ]
}

