    {
      "headline": "Balfour Declaration Incorporated",
      "text": "The Balfour Declaration, which supported the establishment of a 'national home for the Jewish people' in Palestine, was incorporated into the terms of the Mandate, which was approved by the League of Nations on July 24, 1922.",
      "date": "1922-07-24"
    },
    {
      "headline": "Arab Revolt",
      "text": "The Arab Revolt in Palestine began in April 1936 and lasted until 1939. It was a nationalist uprising by Palestinian Arabs against British colonial rule and mass Jewish immigration.",
      "date": "1936-04"
    },
    {
      "headline": "Peel Commission Report",
      "text": "In July 1937, the Peel Commission Report was published, recommending the partition of Palestine into separate Jewish and Arab states, with a small area remaining under British control.",
      "date": "1937-07"
    },
    {
      "headline": "White Paper of 1939",
      "text": "The British government issued the White Paper of 1939, which limited Jewish immigration to Palestine and proposed the establishment of an independent Palestine governed by Arabs and Jews in proportion to their numbers in the population.",
      "date": "1939"
    },
    {
      "headline": "End of World War II",
      "text": "World War II ended in 1945, leading to increased tensions in Palestine as Jewish immigration surged and conflict between Jewish and Arab communities intensified.",
      "date": "1945"
    },
    {
      "headline": "UN Partition Plan",
      "text": "On November 29, 1947, the United Nations General Assembly adopted Resolution 181, recommending the partition of Palestine into independent Arab and Jewish states and an international regime for Jerusalem.",
      "date": "1947-11-29"
    },
    {
      "headline": "End of British Mandate",
      "text": "The British Mandate for Palestine officially ended on May 14, 1948. On the same day, the State of Israel declared independence, leading to the outbreak of the 1948 Arab-Israeli War.",
      "date": "1948-05-14"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Release of Jurassic Park",
      "text": "Jurassic Park was released on June 11, 1993. Directed by Steven Spielberg, the film is based on Michael Crichton's 1990 novel and features a screenplay by Crichton and David Koepp.",
      "date": "1993-06-11"
    },
    {
      "headline": "Development and Pre-production",
      "text": "The development of Jurassic Park began in 1989 when Michael Crichton was writing the novel. Universal Pictures and Amblin Entertainment acquired the rights before the book was published in 1990.",
      "date": "1989"
    },
    {
      "headline": "Casting",
      "text": "The casting for Jurassic Park included Sam Neill, Laura Dern, Jeff Goldblum, and Richard Attenborough. The casting process took place in the early 1990s.",
      "date": "1992"
    },
    {
      "headline": "Filming",
      "text": "Principal photography for Jurassic Park began on August 24, 1992, and concluded on November 30, 1992. Filming locations included Hawaii and California.",
      "date": "1992-08-24"
    },
    {
      "headline": "Post-production and Special Effects",
      "text": "The post-production phase included groundbreaking special effects work by Industrial Light & Magic and the use of animatronics by Stan Winston's team. This phase lasted until early 1993.",
      "date": "1993"
    },
    {
      "headline": "Box Office Success",
      "text": "Jurassic Park became a box office success, grossing over $914 million worldwide during its original release, making it the highest-grossing film at the time until it was surpassed by Titanic in 1997.",
      "date": "1993"
    },
    {
      "headline": "Awards and Recognition",
      "text": "Jurassic Park won three Academy Awards for Best Sound, Best Sound Effects Editing, and Best Visual Effects at the 66th Academy Awards in 1994.",
      "date": "1994"
    },
    {
      "headline": "Legacy and Impact",
      "text": "Jurassic Park is credited with revolutionizing the use of computer-generated imagery in films and has had a lasting impact on the film industry and popular culture.",
      "date": "1993"
    }
  ]
}

