{
  "timeline": [
    {
      "headline": "Emergence in the Bristol Underground Scene",
      "text": "Banksy emerged as a street artist in the early 1990s, becoming part of the Bristol underground scene. This scene was known for collaborations between artists and musicians.",
      "date": "1990"
    },
    {
      "headline": "Adoption of Stenciling Technique",
      "text": "In the late 1990s, Banksy began using stencils to create his street art. This technique allowed him to work quickly and create more intricate designs.",
      "date": "1997"
    },
    {
      "headline": "First Major Exhibition: 'Turf War'",
      "text": "In 2003, Banksy held his first major exhibition, 'Turf War', in a London warehouse. The exhibition featured live animals and drew significant media attention.",
      "date": "2003"
    },
    {
      "headline": "Creation of 'Girl with a Balloon'",
      "text": "In 2002, Banksy created one of his most iconic works, 'Girl with a Balloon', which first appeared on the South Bank of London.",
      "date": "2002"
    },
    {
      "headline": "Release of 'Wall and Piece'",
      "text": "In 2005, Banksy published 'Wall and Piece', a book that compiles many of his works and thoughts on art and politics.",
      "date": "2005"
    },
    {
      "headline": "West Bank Barrier Art",
      "text": "In 2005, Banksy painted several pieces on the Israeli West Bank barrier, drawing international attention to the political situation in the region.",
      "date": "2005"
    },
    {
      "headline": "Debut of 'Exit Through the Gift Shop'",
      "text": "In 2010, Banksy directed and released 'Exit Through the Gift Shop', a documentary film that premiered at the Sundance Film Festival and was later nominated for an Academy Award.",
      "date": "2010"
    },
    {
      "headline": "Dismaland Bemusement Park",
      "text": "In 2015, Banksy opened 'Dismaland', a temporary art project and theme park in Weston-super-Mare, England. The project featured works by 58 artists and attracted over 150,000 visitors.",
      "date": "2015"
    },
    {
      "headline": "Creation of 'Devolved Parliament'",
      "text": "In 2009, Banksy created 'Devolved Parliament', a painting depicting the UK House of Commons populated by chimpanzees. It was later sold at auction in 2019 for a record price.",
      "date": "2009"
    },
    {
      "headline": "Self-Destructing Artwork 'Love is in the Bin'",
      "text": "In 2018, Banksy's 'Girl with a Balloon' partially shredded itself immediately after being sold at auction, creating a new artwork titled 'Love is in the Bin'.",
      "date": "2018"
    }
  ]
}

