{
  "timeline": [
    {
      "headline": "Makar Sankranti Festival",
      "text": "Makar Sankranti is a Hindu festival that marks the transition of the sun into the zodiac sign of Capricorn (Makara) from Sagittarius (Dhanu). It usually falls on January 14th each year. The festival is dedicated to the solar deity, Surya, and signifies the sun's northward journey, known as Uttarayana.",
      "date": "0000-01-14"
    },
    {
      "headline": "Cultural Significance",
      "text": "Makar Sankranti is celebrated across India with various cultural and regional variations. It marks the end of the winter solstice and the beginning of longer days. The festival is associated with harvest and is celebrated with activities like kite flying, bonfires, fairs, dances, and feasts.",
      "date": "0000-01-14"
    },
    {
      "headline": "Regional Celebrations",
      "text": "Different regions in India celebrate Makar Sankranti with unique customs. In Gujarat, it is known as Uttarayan and is famous for kite flying. In Tamil Nadu, it is celebrated as Pongal, a four-day festival. In Punjab, it is known as Maghi, and in Assam, it is celebrated as Bhogali Bihu.",
      "date": "0000-01-14"
    },
    {
      "headline": "Religious Observances",
      "text": "On Makar Sankranti, devotees take holy dips in rivers, especially in the Ganges, Yamuna, Godavari, Krishna, and Kaveri. It is believed that taking a dip in holy rivers on this day absolves sins and leads to Moksha.",
      "date": "0000-01-14"
    }
  ]
}

