{
  "timeline": [
    {
      "headline": "Founding of Carthage",
      "text": "Carthage was founded by the Phoenicians in the 9th century BC. It became a major power in the Mediterranean.",
      "date": "-0800"
    },
    {
      "headline": "Punic Wars",
      "text": "The Punic Wars were a series of conflicts fought between Carthage and Rome from 264 BC to 146 BC, leading to the eventual destruction of Carthage.",
      "date": "-0264"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 146 BC, Carthage was destroyed by the Romans, and its territory became a Roman province.",
      "date": "-0146"
    },
    {
      "headline": "Arab Conquest",
      "text": "In the 7th century, Arab forces conquered the region, bringing Islam and Arabic culture.",
      "date": "0698"
    },
    {
      "headline": "Establishment of the Aghlabid Dynasty",
      "text": "The Aghlabid dynasty was established in 800 AD, ruling over Ifriqiya (modern-day Tunisia) as a vassal of the Abbasid Caliphate.",
      "date": "0800"
    },
    {
      "headline": "Fatimid Caliphate",
      "text": "In 909, the Fatimid Caliphate was established, marking a significant shift in power and culture in the region.",
      "date": "0909"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Tunisia became part of the Ottoman Empire in 1574, remaining under Ottoman control until the late 19th century.",
      "date": "1574"
    },
    {
      "headline": "French Protectorate",
      "text": "In 1881, Tunisia became a French protectorate, marking the beginning of European colonial influence.",
      "date": "1881"
    },
    {
      "headline": "Independence from France",
      "text": "Tunisia gained independence from France on March 20, 1956, becoming a sovereign nation.",
      "date": "1956-03-20"
    },
    {
      "headline": "Establishment of the Republic of Tunisia",
      "text": "On July 25, 1957, Tunisia was declared a republic, with Habib Bourguiba as its first president.",
      "date": "1957-07-25"
    },
    {
      "headline": "Jasmine Revolution",
      "text": "The Jasmine Revolution began in December 2010, leading to the ousting of President Zine El Abidine Ben Ali on January 14, 2011, and sparking the Arab Spring.",
      "date": "2010-12"
    },
    {
      "headline": "Adoption of New Constitution",
      "text": "On January 26, 2014, Tunisia adopted a new constitution, marking a significant step in its democratic transition.",
      "date": "2014-01-26"
    }
  ]
}

