    },
    {
      "headline": "Suriname Becomes an Autonomous Part of the Kingdom of the Netherlands",
      "text": "On December 15, 1954, Suriname became an autonomous part of the Kingdom of the Netherlands, gaining self-governance in internal affairs.",
      "date": "1954-12-15"
