    },
    {
      "headline": "Ordination as a Priest",
      "text": "Martin Luther was ordained as a priest in 1507.",
      "date": "1507"
    },
    {
      "headline": "Luther Begins Teaching at University of Wittenberg",
      "text": "In 1508, Luther began teaching theology at the University of Wittenberg.",
      "date": "1508"
    },
    {
      "headline": "Luther Earns Doctorate in Theology",
      "text": "Martin Luther earned his Doctorate in Theology in 1512, becoming a professor of biblical studies.",
      "date": "1512"
    },
    {
      "headline": "Ninety-Five Theses",
      "text": "On October 31, 1517, Luther nailed his Ninety-Five Theses to the door of the Wittenberg Castle Church, challenging the Catholic Church's practices, particularly the sale of indulgences.",
      "date": "1517-10-31"
    },
    {
      "headline": "Excommunication by Pope Leo X",
      "text": "In 1521, Martin Luther was excommunicated by Pope Leo X after refusing to recant his teachings.",
      "date": "1521"
    },
    {
      "headline": "Diet of Worms",
      "text": "In April 1521, Luther appeared before the Diet of Worms, where he refused to recant his writings, famously stating, 'Here I stand, I can do no other.'",
      "date": "1521-04"
    },
    {
      "headline": "Translation of the New Testament",
      "text": "While in hiding at Wartburg Castle in 1522, Luther translated the New Testament into German, making it more accessible to the general public.",
      "date": "1522"
    },
    {
      "headline": "Publication of the Complete Bible in German",
      "text": "In 1534, Martin Luther published the complete Bible in German, which had a profound impact on the German language and the spread of Protestantism.",
      "date": "1534"
    },
    {
      "headline": "Death of Martin Luther",
      "text": "Martin Luther died on February 18, 1546, in Eisleben, the same town where he was born.",
