{
  "timeline": [
    {
      "headline": "Concept of a Global Network",
      "text": "In 1962, J.C.R. Licklider of MIT first proposed the concept of a global network of computers, which he called the 'Intergalactic Computer Network'.",
      "date": "1962"
    },
    {
      "headline": "Development of ARPANET",
      "text": "In 1969, the Advanced Research Projects Agency Network (ARPANET) was developed by the United States Department of Defense. It was the first network to implement the TCP/IP protocol suite.",
      "date": "1969"
    },
    {
      "headline": "First Message Sent Over ARPANET",
      "text": "On October 29, 1969, the first message was sent over ARPANET from UCLA to the Stanford Research Institute.",
      "date": "1969-10-29"
    },
    {
      "headline": "Introduction of TCP/IP",
      "text": "In 1974, Vint Cerf and Bob Kahn published the first specification of the Transmission Control Protocol (TCP), which later evolved into the Internet Protocol (IP).",
      "date": "1974"
    },
    {
      "headline": "First International ARPANET Connection",
      "text": "In 1973, the first international ARPANET connections were established to the University College of London and the Royal Radar Establishment in Norway.",
      "date": "1973"
    },
    {
      "headline": "Transition to TCP/IP",
      "text": "On January 1, 1983, ARPANET officially switched to using the TCP/IP protocol, marking the beginning of the modern Internet.",
      "date": "1983-01-01"
    },
    {
      "headline": "Domain Name System (DNS) Introduced",
      "text": "In 1984, the Domain Name System (DNS) was introduced, allowing users to use domain names instead of numerical IP addresses.",
      "date": "1984"
    },
    {
      "headline": "World Wide Web Invented",
      "text": "In 1989, Tim Berners-Lee, a British scientist at CERN, invented the World Wide Web (WWW).",
      "date": "1989"
    },
    {
      "headline": "First Website and Browser",
      "text": "In 1991, the first website and web browser were created by Tim Berners-Lee, launching the World Wide Web to the public.",
      "date": "1991"
    },
    {
      "headline": "Commercialization of the Internet",
      "text": "In 1995, the Internet was fully commercialized in the United States, with the NSFNET being decommissioned and restrictions on commercial use being lifted.",
      "date": "1995"
    },
    {
      "headline": "Google Founded",
      "text": "In 1998, Google was founded by Larry Page and Sergey Brin, which would become one of the most influential companies in the Internet industry.",
      "date": "1998"
    },
    {
      "headline": "Introduction of Wi-Fi",
      "text": "In 1999, Wi-Fi technology was introduced, allowing wireless access to the Internet.",
      "date": "1999"
    },
    {
      "headline": "Launch of Facebook",
      "text": "In 2004, Facebook was launched by Mark Zuckerberg and his college roommates, becoming one of the largest social networking platforms.",
      "date": "2004"
    },
    {
      "headline": "Introduction of the iPhone",
      "text": "In 2007, Apple introduced the iPhone, revolutionizing mobile Internet access.",
      "date": "2007"
    },
    {
      "headline": "Introduction of 4G Networks",
      "text": "In 2009, the first 4G networks were launched, providing faster mobile Internet speeds.",
      "date": "2009"
    },
    {
      "headline": "Launch of Instagram",
      "text": "In 2010, Instagram was launched, becoming a major platform for photo sharing and social networking.",
      "date": "2010"
    },
    {
      "headline": "Introduction of 5G Networks",
      "text": "In 2019, 5G networks began to be deployed, offering significantly faster Internet speeds and lower latency.",
      "date": "2019"
    }
  ]
}

