      "headline": "Foundation of Constantinople",
      "text": "Constantinople was founded by Emperor Constantine the Great on the site of the ancient city of Byzantium. It was officially dedicated on May 11, 330.",
      "date": "0330-05-11"
    },
    {
      "headline": "Capital of the Roman Empire",
      "text": "In 330, Constantinople became the capital of the Roman Empire under Emperor Constantine the Great.",
      "date": "0330"
    },
    {
      "headline": "Fall of the Western Roman Empire",
      "text": "Following the collapse of the Western Roman Empire in 476, Constantinople remained the capital of the Eastern Roman Empire, also known as the Byzantine Empire.",
      "date": "0476"
    },
    {
      "headline": "Fourth Crusade and the Latin Empire",
      "text": "In 1204, Constantinople was captured by the Fourth Crusade, leading to the establishment of the Latin Empire, which lasted until 1261.",
      "date": "1204"
    },
    {
      "headline": "Restoration of Byzantine Rule",
      "text": "In 1261, the Byzantine Empire was restored when the Nicaean forces recaptured Constantinople from the Latin Empire.",
      "date": "1261"
    },
    {
      "headline": "Fall of Constantinople",
      "text": "On May 29, 1453, Constantinople fell to the Ottoman Empire under Sultan Mehmed II, marking the end of the Byzantine Empire.",
      "date": "1453-05-29"
    },
    {
      "headline": "Capital of the Ottoman Empire",
      "text": "After its conquest in 1453, Constantinople became the capital of the Ottoman Empire.",
      "date": "1453"
    },
    {
      "headline": "Turkish War of Independence",
      "text": "Following the Turkish War of Independence, the capital of Turkey was moved from Constantinople to Ankara in 1923.",
      "date": "1923"
    },
    {
      "headline": "Renaming to Istanbul",
      "text": "In 1930, Constantinople was officially renamed Istanbul.",
      "date": "1930"
    }
  ]
}

