{
  "timeline": [
    {
      "headline": "1932 United States Presidential Election",
      "text": "Presidential elections were held in the United States on November 8, 1932. Against the backdrop of the Great Depression, incumbent Republican President Herbert Hoover was defeated in a landslide by Democrat Franklin D. Roosevelt, the governor of New York.",
      "date": "1932-11-08"
    },
    {
      "headline": "Franklin D. Roosevelt Wins Majority",
      "text": "Franklin D. Roosevelt was the first Democrat in 80 years to simultaneously win an outright majority of the electoral college and popular vote, a feat last accomplished by Franklin Pierce in 1852.",
      "date": "1932-11-08"
    },
    {
      "headline": "Roosevelt's Popular Vote Majority",
      "text": "Roosevelt was the first Democrat in 56 years to win a majority of the popular vote, which was last achieved by Samuel J. Tilden in 1876.",
      "date": "1932-11-08"
    },
    {
      "headline": "End of the Fourth Party System",
      "text": "The election marked the effective end of the Fourth Party System, which had been dominated by Republicans.",
      "date": "1932-11-08"
    },
    {
      "headline": "Historical Context of Hoover's Defeat",
      "text": "Herbert Hoover became the first incumbent president to lose an election to another term since William Howard Taft in 1912, the last to do so until Gerald Ford lost 44 years later, and the last elected incumbent president to do so until Jimmy Carter lost 48 years later.",
      "date": "1932-11-08"
    },
    {
      "headline": "Democratic Presidential Victory",
      "text": "It was the first time since 1916 that a Democrat was elected president.",
      "date": "1932-11-08"
    }
  ]
}

