      "headline": "Birth of Oliver Cromwell",
      "text": "Oliver Cromwell was born on April 25, 1599, in Huntingdon, England.",
      "date": "1599-04-25"
    },
    {
      "headline": "Marriage to Elizabeth Bourchier",
      "text": "On August 22, 1620, Oliver Cromwell married Elizabeth Bourchier.",
      "date": "1620-08-22"
