    }
  ]
}

{
  "timeline": [
    {
      "headline": "Beginning of British Raj",
      "text": "The British Raj officially began after the Indian Rebellion of 1857, leading to the dissolution of the East India Company's rule and the transfer of control to the British Crown. This transition was formalized by the Government of India Act 1858, which came into effect on November 1, 1858.",
      "date": "1858-11-01"
    },
    {
      "headline": "First Durbar Held",
      "text": "The first Delhi Durbar, a mass assembly at Coronation Park, Delhi, was held in 1877 to mark the proclamation of Queen Victoria as Empress of India.",
      "date": "1877"
    },
    {
      "headline": "Partition of Bengal",
      "text": "The Partition of Bengal was announced on July 20, 1905, and came into effect on October 16, 1905, dividing the province into two parts for administrative purposes.",
      "date": "1905-10-16"
    },
    {
      "headline": "Reversal of Bengal Partition",
      "text": "Due to widespread protests, the partition of Bengal was reversed on December 12, 1911, during the Delhi Durbar, and the capital of British India was moved from Calcutta to Delhi.",
      "date": "1911-12-12"
    },
    {
      "headline": "Montagu-Chelmsford Reforms",
      "text": "The Montagu-Chelmsford Reforms were introduced by the Government of India Act 1919, which expanded the participation of Indians in the governance of British India.",
      "date": "1919"
    },
    {
      "headline": "Salt March",
      "text": "The Salt March, led by Mahatma Gandhi, began on March 12, 1930, as a direct action campaign of tax resistance and nonviolent protest against the British salt monopoly.",
      "date": "1930-03-12"
    },
    {
      "headline": "Government of India Act 1935",
      "text": "The Government of India Act 1935 was enacted, providing for the establishment of an All-India Federation and provincial autonomy.",
      "date": "1935"
    },
    {
      "headline": "India's Participation in World War II",
      "text": "India, as part of the British Empire, participated in World War II from 1939 to 1945, contributing significant resources and manpower to the Allied war effort.",
      "date": "1939"
    },
    {
      "headline": "Quit India Movement",
      "text": "The Quit India Movement was launched by the Indian National Congress on August 8, 1942, demanding an end to British rule in India.",
      "date": "1942-08-08"
    },
    {
      "headline": "End of British Raj",
      "text": "The British Raj ended with the Indian Independence Act 1947, which led to the partition of India and the creation of two independent dominions, India and Pakistan, on August 15, 1947.",
      "date": "1947-08-15"
    }
  ]
}

