      "date": "1923"
    },
    {
      "headline": "Gutzon Borglum Hired",
      "text": "In 1924, sculptor Gutzon Borglum was hired to design and oversee the project. He chose the site of Mount Rushmore for its grand location and quality of granite.",
      "date": "1924"
    },
    {
      "headline": "Construction Begins",
      "text": "On October 4, 1927, construction on Mount Rushmore began. The project was initially funded by federal funds, private donations, and a large contribution from the state of South Dakota.",
      "date": "1927-10-04"
    },
    {
      "headline": "George Washington's Face Completed",
      "text": "The face of George Washington was completed and dedicated on July 4, 1930.",
      "date": "1930-07-04"
    },
    {
      "headline": "Thomas Jefferson's Face Completed",
      "text": "The face of Thomas Jefferson was completed and dedicated on August 30, 1936.",
      "date": "1936-08-30"
    },
    {
      "headline": "Abraham Lincoln's Face Completed",
      "text": "The face of Abraham Lincoln was completed and dedicated on September 17, 1937.",
      "date": "1937-09-17"
    },
    {
      "headline": "Theodore Roosevelt's Face Completed",
      "text": "The face of Theodore Roosevelt was completed and dedicated on July 2, 1939.",
      "date": "1939-07-02"
    },
    {
      "headline": "Death of Gutzon Borglum",
      "text": "Gutzon Borglum died on March 6, 1941, before the completion of the project. His son, Lincoln Borglum, took over the project.",
      "date": "1941-03-06"
    },
    {
      "headline": "Completion of Mount Rushmore",
      "text": "The construction of Mount Rushmore was declared complete on October 31, 1941, although it was not finished to the original design due to lack of funding.",
      "date": "1941-10-31"
    }
  ]
}

