{
  "timeline": [
    {
      "headline": "Earliest Known Use of Pi",
      "text": "The earliest known written approximations of π are found in ancient Egypt and Babylon, dating back to around 1900 BC.",
      "date": "-1900"
    },
    {
      "headline": "Archimedes' Approximation",
      "text": "Around 250 BC, the Greek mathematician Archimedes developed a method to approximate π by inscribing and circumscribing polygons around a circle. He calculated that π is between 3 1/7 (approximately 3.1429) and 3 10/71 (approximately 3.1408).",
      "date": "-0250"
    },
    {
      "headline": "Liu Hui's Calculation",
      "text": "In 263 AD, Chinese mathematician Liu Hui used a 96-sided polygon to calculate π to be approximately 3.14159.",
      "date": "0263"
    },
    {
      "headline": "Zu Chongzhi's Approximation",
      "text": "Around 480 AD, Chinese mathematician Zu Chongzhi calculated π to be approximately 355/113 (3.1415929), a very accurate approximation for the time.",
      "date": "0480"
    },
    {
      "headline": "Madhava of Sangamagrama's Series",
      "text": "In the 14th century, Indian mathematician Madhava of Sangamagrama developed an infinite series to calculate π, which later became known as the Madhava-Leibniz series.",
      "date": "1300"
    },
    {
      "headline": "Ludolph van Ceulen's Calculation",
      "text": "In the late 16th century, Ludolph van Ceulen calculated π to 35 decimal places using polygons with up to 2^62 sides.",
      "date": "1596"
    },
    {
      "headline": "Introduction of the Symbol π",
      "text": "In 1706, Welsh mathematician William Jones introduced the symbol π to represent the ratio of the circumference of a circle to its diameter.",
      "date": "1706"
    },
    {
      "headline": "Euler's Popularization of π",
      "text": "In the 18th century, Swiss mathematician Leonhard Euler popularized the use of the symbol π in his works, helping it become widely accepted.",
      "date": "1737"
    },
    {
      "headline": "Ramanujan's Formulas",
      "text": "In the early 20th century, Indian mathematician Srinivasa Ramanujan developed several rapidly converging series for calculating π.",
      "date": "1910"
    },
    {
      "headline": "Computer Calculations of π",
      "text": "In the mid-20th century, with the advent of computers, π was calculated to thousands and then millions of decimal places, with the first computer-based calculation performed in 1949.",
      "date": "1949"
    }
  ]
}

