{
  "timeline": [
    {
      "headline": "First Lobotomy Procedure",
      "text": "In 1935, the first lobotomy procedure was performed by Portuguese neurologist António Egas Moniz. He developed the procedure as a treatment for mental disorders.",
      "date": "1935"
    },
    {
      "headline": "Introduction of the Transorbital Lobotomy",
      "text": "In 1946, American psychiatrist Walter Freeman developed the transorbital lobotomy, a quicker and less invasive version of the procedure, which involved accessing the brain through the eye sockets.",
      "date": "1946"
    },
    {
      "headline": "Peak Popularity of Lobotomy",
      "text": "During the late 1940s and early 1950s, lobotomies reached peak popularity, with thousands of procedures being performed worldwide, particularly in the United States.",
      "date": "1950"
    },
    {
      "headline": "Decline in Lobotomy Procedures",
      "text": "In the mid-1950s, the use of lobotomies began to decline with the introduction of antipsychotic medications, which offered a less invasive treatment for mental disorders.",
      "date": "1955"
    },
    {
      "headline": "Lobotomy Largely Discredited",
      "text": "By the 1970s, lobotomy was largely discredited as a treatment for mental illness due to its severe side effects and the development of more effective psychiatric medications.",
      "date": "1970"
    }
  ]
}

