      "date": "1924-12-25"
    },
    {
      "headline": "Joined Rashtriya Swayamsevak Sangh (RSS)",
      "text": "In 1939, Vajpayee joined the Rashtriya Swayamsevak Sangh (RSS), a Hindu nationalist volunteer organization.",
      "date": "1939"
    },
    {
      "headline": "Became a Member of Parliament",
      "text": "In 1957, Vajpayee was elected to the Lok Sabha, the lower house of India's Parliament, for the first time.",
      "date": "1957"
    },
    {
      "headline": "Co-founded Bharatiya Janata Party (BJP)",
      "text": "In 1980, Vajpayee co-founded the Bharatiya Janata Party (BJP) and became its first president.",
      "date": "1980"
    },
    {
      "headline": "First Term as Prime Minister",
      "text": "Vajpayee served his first term as the Prime Minister of India for 13 days from May 16, 1996, to May 28, 1996.",
      "date": "1996-05-16"
    },
    {
      "headline": "Second Term as Prime Minister",
      "text": "Vajpayee served his second term as the Prime Minister of India from March 19, 1998, to April 17, 1999.",
      "date": "1998-03-19"
    },
    {
      "headline": "Third Term as Prime Minister",
      "text": "Vajpayee began his third term as the Prime Minister of India on October 13, 1999, and served until May 22, 2004.",
      "date": "1999-10-13"
    },
    {
      "headline": "Pokhran-II Nuclear Tests",
      "text": "In May 1998, during his second term, Vajpayee authorized nuclear tests in Pokhran, Rajasthan, making India a nuclear weapons state.",
      "date": "1998-05"
    },
    {
      "headline": "Lahore Declaration",
      "text": "In February 1999, Vajpayee signed the Lahore Declaration with Pakistan, aiming to improve bilateral relations.",
      "date": "1999-02"
    },
    {
      "headline": "Kargil War",
      "text": "In 1999, during Vajpayee's third term, India fought the Kargil War against Pakistan, which ended in July 1999.",
      "date": "1999-07"
    },
    {
      "headline": "Retirement from Active Politics",
      "text": "Vajpayee retired from active politics in December 2005 due to health issues.",
      "date": "2005-12"
    },
    {
      "headline": "Death of Atal Bihari Vajpayee",
      "text": "Atal Bihari Vajpayee passed away on August 16, 2018, in New Delhi, India.",
      "date": "2018-08-16"
    }
  ]
}

