{
  "timeline": [
    {
      "headline": "Establishment of the Israel Defense Forces",
      "text": "The Israel Defense Forces (IDF) were officially established on May 26, 1948, following the declaration of the State of Israel on May 14, 1948. The IDF was formed by consolidating various paramilitary groups, including the Haganah, Irgun, and Lehi, into a unified military force.",
      "date": "1948-05-26"
    },
    {
      "headline": "First Arab-Israeli War",
      "text": "The IDF participated in the First Arab-Israeli War, also known as the War of Independence, which lasted from May 1948 to March 1949. This conflict involved neighboring Arab states invading the newly declared State of Israel.",
      "date": "1948-05"
    },
    {
      "headline": "Suez Crisis",
      "text": "In October 1956, the IDF launched Operation Kadesh during the Suez Crisis, a military campaign in the Sinai Peninsula against Egypt, in coordination with France and the United Kingdom.",
      "date": "1956-10"
    },
    {
      "headline": "Six-Day War",
      "text": "From June 5 to June 10, 1967, the IDF fought in the Six-Day War against Egypt, Jordan, and Syria. Israel achieved a decisive victory, capturing the Sinai Peninsula, Gaza Strip, West Bank, East Jerusalem, and the Golan Heights.",
      "date": "1967-06-05"
    },
    {
      "headline": "Yom Kippur War",
      "text": "On October 6, 1973, the IDF was involved in the Yom Kippur War, when Egypt and Syria launched a surprise attack on Israel during the Jewish holy day of Yom Kippur. The war lasted until October 25, 1973.",
      "date": "1973-10-06"
    },
    {
      "headline": "Operation Entebbe",
      "text": "On July 4, 1976, the IDF conducted Operation Entebbe, a successful counter-terrorist hostage-rescue mission at Entebbe Airport in Uganda, rescuing 102 hostages held by Palestinian and German terrorists.",
      "date": "1976-07-04"
    },
    {
      "headline": "First Lebanon War",
      "text": "The IDF invaded southern Lebanon on June 6, 1982, in what became known as the First Lebanon War, aiming to expel the Palestine Liberation Organization (PLO) from the region.",
      "date": "1982-06-06"
    },
    {
      "headline": "Second Lebanon War",
      "text": "The IDF engaged in the Second Lebanon War from July 12 to August 14, 2006, against Hezbollah forces in Lebanon, following the abduction of two Israeli soldiers by Hezbollah.",
      "date": "2006-07-12"
    },
    {
      "headline": "Operation Protective Edge",
      "text": "In July 2014, the IDF launched Operation Protective Edge in the Gaza Strip, a military operation aimed at stopping rocket fire from Hamas and destroying tunnels used for attacks on Israel.",
      "date": "2014-07"
    }
  ]
}

