{
  "timeline": [
    {
      "headline": "Founding of the East India Company",
      "text": "The East India Company was founded on December 31, 1600, by a royal charter from Queen Elizabeth I, granting it a monopoly on English trade with the East Indies.",
      "date": "1600-12-31"
    },
    {
      "headline": "First Voyage",
      "text": "In 1601, the East India Company dispatched its first voyage under the command of James Lancaster, marking the beginning of its trading operations.",
      "date": "1601"
    },
    {
      "headline": "Battle of Swally",
      "text": "In 1612, the East India Company won the Battle of Swally against the Portuguese, establishing its naval dominance in the Indian Ocean.",
      "date": "1612"
    },
    {
      "headline": "Establishment of First Factory",
      "text": "In 1613, the company established its first factory in Surat, India, marking the beginning of its commercial presence on the Indian subcontinent.",
      "date": "1613"
    },
    {
      "headline": "Acquisition of Bombay",
      "text": "In 1668, the company acquired Bombay from the British Crown, which had received it as part of the dowry of Catherine of Braganza when she married Charles II.",
      "date": "1668"
    },
    {
      "headline": "Battle of Plassey",
      "text": "On June 23, 1757, the East India Company, led by Robert Clive, defeated the Nawab of Bengal at the Battle of Plassey, marking the beginning of British control over Bengal.",
      "date": "1757-06-23"
    },
    {
      "headline": "Regulating Act of 1773",
      "text": "In 1773, the British Parliament passed the Regulating Act to address the mismanagement of the East India Company and to establish greater control over its operations.",
      "date": "1773"
    },
    {
      "headline": "Pitt's India Act",
      "text": "In 1784, Pitt's India Act was passed, creating a dual system of control by establishing the Board of Control to oversee the company's affairs.",
      "date": "1784"
    },
    {
      "headline": "Charter Act of 1813",
      "text": "The Charter Act of 1813 ended the company's monopoly on trade with India, allowing other British merchants to trade in the region.",
      "date": "1813"
    },
    {
      "headline": "First Anglo-Burmese War",
      "text": "From 1824 to 1826, the East India Company fought the First Anglo-Burmese War, resulting in the annexation of parts of Burma.",
      "date": "1824"
    },
    {
      "headline": "Charter Act of 1833",
      "text": "The Charter Act of 1833 further reduced the company's commercial privileges and centralized the administration of British India.",
      "date": "1833"
    },
    {
      "headline": "Indian Rebellion of 1857",
      "text": "In 1857, a major rebellion against the East India Company's rule broke out, leading to the end of the company's control over India.",
      "date": "1857"
    },
    {
      "headline": "Government of India Act 1858",
      "text": "Following the Indian Rebellion, the Government of India Act 1858 transferred the company's powers to the British Crown, effectively ending its rule in India.",
      "date": "1858"
    },
    {
      "headline": "Dissolution of the East India Company",
      "text": "The East India Company was formally dissolved on June 1, 1874, after the East India Stock Dividend Redemption Act was passed.",
      "date": "1874-06-01"
    }
  ]
}

