{
  "timeline": [
    {
      "headline": "First Settlement by Amerindians",
      "text": "The first known inhabitants of Barbados were Amerindians who arrived from Venezuela's Orinoco Valley around 1600 BCE.",
      "date": "-1600"
    },
    {
      "headline": "Arrival of the Arawaks",
      "text": "The Arawaks, a group of Amerindians, settled in Barbados around 800 CE.",
      "date": "0800"
    },
    {
      "headline": "Arrival of the Caribs",
      "text": "The Caribs, another Amerindian group, arrived in Barbados around 1200 CE, displacing the Arawaks.",
      "date": "1200"
    },
    {
      "headline": "Portuguese Discovery",
      "text": "In 1536, the Portuguese explorer Pedro a Campos discovered Barbados and named it Los Barbados.",
      "date": "1536"
    },
    {
      "headline": "First English Ship Arrives",
      "text": "In 1625, the first English ship, the Olive Blossom, arrived in Barbados, claiming it for King James I.",
      "date": "1625"
    },
    {
      "headline": "First Permanent English Settlement",
      "text": "In 1627, the first permanent English settlement was established at Holetown by Captain Henry Powell.",
      "date": "1627"
    },
    {
      "headline": "Establishment of the House of Assembly",
      "text": "In 1639, the House of Assembly was established, making it one of the oldest parliaments in the world.",
      "date": "1639"
    },
    {
      "headline": "Sugar Revolution",
      "text": "In the 1640s, Barbados underwent the Sugar Revolution, transforming its economy and society with the introduction of sugar cane cultivation.",
      "date": "1640"
    },
    {
      "headline": "Abolition of Slavery",
      "text": "Slavery was abolished in Barbados on August 1, 1834, following the Slavery Abolition Act 1833.",
      "date": "1834-08-01"
    },
    {
      "headline": "Independence from the United Kingdom",
      "text": "Barbados gained independence from the United Kingdom on November 30, 1966, becoming a sovereign nation.",
      "date": "1966-11-30"
    },
    {
      "headline": "Becoming a Republic",
      "text": "On November 30, 2021, Barbados became a republic, removing Queen Elizabeth II as head of state and inaugurating its first President, Sandra Mason.",
      "date": "2021-11-30"
    }
  ]
}

