{
  "timeline": [
    {
      "headline": "Birth of Aristotle",
      "text": "Aristotle was born in 384 BCE in Stagira, a town in Chalcidice, Greece.",
      "date": "-0384"
    },
    {
      "headline": "Aristotle Moves to Athens",
      "text": "In 367 BCE, Aristotle moved to Athens to join Plato's Academy, where he studied under Plato for nearly 20 years.",
      "date": "-0367"
    },
    {
      "headline": "Aristotle Leaves Athens",
      "text": "After Plato's death in 347 BCE, Aristotle left Athens and traveled to Asia Minor and the island of Lesbos.",
      "date": "-0347"
    },
    {
      "headline": "Aristotle Tutors Alexander the Great",
      "text": "In 343 BCE, Aristotle was invited by King Philip II of Macedon to tutor his son, Alexander, who would later become Alexander the Great.",
      "date": "-0343"
    },
    {
      "headline": "Founding of the Lyceum",
      "text": "In 335 BCE, Aristotle returned to Athens and founded his own school, the Lyceum, where he conducted research and taught for the next 12 years.",
      "date": "-0335"
    },
    {
      "headline": "Aristotle Leaves Athens Again",
      "text": "In 323 BCE, following the death of Alexander the Great and the rise of anti-Macedonian sentiment in Athens, Aristotle left the city to avoid prosecution.",
      "date": "-0323"
    },
    {
      "headline": "Death of Aristotle",
      "text": "Aristotle died in 322 BCE in Euboea, Greece, at the age of 62.",
      "date": "-0322"
    }
  ]
}

