{
  "timeline": [
    {
      "headline": "Earliest Attestation of Tamil",
      "text": "The earliest records of Tamil date back to around 300 BCE, with inscriptions found in caves and on pottery.",
      "date": "-0300"
    },
    {
      "headline": "Sangam Literature Period",
      "text": "The Sangam literature, a body of ancient Tamil literature, was composed between 300 BCE and 300 CE. This period is known for its rich poetic tradition.",
      "date": "-0300"
    },
    {
      "headline": "Tolkāppiyam Composition",
      "text": "The Tolkāppiyam, the earliest extant Tamil grammar text, is believed to have been composed around 300 BCE to 200 CE.",
      "date": "-0300"
    },
    {
      "headline": "Tamil-Brahmi Script Development",
      "text": "The Tamil-Brahmi script, an early script used to write Tamil, was developed around 300 BCE.",
      "date": "-0300"
    },
    {
      "headline": "Medieval Tamil Literature",
      "text": "Between 600 CE and 1300 CE, Tamil literature flourished with the creation of devotional texts and epics like the Thirukkural.",
      "date": "0600"
    },
