{
  "timeline": [
    {
      "headline": "Birth of William Henry Harrison",
      "text": "William Henry Harrison was born on February 9, 1773, in Charles City County, Virginia, in the Thirteen Colonies.",
      "date": "1773-02-09"
    },
    {
      "headline": "Military Service Begins",
      "text": "In 1791, William Henry Harrison joined the United States Army and began his military service, which would later include significant roles in the Northwest Indian War.",
      "date": "1791"
    },
    {
      "headline": "Battle of Fallen Timbers",
      "text": "Harrison served as an aide-de-camp to General Anthony Wayne during the Battle of Fallen Timbers on August 20, 1794, which was a decisive victory for the United States.",
      "date": "1794-08-20"
    },
    {
      "headline": "Governor of Indiana Territory",
      "text": "In 1801, Harrison was appointed as the governor of the Indiana Territory, a position he held until 1812.",
      "date": "1801"
    },
    {
      "headline": "Battle of Tippecanoe",
      "text": "On November 7, 1811, Harrison led U.S. forces to victory against Native American warriors at the Battle of Tippecanoe, enhancing his national reputation.",
      "date": "1811-11-07"
    },
    {
      "headline": "War of 1812",
      "text": "During the War of 1812, Harrison served as a major general in the U.S. Army, playing a key role in the American victory at the Battle of the Thames on October 5, 1813.",
      "date": "1813-10-05"
    },
    {
      "headline": "Elected to U.S. House of Representatives",
      "text": "Harrison was elected to the U.S. House of Representatives from Ohio, serving from 1816 to 1819.",
      "date": "1816"
    },
    {
      "headline": "U.S. Senator from Ohio",
      "text": "Harrison served as a U.S. Senator from Ohio from 1825 to 1828.",
      "date": "1825"
    },
    {
      "headline": "Minister to Gran Colombia",
      "text": "In 1828, Harrison was appointed as the U.S. Minister to Gran Colombia, serving until 1829.",
      "date": "1828"
    },
    {
      "headline": "Elected President of the United States",
      "text": "William Henry Harrison was elected as the ninth President of the United States in 1840, taking office on March 4, 1841.",
      "date": "1841-03-04"
    },
    {
      "headline": "Death of William Henry Harrison",
      "text": "Harrison died on April 4, 1841, just 31 days into his presidency, making his the shortest presidency in U.S. history.",
      "date": "1841-04-04"
    }
  ]
}

