    {
      "headline": "Proposal of the Twenty-fifth Amendment",
      "text": "The Twenty-fifth Amendment to the United States Constitution was proposed by Congress on July 6, 1965.",
      "date": "1965-07-06"
    },
    {
      "headline": "Ratification of the Twenty-fifth Amendment",
      "text": "The Twenty-fifth Amendment was ratified on February 10, 1967, when Nevada became the 38th state to approve it.",
      "date": "1967-02-10"
    },
    {
      "headline": "First Use: Spiro Agnew's Resignation",
      "text": "The first use of the Twenty-fifth Amendment occurred on October 10, 1973, when Vice President Spiro Agnew resigned, and President Richard Nixon nominated Gerald Ford as Vice President.",
      "date": "1973-10-10"
    },
    {
      "headline": "Gerald Ford Becomes Vice President",
      "text": "Gerald Ford was confirmed by Congress and sworn in as Vice President on December 6, 1973, under the Twenty-fifth Amendment.",
      "date": "1973-12-06"
    },
    {
      "headline": "Nixon's Resignation and Ford's Presidency",
      "text": "On August 9, 1974, President Richard Nixon resigned, and Vice President Gerald Ford became President, marking the first time the Twenty-fifth Amendment was used for presidential succession.",
      "date": "1974-08-09"
    },
    {
      "headline": "Nelson Rockefeller Becomes Vice President",
      "text": "Nelson Rockefeller was confirmed by Congress and sworn in as Vice President on December 19, 1974, following Gerald Ford's ascension to the presidency.",
      "date": "1974-12-19"
    },
    {
      "headline": "First Use of Section 3: Ronald Reagan",
      "text": "On July 13, 1985, President Ronald Reagan temporarily transferred power to Vice President George H. W. Bush under Section 3 of the Twenty-fifth Amendment during a medical procedure.",
      "date": "1985-07-13"
    },
    {
      "headline": "Use of Section 3: George W. Bush",
      "text": "President George W. Bush invoked Section 3 of the Twenty-fifth Amendment twice, on June 29, 2002, and July 21, 2007, temporarily transferring power to Vice President Dick Cheney during medical procedures.",
      "date": "2002-06-29"
    },
    {
      "headline": "Second Use of Section 3: George W. Bush",
      "text": "On July 21, 2007, President George W. Bush again invoked Section 3 of the Twenty-fifth Amendment, temporarily transferring power to Vice President Dick Cheney during a medical procedure.",
      "date": "2007-07-21"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Early Socialist Thought",
      "text": "Socialist ideas can be traced back to ancient times, with early forms of communal living and shared resources seen in various societies. However, the term 'socialism' itself was not used until the 19th century.",
      "date": "-0001"
    },
    {
      "headline": "Utopian Socialism",
      "text": "In the early 19th century, thinkers like Robert Owen and Charles Fourier developed utopian socialist ideas, advocating for cooperative communities and social reforms.",
      "date": "1820"
    },
    {
      "headline": "Karl Marx and Friedrich Engels Publish The Communist Manifesto",
      "text": "In 1848, Karl Marx and Friedrich Engels published 'The Communist Manifesto', which became one of the most influential political documents, advocating for revolutionary socialism and the abolition of capitalist societies.",
      "date": "1848"
    },
    {
      "headline": "First International",
      "text": "The International Workingmen's Association, known as the First International, was founded in 1864. It aimed to unite various socialist, communist, and anarchist groups.",
      "date": "1864"
    },
    {
      "headline": "Paris Commune",
      "text": "In 1871, the Paris Commune was established, becoming the first socialist government in history, albeit short-lived, lasting only two months.",
      "date": "1871"
    },
    {
      "headline": "Second International",
      "text": "The Second International was founded in 1889 to continue the work of the First International, promoting socialism and coordinating efforts among socialist parties worldwide.",
      "date": "1889"
    },
    {
      "headline": "Russian Revolution",
      "text": "In 1917, the Russian Revolution led to the establishment of the Soviet Union, the first country to be governed under Marxist-Leninist principles.",
      "date": "1917"
    },
    {
      "headline": "Formation of the Communist International",
      "text": "In 1919, the Communist International (Comintern) was founded to promote world communism and coordinate socialist movements globally.",
      "date": "1919"
    },
    {
      "headline": "Rise of Democratic Socialism",
      "text": "Post-World War II, democratic socialism gained prominence in Western Europe, with many countries adopting welfare state policies and mixed economies.",
      "date": "1945"
    },
    {
      "headline": "Collapse of the Soviet Union",
      "text": "In 1991, the Soviet Union dissolved, marking the end of the Cold War and a significant shift in global socialist movements.",
      "date": "1991"
    },
    {
      "headline": "21st Century Socialism",
      "text": "In the 21st century, socialism has seen a resurgence in various forms, including democratic socialism in Western countries and socialist policies in Latin America.",
      "date": "2000"
    }
  ]
}

