{
  "timeline": [
    {
      "headline": "First Inhabitants",
      "text": "The first inhabitants of The Bahamas were the Lucayans, a branch of the Taino people, who arrived around the 9th century.",
      "date": "-0800"
    },
    {
      "headline": "Christopher Columbus' Arrival",
      "text": "On October 12, 1492, Christopher Columbus made his first landfall in the New World on an island he named San Salvador, which is part of The Bahamas.",
      "date": "1492-10-12"
    },
    {
      "headline": "Spanish Claim",
      "text": "The Spanish claimed The Bahamas in the early 16th century, but they did not colonize the islands.",
      "date": "1500"
    },
    {
      "headline": "British Settlement",
      "text": "The first British settlement was established in The Bahamas in 1648 by a group known as the Eleutheran Adventurers.",
      "date": "1648"
    },
    {
      "headline": "Piracy Era",
      "text": "During the late 17th and early 18th centuries, The Bahamas became a haven for pirates, including the infamous Blackbeard.",
      "date": "1700"
    },
    {
      "headline": "British Colony",
      "text": "In 1718, The Bahamas became a British crown colony, and Woodes Rogers was appointed as the first Royal Governor to restore order.",
      "date": "1718"
    },
    {
      "headline": "Abolition of Slavery",
      "text": "Slavery was abolished in The Bahamas on August 1, 1834, following the British Empire's Slavery Abolition Act of 1833.",
      "date": "1834-08-01"
    },
    {
      "headline": "Internal Self-Government",
      "text": "The Bahamas achieved internal self-government in 1964.",
      "date": "1964"
    },
    {
      "headline": "Independence",
      "text": "The Bahamas became an independent Commonwealth realm on July 10, 1973, retaining Queen Elizabeth II as its monarch.",
      "date": "1973-07-10"
    },
    {
      "headline": "Hurricane Dorian",
      "text": "In September 2019, Hurricane Dorian, a Category 5 storm, caused widespread devastation in The Bahamas, particularly on the islands of Abaco and Grand Bahama.",
      "date": "2019-09"
    }
  ]
}

