{
  "timeline": [
    {
      "headline": "Formation of the Manhattan Project",
      "text": "In 1942, the Manhattan Project was formed as a research and development program to produce the first nuclear weapons during World War II. It was led by the United States with collaboration from the United Kingdom and Canada.",
      "date": "1942"
    },
    {
      "headline": "Appointment of Major General Leslie Groves",
      "text": "In 1942, Major General Leslie Groves of the U.S. Army Corps of Engineers was appointed to direct the Manhattan Project.",
      "date": "1942"
    },
    {
      "headline": "J. Robert Oppenheimer Becomes Director",
      "text": "Nuclear physicist J. Robert Oppenheimer was appointed as the director of the Los Alamos Laboratory, which was responsible for designing the nuclear bombs.",
      "date": "1942"
    },
    {
      "headline": "Integration of Tube Alloys",
      "text": "The Manhattan Project absorbed the British nuclear weapons project known as Tube Alloys, integrating efforts between the United States and the United Kingdom.",
      "date": "1943"
    },
    {
      "headline": "Development of the First Nuclear Weapons",
      "text": "From 1942 to 1946, the Manhattan Project developed the first nuclear weapons, employing nearly 130,000 people and costing nearly US$2 billion.",
      "date": "1942-1946"
    },
    {
      "headline": "Trinity Test",
      "text": "On July 16, 1945, the first nuclear weapon test, known as the Trinity Test, was conducted in the New Mexico desert, marking the first detonation of a nuclear device.",
      "date": "1945-07-16"
    },
    {
      "headline": "Bombing of Hiroshima",
      "text": "On August 6, 1945, the United States dropped the atomic bomb 'Little Boy' on the Japanese city of Hiroshima, marking the first use of nuclear weapons in warfare.",
      "date": "1945-08-06"
    },
    {
      "headline": "Bombing of Nagasaki",
      "text": "On August 9, 1945, the United States dropped the atomic bomb 'Fat Man' on the Japanese city of Nagasaki, leading to Japan's surrender and the end of World War II.",
      "date": "1945-08-09"
    },
    {
      "headline": "End of the Manhattan Project",
      "text": "The Manhattan Project officially ended in 1946, transitioning its responsibilities to the United States Atomic Energy Commission.",
      "date": "1946"
    }
  ]
}

