{
  "timeline": [
    {
      "headline": "First Recorded Contact",
      "text": "In 1771, the British surveyor John Ritchie observed lights on North Sentinel Island, marking the first recorded contact with the island.",
      "date": "1771"
    },
    {
      "headline": "British Expedition",
      "text": "In 1867, an Indian merchant ship called the Nineveh was wrecked on the reef surrounding North Sentinel Island. The crew survived and reached the beach, where they were attacked by the Sentinelese. They were later rescued by a Royal Navy ship.",
      "date": "1867"
    },
    {
      "headline": "British Colonial Expedition",
      "text": "In 1880, Maurice Vidal Portman, a British colonial officer, led an expedition to North Sentinel Island. He captured six Sentinelese individuals but later released them after two of them died.",
      "date": "1880"
    },
    {
      "headline": "Indian Government's Contact Attempts",
      "text": "In the 1960s, the Indian government began making attempts to contact the Sentinelese, led by anthropologist T.N. Pandit. These attempts continued sporadically over the following decades.",
      "date": "1960"
    },
    {
      "headline": "End of Contact Expeditions",
      "text": "In 1996, the Indian government decided to cease all attempts to contact the Sentinelese, recognizing their desire for isolation.",
      "date": "1996"
    },
    {
      "headline": "Designation as a Tribal Reserve",
      "text": "In 2005, the Indian government designated North Sentinel Island as a tribal reserve and prohibited travel within three nautical miles of the island.",
      "date": "2005"
    },
    {
      "headline": "Death of John Allen Chau",
      "text": "In November 2018, American missionary John Allen Chau was killed by the Sentinelese when he illegally visited North Sentinel Island in an attempt to contact and convert them.",
      "date": "2018-11"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Iraq Invades Iran",
      "text": "On September 22, 1980, Iraq launched a full-scale invasion of Iran, marking the beginning of the Iran–Iraq War. The invasion was initiated by Iraqi President Saddam Hussein, who aimed to seize control of the oil-rich Khuzestan Province and to undermine the newly established Islamic Republic of Iran.",
      "date": "1980-09-22"
    },
    {
      "headline": "Battle of Khorramshahr",
      "text": "The Battle of Khorramshahr took place from September 22 to November 10, 1980. It was one of the first major battles of the war, resulting in heavy casualties on both sides and the eventual capture of the city by Iraqi forces.",
      "date": "1980-11-10"
    },
    {
      "headline": "Operation Undeniable Victory",
      "text": "In March 1982, Iran launched Operation Undeniable Victory, successfully recapturing the city of Khorramshahr from Iraqi forces. This marked a turning point in the war, as Iran began to regain lost territory.",
      "date": "1982-03"
    },
    {
      "headline": "Iranian Offensive into Iraq",
      "text": "In July 1982, Iranian forces crossed the border into Iraq, initiating a series of offensives aimed at capturing Iraqi territory. This shift in strategy marked the beginning of a prolonged and bloody stalemate.",
      "date": "1982-07"
    },
    {
      "headline": "Operation Karbala-5",
      "text": "In January 1987, Iran launched Operation Karbala-5, one of the largest and most costly battles of the war. The operation aimed to capture the Iraqi city of Basra but ultimately failed, resulting in heavy casualties for both sides.",
      "date": "1987-01"
    },
    {
      "headline": "United Nations Security Council Resolution 598",
      "text": "On July 20, 1987, the United Nations Security Council passed Resolution 598, calling for an immediate ceasefire and a return to pre-war boundaries. Both Iran and Iraq initially rejected the resolution.",
      "date": "1987-07-20"
    },
    {
      "headline": "Iran Accepts UN Resolution 598",
      "text": "On July 18, 1988, Iran accepted United Nations Security Council Resolution 598, agreeing to a ceasefire with Iraq. This decision came after a series of military setbacks and economic hardships.",
      "date": "1988-07-18"
    },
    {
      "headline": "Ceasefire Takes Effect",
      "text": "On August 20, 1988, the ceasefire between Iran and Iraq officially took effect, ending nearly eight years of hostilities. The war resulted in significant casualties and economic damage for both countries.",
      "date": "1988-08-20"
    }
  ]
}

