    },
    {
      "headline": "Commander-in-Chief of the Luftwaffe",
      "text": "In 1935, Göring was appointed Commander-in-Chief of the Luftwaffe, the aerial warfare branch of the German military.",
      "date": "1935"
    },
    {
      "headline": "Named Hitler's Successor",
      "text": "In 1939, Göring was named Hitler's designated successor and deputy in all his offices.",
      "date": "1939"
