{
  "timeline": [
    {
      "headline": "Birth of Commodus",
      "text": "Commodus was born on August 31, 161, in Lanuvium, near Rome, as the son of the Roman Emperor Marcus Aurelius and Faustina the Younger.",
      "date": "0161-08-31"
    },
    {
      "headline": "Commodus Becomes Caesar",
      "text": "In 166, Commodus was made Caesar, a title that marked him as the heir to the Roman Empire.",
      "date": "0166"
    },
    {
      "headline": "Commodus Becomes Co-Emperor",
      "text": "In 177, Commodus was made co-emperor with his father Marcus Aurelius, marking the beginning of his reign.",
      "date": "0177"
    },
    {
      "headline": "Death of Marcus Aurelius",
      "text": "On March 17, 180, Marcus Aurelius died, leaving Commodus as the sole emperor of the Roman Empire.",
      "date": "0180-03-17"
    },
    {
      "headline": "Commodus's Sole Reign Begins",
      "text": "Following the death of his father in 180, Commodus began his sole reign as Roman Emperor, which is often considered the end of the Pax Romana.",
      "date": "0180"
    },
    {
      "headline": "Attempted Assassination",
      "text": "In 182, an assassination attempt was made on Commodus's life, orchestrated by his sister Lucilla and a group of senators.",
      "date": "0182"
    },
    {
      "headline": "Commodus's Increasing Autocracy",
      "text": "Throughout the 180s, Commodus increasingly ruled as an autocrat, alienating the Senate and focusing on personal pleasures and spectacles.",
      "date": "0180s"
    },
    {
      "headline": "Commodus's Gladiatorial Displays",
      "text": "Commodus famously participated in gladiatorial combats, which was considered scandalous for a Roman emperor.",
      "date": "0180s"
    },
    {
      "headline": "Assassination of Commodus",
      "text": "Commodus was assassinated on December 31, 192, as part of a conspiracy involving his inner circle, including his chamberlain and mistress.",
      "date": "0192-12-31"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Agreement of Magna Carta",
      "text": "On 15 June 1215, King John of England agreed to the Magna Carta at Runnymede, near Windsor. It was drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons.",
      "date": "1215-06-15"
    },
    {
      "headline": "Content of Magna Carta",
      "text": "The Magna Carta promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown. It was to be implemented through a council of 25 barons.",
      "date": "1215-06-15"
    },
    {
      "headline": "Annulment by Pope Innocent III",
      "text": "Shortly after its agreement, the Magna Carta was annulled by Pope Innocent III. This annulment contributed to the outbreak of the First Barons' War.",
      "date": "1215"
    },
    {
      "headline": "First Barons' War",
      "text": "Following the annulment of the Magna Carta, the First Barons' War broke out as a result of the failure of both sides to adhere to their commitments.",
      "date": "1215"
    }
  ]
}

