    {
      "headline": "Birth of Jim Simons",
      "text": "James Harris Simons was born on April 25, 1938, in Newton, Massachusetts, USA.",
      "date": "1938-04-25"
    },
    {
      "headline": "Graduation from MIT",
      "text": "In 1958, Simons graduated from the Massachusetts Institute of Technology with a bachelor's degree in mathematics.",
      "date": "1958"
    },
    {
      "headline": "Ph.D. from the University of California, Berkeley",
      "text": "Simons received his Ph.D. in mathematics from the University of California, Berkeley in 1961.",
      "date": "1961"
    },
    {
      "headline": "Work at the Institute for Defense Analyses",
      "text": "In 1964, Simons began working at the Institute for Defense Analyses, a research and development center for the United States Department of Defense.",
      "date": "1964"
    },
    {
      "headline": "Chair of the Mathematics Department at Stony Brook University",
      "text": "In 1968, Simons became the chair of the mathematics department at Stony Brook University, where he made significant contributions to the field of mathematics.",
      "date": "1968"
    },
    {
      "headline": "Chern-Simons Theory",
      "text": "In 1974, Simons co-developed the Chern-Simons theory, a theory in mathematics and theoretical physics.",
      "date": "1974"
    },
    {
      "headline": "Founding of Renaissance Technologies",
      "text": "In 1982, Simons founded Renaissance Technologies, a private hedge fund based in East Setauket, New York.",
      "date": "1982"
    },
    {
      "headline": "Retirement from Renaissance Technologies",
      "text": "Simons retired as CEO of Renaissance Technologies in 2009, although he continued to play a role in the company.",
      "date": "2009"
    },
    {
      "headline": "Philanthropic Efforts",
      "text": "Throughout his life, Simons has been involved in various philanthropic efforts, including the establishment of the Simons Foundation in 1994, which supports research in mathematics and the basic sciences.",
      "date": "1994"
    }
  ]
}

