    {
      "headline": "Establishment of the Office",
      "text": "The office of the Speaker of the United States House of Representatives was established in 1789 by Article I, Section II, of the U.S. Constitution.",
      "date": "1789"
    },
    {
      "headline": "First Speaker of the House",
      "text": "Frederick Muhlenberg was elected as the first Speaker of the United States House of Representatives on April 1, 1789.",
      "date": "1789-04-01"
    },
    {
      "headline": "Role and Responsibilities",
      "text": "The Speaker serves as the political and parliamentary leader of the House, its presiding officer, de facto leader of the majority party, and the administrative head of the institution.",
      "date": "1789"
    },
    {
      "headline": "First Female Speaker",
      "text": "Nancy Pelosi became the first female Speaker of the House on January 4, 2007.",
      "date": "2007-01-04"
    },
    {
      "headline": "Longest-Serving Speaker",
      "text": "Sam Rayburn holds the record for the longest-serving Speaker of the House, serving for over 17 years in total across three different periods (1940–1947, 1949–1953, and 1955–1961).",
      "date": "1940"
    },
    {
      "headline": "Speaker Succession",
      "text": "The Speaker is second in the United States presidential line of succession, after the Vice President.",
      "date": "1947"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of the Kuomintang",
      "text": "The Kuomintang (KMT) was founded on August 25, 1912, by Sun Yat-sen. It was established as a nationalist party with the aim of unifying China and overthrowing the Qing dynasty.",
      "date": "1912-08-25"
    },
    {
      "headline": "First United Front",
      "text": "In 1923, the KMT formed the First United Front with the Chinese Communist Party (CCP) to end warlordism in China. This alliance was facilitated by the Soviet Union.",
      "date": "1923"
    },
    {
      "headline": "Northern Expedition",
      "text": "The Northern Expedition was launched in 1926 by the KMT to unify China under its control by defeating warlords. It was a military campaign led by Chiang Kai-shek.",
      "date": "1926"
    },
    {
      "headline": "Break with the CCP",
      "text": "In 1927, the KMT broke its alliance with the CCP, leading to the Chinese Civil War. This event is marked by the Shanghai Massacre, where thousands of communists were killed.",
      "date": "1927"
    },
    {
      "headline": "Establishment of the Nanjing Government",
      "text": "In 1928, the KMT established a central government in Nanjing, marking the beginning of the Nanjing Decade, a period of relative stability and modernization in China.",
      "date": "1928"
    },
    {
      "headline": "Second United Front",
      "text": "In 1937, the KMT formed the Second United Front with the CCP to resist Japanese invasion during the Second Sino-Japanese War.",
      "date": "1937"
    },
    {
      "headline": "End of World War II and Resumption of Civil War",
      "text": "After the end of World War II in 1945, the Chinese Civil War resumed between the KMT and the CCP.",
      "date": "1945"
    },
    {
      "headline": "Retreat to Taiwan",
      "text": "In 1949, after losing the Chinese Civil War to the CCP, the KMT retreated to Taiwan, where it established a government in exile.",
      "date": "1949"
    },
    {
      "headline": "Martial Law in Taiwan",
      "text": "The KMT imposed martial law in Taiwan from 1949 until 1987, during which time it maintained a one-party state.",
      "date": "1949"
    },
    {
      "headline": "Lifting of Martial Law",
      "text": "In 1987, the KMT lifted martial law in Taiwan, leading to democratic reforms and the eventual transition to a multi-party system.",
      "date": "1987"
    },
    {
      "headline": "First Direct Presidential Election",
      "text": "In 1996, Taiwan held its first direct presidential election, marking a significant step in its democratic development under the KMT's leadership.",
      "date": "1996"
    },
    {
      "headline": "Return to Power",
      "text": "The KMT returned to power in Taiwan in 2008 with the election of Ma Ying-jeou as President.",
      "date": "2008"
    },
    {
      "headline": "Current Status",
      "text": "As of 2024, the KMT is the largest single party in the Legislative Yuan in Taiwan, with Eric Chu serving as the current chairman.",
      "date": "2024"
    }
  ]
}

