{
  "timeline": [
    {
      "headline": "Formation of the NHL",
      "text": "The National Hockey League (NHL) was formed on November 26, 1917, in Montreal, Quebec, Canada. It was established as a successor to the National Hockey Association (NHA).",
      "date": "1917-11-26"
    },
    {
      "headline": "First NHL Season",
      "text": "The NHL's first season began on December 19, 1917, with four teams: the Montreal Canadiens, Montreal Wanderers, Ottawa Senators, and Toronto Arenas.",
      "date": "1917-12-19"
    },
    {
      "headline": "First Stanley Cup Championship",
      "text": "The Toronto Arenas won the first NHL Stanley Cup championship in 1918, defeating the Vancouver Millionaires of the Pacific Coast Hockey Association.",
      "date": "1918"
    },
    {
      "headline": "Expansion to the United States",
      "text": "The NHL expanded to the United States in 1924 with the addition of the Boston Bruins, marking the league's first American team.",
      "date": "1924"
    },
    {
      "headline": "Original Six Era Begins",
      "text": "The Original Six era began in 1942, consisting of the Montreal Canadiens, Toronto Maple Leafs, Boston Bruins, Detroit Red Wings, Chicago Black Hawks, and New York Rangers.",
      "date": "1942"
    },
    {
      "headline": "NHL Expansion",
      "text": "The NHL expanded from six to twelve teams in 1967, adding the Los Angeles Kings, Minnesota North Stars, Oakland Seals, Philadelphia Flyers, Pittsburgh Penguins, and St. Louis Blues.",
      "date": "1967"
    },
    {
      "headline": "First European Player Drafted",
      "text": "In 1974, the NHL saw its first European player drafted, with Swedish player Börje Salming joining the Toronto Maple Leafs.",
      "date": "1974"
    },
    {
      "headline": "Merger with WHA",
      "text": "The NHL merged with the World Hockey Association (WHA) in 1979, adding four teams: the Edmonton Oilers, Hartford Whalers, Quebec Nordiques, and Winnipeg Jets.",
      "date": "1979"
    },
    {
      "headline": "Introduction of the Salary Cap",
      "text": "The NHL introduced a salary cap in 2005 following a lockout that led to the cancellation of the 2004-2005 season.",
      "date": "2005"
    },
    {
      "headline": "NHL Centennial",
      "text": "The NHL celebrated its centennial anniversary in 2017, marking 100 years since its founding.",
      "date": "2017"
    },
    {
      "headline": "Seattle Kraken Joins the NHL",
      "text": "The Seattle Kraken became the NHL's 32nd team, joining the league for the 2021-2022 season.",
      "date": "2021"
    }
  ]
}

