    {
      "headline": "Ordination as a Franciscan Friar",
      "text": "William of Ockham was ordained as a Franciscan friar, which significantly influenced his philosophical and theological work.",
      "date": "1310"
    },
    {
      "headline": "Development of Occam's Razor",
      "text": "During his academic career, William of Ockham developed the principle of parsimony, later known as Occam's razor, which suggests that the simplest explanation is usually the correct one.",
      "date": "1320"
    },
    {
      "headline": "Conflict with the Papacy",
      "text": "William of Ockham was summoned to Avignon, France, to answer charges of heresy due to his controversial views, which included his principle of parsimony.",
      "date": "1324"
    },
    {
      "headline": "Escape to Munich",
      "text": "In 1328, William of Ockham fled to Munich under the protection of Emperor Louis IV after being excommunicated by Pope John XXII.",
      "date": "1328"
    },
    {
      "headline": "Death of William of Ockham",
      "text": "William of Ockham died on April 9, 1347, in Munich, Bavaria, Holy Roman Empire.",
