{
  "timeline": [
    {
      "headline": "Proto-Indo-European Language",
      "text": "The Proto-Indo-European language is the reconstructed common ancestor of the Indo-European language family. It is believed to have been spoken as a single language from approximately 4500 BCE to 2500 BCE.",
      "date": "-04500"
    },
    {
      "headline": "Indo-European Migrations",
      "text": "The Indo-European migrations began around 4000 BCE, spreading the Proto-Indo-European language across Europe and Asia. These migrations led to the diversification of the language into various branches.",
      "date": "-04000"
    },
    {
      "headline": "Formation of Major Branches",
      "text": "By around 3000 BCE, the major branches of the Indo-European languages, such as the Anatolian, Indo-Iranian, and Tocharian branches, began to form.",
      "date": "-03000"
    },
    {
      "headline": "Anatolian Languages",
      "text": "The Anatolian languages, including Hittite, were among the earliest Indo-European languages to be attested, with records dating back to around 1800 BCE.",
      "date": "-01800"
    },
    {
      "headline": "Emergence of the Greek Language",
      "text": "The Greek language, part of the Hellenic branch, emerged around 1600 BCE and became one of the earliest attested Indo-European languages with the Linear B script.",
      "date": "-01600"
    },
    {
      "headline": "Indo-Iranian Languages",
      "text": "The Indo-Iranian branch split into the Indo-Aryan and Iranian languages around 1500 BCE, with the Rigveda being one of the earliest texts in an Indo-Aryan language.",
      "date": "-01500"
    },
    {
      "headline": "Italic Languages and Latin",
      "text": "The Italic languages, including Latin, began to develop around 1000 BCE. Latin would later become the dominant language of the Roman Empire.",
      "date": "-01000"
    },
    {
      "headline": "Celtic Languages",
      "text": "The Celtic languages began to spread across Europe around 1200 BCE, with evidence of their presence in the Hallstatt culture.",
      "date": "-01200"
    },
    {
      "headline": "Germanic Languages",
      "text": "The Germanic branch began to form around 500 BCE, eventually leading to languages such as Gothic, Old Norse, and Old English.",
      "date": "-00500"
    },
    {
      "headline": "Balto-Slavic Languages",
      "text": "The Balto-Slavic languages began to diverge into Baltic and Slavic branches around 500 CE.",
      "date": "0500"
    },
    {
      "headline": "Colonial Expansion",
      "text": "From the 15th century onwards, European colonial expansion spread Indo-European languages such as English, Spanish, Portuguese, and French across the world.",
      "date": "1500"
    }
  ]
}

