{
  "timeline": [
    {
      "headline": "Initial Construction of Göbekli Tepe",
      "text": "Göbekli Tepe was first constructed around 9500 BCE. It is one of the earliest known examples of monumental architecture, featuring large circular structures with massive stone pillars.",
      "date": "-9500"
    },
    {
      "headline": "Development of Megalithic Structures",
      "text": "During the Pre-Pottery Neolithic period, Göbekli Tepe saw the development of its iconic megalithic structures. These structures include T-shaped pillars, some of which are decorated with anthropomorphic details and reliefs of wild animals.",
      "date": "-9500"
    },
    {
      "headline": "Peak of Göbekli Tepe's Use",
      "text": "Göbekli Tepe reached its peak use around 9000 BCE. The site served as a significant religious and possibly social center for the people of the region.",
      "date": "-9000"
    },
    {
      "headline": "Abandonment of Göbekli Tepe",
      "text": "The site was gradually abandoned around 8000 BCE. The reasons for its abandonment are still a subject of research and debate among archaeologists.",
      "date": "-8000"
    },
    {
      "headline": "Rediscovery and Excavation",
      "text": "Göbekli Tepe was rediscovered in the 20th century, with major excavations beginning in the 1990s. These excavations have provided significant insights into prehistoric religion and architecture.",
      "date": "1990"
    }
  ]
}

