{
  "timeline": [
    {
      "headline": "Establishment of the Continental Navy",
      "text": "The Continental Navy, the precursor to the United States Navy, was established on October 13, 1775, during the American Revolutionary War.",
      "date": "1775-10-13"
    },
    {
      "headline": "Disbandment of the Continental Navy",
      "text": "After the American Revolutionary War, the Continental Navy was disbanded in 1785 due to lack of funds and the belief that a standing navy was unnecessary.",
      "date": "1785"
    },
    {
      "headline": "Reestablishment of the United States Navy",
      "text": "The United States Navy was reestablished on March 27, 1794, with the Naval Act of 1794, which authorized the construction of six frigates.",
      "date": "1794-03-27"
    },
    {
      "headline": "Launch of USS Constitution",
      "text": "The USS Constitution, one of the six original frigates, was launched on October 21, 1797, and remains the world's oldest commissioned naval vessel still afloat.",
      "date": "1797-10-21"
    },
    {
      "headline": "War of 1812",
      "text": "During the War of 1812, the United States Navy achieved several significant victories against the British Royal Navy, enhancing its reputation.",
      "date": "1812"
    },
    {
      "headline": "Establishment of the United States Naval Academy",
      "text": "The United States Naval Academy was established on October 10, 1845, in Annapolis, Maryland, to train future officers of the Navy.",
      "date": "1845-10-10"
    },
    {
      "headline": "American Civil War",
      "text": "During the American Civil War (1861-1865), the U.S. Navy played a crucial role in blockading Confederate ports and controlling the Mississippi River.",
      "date": "1861"
    },
    {
      "headline": "Spanish-American War",
      "text": "In 1898, the U.S. Navy defeated the Spanish fleet in the Battle of Manila Bay and the Battle of Santiago de Cuba, marking a turning point in naval warfare.",
      "date": "1898"
    },
    {
      "headline": "World War I",
      "text": "During World War I (1917-1918), the U.S. Navy expanded significantly and played a key role in convoying troops and supplies to Europe.",
      "date": "1917"
    },
    {
      "headline": "World War II",
      "text": "The U.S. Navy was instrumental in the Allied victory in World War II (1941-1945), particularly in the Pacific Theater against Japan.",
      "date": "1941"
    },
    {
      "headline": "Cold War Era",
      "text": "During the Cold War (1947-1991), the U.S. Navy maintained a significant presence worldwide to counter the Soviet Union's naval forces.",
      "date": "1947"
    },
    {
      "headline": "Operation Desert Storm",
      "text": "In 1991, the U.S. Navy played a major role in Operation Desert Storm, enforcing a naval blockade and launching missile strikes against Iraq.",
      "date": "1991"
    },
    {
      "headline": "Global War on Terror",
      "text": "Following the September 11 attacks in 2001, the U.S. Navy has been involved in various operations as part of the Global War on Terror.",
      "date": "2001"
    },
    {
      "headline": "Modernization and Expansion",
      "text": "As of 2023, the U.S. Navy continues to modernize its fleet, with 299 deployable combat vessels and about 4,012 operational aircraft.",
      "date": "2023"
    }
  ]
}

