{
  "timeline": [
    {
      "headline": "End of World War I and German Revolution",
      "text": "On November 9, 1918, the German Empire was overthrown in the German Revolution, leading to the abdication of Kaiser Wilhelm II and the proclamation of the Weimar Republic.",
      "date": "1918-11-09"
    },
    {
      "headline": "Signing of the Armistice",
      "text": "On November 11, 1918, the Armistice of Compiègne was signed, ending World War I and marking the defeat of Germany.",
      "date": "1918-11-11"
    },
    {
      "headline": "Weimar National Assembly",
      "text": "In January 1919, elections were held for the Weimar National Assembly, which convened in Weimar to draft a new constitution.",
      "date": "1919-01"
    },
    {
      "headline": "Treaty of Versailles",
      "text": "On June 28, 1919, the Treaty of Versailles was signed, imposing heavy reparations and territorial losses on Germany.",
      "date": "1919-06-28"
    },
    {
      "headline": "Adoption of the Weimar Constitution",
      "text": "The Weimar Constitution was adopted on August 11, 1919, establishing Germany as a democratic republic.",
      "date": "1919-08-11"
    },
    {
      "headline": "Kapp Putsch",
      "text": "In March 1920, the Kapp Putsch, a failed coup attempt by right-wing elements, took place in an effort to overthrow the Weimar Republic.",
      "date": "1920-03"
    },
    {
      "headline": "Hyperinflation Crisis",
      "text": "In 1923, Germany experienced a period of hyperinflation, severely affecting the economy and leading to social unrest.",
      "date": "1923"
    },
    {
      "headline": "Occupation of the Ruhr",
      "text": "In January 1923, French and Belgian troops occupied the Ruhr region in response to Germany's failure to pay reparations.",
      "date": "1923-01"
    },
    {
      "headline": "Beer Hall Putsch",
      "text": "On November 8-9, 1923, Adolf Hitler and the Nazi Party attempted a coup in Munich, known as the Beer Hall Putsch, which failed.",
      "date": "1923-11-08"
    },
    {
      "headline": "Dawes Plan",
      "text": "In 1924, the Dawes Plan was implemented to restructure Germany's reparations payments and stabilize the economy.",
      "date": "1924"
    },
    {
      "headline": "Locarno Treaties",
      "text": "In 1925, the Locarno Treaties were signed, aiming to normalize relations between Germany and its neighbors.",
      "date": "1925"
    },
    {
      "headline": "Germany Joins the League of Nations",
      "text": "In 1926, Germany was admitted to the League of Nations, marking its return to the international community.",
      "date": "1926"
    },
    {
      "headline": "Young Plan",
      "text": "In 1929, the Young Plan was introduced to further reduce Germany's reparations and extend the payment period.",
      "date": "1929"
    },
    {
      "headline": "Great Depression",
      "text": "The onset of the Great Depression in 1929 led to severe economic challenges and political instability in Germany.",
      "date": "1929"
    },
    {
      "headline": "Rise of the Nazi Party",
      "text": "In the early 1930s, the Nazi Party gained significant political power, becoming the largest party in the Reichstag by 1932.",
      "date": "1932"
    },
    {
      "headline": "Appointment of Adolf Hitler as Chancellor",
      "text": "On January 30, 1933, Adolf Hitler was appointed Chancellor of Germany, marking the beginning of the end for the Weimar Republic.",
      "date": "1933-01-30"
    },
    {
      "headline": "Reichstag Fire and Enabling Act",
      "text": "Following the Reichstag Fire on February 27, 1933, the Enabling Act was passed on March 23, 1933, granting Hitler dictatorial powers and effectively ending the Weimar Republic.",
      "date": "1933-03-23"
    }
  ]
}

