{
  "timeline": [
    {
      "headline": "Publication of The Communist Manifesto",
      "text": "The Communist Manifesto, written by Karl Marx and Friedrich Engels, was published on February 21, 1848. It laid out the principles of Marxism and called for the working class to rise against the bourgeoisie.",
      "date": "1848-02-21"
    },
    {
      "headline": "Publication of Das Kapital",
      "text": "The first volume of Das Kapital, Marx's critical analysis of political economy, was published in 1867. It is one of the foundational texts of Marxist theory.",
      "date": "1867"
    },
    {
      "headline": "Formation of the First International",
      "text": "The International Workingmen's Association, known as the First International, was founded in 1864. It aimed to unite various left-wing socialist, communist, and anarchist political groups and trade unions.",
      "date": "1864"
    },
    {
      "headline": "Death of Karl Marx",
      "text": "Karl Marx, one of the founders of Marxism, died on March 14, 1883, in London, England.",
      "date": "1883-03-14"
    },
    {
      "headline": "Russian Revolution",
      "text": "The Russian Revolution of 1917 led to the overthrow of the Tsarist autocracy and the rise of the Soviet Union, the first state to be governed by Marxist principles.",
      "date": "1917"
    },
    {
      "headline": "Formation of the Communist International",
      "text": "The Communist International, also known as the Comintern, was founded in 1919 to promote world communism and coordinate international communist movements.",
      "date": "1919"
    },
    {
      "headline": "Publication of Mao Zedong's On Contradiction",
      "text": "In 1937, Mao Zedong published 'On Contradiction,' which became a fundamental text for Maoist thought, a branch of Marxism.",
      "date": "1937"
    },
    {
      "headline": "Cuban Revolution",
      "text": "The Cuban Revolution, led by Fidel Castro and Che Guevara, culminated in 1959 with the establishment of a Marxist-Leninist government in Cuba.",
      "date": "1959"
    },
    {
      "headline": "Cultural Revolution in China",
      "text": "The Cultural Revolution, initiated by Mao Zedong in 1966, aimed to preserve Chinese communism by purging remnants of capitalist and traditional elements from Chinese society.",
      "date": "1966"
    },
    {
      "headline": "Fall of the Berlin Wall",
      "text": "The fall of the Berlin Wall on November 9, 1989, symbolized the collapse of communist regimes in Eastern Europe and marked a significant decline in the influence of Marxist-Leninist states.",
      "date": "1989-11-09"
    },
    {
      "headline": "Dissolution of the Soviet Union",
      "text": "The Soviet Union, the largest Marxist-Leninist state, was officially dissolved on December 26, 1991, marking the end of the Cold War and a significant shift in global political dynamics.",
      "date": "1991-12-26"
    }
  ]
}

