    {
      "headline": "Foundation of Delhi",
      "text": "The city of Delhi has a long history, and its foundation is often associated with the ancient city of Indraprastha, which is mentioned in the Indian epic Mahabharata. Indraprastha is believed to have been established around 1400 BCE.",
      "date": "-1400"
    },
    {
      "headline": "Delhi Sultanate Established",
      "text": "The Delhi Sultanate was established in 1206 by Qutb-ud-din Aibak, marking the beginning of Muslim rule in Northern India.",
      "date": "1206"
    },
    {
      "headline": "Tughlaq Dynasty",
      "text": "The Tughlaq dynasty ruled over the Delhi Sultanate from 1320 to 1413, known for its architectural contributions and administrative reforms.",
      "date": "1320"
    },
    {
      "headline": "Mughal Empire Establishment",
      "text": "In 1526, the Mughal Empire was established by Babur after defeating Ibrahim Lodi at the First Battle of Panipat, marking the beginning of Mughal rule in Delhi.",
      "date": "1526"
    },
    {
      "headline": "Shah Jahan Builds Shahjahanabad",
      "text": "In 1639, Mughal Emperor Shah Jahan built the city of Shahjahanabad, which is now known as Old Delhi, including the Red Fort and Jama Masjid.",
      "date": "1639"
    },
    {
      "headline": "British Capture Delhi",
      "text": "The British East India Company captured Delhi in 1803 during the Second Anglo-Maratha War.",
      "date": "1803"
    },
    {
      "headline": "Delhi Durbar",
      "text": "In 1911, the Delhi Durbar was held to commemorate the coronation of King George V and Queen Mary as Emperor and Empress of India, and the capital of British India was shifted from Calcutta to Delhi.",
      "date": "1911"
    },
    {
      "headline": "Independence and Partition",
      "text": "In 1947, India gained independence from British rule, and Delhi became the capital of the newly independent nation.",
      "date": "1947"
    },
    {
      "headline": "Delhi Becomes a Union Territory",
      "text": "On 1 November 1956, Delhi was officially declared a union territory of India.",
      "date": "1956-11-01"
    },
    {
      "headline": "Formation of the National Capital Territory",
      "text": "In 1995, the National Capital Territory (NCT) of Delhi was established, providing a special status to the region.",
      "date": "1995"
    }
  ]
}

