{
  "timeline": [
    {
      "headline": "Launch of Google Search",
      "text": "Google Search was officially launched in 1997, initially as a research project by Larry Page and Sergey Brin, who were Ph.D. students at Stanford University.",
      "date": "1997"
    },
    {
      "headline": "Incorporation of Google Inc.",
      "text": "Google Inc. was incorporated on September 4, 1998, marking the formal establishment of the company behind Google Search.",
      "date": "1998-09-04"
    },
    {
      "headline": "PageRank Algorithm",
      "text": "The PageRank algorithm, developed by Larry Page and Sergey Brin, became a key component of Google's search technology, significantly improving the relevance of search results.",
      "date": "1998"
    },
    {
      "headline": "First Google Doodle",
      "text": "The first Google Doodle was created in 1998 to commemorate the Burning Man Festival, marking the beginning of a tradition of creative and thematic Google logos.",
      "date": "1998"
    },
    {
      "headline": "Introduction of AdWords",
      "text": "In October 2000, Google introduced AdWords, a program that allowed businesses to advertise on the Google search results page, revolutionizing online advertising.",
      "date": "2000-10"
    },
    {
      "headline": "Launch of Google Images",
      "text": "Google Images was launched on July 12, 2001, allowing users to search for images on the web, expanding the capabilities of Google Search.",
      "date": "2001-07-12"
    },
    {
      "headline": "Introduction of Google News",
      "text": "Google News was launched in September 2002, providing users with a comprehensive news aggregation service.",
      "date": "2002-09"
    },
    {
      "headline": "Launch of Google Scholar",
      "text": "Google Scholar was launched in November 2004, offering a freely accessible web search engine for scholarly literature across various disciplines.",
      "date": "2004-11"
    },
    {
      "headline": "Introduction of Google Suggest",
      "text": "In December 2004, Google introduced Google Suggest, a feature that provided search suggestions in real-time as users typed their queries.",
      "date": "2004-12"
    },
    {
      "headline": "Launch of Google Maps",
      "text": "Google Maps was launched in February 2005, providing users with detailed maps and satellite imagery, further enhancing the search experience.",
      "date": "2005-02"
    },
    {
      "headline": "Introduction of Universal Search",
      "text": "In May 2007, Google introduced Universal Search, integrating different types of content such as videos, images, and news into the main search results.",
      "date": "2007-05"
    },
    {
      "headline": "Launch of Google Instant",
      "text": "Google Instant was launched in September 2010, offering real-time search results as users typed their queries, aiming to make search faster and more efficient.",
      "date": "2010-09"
    },
    {
      "headline": "Introduction of Knowledge Graph",
      "text": "In May 2012, Google introduced the Knowledge Graph, a knowledge base used to enhance search results with semantic-search information gathered from a wide variety of sources.",
      "date": "2012-05"
    },
    {
      "headline": "Launch of Google Hummingbird",
      "text": "Google Hummingbird, a significant search algorithm update, was launched in September 2013, focusing on understanding the meaning behind search queries.",
      "date": "2013-09"
    },
    {
      "headline": "Introduction of Mobile-Friendly Update",
      "text": "In April 2015, Google released the Mobile-Friendly Update, prioritizing mobile-friendly websites in search results to improve the mobile search experience.",
      "date": "2015-04"
    },
    {
      "headline": "Launch of Google BERT",
      "text": "In October 2019, Google launched BERT (Bidirectional Encoder Representations from Transformers), an update to better understand the context of words in search queries.",
