    {
      "headline": "Spanish Colonization",
      "text": "In 1778, Spain acquired the islands of Bioko and Annobón from Portugal under the Treaty of El Pardo.",
      "date": "1778"
    },
    {
      "headline": "Establishment of Spanish Guinea",
      "text": "In 1900, the mainland territory of Río Muni was incorporated into the Spanish colony, forming Spanish Guinea.",
      "date": "1900"
    },
    {
      "headline": "Autonomy Granted",
      "text": "In 1963, Spain granted limited autonomy to Spanish Guinea, establishing a local government.",
      "date": "1963"
    },
    {
      "headline": "Independence from Spain",
      "text": "On October 12, 1968, Equatorial Guinea gained independence from Spain.",
      "date": "1968-10-12"
    },
    {
      "headline": "Francisco Macías Nguema's Presidency",
      "text": "Francisco Macías Nguema became the first President of Equatorial Guinea after independence in 1968.",
      "date": "1968"
    },
    {
      "headline": "Coup and Execution of Macías Nguema",
      "text": "On August 3, 1979, Francisco Macías Nguema was overthrown in a coup led by his nephew Teodoro Obiang Nguema Mbasogo. Macías was executed on September 29, 1979.",
      "date": "1979-09-29"
    },
    {
      "headline": "Teodoro Obiang Nguema Mbasogo's Presidency",
      "text": "Teodoro Obiang Nguema Mbasogo became President of Equatorial Guinea following the 1979 coup.",
      "date": "1979"
    },
    {
      "headline": "Discovery of Oil",
      "text": "In the mid-1990s, significant oil reserves were discovered off the coast of Equatorial Guinea, transforming its economy.",
      "date": "1990"
    },
    {
      "headline": "Constitutional Reforms",
      "text": "In 2011, a constitutional referendum was held, introducing reforms such as term limits for the presidency.",
      "date": "2011"
    }
  ]
}

