{
  "timeline": [
    {
      "headline": "Birth of Rama",
      "text": "Rama was born on the ninth day of the bright half of the lunar cycle of Chaitra, which falls in March–April, in the city of Ayodhya. He is considered the seventh avatar of the god Vishnu.",
      "date": "-0511"  },
    {
      "headline": "Marriage to Sita",
      "text": "Rama married Sita, the daughter of King Janaka of Mithila, after successfully breaking the bow of Shiva in a swayamvara (a ceremony where a princess chooses her husband from among a group of suitors).",
      "date": "-0495"
    },
    {
      "headline": "Exile to the Forest",
      "text": "Rama was exiled to the forest for 14 years due to a promise made by his father, King Dasharatha, to his stepmother Kaikeyi. Sita and his brother Lakshmana accompanied him.",
      "date": "-0490"
    },
    {
      "headline": "Abduction of Sita",
      "text": "During their exile, Sita was abducted by the demon king Ravana, leading to the events of the Ramayana where Rama sets out to rescue her.",
      "date": "-0485"
    },
    {
      "headline": "Battle with Ravana",
      "text": "Rama fought and defeated Ravana in a great battle, with the help of an army of monkeys led by Hanuman and Sugriva, and rescued Sita.",
      "date": "-0484"
    },
    {
      "headline": "Return to Ayodhya",
      "text": "After completing his 14 years of exile, Rama returned to Ayodhya with Sita and Lakshmana, where he was crowned king.",
      "date": "-0480"
    },
    {
      "headline": "Rule of Rama",
      "text": "Rama's rule, known as 'Rama Rajya', is celebrated as a period of peace, prosperity, and justice. It is considered an ideal form of governance.",
      "date": "-0480"
    },
    {
      "headline": "Departure from Earth",
      "text": "Rama eventually left the earth and returned to his divine abode, marking the end of his earthly life.",
      "date": "-0450"
    }
  ]
}

