    },
    {
      "headline": "Release of 'Amnesiac'",
      "text": "Radiohead released their fifth album, 'Amnesiac', on June 5, 2001. The album was recorded during the same sessions as 'Kid A' and continued to explore experimental sounds.",
      "date": "2001-06-05"
    },
