    {
      "headline": "Founding of Las Vegas",
      "text": "Las Vegas was founded as a city on May 15, 1905, when 110 acres of land adjacent to the Union Pacific Railroad tracks were auctioned off.",
      "date": "1905-05-15"
    },
    {
      "headline": "Incorporation of Las Vegas",
      "text": "Las Vegas was officially incorporated as a city on March 16, 1911.",
      "date": "1911-03-16"
    },
    {
      "headline": "Construction of Hoover Dam",
      "text": "The construction of the Hoover Dam began in 1931 and was completed in 1936. This project brought thousands of workers to the area, boosting the local economy.",
      "date": "1931"
    },
    {
      "headline": "Opening of El Rancho Vegas",
      "text": "El Rancho Vegas, the first hotel-casino on what would become the Las Vegas Strip, opened on April 3, 1941.",
      "date": "1941-04-03"
    },
    {
      "headline": "Opening of the Flamingo Hotel",
      "text": "The Flamingo Hotel, one of the first luxury hotels on the Las Vegas Strip, opened on December 26, 1946.",
      "date": "1946-12-26"
    },
    {
      "headline": "Las Vegas Becomes a City of Entertainment",
      "text": "In the 1950s, Las Vegas began to establish itself as a major entertainment destination, with performances by famous entertainers such as Frank Sinatra and Elvis Presley.",
      "date": "1950"
    },
    {
      "headline": "Opening of Caesars Palace",
      "text": "Caesars Palace, one of the most iconic resorts on the Las Vegas Strip, opened on August 5, 1966.",
      "date": "1966-08-05"
    },
    {
      "headline": "Opening of The Mirage",
      "text": "The Mirage, a new kind of resort with a focus on luxury and entertainment, opened on November 22, 1989, marking the beginning of a new era for Las Vegas.",
      "date": "1989-11-22"
    },
    {
      "headline": "Opening of the Bellagio",
      "text": "The Bellagio, known for its elegance and the famous Fountains of Bellagio, opened on October 15, 1998.",
      "date": "1998-10-15"
    },
    {
      "headline": "Las Vegas Celebrates Centennial",
      "text": "Las Vegas celebrated its 100th anniversary on May 15, 2005, with various events and celebrations throughout the city.",
      "date": "2005-05-15"
    },
    {
      "headline": "Las Vegas Shooting",
      "text": "On October 1, 2017, a mass shooting occurred at the Route 91 Harvest music festival, resulting in 58 deaths and over 800 injuries, marking it as the deadliest mass shooting in modern U.S. history.",
      "date": "2017-10-01"
