{
  "timeline": [
    {
      "headline": "Founding of BMW",
      "text": "BMW was founded on March 7, 1916, as Bayerische Flugzeugwerke AG. The company was established to manufacture aircraft engines.",
      "date": "1916-03-07"
    },
    {
      "headline": "Renaming to BMW",
      "text": "In 1917, the company was renamed Bayerische Motoren Werke GmbH, which later became Bayerische Motoren Werke AG.",
      "date": "1917"
    },
    {
      "headline": "End of World War I Production",
      "text": "Following the end of World War I in 1918, BMW was forced to cease aircraft engine production due to the Treaty of Versailles.",
      "date": "1918"
    },
    {
      "headline": "First Motorcycle",
      "text": "BMW produced its first motorcycle, the BMW R32, in 1923.",
      "date": "1923"
    },
    {
      "headline": "Entry into Automobile Manufacturing",
      "text": "BMW entered the automobile manufacturing industry in 1928 with the purchase of Fahrzeugfabrik Eisenach, which produced the Dixi 3/15.",
      "date": "1928"
    },
    {
      "headline": "World War II Aircraft Engines",
      "text": "BMW resumed aircraft engine production in 1933 and continued through World War II, producing engines for German military aircraft.",
      "date": "1933"
    },
    {
      "headline": "Post-War Production Ban",
      "text": "After World War II, BMW was banned from producing motor vehicles and aircraft engines by the Allies until 1948.",
      "date": "1945"
    },
    {
      "headline": "Resumption of Motorcycle Production",
      "text": "BMW resumed motorcycle production in 1948 with the R24 model.",
      "date": "1948"
    },
    {
      "headline": "Resumption of Automobile Production",
      "text": "In 1952, BMW resumed automobile production with the BMW 501 luxury saloon.",
      "date": "1952"
    },
    {
      "headline": "Introduction of the BMW 1500",
      "text": "The BMW 1500, introduced in 1962, marked the beginning of BMW's successful 'New Class' of compact sedans.",
      "date": "1962"
    },
    {
      "headline": "Acquisition of Hans Glas GmbH",
      "text": "In 1966, BMW acquired Hans Glas GmbH, which helped expand its production capabilities.",
      "date": "1966"
    },
    {
      "headline": "Launch of the BMW 3 Series",
      "text": "The BMW 3 Series was launched in 1975, becoming one of the company's most successful models.",
      "date": "1975"
    },
    {
      "headline": "Acquisition of Rover Group",
      "text": "BMW acquired the British Rover Group in 1994, although it was sold in 2000 due to financial losses.",
      "date": "1994"
    },
    {
      "headline": "Acquisition of Rolls-Royce Motor Cars",
      "text": "In 1998, BMW acquired the rights to the Rolls-Royce brand, and began producing Rolls-Royce cars in 2003.",
      "date": "1998"
    },
    {
      "headline": "Introduction of the BMW i Series",
      "text": "BMW introduced its i Series of electric and plug-in hybrid vehicles in 2013, starting with the BMW i3.",
      "date": "2013"
    }
  ]
}

