    },
    {
      "headline": "Recovery and Relocation to the UK",
      "text": "After the assassination attempt, Malala was transferred to the UK for medical treatment and rehabilitation, eventually settling in Birmingham with her family.",
      "date": "2012"
    },
    {
      "headline": "Address to the United Nations",
      "text": "On July 12, 2013, Malala addressed the United Nations, calling for worldwide access to education. This day was declared 'Malala Day' by the UN.",
      "date": "2013-07-12"
    },
    {
      "headline": "Publication of 'I Am Malala'",
      "text": "In October 2013, Malala published her autobiography, 'I Am Malala: The Girl Who Stood Up for Education and Was Shot by the Taliban'.",
      "date": "2013-10"
    },
    {
      "headline": "Nobel Peace Prize",
      "text": "On October 10, 2014, Malala Yousafzai was awarded the Nobel Peace Prize, becoming the youngest-ever laureate at the age of 17.",
      "date": "2014-10-10"
    },
    {
      "headline": "Co-founding the Malala Fund",
      "text": "Malala co-founded the Malala Fund, an organization advocating for girls' education worldwide.",
      "date": "2013"
