      "headline": "Birth of Saint Peter",
      "text": "Saint Peter, originally named Simon, was born in Bethsaida, a town in Galilee, around the year 1 AD.",
      "date": "0001"
    },
    {
      "headline": "Called by Jesus",
      "text": "Around 30 AD, Simon, later named Peter by Jesus, was called to be a disciple while he was fishing with his brother Andrew.",
      "date": "0030"
    },
    {
      "headline": "Confession of Peter",
      "text": "In approximately 30-33 AD, Peter confessed Jesus as the Messiah, an event recorded in the New Testament.",
      "date": "0030"
    },
    {
      "headline": "Denial of Jesus",
      "text": "During the events leading to the crucifixion of Jesus, Peter denied knowing Jesus three times, as foretold by Jesus, around 33 AD.",
      "date": "0033"
    },
    {
      "headline": "Leadership in Early Church",
      "text": "After the resurrection of Jesus, Peter became a prominent leader in the early Christian Church, particularly in Jerusalem, around 33-34 AD.",
      "date": "0033"
    },
    {
      "headline": "Council of Jerusalem",
      "text": "Peter played a significant role in the Council of Jerusalem, which took place around 48-50 AD, addressing the issue of Gentile converts and Jewish law.",
      "date": "0049"
    },
    {
      "headline": "Bishop of Antioch",
      "text": "According to tradition, Peter served as the first bishop of Antioch before moving to Rome, around 50-54 AD.",
      "date": "0050"
    },
    {
      "headline": "Martyrdom in Rome",
      "text": "Saint Peter was martyred in Rome under Emperor Nero's reign, traditionally believed to have occurred around 64 AD. He was crucified upside down at his own request.",
      "date": "0064"
    }
  ]
}

