{
  "timeline": [
    {
      "headline": "Enrico Fermi's Question",
      "text": "In 1950, physicist Enrico Fermi posed the question, 'Where is everybody?' during a casual conversation with colleagues, highlighting the apparent contradiction between the high probability of extraterrestrial life and the lack of evidence for, or contact with, such civilizations.",
      "date": "1950"
    },
    {
      "headline": "Publication of the Fermi Paradox",
      "text": "The term 'Fermi paradox' was popularized in the 1970s, although Fermi's original question was not published in his lifetime. The paradox addresses the contradiction between the high probability estimates for the existence of extraterrestrial civilizations and the lack of evidence for, or contact with, such civilizations.",
      "date": "1970"
    },
    {
      "headline": "Drake Equation Formulation",
      "text": "In 1961, Frank Drake formulated the Drake Equation, which attempts to estimate the number of active, communicative extraterrestrial civilizations in the Milky Way galaxy. This equation is often discussed in relation to the Fermi paradox.",
      "date": "1961"
    },
    {
      "headline": "SETI Institute Founded",
      "text": "In 1984, the SETI (Search for Extraterrestrial Intelligence) Institute was founded to explore, understand, and explain the origin and nature of life in the universe, and to apply the knowledge gained to inspire and guide present and future generations. The institute's work is closely related to the themes of the Fermi paradox.",
      "date": "1984"
    },
    {
      "headline": "Publication of 'Rare Earth' Hypothesis",
      "text": "In 2000, the book 'Rare Earth: Why Complex Life is Uncommon in the Universe' by Peter Ward and Donald Brownlee was published. It argues that while microbial life may be common, complex life is rare in the universe, offering a potential explanation for the Fermi paradox.",
      "date": "2000"
    },
    {
      "headline": "Publication of 'The Great Filter' Hypothesis",
      "text": "In 1996, economist Robin Hanson published an essay introducing 'The Great Filter' hypothesis, which suggests that there is some stage in the process from pre-life to an advanced civilization that is extremely unlikely or impossible for life to surpass, potentially explaining the Fermi paradox.",
      "date": "1996"
    }
  ]
}

