{
  "timeline": [
    {
      "headline": "First Recorded Cases of Leprosy",
      "text": "Leprosy is one of the oldest diseases known to humankind, with descriptions dating back to around 600 BCE in ancient Indian texts.",
      "date": "-0600"
    },
    {
      "headline": "Leprosy in Ancient China",
      "text": "Leprosy was recognized in China by 500 BCE, where it was known as 'li' and described in medical texts.",
      "date": "-0500"
    },
    {
      "headline": "Leprosy in Ancient Greece",
      "text": "The disease was known in ancient Greece by 300 BCE, where it was referred to as 'elephantiasis' due to the thickening of the skin.",
      "date": "-0300"
    },
    {
      "headline": "Leprosy in the Roman Empire",
      "text": "Leprosy spread throughout the Roman Empire, with significant cases reported by 62 BCE.",
      "date": "-0062"
    },
    {
      "headline": "Leprosy in the Middle Ages",
      "text": "During the Middle Ages, leprosy was widespread in Europe, with numerous leper colonies established to isolate those affected.",
      "date": "1100"
    },
    {
      "headline": "Discovery of Mycobacterium leprae",
      "text": "In 1873, Dr. Gerhard Armauer Hansen discovered Mycobacterium leprae, the bacterium that causes leprosy, marking a significant advancement in understanding the disease.",
      "date": "1873"
    },
    {
      "headline": "Introduction of Dapsone",
      "text": "In the 1940s, Dapsone was introduced as the first effective treatment for leprosy, significantly reducing the disease's impact.",
      "date": "1940"
    },
