    {
      "headline": "Birth of Samuel Langhorne Clemens",
      "text": "Samuel Langhorne Clemens, later known as Mark Twain, was born on November 30, 1835, in Florida, Missouri.",
      "date": "1835-11-30"
    },
    {
      "headline": "Family Moves to Hannibal, Missouri",
      "text": "In 1839, Clemens' family moved to Hannibal, Missouri, a port town on the Mississippi River, which would later serve as the inspiration for the fictional town of St. Petersburg in his novels.",
      "date": "1839"
    },
    {
      "headline": "Apprenticeship as a Printer",
      "text": "At the age of 11, following his father's death in 1847, Clemens left school and began working as a printer's apprentice.",
      "date": "1847"
    },
    {
      "headline": "Becomes a River Pilot",
      "text": "In 1859, Clemens became a licensed river pilot on the Mississippi River, a profession he held until the outbreak of the American Civil War in 1861.",
      "date": "1859"
    },
    {
      "headline": "Adopts the Pen Name 'Mark Twain'",
      "text": "In 1863, while working as a journalist in Nevada, Clemens began signing his articles with the pen name 'Mark Twain,' a term from his river piloting days.",
      "date": "1863"
    },
    {
      "headline": "Publication of 'The Celebrated Jumping Frog of Calaveras County'",
      "text": "Twain gained national attention with the publication of his short story 'The Celebrated Jumping Frog of Calaveras County' in 1865.",
      "date": "1865"
    },
    {
      "headline": "Marriage to Olivia Langdon",
      "text": "On February 2, 1870, Twain married Olivia Langdon in Elmira, New York.",
      "date": "1870-02-02"
    },
    {
      "headline": "Publication of 'The Innocents Abroad'",
      "text": "In 1869, Twain published 'The Innocents Abroad,' a travel book that became a bestseller.",
      "date": "1869"
    },
    {
      "headline": "Publication of 'The Gilded Age: A Tale of Today'",
      "text": "In 1873, Twain co-authored 'The Gilded Age: A Tale of Today' with Charles Dudley Warner, marking his first novel.",
      "date": "1873"
    },
    {
      "headline": "Publication of 'The Adventures of Tom Sawyer'",
      "text": "Twain published 'The Adventures of Tom Sawyer' in 1876, which became one of his most famous works.",
      "date": "1876"
    },
    {
      "headline": "Publication of 'Adventures of Huckleberry Finn'",
      "text": "In 1884, Twain published 'Adventures of Huckleberry Finn,' often regarded as the 'Great American Novel.'",
      "date": "1884"
    },
    {
      "headline": "Publication of 'A Connecticut Yankee in King Arthur's Court'",
      "text": "Twain published 'A Connecticut Yankee in King Arthur's Court' in 1889, a satirical novel that explores themes of technology and social issues.",
      "date": "1889"
    },
    {
      "headline": "Publication of 'Pudd'nhead Wilson'",
      "text": "In 1894, Twain published 'Pudd'nhead Wilson,' a novel that addresses themes of race and identity.",
      "date": "1894"
    },
    {
      "headline": "Death of Olivia Langdon Clemens",
      "text": "Twain's wife, Olivia Langdon Clemens, passed away on June 5, 1904.",
      "date": "1904-06-05"
    },
    {
      "headline": "Death of Mark Twain",
      "text": "Mark Twain died on April 21, 1910, in Redding, Connecticut, at the age of 74.",
      "date": "1910-04-21"
    }
  ]
}

