{
  "timeline": [
    {
      "headline": "White Revolution",
      "text": "The White Revolution was a series of reforms launched in 1963 by Shah Mohammad Reza Pahlavi to modernize and Westernize Iran. These reforms included land redistribution, women's suffrage, and the nationalization of forests and pastures.",
      "date": "1963"
    },
    {
      "headline": "Ayatollah Khomeini's Exile",
      "text": "Ayatollah Ruhollah Khomeini, a vocal critic of the Shah's regime, was arrested and later exiled from Iran in 1964 due to his opposition to the White Revolution and the Shah's policies.",
      "date": "1964"
    },
    {
      "headline": "Rising Opposition",
      "text": "Throughout the 1970s, opposition to the Shah's regime grew, fueled by economic challenges, political repression, and cultural Westernization that many Iranians opposed.",
      "date": "1970s"
    },
    {
      "headline": "Cinema Rex Fire",
      "text": "On August 19, 1978, the Cinema Rex in Abadan was set on fire, resulting in the deaths of over 400 people. The incident intensified anti-Shah sentiments and was blamed on SAVAK, the Shah's secret police, by the opposition.",
      "date": "1978-08-19"
    },
    {
      "headline": "Black Friday",
      "text": "On September 8, 1978, known as Black Friday, the Shah's troops opened fire on protesters in Tehran, killing and wounding many. This event marked a turning point in the revolution, escalating protests and strikes.",
      "date": "1978-09-08"
    },
    {
      "headline": "Shah Leaves Iran",
      "text": "On January 16, 1979, Shah Mohammad Reza Pahlavi left Iran for exile, marking the collapse of the Pahlavi dynasty and paving the way for the Islamic Revolution.",
      "date": "1979-01-16"
    },
    {
      "headline": "Ayatollah Khomeini Returns",
      "text": "Ayatollah Ruhollah Khomeini returned to Iran from exile on February 1, 1979, and was greeted by millions of supporters. His return marked a significant moment in the revolution.",
      "date": "1979-02-01"
    },
    {
      "headline": "Islamic Republic Declared",
      "text": "On April 1, 1979, following a national referendum, Iran was officially declared an Islamic Republic, with Ayatollah Khomeini as its Supreme Leader.",
      "date": "1979-04-01"
    },
    {
      "headline": "U.S. Embassy Hostage Crisis",
      "text": "On November 4, 1979, Iranian students seized the U.S. Embassy in Tehran, taking 52 American diplomats and citizens hostage. The crisis lasted 444 days and significantly impacted U.S.-Iran relations.",
      "date": "1979-11-04"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Pre-Colonial Period",
      "text": "Various ethnic groups, including the Mossi, Gurunsi, and Lobi, inhabited the region that is now Burkina Faso long before European colonization.",
      "date": "-1000"
    },
    {
      "headline": "French Colonization",
      "text": "The area became part of French West Africa in the late 19th century as France expanded its colonial empire in Africa.",
      "date": "1896"
    },
    {
      "headline": "Creation of Upper Volta",
      "text": "The French established the colony of Upper Volta on March 1, 1919, separating it from the Upper Senegal and Niger colony.",
      "date": "1919-03-01"
    },
    {
      "headline": "Dissolution of Upper Volta",
      "text": "Upper Volta was dissolved on September 5, 1932, and its territory was divided among the French colonies of Ivory Coast, French Sudan (now Mali), and Niger.",
      "date": "1932-09-05"
    },
    {
      "headline": "Reconstitution of Upper Volta",
      "text": "Upper Volta was reconstituted as a separate colony within French West Africa on September 4, 1947.",
      "date": "1947-09-04"
    },
    {
      "headline": "Independence from France",
      "text": "Upper Volta gained full independence from France on August 5, 1960, with Maurice Yaméogo as its first president.",
      "date": "1960-08-05"
    },
    {
      "headline": "Military Coup",
      "text": "A military coup led by Sangoulé Lamizana overthrew President Maurice Yaméogo on January 3, 1966.",
      "date": "1966-01-03"
    },
    {
      "headline": "Thomas Sankara's Presidency",
      "text": "Thomas Sankara became president after a coup on August 4, 1983, and initiated a series of revolutionary programs.",
      "date": "1983-08-04"
    },
    {
      "headline": "Renaming to Burkina Faso",
      "text": "On August 4, 1984, Thomas Sankara renamed the country from Upper Volta to Burkina Faso, meaning 'Land of Incorruptible People.'",
      "date": "1984-08-04"
    },
    {
      "headline": "Assassination of Thomas Sankara",
      "text": "Thomas Sankara was assassinated during a coup led by Blaise Compaoré on October 15, 1987.",
      "date": "1987-10-15"
    },
    {
      "headline": "Blaise Compaoré's Presidency",
      "text": "Blaise Compaoré became president following the coup and remained in power until 2014.",
      "date": "1987-10-15"
    },
    {
      "headline": "2014 Burkinabé Uprising",
      "text": "Mass protests erupted in October 2014, leading to the resignation of President Blaise Compaoré on October 31, 2014.",
      "date": "2014-10-31"
    },
    {
      "headline": "Transitional Government",
      "text": "A transitional government was established in November 2014, with Michel Kafando as interim president.",
      "date": "2014-11"
    },
    {
      "headline": "2015 Presidential Election",
      "text": "Roch Marc Christian Kaboré was elected president in the November 2015 elections, marking a return to civilian rule.",
      "date": "2015-11"
    }
  ]
}

