{
  "timeline": [
    {
      "headline": "Birth of Vinayak Damodar Savarkar",
      "text": "Vinayak Damodar Savarkar was born on May 28, 1883, in Bhagur, a village near Nashik in the Bombay Presidency of British India.",
      "date": "1883-05-28"
    },
    {
      "headline": "Formation of Mitra Mela",
      "text": "In 1900, Savarkar founded a secret society called Mitra Mela, which later evolved into the Abhinav Bharat Society, aimed at overthrowing British rule in India.",
      "date": "1900"
    },
    {
      "headline": "Studies in England",
      "text": "In 1906, Savarkar went to England to study law at Gray's Inn, London, where he continued his political activism.",
      "date": "1906"
    },
    {
      "headline": "Publication of 'The First War of Indian Independence'",
      "text": "In 1909, Savarkar published 'The First War of Indian Independence', a book on the Indian Rebellion of 1857, which was banned by the British authorities.",
      "date": "1909"
    },
    {
      "headline": "Arrest and Trial",
      "text": "Savarkar was arrested in 1909 for his involvement in revolutionary activities and was sentenced to life imprisonment in 1910.",
      "date": "1910"
    },
    {
      "headline": "Imprisonment in Cellular Jail",
      "text": "Savarkar was transported to the Andaman Islands and imprisoned in the Cellular Jail from 1911 to 1921.",
      "date": "1911"
    },
    {
      "headline": "Release from Cellular Jail",
      "text": "Savarkar was released from the Cellular Jail in 1921 but was kept under surveillance and restricted to Ratnagiri.",
      "date": "1921"
    },
    {
      "headline": "Development of Hindutva Ideology",
      "text": "While confined in Ratnagiri in 1922, Savarkar developed the Hindu nationalist political ideology of Hindutva.",
      "date": "1922"
    },
    {
      "headline": "President of Hindu Mahasabha",
      "text": "Savarkar became the president of the Hindu Mahasabha in 1937, a position he held until 1943.",
      "date": "1937"
    },
    {
      "headline": "Retirement from Active Politics",
      "text": "In 1948, after being acquitted in the Gandhi assassination trial, Savarkar retired from active politics.",
      "date": "1948"
    },
    {
      "headline": "Death of Vinayak Damodar Savarkar",
      "text": "Vinayak Damodar Savarkar passed away on February 26, 1966, in Bombay, India.",
      "date": "1966-02-26"
    }
  ]
}

