{
  "timeline": [
    {
      "headline": "Foundation of the Mongol Empire",
      "text": "In 1206, Temüjin was proclaimed Genghis Khan, the ruler of all Mongols, marking the foundation of the Mongol Empire.",
      "date": "1206"
    },
    {
      "headline": "Conquest of the Western Xia",
      "text": "Between 1209 and 1210, Genghis Khan led the Mongol forces to victory over the Western Xia, a Tangut state in northwestern China.",
      "date": "1209"
    },
    {
      "headline": "Conquest of the Jin Dynasty",
      "text": "From 1211 to 1234, the Mongol Empire waged a series of campaigns against the Jin Dynasty in northern China, eventually leading to its conquest.",
      "date": "1211"
    },
    {
      "headline": "Invasion of the Khwarazmian Empire",
      "text": "In 1219, Genghis Khan launched a successful invasion of the Khwarazmian Empire, which stretched across modern-day Iran and Central Asia.",
      "date": "1219"
    },
    {
      "headline": "Death of Genghis Khan",
      "text": "Genghis Khan died in 1227 during a campaign against the Western Xia. His death marked a significant transition in the Mongol Empire.",
      "date": "1227"
    },
    {
      "headline": "Ogedei Khan's Reign",
      "text": "Ogedei Khan, the third son of Genghis Khan, became the Great Khan in 1229 and continued the expansion of the empire.",
      "date": "1229"
    },
    {
      "headline": "Conquest of the Song Dynasty",
      "text": "The Mongol Empire began its conquest of the Song Dynasty in southern China in 1235, which was completed in 1279 under Kublai Khan.",
      "date": "1235"
    },
    {
      "headline": "Mongol Invasion of Europe",
      "text": "In 1236, the Mongols began their invasion of Europe, reaching as far as Poland and Hungary by 1241.",
      "date": "1236"
    },
    {
      "headline": "Death of Ogedei Khan",
      "text": "Ogedei Khan died in 1241, leading to a temporary halt in the Mongol expansion into Europe.",
      "date": "1241"
    },
    {
      "headline": "Reign of Kublai Khan",
      "text": "Kublai Khan became the Great Khan in 1260 and established the Yuan Dynasty in China in 1271, marking the Mongol Empire's peak.",
      "date": "1260"
    },
    {
      "headline": "Establishment of the Yuan Dynasty",
      "text": "In 1271, Kublai Khan officially founded the Yuan Dynasty in China, solidifying Mongol rule over the region.",
      "date": "1271"
    },
    {
      "headline": "Fall of the Song Dynasty",
      "text": "The Mongol Empire completed its conquest of the Song Dynasty in 1279, unifying China under Mongol rule.",
      "date": "1279"
    },
    {
      "headline": "Death of Kublai Khan",
      "text": "Kublai Khan died in 1294, leading to a gradual decline in the power and unity of the Mongol Empire.",
      "date": "1294"
    },
    {
      "headline": "Fragmentation of the Mongol Empire",
      "text": "By the mid-14th century, the Mongol Empire had fragmented into several khanates, marking the end of its unity.",
      "date": "1350"
    }
  ]
}

