{
  "timeline": [
    {
      "headline": "First Mention of Amsterdam",
      "text": "The earliest recorded mention of Amsterdam is from a document dated October 27, 1275, when the inhabitants of 'Amestelledamme' were granted freedom from paying bridge tolls by Count Floris V.",
      "date": "1275-10-27"
    },
    {
      "headline": "Amsterdam Receives City Rights",
      "text": "Amsterdam was officially granted city rights in 1306, marking its formal recognition as a city.",
      "date": "1306"
    },
    {
      "headline": "Construction of the Dam",
      "text": "In the late 13th century, a dam was constructed in the Amstel River, which led to the development of the city around it.",
      "date": "1290"
    },
    {
      "headline": "Amsterdam Becomes a Major Trading Hub",
      "text": "By the 14th century, Amsterdam had become an important trading city, with its port playing a key role in the Hanseatic League.",
      "date": "1300"
    },
    {
      "headline": "The Alteratie",
      "text": "On May 26, 1578, Amsterdam underwent the Alteratie, a peaceful revolution that led to the city's conversion from Catholicism to Protestantism.",
      "date": "1578-05-26"
    },
    {
      "headline": "Dutch Golden Age",
      "text": "During the 17th century, Amsterdam experienced its Golden Age, becoming the wealthiest city in the world due to its dominance in trade, finance, and the arts.",
      "date": "1600"
    },
    {
      "headline": "Construction of the Canal Ring",
      "text": "In the early 17th century, the famous canal ring of Amsterdam was constructed, which is now a UNESCO World Heritage Site.",
      "date": "1613"
    },
    {
      "headline": "Establishment of the Dutch East India Company",
      "text": "In 1602, the Dutch East India Company was established in Amsterdam, becoming the world's first multinational corporation and the first company to issue stock.",
      "date": "1602"
    },
    {
      "headline": "Annexation by France",
      "text": "In 1810, Amsterdam was annexed by the French Empire under Napoleon Bonaparte.",
      "date": "1810"
    },
    {
      "headline": "End of French Rule",
      "text": "In 1813, French rule ended, and Amsterdam became part of the Kingdom of the Netherlands.",
      "date": "1813"
    },
    {
      "headline": "Opening of the Rijksmuseum",
      "text": "The Rijksmuseum, the national museum of the Netherlands, was opened in Amsterdam in 1885.",
      "date": "1885"
    },
    {
      "headline": "World War II Occupation",
      "text": "During World War II, Amsterdam was occupied by Nazi Germany from 1940 to 1945.",
      "date": "1940"
    },
    {
      "headline": "Liberation of Amsterdam",
      "text": "Amsterdam was liberated from Nazi occupation on May 5, 1945.",
      "date": "1945-05-05"
    },
    {
      "headline": "Amsterdam Becomes a UNESCO World Heritage Site",
      "text": "In 2010, the 17th-century canal ring area of Amsterdam inside the Singelgracht was added to the UNESCO World Heritage List.",
      "date": "2010"
    }
  ]
}

