    },
    {
      "headline": "Deadliest Structural Fire in the UK Since 1988",
      "text": "The Grenfell Tower fire was the deadliest structural fire in the United Kingdom since the 1988 Piper Alpha oil-platform disaster and the worst UK residential fire since the Blitz of World War II.",
      "date": "2017-06-14"
    }
  ]
}

