    {
      "headline": "Formation of the Constituent Assembly",
      "text": "The Constituent Assembly of India was formed in 1946 to draft the Constitution of India. The assembly was elected by the members of the provincial legislative assemblies.",
      "date": "1946"
    },
    {
      "headline": "First Session of the Constituent Assembly",
      "text": "The first session of the Constituent Assembly was held on December 9, 1946. Dr. Sachchidananda Sinha was elected as the temporary president of the assembly.",
      "date": "1946-12-09"
    },
    {
      "headline": "Dr. Rajendra Prasad Elected as Permanent President",
      "text": "On December 11, 1946, Dr. Rajendra Prasad was elected as the permanent president of the Constituent Assembly.",
      "date": "1946-12-11"
    },
    {
      "headline": "Objective Resolution Introduced",
      "text": "On December 13, 1946, Jawaharlal Nehru introduced the Objective Resolution, which outlined the aims of the assembly and later became the Preamble of the Constitution.",
      "date": "1946-12-13"
    },
    {
      "headline": "Adoption of the National Flag",
      "text": "The Constituent Assembly adopted the national flag of India on July 22, 1947.",
      "date": "1947-07-22"
    },
    {
      "headline": "Draft Constitution Prepared",
      "text": "The draft of the Indian Constitution was prepared by the Drafting Committee, chaired by Dr. B.R. Ambedkar, and submitted to the Constituent Assembly on November 4, 1947.",
      "date": "1947-11-04"
    },
    {
      "headline": "Constitution Adopted",
      "text": "The Constitution of India was adopted by the Constituent Assembly on November 26, 1949.",
      "date": "1949-11-26"
    },
    {
      "headline": "Constitution Came into Effect",
      "text": "The Constitution of India came into effect on January 26, 1950, marking the transition of India to a republic.",
      "date": "1950-01-26"
    },
    {
      "headline": "First Amendment",
      "text": "The first amendment to the Constitution of India was enacted in 1951, addressing issues related to land reform and the right to freedom of speech.",
      "date": "1951"
    }
  ]
}

