  "timeline": [
    {
      "headline": "Beginning of the Middle Ages",
      "text": "The Middle Ages began with the fall of the Western Roman Empire, traditionally dated to the year 476.",
      "date": "0476"
    },
    {
      "headline": "Reign of Charlemagne",
      "text": "Charlemagne was crowned Emperor of the Romans by Pope Leo III on December 25, 800, marking a significant moment in the Carolingian Renaissance.",
      "date": "0800-12-25"
    },
    {
      "headline": "The Great Schism",
      "text": "The Great Schism of 1054 was the break of communion between what are now the Roman Catholic Church and Eastern Orthodox Churches.",
      "date": "1054"
    },
    {
      "headline": "The Norman Conquest",
      "text": "The Norman Conquest of England began with the Battle of Hastings on October 14, 1066, when William the Conqueror defeated King Harold II.",
      "date": "1066-10-14"
    },
    {
      "headline": "First Crusade",
      "text": "The First Crusade was launched in 1096 and resulted in the capture of Jerusalem in 1099.",
      "date": "1096"
    },
    {
      "headline": "Signing of the Magna Carta",
      "text": "The Magna Carta was signed by King John of England on June 15, 1215, establishing the principle that everyone is subject to the law.",
      "date": "1215-06-15"
    },
    {
      "headline": "The Black Death",
      "text": "The Black Death, one of the deadliest pandemics in human history, peaked in Europe between 1347 and 1351.",
      "date": "1347"
    },
    {
      "headline": "The Hundred Years' War",
      "text": "The Hundred Years' War between England and France began in 1337 and lasted until 1453, significantly impacting medieval Europe.",
      "date": "1337"
    },
    {
      "headline": "Fall of Constantinople",
      "text": "The Fall of Constantinople to the Ottoman Empire on May 29, 1453, marked the end of the Byzantine Empire and is often considered the end of the Middle Ages.",
      "date": "1453-05-29"
    },
    {
      "headline": "End of the Middle Ages",
      "text": "The Middle Ages are generally considered to have ended with the beginning of the Renaissance and the Age of Discovery in the late 15th century.",
      "date": "1492"
    }
  ]
}

