    {
      "headline": "Foundation of Vindobona",
      "text": "The area of present-day Vienna was settled by the Celts around 500 BCE. The Romans established the military camp of Vindobona in the 1st century AD.",
      "date": "-0500"
    },
    {
      "headline": "Roman Settlement",
      "text": "Vindobona became a significant Roman settlement in the 1st century AD, serving as a military camp on the Danube Limes.",
      "date": "0001"
