    {
      "headline": "Charlemagne's Rule",
      "text": "In 803, Charlemagne incorporated the area into the Carolingian Empire, marking the beginning of Vienna's development as a city.",
      "date": "0803"
    },
    {
      "headline": "First Mention of Vienna",
      "text": "The name 'Vienna' was first mentioned in 881 in the Salzburg Annals, referring to a battle near the city.",
      "date": "0881"
    },
    {
      "headline": "Babenberg Rule",
      "text": "In 976, the Babenberg dynasty began ruling Vienna, which became the capital of the Margraviate of Austria.",
      "date": "0976"
    },
    {
      "headline": "Elevation to a Duchy",
      "text": "In 1156, the Privilegium Minus elevated Austria to a duchy, with Vienna as its capital.",
      "date": "1156"
    },
    {
      "headline": "University of Vienna Founded",
      "text": "The University of Vienna was founded in 1365, making it one of the oldest universities in the German-speaking world.",
      "date": "1365"
    },
    {
      "headline": "First Siege by the Ottoman Empire",
      "text": "The first Ottoman siege of Vienna took place in 1529, marking a significant event in the city's history.",
      "date": "1529"
    },
    {
      "headline": "Second Siege by the Ottoman Empire",
      "text": "The second Ottoman siege occurred in 1683, ending with the Battle of Vienna, which was a turning point in European history.",
      "date": "1683"
    },
    {
      "headline": "Congress of Vienna",
      "text": "From 1814 to 1815, the Congress of Vienna was held to redraw the continent's political map after the defeat of Napoleon.",
      "date": "1814"
    },
    {
      "headline": "Austro-Hungarian Compromise",
      "text": "In 1867, the Austro-Hungarian Compromise established the dual monarchy of Austria-Hungary, with Vienna as one of its capitals.",
      "date": "1867"
    },
    {
      "headline": "Anschluss with Nazi Germany",
      "text": "In 1938, Austria was annexed by Nazi Germany in an event known as the Anschluss, with Vienna becoming a provincial city in the Third Reich.",
      "date": "1938"
    },
    {
      "headline": "Vienna Declared a Federal State",
      "text": "In 1920, Vienna was declared a federal state of Austria, gaining a unique status within the country.",
      "date": "1920"
    },
    {
      "headline": "End of World War II",
      "text": "In 1945, Vienna was liberated by Soviet troops, marking the end of Nazi rule and the beginning of the city's reconstruction.",
      "date": "1945"
    },
    {
      "headline": "Austrian State Treaty",
      "text": "In 1955, the Austrian State Treaty was signed, re-establishing Austria as a sovereign state and ending the Allied occupation.",
      "date": "1955"
    },
    {
      "headline": "Vienna as a UN Headquarters",
      "text": "In 1979, Vienna became one of the four official headquarters of the United Nations, enhancing its international significance.",
      "date": "1979"
    }
  ]
}

