{
  "timeline": [
    {
      "headline": "First Church Construction",
      "text": "The first church on the site of Hagia Sophia was commissioned by Emperor Constantius II and was completed in AD 360.",
      "date": "0360"
    },
    {
      "headline": "Second Church Construction",
      "text": "The first church was destroyed during riots in AD 404. A second church was commissioned by Emperor Theodosius II and completed in AD 415.",
      "date": "0415"
    },
    {
      "headline": "Destruction of the Second Church",
      "text": "The second church was burned down during the Nika riots in AD 532.",
      "date": "0532"
    },
    {
      "headline": "Completion of the Current Hagia Sophia",
      "text": "The current structure of Hagia Sophia was commissioned by Emperor Justinian I and completed in AD 537, becoming the world's largest interior space and a masterpiece of Byzantine architecture.",
      "date": "0537"
    },
    {
      "headline": "Fourth Crusade and Latin Church",
      "text": "During the Fourth Crusade, Hagia Sophia was converted into a Roman Catholic cathedral from 1204 to 1261.",
      "date": "1204"
    },
    {
      "headline": "Return to Eastern Orthodox Church",
      "text": "Hagia Sophia was restored to the Eastern Orthodox Church in 1261 after the recapture of Constantinople by the Byzantine Empire.",
      "date": "1261"
    },
    {
      "headline": "Conversion to a Mosque",
      "text": "Following the Ottoman conquest of Constantinople in 1453, Hagia Sophia was converted into a mosque by Sultan Mehmed II.",
      "date": "1453"
    },
    {
      "headline": "Transformation into a Museum",
      "text": "In 1935, under the secular reforms of Mustafa Kemal Atatürk, Hagia Sophia was secularized and opened as a museum.",
      "date": "1935"
    },
    {
      "headline": "Reconversion to a Mosque",
      "text": "In 2020, Hagia Sophia was reclassified as a mosque, a decision that sparked international controversy.",
      "date": "2020"
    }
  ]
}

