    {
      "headline": "Ottoman Rule",
      "text": "The West Bank was part of the Ottoman Empire from 1517 until the end of World War I in 1917.",
      "date": "1517"
    },
    {
      "headline": "British Mandate",
      "text": "Following the defeat of the Ottoman Empire in World War I, the West Bank became part of the British Mandate for Palestine in 1920.",
      "date": "1920"
    },
    {
      "headline": "UN Partition Plan",
      "text": "The United Nations proposed a partition plan in 1947 to divide the British Mandate of Palestine into Jewish and Arab states, with the West Bank allocated to the Arab state.",
      "date": "1947"
    },
    {
      "headline": "Jordanian Annexation",
      "text": "After the 1948 Arab-Israeli War, the West Bank was occupied and later annexed by Jordan in 1950.",
      "date": "1950"
    },
    {
      "headline": "Six-Day War",
      "text": "In June 1967, during the Six-Day War, Israel captured the West Bank from Jordan.",
      "date": "1967-06"
    },
    {
      "headline": "Oslo Accords",
      "text": "The Oslo Accords, signed in 1993, led to the establishment of the Palestinian Authority and partial self-governance in parts of the West Bank.",
      "date": "1993"
    },
    {
      "headline": "Second Intifada",
      "text": "The Second Intifada, a period of intensified Israeli-Palestinian violence, began in September 2000 and had significant impacts on the West Bank.",
      "date": "2000-09"
    },
    {
      "headline": "UN General Assembly Resolution",
      "text": "In November 2012, the United Nations General Assembly passed a resolution upgrading Palestine to non-member observer state status, which includes the West Bank.",
      "date": "2012-11"
    }
  ]
}

