{
  "timeline": [
    {
      "headline": "Council of Clermont",
      "text": "In November 1095, Pope Urban II called for the First Crusade at the Council of Clermont, urging Christians to reclaim the Holy Land from Muslim control.",
      "date": "1095-11"
    },
    {
      "headline": "First Crusade Begins",
      "text": "The First Crusade began in 1096, initiated by Pope Urban II's call to arms. It was the first of a series of religious wars aimed at reclaiming Jerusalem and the Holy Land.",
      "date": "1096"
    },
    {
      "headline": "Siege of Jerusalem",
      "text": "On July 15, 1099, the First Crusade culminated in the capture of Jerusalem by the Crusaders, establishing several Crusader states.",
      "date": "1099-07-15"
    },
    {
      "headline": "Second Crusade",
      "text": "The Second Crusade was launched in 1147 in response to the fall of the County of Edessa, the first Crusader state to be established and the first to fall.",
      "date": "1147"
    },
    {
      "headline": "Battle of Hattin",
      "text": "On July 4, 1187, the Muslim forces under Saladin defeated the Crusader states at the Battle of Hattin, leading to the recapture of Jerusalem.",
      "date": "1187-07-04"
    },
    {
      "headline": "Third Crusade",
      "text": "The Third Crusade (1189–1192) was launched in response to the capture of Jerusalem by Saladin. It was led by European monarchs including Richard the Lionheart.",
      "date": "1189"
    },
    {
      "headline": "Fourth Crusade",
      "text": "The Fourth Crusade (1202–1204) was diverted from its original goal and resulted in the sack of Constantinople, a Christian city, in 1204.",
      "date": "1202"
    },
    {
      "headline": "Sack of Constantinople",
      "text": "On April 12, 1204, Crusaders of the Fourth Crusade captured and sacked Constantinople, leading to the establishment of the Latin Empire.",
      "date": "1204-04-12"
    },
    {
      "headline": "Fifth Crusade",
      "text": "The Fifth Crusade (1217–1221) aimed to capture Egypt as a means to conquer Jerusalem, but ultimately failed.",
      "date": "1217"
    },
    {
      "headline": "Sixth Crusade",
      "text": "The Sixth Crusade (1228–1229) led by Holy Roman Emperor Frederick II, resulted in a peaceful handover of Jerusalem through negotiation.",
      "date": "1228"
    },
    {
      "headline": "Seventh Crusade",
      "text": "The Seventh Crusade (1248–1254) was led by Louis IX of France and ended in failure with his capture in Egypt.",
      "date": "1248"
    },
    {
      "headline": "Eighth Crusade",
      "text": "The Eighth Crusade was launched by Louis IX of France in 1270, targeting Tunis, but ended with his death and the failure of the campaign.",
      "date": "1270"
    },
    {
      "headline": "Fall of Acre",
      "text": "On May 18, 1291, the city of Acre, the last major Crusader stronghold in the Holy Land, fell to the Mamluks, marking the end of the Crusader presence in the region.",
      "date": "1291-05-18"
    },
    {
      "headline": "End of Crusading Era",
      "text": "Crusading declined rapidly after the 15th century, particularly following the fall of Constantinople to the Ottomans in 1453.",
      "date": "1453"
    }
  ]
}

