{
  "timeline": [
    {
      "headline": "Traditional Use by Indigenous South Americans",
      "text": "For thousands of years, Indigenous South Americans have used coca leaves for medicinal and ritual purposes. The leaves are chewed or brewed into tea to combat fatigue, hunger, and altitude sickness.",
      "date": "-3000"
    },
    {
      "headline": "Isolation of Cocaine",
      "text": "In 1859, German chemist Albert Niemann isolated cocaine from coca leaves, marking the first time the active ingredient was extracted in its pure form.",
      "date": "1859"
    },
    {
      "headline": "Introduction to Medicine",
      "text": "In the 1880s, cocaine began to be used in the medical field as a local anesthetic, particularly in eye surgery, due to its numbing properties.",
      "date": "1880"
    },
    {
      "headline": "Freud's Advocacy",
      "text": "In 1884, Sigmund Freud published 'Über Coca,' advocating for the use of cocaine as a treatment for various ailments, including depression and sexual impotence.",
      "date": "1884"
    },
    {
      "headline": "Coca-Cola Formulation",
      "text": "In 1886, John Stith Pemberton formulated Coca-Cola, which originally contained coca leaf extract, providing a small amount of cocaine per serving.",
      "date": "1886"
    },
    {
      "headline": "Harrison Narcotics Tax Act",
      "text": "In 1914, the Harrison Narcotics Tax Act was passed in the United States, regulating and taxing the production, importation, and distribution of opiates and coca products, including cocaine.",
      "date": "1914"
    },
    {
      "headline": "Removal from Coca-Cola",
      "text": "By 1929, Coca-Cola had removed cocaine from its formula, using 'spent' coca leaves that had the cocaine extracted.",
      "date": "1929"
    },
    {
      "headline": "Controlled Substances Act",
      "text": "In 1970, the United States passed the Controlled Substances Act, classifying cocaine as a Schedule II drug, recognizing its potential for abuse but also its medical uses.",
      "date": "1970"
    },
    {
      "headline": "Crack Cocaine Epidemic",
      "text": "In the 1980s, the United States experienced a crack cocaine epidemic, characterized by a surge in the use of the smokable form of cocaine, leading to widespread social and health issues.",
      "date": "1980"
    }
  ]
}

