    {
      "headline": "Beginning of the Czech Kindertransport",
      "text": "In early 1939, Winton began organizing the rescue of children from Czechoslovakia, compiling a list of children in danger and arranging for their safe passage to Britain.",
      "date": "1939"
    },
    {
      "headline": "First Kindertransport Train",
      "text": "On March 14, 1939, the first train carrying children organized by Winton left Prague for Britain.",
      "date": "1939-03-14"
    },
    {
      "headline": "Last Kindertransport Train",
      "text": "The last train organized by Winton left Prague on August 2, 1939, just before the outbreak of World War II.",
      "date": "1939-08-02"
    },
    {
      "headline": "Recognition and Knighthood",
      "text": "In 2003, Nicholas Winton was knighted by Queen Elizabeth II for his services to humanity, particularly for his work in the Czech Kindertransport.",
      "date": "2003"
    },
    {
      "headline": "Death of Nicholas Winton",
      "text": "Nicholas Winton passed away on July 1, 2015, at the age of 106, in Slough, England.",
      "date": "2015-07-01"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Launch of the Cultural Revolution",
      "text": "The Cultural Revolution was officially launched by Mao Zedong in May 1966. Its goal was to preserve Chinese socialism by purging remnants of capitalist and traditional elements from Chinese society.",
      "date": "1966-05"
    },
    {
      "headline": "Formation of the Red Guards",
      "text": "In August 1966, Mao Zedong encouraged the formation of the Red Guards, a mass student-led paramilitary social movement mobilized to carry out the goals of the Cultural Revolution.",
      "date": "1966-08"
    },
    {
      "headline": "The Sixteen Points",
      "text": "On August 8, 1966, the Central Committee of the Communist Party of China adopted the 'Decision Concerning the Great Proletarian Cultural Revolution', also known as the Sixteen Points, which outlined the objectives and methods of the Cultural Revolution.",
      "date": "1966-08-08"
    },
    {
      "headline": "Attack on the Four Olds",
      "text": "In 1966, the campaign to destroy the 'Four Olds' (old customs, old culture, old habits, and old ideas) began, leading to widespread destruction of cultural heritage and artifacts.",
      "date": "1966"
    },
    {
      "headline": "Down to the Countryside Movement",
      "text": "In 1968, the 'Down to the Countryside Movement' was initiated, sending millions of urban youths to rural areas to learn from the peasantry.",
      "date": "1968"
    },
    {
      "headline": "Lin Biao Incident",
      "text": "In September 1971, Lin Biao, a key supporter of the Cultural Revolution and Mao's designated successor, died in a plane crash under mysterious circumstances after allegedly plotting a coup against Mao.",
      "date": "1971-09"
    },
    {
      "headline": "End of the Cultural Revolution",
      "text": "The Cultural Revolution effectively ended with the death of Mao Zedong on September 9, 1976, and the subsequent arrest of the Gang of Four, who were blamed for many of the excesses of the period.",
      "date": "1976-09-09"
    }
  ]
}

