{
  "timeline": [
    {
      "headline": "Papal Bull Inter gravissimas Issued",
      "text": "On February 24, 1582, Pope Gregory XIII issued the papal bull Inter gravissimas, which introduced the Gregorian calendar as a modification of the Julian calendar.",
      "date": "1582-02-24"
    },
    {
      "headline": "Gregorian Calendar Implemented",
      "text": "The Gregorian calendar was first implemented on October 15, 1582. This date followed October 4, 1582, in the countries that adopted the new calendar immediately, effectively skipping 10 days to realign the calendar with the solar year.",
      "date": "1582-10-15"
    },
    {
      "headline": "Adoption by Catholic Countries",
      "text": "By the end of 1582, the Gregorian calendar was adopted by several Catholic countries, including Spain, Portugal, the Polish–Lithuanian Commonwealth, and most of Italy.",
      "date": "1582"
    },
    {
      "headline": "Adoption by Protestant Countries",
      "text": "Protestant countries were initially reluctant to adopt the Gregorian calendar due to its Catholic origins. However, many began to adopt it over the following centuries, with Germany and the Netherlands adopting it in 1700.",
      "date": "1700"
    },
    {
      "headline": "Adoption by Great Britain and its Colonies",
      "text": "Great Britain and its colonies adopted the Gregorian calendar in 1752. To align with the calendar, they skipped 11 days, with September 2, 1752, being followed by September 14, 1752.",
      "date": "1752-09-14"
    },
    {
      "headline": "Adoption by Eastern Orthodox Countries",
      "text": "Many Eastern Orthodox countries adopted the Gregorian calendar in the 20th century. Greece was the last European country to adopt it, doing so in 1923.",
      "date": "1923"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Secularization of the Teutonic Order",
      "text": "In 1525, the Prussian part of the State of the Teutonic Order was secularized, marking the origin of Prussia as a duchy under the suzerainty of the Kingdom of Poland.",
      "date": "1525"
    },
    {
      "headline": "Duchy of Prussia",
      "text": "The Duchy of Prussia was established in 1525 following the secularization of the Teutonic Order's Prussian territories.",
      "date": "1525"
    },
    {
      "headline": "Union of Brandenburg and Prussia",
      "text": "In 1618, the Duchy of Prussia was inherited by the Electors of Brandenburg, creating a personal union between Brandenburg and Prussia.",
      "date": "1618"
    },
    {
      "headline": "Kingdom of Prussia Established",
      "text": "In 1701, Frederick I crowned himself King in Prussia, marking the elevation of the Duchy of Prussia to the Kingdom of Prussia.",
      "date": "1701"
    },
    {
      "headline": "Frederick the Great's Reign",
      "text": "Frederick II, known as Frederick the Great, reigned from 1740 to 1786, expanding Prussian territories and establishing it as a major European power.",
      "date": "1740"
    },
    {
      "headline": "Prussia in the Napoleonic Wars",
      "text": "Prussia was involved in the Napoleonic Wars from 1806 to 1815, initially suffering defeats but later contributing to Napoleon's defeat.",
      "date": "1806"
    },
    {
      "headline": "Prussian-led Unification of Germany",
      "text": "In 1871, Prussia led the unification of Germany, resulting in the proclamation of the German Empire with the Prussian king as the German Emperor.",
      "date": "1871"
    },
    {
      "headline": "End of the Kingdom of Prussia",
      "text": "The Kingdom of Prussia was abolished in 1918 following Germany's defeat in World War I and the abdication of Kaiser Wilhelm II.",
      "date": "1918"
    },
    {
      "headline": "Formal Abolition of Prussia",
      "text": "Prussia was formally abolished in 1947 by the Allied Control Council after World War II.",
      "date": "1947"
    }
  ]
}

