{
  "timeline": [
    {
      "headline": "Founding of the Knights Templar",
      "text": "The Knights Templar were founded in 1119 by a small group of knights led by Hugues de Payens. Their primary mission was to protect Christian pilgrims traveling to the Holy Land.",
      "date": "1119"
    },
    {
      "headline": "Official Recognition by the Church",
      "text": "In 1129, the Knights Templar were officially recognized by the Catholic Church at the Council of Troyes, which provided them with a rule and papal endorsement.",
      "date": "1129"
    },
    {
      "headline": "Establishment of the Templar Banking System",
      "text": "During the 1130s, the Knights Templar established a network of financial operations across Europe, which included a form of banking that allowed pilgrims to deposit funds in their home countries and withdraw them in the Holy Land.",
      "date": "1130"
    },
    {
      "headline": "Construction of the Templar Fleet",
      "text": "In the mid-12th century, the Knights Templar began constructing a fleet of ships to protect pilgrims traveling by sea and to support their military operations.",
      "date": "1150"
    },
    {
      "headline": "Battle of Montgisard",
      "text": "On November 25, 1177, the Knights Templar played a crucial role in the Battle of Montgisard, where they helped defeat the forces of Saladin, the Sultan of Egypt and Syria.",
      "date": "1177-11-25"
    },
    {
      "headline": "Fall of Acre",
      "text": "In 1291, the city of Acre, the last major stronghold of the Crusaders in the Holy Land, fell to the Mamluks. This marked the end of the Crusader presence in the region and a significant loss for the Knights Templar.",
      "date": "1291"
    },
    {
      "headline": "Arrest of the Knights Templar",
      "text": "On October 13, 1307, King Philip IV of France ordered the arrest of the Knights Templar across France. Many members were charged with heresy, and the order's assets were seized.",
      "date": "1307-10-13"
    },
    {
      "headline": "Dissolution of the Knights Templar",
      "text": "In 1312, Pope Clement V officially dissolved the Knights Templar at the Council of Vienne, transferring most of their assets to the Knights Hospitaller.",
      "date": "1312"
    },
    {
      "headline": "Execution of Jacques de Molay",
      "text": "On March 18, 1314, Jacques de Molay, the last Grand Master of the Knights Templar, was executed by burning at the stake in Paris after recanting his earlier confessions under torture.",
      "date": "1314-03-18"
    }
  ]
}

