{
  "timeline": [
    {
      "headline": "Beginning of the Armenian Genocide",
      "text": "On April 24, 1915, the Ottoman government arrested and executed several hundred Armenian intellectuals and community leaders in Constantinople, marking the beginning of the Armenian Genocide.",
      "date": "1915-04-24"
    },
    {
      "headline": "Tehcir Law Enacted",
      "text": "On May 29, 1915, the Ottoman government enacted the Tehcir Law, which authorized the deportation of Armenians from their homes, leading to mass deportations and deaths.",
      "date": "1915-05-29"
    },
    {
      "headline": "Mass Deportations",
      "text": "Throughout 1915 and 1916, Armenians were forcibly deported from their homes and subjected to death marches towards the Syrian Desert, where many perished due to starvation, dehydration, and massacres.",
      "date": "1915"
    },
    {
      "headline": "Battle of Musa Dagh",
      "text": "In July 1915, Armenians in the region of Musa Dagh resisted deportation orders and defended themselves against Ottoman forces for several weeks before being rescued by French warships.",
      "date": "1915-07"
    },
    {
      "headline": "End of Major Deportations",
      "text": "By 1917, the major deportations and massacres had largely ceased, although the effects of the genocide continued to be felt by survivors and their descendants.",
      "date": "1917"
    },
    {
      "headline": "Treaty of Sèvres",
      "text": "On August 10, 1920, the Treaty of Sèvres was signed, which included provisions for the establishment of an independent Armenian state, although it was never implemented.",
      "date": "1920-08-10"
    },
    {
      "headline": "Recognition of the Armenian Genocide",
      "text": "Over the years, various countries and international bodies have recognized the events as genocide, with increasing recognition in the late 20th and early 21st centuries.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Origins of Aphrodite's Cult",
      "text": "Aphrodite's cult is largely derived from the Phoenician goddess Astarte, a cognate of the East Semitic goddess Ishtar, whose cult was based on the Sumerian cult of Inanna. This syncretism reflects the blending of cultures and religious practices in the ancient Mediterranean world.",
      "date": "-2000"
    },
    {
      "headline": "Establishment of Cult Centers",
      "text": "Aphrodite's main cult centers were established in Cythera, Cyprus, Corinth, and Athens. These locations became significant sites for worship and celebration of the goddess, reflecting her widespread influence across the Greek world.",
      "date": "-1000"
    },
    {
      "headline": "Aphrodisia Festival",
      "text": "The Aphrodisia, Aphrodite's main festival, was celebrated annually in midsummer. This festival involved various rituals and celebrations in honor of the goddess, emphasizing her role in love and beauty.",
      "date": "-0500"
    },
    {
      "headline": "Worship in Laconia",
      "text": "In Laconia, Aphrodite was worshipped as a warrior goddess. This unique aspect of her worship highlights the diverse interpretations and attributes associated with Aphrodite in different regions.",
      "date": "-0400"
    },
    {
      "headline": "Aphrodite as Patron of Prostitutes",
      "text": "Aphrodite was also the patron goddess of prostitutes, an association which led early scholars to propose the concept of 'sacred prostitution' in Greco-Roman culture. However, this idea is now generally seen as erroneous.",
      "date": "-0300"
    }
  ]
}

