    },
    {
      "headline": "Spanish as an Official UN Language",
      "text": "Spanish was recognized as one of the six official languages of the United Nations in 1945.",
      "date": "1945"
    },
    {
      "headline": "Spanish Language Day Established",
      "text": "In 2010, the United Nations established Spanish Language Day to celebrate the language's cultural and historical significance.",
      "date": "2010"
    }
  ]
}

