{
  "timeline": [
    {
      "headline": "Unification of Upper and Lower Egypt",
      "text": "Around 3100 BC, the political unification of Upper and Lower Egypt was achieved under the rule of the first pharaoh, traditionally identified as Menes.",
      "date": "-3100"
    },
    {
      "headline": "Old Kingdom Period",
      "text": "The Old Kingdom period, also known as the 'Age of the Pyramids', lasted from around 2686 BC to 2181 BC. It is most famous for the construction of the pyramids, including the Great Pyramid of Giza.",
      "date": "-2686"
    },
    {
      "headline": "First Intermediate Period",
      "text": "The First Intermediate Period (c. 2181–2055 BC) was a time of political fragmentation and climate instability following the collapse of the Old Kingdom.",
      "date": "-2181"
    },
    {
      "headline": "Middle Kingdom Period",
      "text": "The Middle Kingdom (c. 2055–1650 BC) is known for its cultural renaissance and the consolidation of power by pharaohs such as Mentuhotep II and Amenemhat I.",
      "date": "-2055"
    },
    {
      "headline": "Second Intermediate Period",
      "text": "The Second Intermediate Period (c. 1650–1550 BC) was marked by the division of Egypt and the rule of the Hyksos in the north.",
      "date": "-1650"
    },
    {
      "headline": "New Kingdom Period",
      "text": "The New Kingdom (c. 1550–1077 BC) was a time of imperial expansion and prosperity, with famous pharaohs like Hatshepsut, Akhenaten, Tutankhamun, and Ramses II.",
      "date": "-1550"
    },
    {
      "headline": "Third Intermediate Period",
      "text": "The Third Intermediate Period (c. 1077–664 BC) saw the decline of centralized power and the division of Egypt into smaller states.",
      "date": "-1077"
    },
    {
      "headline": "Late Period",
      "text": "The Late Period (c. 664–332 BC) was characterized by foreign invasions and the eventual conquest by the Persians and later by Alexander the Great.",
      "date": "-664"
    },
    {
      "headline": "Conquest by Alexander the Great",
      "text": "In 332 BC, Alexander the Great conquered Egypt, marking the end of the Late Period and the beginning of the Hellenistic period under the Ptolemaic dynasty.",
      "date": "-332"
    }
  ]
}

