{
  "timeline": [
    {
      "headline": "Construction of the Ark",
      "text": "According to the Book of Exodus, the Ark of the Covenant was constructed by the Israelites under the guidance of Moses, following the instructions given by God on Mount Sinai. This event is traditionally dated to the time of the Exodus, which is often placed around the 13th century BCE.",
      "date": "-1300"
    },
    {
      "headline": "Ark in the Tabernacle",
      "text": "The Ark was housed in the Tabernacle, a portable earthly dwelling place for the divine presence, during the Israelites' 40 years of wandering in the desert.",
      "date": "-1300"
    },
    {
      "headline": "Crossing of the Jordan River",
      "text": "The Ark played a crucial role during the crossing of the Jordan River. The waters of the river were said to have stopped flowing when the priests carrying the Ark stepped into it, allowing the Israelites to cross on dry ground. This event is traditionally dated to around the late 13th century BCE.",
      "date": "-1290"
    },
    {
      "headline": "Capture by the Philistines",
      "text": "The Ark was captured by the Philistines during a battle at Ebenezer. It was taken to several Philistine cities, causing plagues and misfortune wherever it went. This event is described in the First Book of Samuel and is traditionally dated to the 11th century BCE.",
      "date": "-1100"
    },
    {
      "headline": "Return to the Israelites",
      "text": "After seven months, the Philistines returned the Ark to the Israelites, placing it on a cart pulled by two cows. It was returned to the town of Beth Shemesh and later moved to Kiriath-Jearim.",
      "date": "-1100"
    },
    {
      "headline": "Ark in Jerusalem",
      "text": "King David brought the Ark to Jerusalem with great celebration, placing it in a tent he had prepared. This event is traditionally dated to around 1000 BCE.",
      "date": "-1000"
    },
    {
      "headline": "Placement in Solomon's Temple",
      "text": "The Ark was placed in the Holy of Holies in Solomon's Temple in Jerusalem. This event is traditionally dated to the completion of the Temple around 957 BCE.",
      "date": "-0957"
    },
    {
      "headline": "Disappearance of the Ark",
      "text": "The fate of the Ark after the destruction of Solomon's Temple by the Babylonians in 587 BCE is unknown. Various theories and legends exist about its disappearance.",
      "date": "-0587"
    }
  ]
}

