      "headline": "Birth of Aleister Crowley",
      "text": "Aleister Crowley was born on October 12, 1875, in Royal Leamington Spa, Warwickshire, England.",
      "date": "1875-10-12"
    },
    {
      "headline": "Enrollment at Trinity College, Cambridge",
      "text": "In 1895, Crowley began his studies at Trinity College, Cambridge, where he focused on English literature and poetry.",
      "date": "1895"
    },
    {
      "headline": "Publication of 'Aceldama'",
      "text": "In 1898, Crowley published his first book of poetry, 'Aceldama: A Place to Bury Strangers In'.",
      "date": "1898"
    },
    {
      "headline": "Joining the Hermetic Order of the Golden Dawn",
      "text": "In 1898, Crowley joined the Hermetic Order of the Golden Dawn, a secret society devoted to the study and practice of the occult, metaphysics, and paranormal activities.",
      "date": "1898"
    },
    {
      "headline": "Publication of 'The Book of the Law'",
      "text": "In 1904, Crowley wrote 'The Book of the Law', which became the central sacred text of Thelema, a new religious movement he founded.",
      "date": "1904"
    },
    {
      "headline": "Founding of the A∴A∴",
      "text": "In 1907, Crowley founded the A∴A∴, a magical order dedicated to the advancement of humanity through spiritual enlightenment.",
      "date": "1907"
    },
    {
      "headline": "Publication of 'The Equinox'",
      "text": "Between 1909 and 1913, Crowley published 'The Equinox', a biannual periodical that served as the official organ of the A∴A∴.",
      "date": "1909"
    },
    {
      "headline": "Becoming a leader in Ordo Templi Orientis",
      "text": "In 1912, Crowley was appointed as the head of the British branch of the Ordo Templi Orientis (O.T.O.), a fraternal and religious organization.",
      "date": "1912"
    },
    {
      "headline": "Establishment of the Abbey of Thelema",
      "text": "In 1920, Crowley established the Abbey of Thelema in Cefalù, Sicily, as a commune for his followers to practice Thelemic rituals.",
      "date": "1920"
    },
    {
      "headline": "Expulsion from Italy",
      "text": "In 1923, Crowley was expelled from Italy by Benito Mussolini's government due to reports of immoral activities at the Abbey of Thelema.",
      "date": "1923"
    },
    {
      "headline": "Publication of 'Magick in Theory and Practice'",
      "text": "In 1929, Crowley published 'Magick in Theory and Practice', a comprehensive guide to his magical philosophy and practices.",
      "date": "1929"
    },
    {
      "headline": "Death of Aleister Crowley",
      "text": "Aleister Crowley died on December 1, 1947, in Hastings, East Sussex, England.",
      "date": "1947-12-01"
    }
  ]
}

