{
  "timeline": [
    {
      "headline": "Early Harappan Phase",
      "text": "The Early Harappan Phase of the Indus Valley Civilisation began around 3300 BCE. This phase is characterized by the establishment of agricultural communities and the development of trade networks.",
      "date": "-3300"
    },
    {
      "headline": "Mature Harappan Phase",
      "text": "The Mature Harappan Phase, starting around 2600 BCE, marks the peak of the Indus Valley Civilisation. During this period, the civilisation saw the development of urban centers like Harappa and Mohenjo-Daro, advanced architecture, and a complex social structure.",
      "date": "-2600"
    },
    {
      "headline": "Decline of the Indus Valley Civilisation",
      "text": "The decline of the Indus Valley Civilisation began around 1900 BCE. This period saw the gradual abandonment of cities and a decline in trade and urban life, possibly due to environmental changes and shifting river patterns.",
      "date": "-1900"
    },
    {
      "headline": "Late Harappan Phase",
      "text": "The Late Harappan Phase lasted from around 1900 BCE to 1300 BCE. This phase is characterized by the fragmentation of the civilisation into smaller cultures and the continuation of some Harappan traditions in rural areas.",
      "date": "-1900"
    },
    {
      "headline": "End of the Indus Valley Civilisation",
      "text": "The Indus Valley Civilisation came to an end around 1300 BCE. By this time, the major urban centers had been abandoned, and the civilisation had transitioned into smaller, regional cultures.",
      "date": "-1300"
    }
  ]
}

