{
  "timeline": [
    {
      "headline": "Birth of Abraham",
      "text": "Abraham, originally named Abram, is traditionally believed to have been born in the city of Ur in Mesopotamia. His birth is estimated to have occurred around 2000 BCE.",
      "date": "-2000"
    },
    {
      "headline": "Call of Abram",
      "text": "According to the Bible, God called Abram to leave his homeland and journey to a land that God would show him. This event marks the beginning of Abram's covenant with God.",
      "date": "-1900"
    },
    {
      "headline": "Abram's Journey to Canaan",
      "text": "Abram, along with his wife Sarai and nephew Lot, traveled to the land of Canaan as instructed by God.",
      "date": "-1900"
    },
    {
      "headline": "Covenant of the Pieces",
      "text": "God made a covenant with Abram, promising that his descendants would inherit the land of Canaan. This event is known as the Covenant of the Pieces.",
      "date": "-1890"
    },
    {
      "headline": "Birth of Ishmael",
      "text": "Abram's first son, Ishmael, was born to Hagar, Sarai's Egyptian maidservant, as Sarai was barren at the time.",
      "date": "-1886"
    },
    {
      "headline": "Name Change to Abraham",
      "text": "God changed Abram's name to Abraham, meaning 'father of many nations,' and Sarai's name to Sarah. This was part of God's covenant with Abraham.",
      "date": "-1875"
    },
    {
      "headline": "Birth of Isaac",
      "text": "Isaac, the son of Abraham and Sarah, was born as the child of promise, fulfilling God's promise to Abraham.",
      "date": "-1871"
    },
    {
      "headline": "Binding of Isaac",
      "text": "God tested Abraham's faith by asking him to sacrifice his son Isaac. Abraham prepared to obey, but an angel stopped him, and a ram was sacrificed instead.",
      "date": "-1850"
    },
    {
      "headline": "Death of Sarah",
      "text": "Sarah, Abraham's wife, died at the age of 127 in Hebron, Canaan.",
      "date": "-1840"
    },
    {
      "headline": "Death of Abraham",
      "text": "Abraham died at the age of 175 and was buried in the Cave of Machpelah in Hebron, Canaan.",
      "date": "-1825"
    }
  ]
}

