    {
      "headline": "Ironman Becomes Part of the World Triathlon Corporation",
      "text": "In 1990, the Ironman brand and events became part of the World Triathlon Corporation (WTC), which was established to manage and promote Ironman races globally.",
      "date": "1990"
    },
    {
      "headline": "Ironman 70.3 Series Launch",
      "text": "In 2005, the Ironman 70.3 series was launched, featuring half the distances of the full Ironman races. The series provided a stepping stone for athletes aspiring to complete a full Ironman.",
      "date": "2005"
    },
    {
      "headline": "Ironman Acquired by Dalian Wanda Group",
