    {
      "headline": "Discovery of St. James' Tomb",
      "text": "In the early 9th century, the tomb of St. James was discovered in Galicia, Spain. This discovery marked the beginning of the pilgrimage to Santiago de Compostela.",
      "date": "0813"
    },
    {
      "headline": "Construction of the Original Church",
      "text": "In 829, King Alfonso II of Asturias ordered the construction of a church on the site of St. James' tomb, establishing Santiago de Compostela as a pilgrimage destination.",
      "date": "0829"
    },
    {
      "headline": "Establishment of the Pilgrimage Route",
      "text": "By the 10th century, the Camino de Santiago had become a well-established pilgrimage route, attracting pilgrims from across Europe.",
      "date": "0900"
    },
    {
      "headline": "Construction of the Cathedral of Santiago de Compostela",
      "text": "Construction of the Cathedral of Santiago de Compostela began in 1075 under the reign of Alfonso VI of León and Castile, to accommodate the increasing number of pilgrims.",
      "date": "1075"
    },
    {
      "headline": "Completion of the Cathedral",
      "text": "The Cathedral of Santiago de Compostela was completed in 1211, becoming a major religious and architectural landmark.",
      "date": "1211"
    },
    {
      "headline": "Peak of Pilgrimage Popularity",
      "text": "During the 12th and 13th centuries, the Camino de Santiago reached its peak in popularity, with thousands of pilgrims traveling the route annually.",
      "date": "1200"
    },
    {
      "headline": "Decline of Pilgrimage",
      "text": "In the 16th century, the popularity of the Camino de Santiago began to decline due to the Protestant Reformation and political instability in Europe.",
      "date": "1500"
    },
    {
      "headline": "Revival of the Camino",
      "text": "In the late 20th century, there was a revival of interest in the Camino de Santiago, with increasing numbers of pilgrims walking the route each year.",
      "date": "1980"
    },
    {
      "headline": "UNESCO World Heritage Site Designation",
      "text": "In 1993, the Camino de Santiago was designated as a UNESCO World Heritage Site, recognizing its cultural and historical significance.",
      "date": "1993"
    }
  ]
}

