  "timeline": [
    {
      "headline": "Dyatlov Group Begins Expedition",
      "text": "On January 23, 1959, a group of ten hikers from the Ural Polytechnical Institute, led by Igor Dyatlov, began their expedition to reach Otorten, a mountain 10 kilometers north of the site where the incident occurred.",
      "date": "1959-01-23"
    },
    {
      "headline": "Yuri Yudin Leaves the Group",
      "text": "On January 28, 1959, one of the group members, Yuri Yudin, left the expedition due to illness, reducing the group to nine members.",
      "date": "1959-01-28"
    },
    {
      "headline": "Dyatlov Group Establishes Final Camp",
      "text": "On February 1, 1959, the Dyatlov group established their final camp on the eastern slopes of Kholat Syakhl.",
      "date": "1959-02-01"
    },
    {
      "headline": "Dyatlov Pass Incident Occurs",
      "text": "Between February 1 and 2, 1959, the nine hikers died under mysterious circumstances. They fled their tent in the middle of the night, inadequately dressed for the harsh conditions, and perished in the snow.",
      "date": "1959-02-02"
    },
    {
      "headline": "Search Party Discovers Tent",
      "text": "On February 26, 1959, a search party discovered the group's abandoned and damaged tent on Kholat Syakhl.",
      "date": "1959-02-26"
    },
    {
      "headline": "First Bodies Found",
      "text": "On February 27, 1959, the first two bodies were found at the edge of a forest, near a cedar tree.",
      "date": "1959-02-27"
    },
    {
      "headline": "Additional Bodies Discovered",
      "text": "By March 5, 1959, three more bodies were found, including that of Igor Dyatlov, between the tent and the forest.",
      "date": "1959-03-05"
    },
    {
      "headline": "Last Four Bodies Found",
      "text": "On May 4, 1959, the remaining four bodies were discovered in a ravine further into the woods.",
      "date": "1959-05-04"
    },
    {
      "headline": "Official Investigation Concludes",
      "text": "In May 1959, the official investigation concluded that the hikers' deaths were due to a 'compelling natural force.' The case was closed with no definitive explanation.",
      "date": "1959-05"
    }
  ]
}

