    {
      "headline": "Revelation Begins",
      "text": "According to Islamic tradition, the revelation of the Quran began in 610 CE when the Prophet Muhammad received the first verses from the Angel Gabriel in the Cave of Hira.",
      "date": "0610"
    },
    {
      "headline": "Migration to Medina",
      "text": "In 622 CE, the Prophet Muhammad and his followers migrated from Mecca to Medina, an event known as the Hijra. This marked the beginning of the Islamic calendar and the Quran's revelations continued in Medina.",
      "date": "0622"
    },
    {
      "headline": "Completion of Revelation",
      "text": "The Quran's revelation is believed to have been completed in 632 CE, the year of the Prophet Muhammad's death.",
      "date": "0632"
    },
    {
      "headline": "Compilation Under Caliph Abu Bakr",
      "text": "After the death of Prophet Muhammad, the first caliph, Abu Bakr, initiated the compilation of the Quran into a single book form around 632-634 CE, due to concerns over the loss of those who had memorized it.",
      "date": "0632"
    },
    {
      "headline": "Standardization Under Caliph Uthman",
      "text": "Around 650 CE, the third caliph, Uthman ibn Affan, ordered the standardization of the Quranic text to preserve its authenticity and prevent variations. This resulted in the Uthmanic codex, which is the basis for all modern Quranic texts.",
      "date": "0650"
    }
  ]
}

