    {
      "headline": "First Battle of St Albans",
      "text": "The first battle of the Wars of the Roses took place on May 22, 1455. The Yorkists, led by Richard, Duke of York, defeated the Lancastrians, capturing King Henry VI.",
      "date": "1455-05-22"
    },
    {
      "headline": "Battle of Blore Heath",
      "text": "On September 23, 1459, the Yorkists, led by Richard Neville, Earl of Salisbury, defeated a Lancastrian force at Blore Heath.",
      "date": "1459-09-23"
    },
    {
      "headline": "Battle of Northampton",
      "text": "On July 10, 1460, the Yorkists won a decisive victory at the Battle of Northampton, capturing King Henry VI once again.",
      "date": "1460-07-10"
    },
    {
      "headline": "Battle of Wakefield",
      "text": "On December 30, 1460, the Lancastrians defeated the Yorkists at the Battle of Wakefield, killing Richard, Duke of York.",
