    },
    {
      "headline": "Battle of Towton",
      "text": "The Battle of Towton, fought on March 29, 1461, was the largest and bloodiest battle of the Wars of the Roses. The Yorkists, led by Edward IV, defeated the Lancastrians.",
      "date": "1461-03-29"
    },
    {
      "headline": "Edward IV becomes King",
      "text": "Edward IV was proclaimed King of England on March 4, 1461, following his victory at the Battle of Towton.",
