{
  "timeline": [
    {
      "headline": "Jacques Cartier Claims Quebec",
      "text": "In 1534, French explorer Jacques Cartier claimed the area now known as Quebec for France, marking the beginning of French influence in the region.",
      "date": "1534"
    },
    {
      "headline": "Founding of Quebec City",
      "text": "On July 3, 1608, Samuel de Champlain founded Quebec City, establishing one of the first permanent European settlements in North America.",
      "date": "1608-07-03"
    },
    {
      "headline": "Treaty of Paris",
      "text": "In 1763, the Treaty of Paris was signed, ending the Seven Years' War. As a result, France ceded control of Quebec to Great Britain.",
      "date": "1763"
    },
    {
      "headline": "Quebec Act",
      "text": "In 1774, the British Parliament passed the Quebec Act, which expanded the territory of Quebec and restored French civil law while maintaining British criminal law.",
      "date": "1774"
    },
    {
      "headline": "Constitutional Act",
      "text": "In 1791, the Constitutional Act was passed, dividing the Province of Quebec into Upper Canada and Lower Canada, with Lower Canada corresponding to present-day Quebec.",
      "date": "1791"
    },
    {
      "headline": "Rebellions of 1837-1838",
      "text": "Between 1837 and 1838, the Lower Canada Rebellion took place as French-speaking Canadiens sought political reform and greater autonomy from British rule.",
      "date": "1837"
    },
    {
      "headline": "Act of Union",
      "text": "In 1840, the Act of Union was passed, uniting Upper and Lower Canada into the Province of Canada, with Quebec becoming Canada East.",
      "date": "1840"
    },
    {
      "headline": "Confederation of Canada",
      "text": "On July 1, 1867, Quebec became one of the four original provinces to join the Canadian Confederation.",
      "date": "1867-07-01"
    },
    {
      "headline": "Quiet Revolution",
      "text": "During the 1960s, the Quiet Revolution occurred in Quebec, characterized by rapid secularization, economic reforms, and the rise of Quebec nationalism.",
      "date": "1960"
    },
    {
      "headline": "October Crisis",
      "text": "In October 1970, the October Crisis occurred when the Front de libération du Québec (FLQ) kidnapped government officials, leading to the invocation of the War Measures Act.",
      "date": "1970-10"
    },
    {
      "headline": "First Quebec Referendum",
      "text": "On May 20, 1980, Quebec held its first referendum on sovereignty-association, which was defeated with 60% voting against it.",
      "date": "1980-05-20"
    },
    {
      "headline": "Second Quebec Referendum",
      "text": "On October 30, 1995, Quebec held a second referendum on independence, which was narrowly defeated with 50.58% voting against it.",
      "date": "1995-10-30"
    }
  ]
}

