{
  "timeline": [
    {
      "headline": "Birth of Robert E. Lee",
      "text": "Robert Edward Lee was born on January 19, 1807, in Stratford Hall, Virginia.",
      "date": "1807-01-19"
    },
    {
      "headline": "Graduation from West Point",
      "text": "In 1829, Robert E. Lee graduated second in his class from the United States Military Academy at West Point.",
      "date": "1829"
    },
    {
      "headline": "Marriage to Mary Anna Custis",
      "text": "On June 30, 1831, Robert E. Lee married Mary Anna Custis, the great-granddaughter of Martha Washington, at Arlington House.",
      "date": "1831-06-30"
    },
    {
      "headline": "Mexican-American War Service",
      "text": "From 1846 to 1848, Lee served with distinction in the Mexican-American War, earning a reputation for his bravery and skill.",
      "date": "1846"
    },
    {
      "headline": "Superintendent of West Point",
      "text": "Lee served as the Superintendent of the United States Military Academy at West Point from 1852 to 1855.",
      "date": "1852"
    },
    {
      "headline": "Resignation from U.S. Army",
      "text": "On April 20, 1861, Lee resigned his commission in the United States Army following the secession of Virginia from the Union.",
      "date": "1861-04-20"
    },
    {
      "headline": "Commander of the Army of Northern Virginia",
      "text": "In June 1862, Lee was appointed commander of the Army of Northern Virginia, the Confederacy's most powerful army.",
      "date": "1862-06"
    },
    {
      "headline": "Battle of Gettysburg",
      "text": "From July 1 to July 3, 1863, Lee led his forces in the Battle of Gettysburg, a pivotal battle in the American Civil War.",
      "date": "1863-07-01"
    },
    {
      "headline": "Surrender at Appomattox Court House",
      "text": "On April 9, 1865, Lee surrendered the Army of Northern Virginia to Union General Ulysses S. Grant at Appomattox Court House, effectively ending the Civil War.",
      "date": "1865-04-09"
    },
    {
      "headline": "President of Washington College",
      "text": "In October 1865, Lee became the president of Washington College in Lexington, Virginia, where he served until his death.",
      "date": "1865-10"
    },
    {
      "headline": "Death of Robert E. Lee",
      "text": "Robert E. Lee died on October 12, 1870, in Lexington, Virginia, after suffering a stroke.",
      "date": "1870-10-12"
    }
  ]
}

