{
  "timeline": [
    {
      "headline": "Birth of Leon Trotsky",
      "text": "Leon Trotsky was born as Lev Davidovich Bronstein on November 7, 1879, in Yanovka, Kherson Governorate, Russian Empire.",
      "date": "1879-11-07"
    },
    {
      "headline": "Involvement in the 1905 Revolution",
      "text": "Trotsky became a key figure in the 1905 Russian Revolution, serving as chairman of the St. Petersburg Soviet.",
      "date": "1905"
    },
    {
      "headline": "Escape from Siberian Exile",
      "text": "In 1907, Trotsky escaped from his exile in Siberia, where he had been sent after the failed 1905 Revolution.",
      "date": "1907"
    },
    {
      "headline": "October Revolution of 1917",
      "text": "Trotsky played a leading role in the October Revolution of 1917, which led to the Bolsheviks seizing power in Russia.",
      "date": "1917-10"
    },
    {
      "headline": "Commissar of Foreign Affairs",
      "text": "In 1917, following the October Revolution, Trotsky was appointed as the People's Commissar for Foreign Affairs.",
      "date": "1917"
    },
    {
      "headline": "Commissar of Military and Naval Affairs",
      "text": "In 1918, Trotsky became the People's Commissar for Military and Naval Affairs, playing a crucial role in the Red Army's success during the Russian Civil War.",
      "date": "1918"
    },
    {
      "headline": "Russian Civil War",
      "text": "From 1918 to 1922, Trotsky was a key leader in the Russian Civil War, organizing and leading the Red Army to victory.",
      "date": "1918"
    },
    {
      "headline": "Formation of the Soviet Union",
      "text": "Trotsky was instrumental in the establishment of the Soviet Union in 1922.",
      "date": "1922"
    },
    {
      "headline": "Expulsion from the Communist Party",
      "text": "In 1927, Trotsky was expelled from the Communist Party due to his opposition to Joseph Stalin's policies.",
      "date": "1927"
    },
    {
      "headline": "Exile from the Soviet Union",
      "text": "Trotsky was exiled from the Soviet Union in 1929, marking the beginning of his life in exile.",
      "date": "1929"
    },
    {
      "headline": "Assassination in Mexico",
      "text": "Leon Trotsky was assassinated on August 21, 1940, in Coyoacán, Mexico, by Ramón Mercader, an agent of the Soviet NKVD.",
      "date": "1940-08-21"
    }
  ]
}

