{
  "timeline": [
    {
      "headline": "Birth of Charles de Gaulle",
      "text": "Charles André Joseph Marie de Gaulle was born on November 22, 1890, in Lille, France.",
      "date": "1890-11-22"
    },
    {
      "headline": "Graduation from Saint-Cyr",
      "text": "In 1912, Charles de Gaulle graduated from the French military academy, Saint-Cyr.",
      "date": "1912"
    },
    {
      "headline": "World War I Service",
      "text": "During World War I, de Gaulle served as a captain in the French Army and was wounded and captured at the Battle of Verdun in 1916.",
      "date": "1916"
    },
    {
      "headline": "Publication of 'The Army of the Future'",
      "text": "In 1934, de Gaulle published 'Vers l'Armée de Métier' (The Army of the Future), advocating for a professional army and mechanized warfare.",
      "date": "1934"
    },
    {
      "headline": "Appointed Undersecretary of National Defence",
      "text": "In June 1940, de Gaulle was appointed Undersecretary of National Defence and War by Prime Minister Paul Reynaud.",
      "date": "1940-06"
    },
    {
      "headline": "Appeal of 18 June",
      "text": "On June 18, 1940, de Gaulle delivered his famous appeal from London, urging the French to resist German occupation.",
      "date": "1940-06-18"
    },
    {
      "headline": "Leader of Free French Forces",
      "text": "During World War II, de Gaulle became the leader of the Free French Forces, organizing resistance against Nazi Germany.",
      "date": "1940"
    },
    {
      "headline": "Chairman of the Provisional Government",
      "text": "From 1944 to 1946, de Gaulle chaired the Provisional Government of the French Republic, working to restore democracy in France after the liberation.",
      "date": "1944"
    },
    {
      "headline": "Resignation from Provisional Government",
      "text": "De Gaulle resigned from the Provisional Government in January 1946 due to political disagreements.",
      "date": "1946-01"
    },
    {
      "headline": "Founding of the Fifth Republic",
      "text": "In 1958, amid the Algerian War, de Gaulle was appointed Prime Minister and rewrote the Constitution of France, founding the Fifth Republic.",
      "date": "1958"
    },
    {
      "headline": "Elected President of France",
      "text": "De Gaulle was elected President of France in December 1958, a position he held until 1969.",
      "date": "1958-12"
    },
    {
      "headline": "Resignation as President",
      "text": "Charles de Gaulle resigned as President of France on April 28, 1969, following a failed referendum on regional reform.",
      "date": "1969-04-28"
    },
    {
      "headline": "Death of Charles de Gaulle",
      "text": "Charles de Gaulle died on November 9, 1970, in Colombey-les-Deux-Églises, France.",
      "date": "1970-11-09"
    }
  ]
}

