{
  "timeline": [
    {
      "headline": "Start of Abu Ghraib Prisoner Abuse",
      "text": "The abuse of prisoners at Abu Ghraib prison began in late 2003, during the early stages of the Iraq War. Members of the United States Army and the Central Intelligence Agency were involved in committing a series of human rights violations and war crimes against detainees.",
      "date": "2003"
    },
    {
      "headline": "Death of Manadel al-Jamadi",
      "text": "On November 4, 2003, Manadel al-Jamadi, an Iraqi prisoner, died during a CIA interrogation at Abu Ghraib prison. His death was ruled a homicide, and his body was later photographed wrapped in ice and posed with grinning U.S. soldiers.",
      "date": "2003-11-04"
    },
    {
      "headline": "Photographs of Abuse Released",
      "text": "In April 2004, CBS News released photographs showing the abuse of prisoners at Abu Ghraib. The images depicted physical abuse, sexual humiliation, and psychological torture, causing shock and outrage worldwide.",
      "date": "2004-04"
    },
    {
      "headline": "Public Outrage and Condemnation",
      "text": "Following the release of the photographs in April 2004, there was widespread condemnation of the abuses at Abu Ghraib both within the United States and internationally. The scandal led to investigations and calls for accountability.",
      "date": "2004-04"
    },
    {
      "headline": "Court-Martial of Soldiers",
      "text": "Several U.S. soldiers were court-martialed and convicted for their roles in the Abu Ghraib abuses. The most notable conviction was that of Charles Graner, who was sentenced to 10 years in prison in January 2005.",
      "date": "2005-01"
    }
  ]
}

