{
  "timeline": [
    {
      "headline": "First Observance of Memorial Day",
      "text": "The first widely publicized observance of a Memorial Day-type event took place on May 1, 1865, in Charleston, South Carolina. Freed African Americans held a parade of 10,000 people to honor 257 dead Union soldiers who had been buried in a mass grave in a Confederate prison camp.",
      "date": "1865-05-01"
    },
    {
      "headline": "Decoration Day Proclamation",
      "text": "On May 5, 1868, General John A. Logan, leader of an organization for Northern Civil War veterans, called for a nationwide day of remembrance later that month. The 30th of May, 1868, was designated for the purpose of strewing with flowers, or otherwise decorating the graves of comrades who died in defense of their country during the late rebellion.",
      "date": "1868-05-05"
    },
    {
      "headline": "First Decoration Day",
      "text": "The first Decoration Day was observed on May 30, 1868. On this day, General James Garfield made a speech at Arlington National Cemetery, and 5,000 participants decorated the graves of the 20,000 Union and Confederate soldiers buried there.",
      "date": "1868-05-30"
    },
    {
      "headline": "New York Recognizes Decoration Day",
      "text": "In 1873, New York became the first state to officially recognize Decoration Day as a holiday.",
      "date": "1873"
    },
    {
      "headline": "Memorial Day Becomes More Widely Recognized",
      "text": "By 1890, all Northern states had adopted Decoration Day as a holiday. The South, however, refused to acknowledge the day, honoring their dead on separate days until after World War I.",
      "date": "1890"
    },
    {
      "headline": "Memorial Day After World War I",
      "text": "After World War I, the holiday evolved to commemorate American military personnel who died in all wars, not just the Civil War.",
      "date": "1918"
    },
    {
      "headline": "Uniform Monday Holiday Act",
      "text": "In 1968, Congress passed the Uniform Monday Holiday Act, which established Memorial Day as the last Monday in May in order to create a three-day weekend for federal employees. The change went into effect in 1971.",
      "date": "1968"
    },
    {
      "headline": "Memorial Day Becomes a Federal Holiday",
      "text": "Memorial Day was declared a federal holiday in 1971, following the Uniform Monday Holiday Act.",
      "date": "1971"
    }
  ]
}

