{
  "timeline": [
    {
      "headline": "Adoption of the Declaration of Independence",
      "text": "On July 4, 1776, the Declaration of Independence was adopted unanimously by the 56 delegates to the Second Continental Congress, who convened at Pennsylvania State House, later renamed Independence Hall, in Philadelphia. This document declared the Thirteen Colonies as independent sovereign states no longer subject to British colonial rule.",
      "date": "1776-07-04"
    },
    {
      "headline": "Drafting of the Declaration",
      "text": "In June 1776, the Continental Congress appointed a Committee of Five to draft a declaration of independence. The committee consisted of John Adams, Benjamin Franklin, Thomas Jefferson, Robert R. Livingston, and Roger Sherman. Thomas Jefferson was chosen to be the principal author.",
      "date": "1776-06"
    },
    {
      "headline": "Presentation to Congress",
      "text": "On June 28, 1776, the Committee of Five presented the draft of the Declaration of Independence to the Continental Congress.",
      "date": "1776-06-28"
    },
    {
      "headline": "Congressional Debate and Revision",
      "text": "Between July 1 and July 4, 1776, the Continental Congress debated and revised the Declaration of Independence. The final version was agreed upon and adopted on July 4, 1776.",
      "date": "1776-07-01"
    },
    {
      "headline": "Signing of the Declaration",
      "text": "The official signing of the Declaration of Independence took place on August 2, 1776, when most of the 56 delegates signed the document.",
      "date": "1776-08-02"
    },
    {
      "headline": "Public Reading of the Declaration",
      "text": "On July 8, 1776, the Declaration of Independence was publicly read for the first time in Philadelphia at the State House Yard.",
      "date": "1776-07-08"
