{
  "timeline": [
    {
      "headline": "Founding of Saint Petersburg",
      "text": "Saint Petersburg was founded by Tsar Peter the Great on May 27, 1703. It was established on the site of the Swedish fortress Nyenskans, which was captured by Russian troops during the Great Northern War.",
      "date": "1703-05-27"
    },
    {
      "headline": "Saint Petersburg Becomes Capital of Russia",
      "text": "In 1712, Saint Petersburg replaced Moscow as the capital of Russia, serving as the political and cultural center of the Russian Empire.",
      "date": "1712"
    },
    {
      "headline": "Construction of the Winter Palace",
      "text": "The Winter Palace, which became the official residence of the Russian monarchs, was completed in 1732. It is one of the most famous buildings in Saint Petersburg.",
      "date": "1732"
    },
    {
      "headline": "Renaming to Petrograd",
      "text": "During World War I, in 1914, the city was renamed Petrograd, as part of a wave of anti-German sentiment.",
      "date": "1914"
    },
    {
      "headline": "Russian Revolution and the October Revolution",
      "text": "Petrograd was a key location during the Russian Revolution of 1917, including the February Revolution and the October Revolution, which led to the overthrow of the Russian Provisional Government and the establishment of Soviet power.",
      "date": "1917"
    },
    {
      "headline": "Renaming to Leningrad",
      "text": "Following the death of Vladimir Lenin in 1924, the city was renamed Leningrad in his honor.",
      "date": "1924"
    },
    {
      "headline": "Siege of Leningrad",
      "text": "During World War II, Leningrad was besieged by German and Finnish forces from September 8, 1941, to January 27, 1944. The siege lasted 872 days and resulted in severe famine and casualties.",
      "date": "1941-09-08"
    },
    {
      "headline": "End of the Siege of Leningrad",
      "text": "The siege of Leningrad was lifted on January 27, 1944, marking a significant turning point in the city's history during World War II.",
      "date": "1944-01-27"
    },
    {
      "headline": "Renaming to Saint Petersburg",
      "text": "After a referendum held on June 12, 1991, the city's name was changed back to Saint Petersburg, following the dissolution of the Soviet Union.",
      "date": "1991-06-12"
    }
  ]
}

{
