    {
      "headline": "Discovery of Adrenochrome",
      "text": "Adrenochrome is a chemical compound produced by the oxidation of adrenaline (epinephrine). It was discovered as a result of early research into the oxidation products of adrenaline.",
      "date": "1930"
    },
    {
      "headline": "Research into Adrenochrome and Schizophrenia",
      "text": "From the 1950s through to the 1970s, adrenochrome was the subject of limited research as a potential cause of schizophrenia. Researchers hypothesized that it might play a role in the development of mental disorders.",
      "date": "1950"
    },
    {
      "headline": "Development of Carbazochrome",
      "text": "The semicarbazide derivative of adrenochrome, known as carbazochrome, was developed as a hemostatic medication. It is used to reduce bleeding by promoting blood clotting.",
      "date": "1960"
    },
    {
      "headline": "Decline in Medical Interest",
      "text": "By the 1970s, interest in adrenochrome as a medical compound declined due to a lack of evidence supporting its efficacy in treating schizophrenia or other conditions.",
      "date": "1970"
    }
  ]
}

