{
  "timeline": [
    {
      "headline": "Early Japanese Art Influences",
      "text": "Manga has its roots in early Japanese art, such as the 12th-century scrolls like the 'Chōjū-jinbutsu-giga' (Scrolls of Frolicking Animals and Humans), which depicted humorous scenes of animals acting like humans.",
      "date": "-1100"
    },
    {
      "headline": "Ukiyo-e and Kibyōshi",
      "text": "During the Edo period (1603-1868), the ukiyo-e art form and kibyōshi, a genre of illustrated books, contributed to the development of manga. These works often combined images with text to tell stories.",
      "date": "1603"
    },
    {
      "headline": "Hokusai Manga",
      "text": "In 1814, the famous ukiyo-e artist Hokusai published the first volume of 'Hokusai Manga', a collection of sketches that influenced the modern form of manga.",
      "date": "1814"
    },
    {
      "headline": "Meiji Era and Western Influence",
      "text": "During the Meiji era (1868-1912), Japan opened up to Western influences, which impacted manga's development. Artists began incorporating Western styles and techniques into their work.",
      "date": "1868"
    },
    {
      "headline": "Birth of Modern Manga",
      "text": "The late 19th century saw the emergence of modern manga, with artists like Rakuten Kitazawa, who used the term 'manga' to describe their work, blending traditional Japanese art with Western styles.",
      "date": "1902"
    },
    {
      "headline": "Post-War Manga Boom",
      "text": "After World War II, manga experienced a boom in popularity. Osamu Tezuka, often called the 'God of Manga', played a significant role in this era with works like 'Astro Boy' (1952).",
      "date": "1952"
    },
    {
      "headline": "Shōnen and Shōjo Manga",
      "text": "In the 1950s and 1960s, manga began to diversify into genres such as shōnen (for boys) and shōjo (for girls), each with distinct themes and styles.",
      "date": "1950"
    },
    {
      "headline": "International Popularity",
      "text": "By the late 20th century, manga had gained international popularity, with series like 'Dragon Ball' (1984) and 'Sailor Moon' (1991) becoming global phenomena.",
      "date": "1984"
    },
    {
      "headline": "Digital Manga",
      "text": "In the 21st century, digital platforms have transformed manga distribution, making it more accessible worldwide and allowing for new forms of storytelling.",
      "date": "2000"
    }
  ]
}

