{
  "timeline": [
    {
      "headline": "Establishment of the House of Commons",
      "text": "The House of Commons was established in the 13th century as part of the English Parliament. It evolved from the earlier councils and assemblies that advised the monarch.",
      "date": "1295"
    },
    {
      "headline": "Model Parliament",
      "text": "In 1295, King Edward I summoned what came to be known as the 'Model Parliament', which included commoners, marking a significant step towards the establishment of the House of Commons.",
      "date": "1295"
    },
    {
      "headline": "First Speaker of the House of Commons",
      "text": "The first Speaker of the House of Commons, Sir Peter de la Mare, was appointed in 1376.",
      "date": "1376"
    },
    {
      "headline": "The English Civil War and the Long Parliament",
      "text": "During the English Civil War (1642–1651), the Long Parliament sat from 1640 until 1660, playing a crucial role in the conflict between the monarchy and Parliament.",
      "date": "1640"
    },
    {
      "headline": "The Glorious Revolution",
      "text": "The Glorious Revolution of 1688 led to the establishment of constitutional monarchy and the supremacy of Parliament over the monarchy, significantly enhancing the power of the House of Commons.",
      "date": "1688"
    },
    {
      "headline": "Acts of Union 1707",
      "text": "The Acts of Union 1707 united the Parliaments of England and Scotland, creating the Parliament of Great Britain, with the House of Commons as its lower house.",
      "date": "1707"
    },
    {
      "headline": "Reform Act 1832",
      "text": "The Reform Act 1832, also known as the Great Reform Act, was passed to reform the electoral system of England and Wales, significantly expanding the electorate of the House of Commons.",
      "date": "1832"
    },
    {
      "headline": "Parliament Act 1911",
      "text": "The Parliament Act 1911 reduced the power of the House of Lords and established the supremacy of the House of Commons in the legislative process.",
      "date": "1911"
    },
    {
      "headline": "Representation of the People Act 1918",
      "text": "The Representation of the People Act 1918 granted suffrage to women over the age of 30 and all men over the age of 21, significantly expanding the electorate of the House of Commons.",
      "date": "1918"
    },
    {
      "headline": "House of Commons (Redistribution of Seats) Act 1949",
      "text": "The House of Commons (Redistribution of Seats) Act 1949 was enacted to provide for the periodic review of parliamentary constituencies, ensuring fair representation.",
      "date": "1949"
    },
    {
      "headline": "Establishment of the House of Commons Commission",
      "text": "The House of Commons Commission was established in 1978 to oversee the administration of the House of Commons.",
      "date": "1978"
    }
  ]
}

