    {
      "headline": "Birth of Solomon",
      "text": "Solomon, also known as Jedidiah, was born to King David and Bathsheba. The exact date of his birth is not recorded, but it is estimated to be around 990 BCE.",
      "date": "-0990"
    },
    {
      "headline": "Solomon Becomes King",
      "text": "Solomon became the king of Israel after the death of his father, King David. His reign is traditionally dated from 970 BCE.",
      "date": "-0970"
    },
    {
      "headline": "Construction of the First Temple",
      "text": "Solomon is credited with building the First Temple in Jerusalem, a significant event in Jewish history. The construction is believed to have started in the fourth year of Solomon's reign, around 966 BCE, and completed in 957 BCE.",
      "date": "-0966"
    },
    {
      "headline": "Visit of the Queen of Sheba",
      "text": "The Queen of Sheba visited Solomon, bringing gifts and testing his wisdom. This event is traditionally dated to the mid-10th century BCE.",
      "date": "-0950"
    },
    {
      "headline": "Solomon's Wealth and Wisdom",
      "text": "Solomon was renowned for his wealth and wisdom, which attracted visitors from various regions. His reign is often considered a period of prosperity for Israel.",
      "date": "-0940"
    },
    {
      "headline": "Solomon's Apostasy",
      "text": "Later in his reign, Solomon turned away from the worship of Yahweh, influenced by his foreign wives, and began to worship other gods. This event is traditionally dated towards the end of his reign.",
      "date": "-0935"
    },
    {
      "headline": "Death of Solomon",
      "text": "Solomon died after a 40-year reign, traditionally dated to 931 BCE. His son Rehoboam succeeded him as king.",
      "date": "-0931"
    },
    {
      "headline": "Division of the Kingdom",
      "text": "Following Solomon's death, the Kingdom of Israel split into two: the northern Kingdom of Israel and the southern Kingdom of Judah, due to Rehoboam's harsh policies. This division occurred shortly after 931 BCE.",
      "date": "-0930"
    }
  ]
}

