      "headline": "Trojan War Ends",
      "text": "The Trojan War, which lasted ten years, comes to an end. Odysseus, the Greek hero and king of Ithaca, begins his journey home.",
      "date": "-1180"
    },
    {
      "headline": "Odysseus and the Lotus-Eaters",
      "text": "During his journey home, Odysseus encounters the Lotus-Eaters, a group of people who consume a plant that causes forgetfulness of home.",
      "date": "-1170"
    },
    {
      "headline": "Encounter with Polyphemus",
      "text": "Odysseus and his men become trapped in the cave of Polyphemus, a Cyclops. Odysseus blinds Polyphemus to escape.",
      "date": "-1170"
    },
    {
      "headline": "Visit to Aeolus",
      "text": "Odysseus receives a bag of winds from Aeolus, the ruler of the winds, to help him sail home.",
      "date": "-1170"
    },
    {
      "headline": "Laestrygonians Attack",
      "text": "Odysseus's fleet is attacked by the Laestrygonians, a tribe of giant cannibals, resulting in the loss of all ships except Odysseus's.",
      "date": "-1170"
    },
    {
      "headline": "Circe's Island",
      "text": "Odysseus and his men land on the island of Aeaea, home to the witch-goddess Circe, who turns some of his men into swine.",
      "date": "-1170"
    },
    {
      "headline": "Journey to the Underworld",
      "text": "Odysseus travels to the Underworld to seek advice from the prophet Tiresias on how to return to Ithaca.",
      "date": "-1170"
    },
    {
      "headline": "Sirens, Scylla, and Charybdis",
      "text": "Odysseus navigates past the Sirens, who lure sailors to their deaths with their singing, and between Scylla and Charybdis, two sea monsters.",
      "date": "-1170"
    },
    {
      "headline": "Cattle of Helios",
      "text": "Odysseus's men disobey his orders and slaughter the sacred cattle of the sun god Helios, leading to their destruction.",
      "date": "-1170"
    },
    {
      "headline": "Calypso's Island",
      "text": "Odysseus is held captive on the island of Ogygia by the nymph Calypso for seven years.",
      "date": "-1163"
    },
    {
      "headline": "Release from Calypso",
      "text": "Odysseus is released from Calypso's island by the intervention of the gods and sets sail for Ithaca.",
      "date": "-1156"
    },
    {
      "headline": "Arrival in Ithaca",
      "text": "Odysseus finally returns to Ithaca after a ten-year journey. He finds his home overrun by suitors vying for his wife Penelope's hand.",
      "date": "-1155"
    },
    {
      "headline": "Slaughter of the Suitors",
      "text": "Odysseus, with the help of his son Telemachus and a few loyal servants, slaughters the suitors and reclaims his home.",
      "date": "-1155"
    },
    {
      "headline": "Reunion with Penelope",
      "text": "Odysseus is reunited with his wife Penelope after proving his identity to her.",
      "date": "-1155"
    }
  ]
}

