{
  "timeline": [
    {
      "headline": "Independence Declared",
      "text": "Czechoslovakia declared its independence from Austria-Hungary on October 28, 1918.",
      "date": "1918-10-28"
    },
    {
      "headline": "Munich Agreement",
      "text": "On September 30, 1938, the Munich Agreement was signed, allowing Nazi Germany to annex the Sudetenland, a region of Czechoslovakia.",
      "date": "1938-09-30"
    },
    {
      "headline": "Territorial Losses",
      "text": "Following the Munich Agreement, Czechoslovakia lost further territories to Hungary and Poland in late 1938.",
      "date": "1938"
    },
    {
      "headline": "Dissolution of Czechoslovakia",
      "text": "In March 1939, Slovakia proclaimed its independence, and Carpathian Ruthenia became part of Hungary. The German Protectorate of Bohemia and Moravia was established in the remaining Czech lands.",
      "date": "1939-03"
    },
    {
      "headline": "Government-in-Exile",
      "text": "After the outbreak of World War II in 1939, former Czechoslovak President Edvard Beneš formed a government-in-exile and sought recognition from the Allies.",
      "date": "1939"
    },
    {
      "headline": "End of World War II",
      "text": "Czechoslovakia was re-established after the end of World War II in 1945.",
      "date": "1945"
    },
    {
      "headline": "Communist Coup",
      "text": "In February 1948, the Communist Party of Czechoslovakia seized power in a coup d'état, leading to the establishment of a communist regime.",
      "date": "1948-02"
    },
    {
      "headline": "Prague Spring",
      "text": "In 1968, the Prague Spring occurred, a period of political liberalization and reform in Czechoslovakia that was ultimately crushed by a Soviet-led invasion in August 1968.",
      "date": "1968-08"
    },
    {
      "headline": "Velvet Revolution",
      "text": "The Velvet Revolution was a non-violent transition of power in Czechoslovakia that took place from November 17 to December 29, 1989, leading to the end of communist rule.",
      "date": "1989-11-17"
    },
    {
      "headline": "Dissolution of Czechoslovakia",
      "text": "Czechoslovakia peacefully dissolved into two separate countries, the Czech Republic and Slovakia, on January 1, 1993.",
      "date": "1993-01-01"
    }
  ]
}

