{
  "timeline": [
    {
      "headline": "Publication of 'A Theory of Human Motivation'",
      "text": "In 1943, Abraham Maslow published 'A Theory of Human Motivation' in the journal Psychological Review, where he first introduced his hierarchy of needs.",
      "date": "1943"
    },
    {
      "headline": "Introduction of the Hierarchy of Needs",
      "text": "In 1943, Maslow introduced the hierarchy of needs, which included five levels: physiological, safety, love and belonging, esteem, and self-actualization.",
      "date": "1943"
    },
    {
      "headline": "Expansion of the Hierarchy",
      "text": "In the 1960s and 1970s, Maslow expanded his hierarchy to include a sixth level, which he called 'meta-needs' or 'self-transcendence'.",
      "date": "1960"
    },
    {
      "headline": "Publication of 'Toward a Psychology of Being'",
      "text": "In 1962, Maslow published 'Toward a Psychology of Being', where he further elaborated on his hierarchy of needs and the concept of self-actualization.",
      "date": "1962"
    },
    {
      "headline": "Maslow's Later Writings",
      "text": "In his later writings, Maslow explored the concept of metamotivation and the idea of self-transcendence, which he considered to be a higher level beyond self-actualization.",
      "date": "1970"
    }
  ]
}

