{
  "timeline": [
    {
      "headline": "Ancient Near Eastern Cosmology",
      "text": "In ancient Near Eastern cultures, the Earth was often depicted as a flat disk floating in the ocean. This cosmography was prevalent in ancient Mesopotamian, Egyptian, and Hebrew cultures.",
      "date": "-2000"
    },
    {
      "headline": "Greek Philosophers Propose Spherical Earth",
      "text": "By the 6th century BCE, Greek philosophers such as Pythagoras began to propose that the Earth was spherical, challenging the flat Earth model.",
      "date": "-0600"
    },
    {
      "headline": "Eratosthenes Measures Earth's Circumference",
      "text": "Around 240 BCE, Eratosthenes of Cyrene calculated the Earth's circumference with remarkable accuracy, providing strong evidence for a spherical Earth.",
      "date": "-0240"
    },
    {
      "headline": "Middle Ages and Flat Earth Myth",
      "text": "During the Middle Ages, the myth that people believed in a flat Earth persisted, although most educated Europeans understood the Earth was spherical.",
      "date": "0500"
    },
    {
      "headline": "Modern Resurgence of Flat Earth Theory",
      "text": "In the 19th and 20th centuries, the flat Earth theory saw a resurgence as a conspiracy theory, with figures like Samuel Rowbotham promoting it through publications and lectures.",
      "date": "1800"
    },
    {
      "headline": "Flat Earth Society Founded",
      "text": "In 1956, the Flat Earth Society was founded by Samuel Shenton, further promoting the flat Earth theory in the modern era.",
      "date": "1956"
    },
    {
      "headline": "Internet Era and Flat Earth Conspiracy",
      "text": "With the rise of the internet in the late 20th and early 21st centuries, the flat Earth theory gained new followers, spreading rapidly through online communities and social media.",
      "date": "2000"
    }
  ]
}

