{
  "timeline": [
    {
      "headline": "Operation Barbarossa Begins",
      "text": "Operation Barbarossa, the invasion of the Soviet Union by Nazi Germany and its Axis allies, commenced on Sunday, 22 June 1941. It marked the largest land offensive in human history.",
      "date": "1941-06-22"
    },
    {
      "headline": "Battle of Smolensk",
      "text": "The Battle of Smolensk took place from 10 July to 10 September 1941. It was a significant early battle in Operation Barbarossa, resulting in a German victory but delaying their advance towards Moscow.",
      "date": "1941-07"
    },
    {
      "headline": "Siege of Leningrad Begins",
      "text": "The Siege of Leningrad began on 8 September 1941, when German and Finnish forces encircled the city, leading to a prolonged siege that lasted until January 1944.",
      "date": "1941-09-08"
    },
    {
      "headline": "Battle of Kiev",
      "text": "The Battle of Kiev occurred from 23 August to 26 September 1941. It resulted in a decisive German victory, with the encirclement and capture of a large Soviet force.",
      "date": "1941-08"
    },
    {
      "headline": "Battle of Moscow Begins",
      "text": "The Battle of Moscow began on 2 October 1941, as German forces launched Operation Typhoon, aiming to capture the Soviet capital.",
      "date": "1941-10-02"
    },
    {
      "headline": "Soviet Counteroffensive at Moscow",
      "text": "On 5 December 1941, the Soviet Union launched a counteroffensive at Moscow, pushing back the German forces and marking a turning point in the battle.",
      "date": "1941-12-05"
    },
    {
      "headline": "Operation Barbarossa Ends",
      "text": "Operation Barbarossa effectively ended in December 1941, as the German advance was halted by the Soviet counteroffensive and the onset of winter.",
      "date": "1941-12"
    }
  ]
}

