      "headline": "Crossing the Alps",
      "text": "In 218 BCE, Hannibal famously crossed the Alps with his army, including war elephants, to invade Italy.",
      "date": "-0218"
    },
    {
      "headline": "Battle of Trebia",
      "text": "Hannibal defeated the Roman forces at the Battle of Trebia in December 218 BCE.",
      "date": "-0218-12"
    },
    {
      "headline": "Battle of Lake Trasimene",
      "text": "In 217 BCE, Hannibal achieved a major victory against Rome at the Battle of Lake Trasimene.",
      "date": "-0217"
    },
    {
      "headline": "Battle of Cannae",
      "text": "Hannibal won a decisive victory at the Battle of Cannae on August 2, 216 BCE, one of the most significant battles of the Second Punic War.",
      "date": "-0216-08-02"
    },
    {
      "headline": "Battle of Zama",
      "text": "Hannibal was defeated by the Roman general Scipio Africanus at the Battle of Zama in 202 BCE, effectively ending the Second Punic War.",
