{
  "timeline": [
    {
      "headline": "Formation of the Allies",
      "text": "The Allies of World War II were formed as an international military coalition to oppose the Axis powers during World War II. The coalition began to take shape in 1939.",
      "date": "1939"
    },
    {
      "headline": "United Kingdom Declares War on Germany",
      "text": "On September 3, 1939, the United Kingdom declared war on Germany following the German invasion of Poland, marking the UK's entry into World War II.",
      "date": "1939-09-03"
    },
    {
      "headline": "Soviet Union Joins the Allies",
      "text": "The Soviet Union joined the Allies after being invaded by Germany on June 22, 1941, in Operation Barbarossa.",
      "date": "1941-06-22"
    },
    {
      "headline": "United States Enters World War II",
      "text": "The United States entered World War II on December 8, 1941, following the Japanese attack on Pearl Harbor on December 7, 1941.",
      "date": "1941-12-08"
    },
    {
      "headline": "China's Role as a Principal Ally",
      "text": "China was recognized as one of the principal Allies, having been in conflict with Japan since 1937. By the end of 1941, China was acknowledged as one of the 'Big Four' Allies.",
      "date": "1941"
    },
    {
      "headline": "Declaration by United Nations",
      "text": "On January 1, 1942, the Declaration by United Nations was signed by 26 nations, formalizing the coalition of the Allies and committing to the principles of the Atlantic Charter.",
      "date": "1942-01-01"
    },
    {
      "headline": "D-Day: Allied Invasion of Normandy",
      "text": "On June 6, 1944, the Allies launched the D-Day invasion, a significant military operation that marked the beginning of the liberation of Western Europe from Nazi occupation.",
      "date": "1944-06-06"
    },
    {
      "headline": "Victory in Europe Day",
      "text": "Victory in Europe Day (V-E Day) was celebrated on May 8, 1945, marking the formal acceptance of Nazi Germany's unconditional surrender by the Allies, effectively ending World War II in Europe.",
      "date": "1945-05-08"
    },
    {
      "headline": "Victory over Japan Day",
      "text": "Victory over Japan Day (V-J Day) was celebrated on September 2, 1945, following Japan's formal surrender, which marked the end of World War II.",
      "date": "1945-09-02"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Discovery of the Mariana Trench",
      "text": "The Mariana Trench was first discovered by the HMS Challenger expedition, which took place from 1872 to 1876. This expedition was the first to sound the depths of the trench, leading to its discovery.",
      "date": "1875"
    },
    {
      "headline": "First Measurement of Challenger Deep",
      "text": "In 1951, the British survey ship HMS Challenger II returned to the area and made a depth measurement of 10,900 meters (35,760 feet) at the Challenger Deep, the deepest part of the trench.",
      "date": "1951"
    },
    {
      "headline": "Trieste Descent",
      "text": "On January 23, 1960, the bathyscaphe Trieste, manned by Jacques Piccard and Don Walsh, made the first manned descent to the bottom of the Mariana Trench, reaching a depth of approximately 10,916 meters (35,814 feet).",
      "date": "1960-01-23"
    },
    {
      "headline": "Unmanned Descent by Kaiko",
      "text": "In 1995, the Japanese remotely operated vehicle Kaiko made an unmanned descent to the bottom of the Mariana Trench, reaching the Challenger Deep.",
      "date": "1995"
    },
    {
      "headline": "Nereus Exploration",
      "text": "In 2009, the hybrid remotely operated vehicle Nereus reached the bottom of the Mariana Trench, providing valuable data and samples.",
      "date": "2009"
    },
    {
      "headline": "James Cameron's Solo Dive",
      "text": "On March 26, 2012, filmmaker James Cameron made a solo descent to the bottom of the Mariana Trench in the Deepsea Challenger submersible, reaching a depth of 10,908 meters (35,787 feet).",
      "date": "2012-03-26"
    },
    {
      "headline": "Five Deeps Expedition",
      "text": "In 2019, the Five Deeps Expedition, led by Victor Vescovo, reached the bottom of the Mariana Trench, setting a new record for the deepest manned sea dive at 10,927 meters (35,853 feet).",
      "date": "2019"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of David Berkowitz",
      "text": "David Richard Berkowitz was born on June 1, 1953, in Brooklyn, New York City.",
      "date": "1953-06-01"
    },
    {
      "headline": "Adoption by the Berkowitz Family",
      "text": "Shortly after his birth, David was adopted by Nathan and Pearl Berkowitz.",
