      "headline": "Service in the United States Army",
      "text": "David Berkowitz served in the United States Army from 1971 to 1974.",
      "date": "1971"
    },
    {
      "headline": "First Attack",
      "text": "On July 29, 1976, Berkowitz committed his first attack, shooting two young women in the Bronx, New York City.",
      "date": "1976-07-29"
    },
    {
      "headline": "Second Attack",
      "text": "On October 23, 1976, Berkowitz attacked Carl Denaro and Rosemary Keenan in Queens, New York City.",
      "date": "1976-10-23"
    },
    {
      "headline": "Third Attack",
      "text": "On November 26, 1976, Berkowitz shot two teenage girls, Donna DeMasi and Joanne Lomino, in Queens, New York City.",
      "date": "1976-11-26"
    },
    {
      "headline": "Fourth Attack",
      "text": "On January 30, 1977, Berkowitz killed Christine Freund and wounded her fiancé, John Diel, in Queens, New York City.",
      "date": "1977-01-30"
    },
    {
      "headline": "Fifth Attack",
      "text": "On March 8, 1977, Berkowitz shot Virginia Voskerichian in Manhattan, New York City, resulting in her death.",
      "date": "1977-03-08"
    },
    {
      "headline": "Sixth Attack",
      "text": "On April 17, 1977, Berkowitz killed Alexander Esau and Valentina Suriani in the Bronx, New York City.",
      "date": "1977-04-17"
    },
    {
      "headline": "Seventh Attack",
      "text": "On June 26, 1977, Berkowitz shot Salvatore Lupo and Judy Placido in Queens, New York City, both survived.",
      "date": "1977-06-26"
    },
    {
      "headline": "Final Attack",
      "text": "On July 31, 1977, Berkowitz killed Stacy Moskowitz and wounded Robert Violante in Brooklyn, New York City.",
      "date": "1977-07-31"
    },
    {
      "headline": "Arrest of David Berkowitz",
      "text": "David Berkowitz was arrested on August 10, 1977, outside his apartment in Yonkers, New York.",
      "date": "1977-08-10"
    },
    {
      "headline": "Guilty Plea",
      "text": "On May 8, 1978, Berkowitz pled guilty to all of the shootings.",
      "date": "1978-05-08"
    },
    {
      "headline": "Sentencing",
      "text": "On June 12, 1978, Berkowitz was sentenced to six consecutive life sentences in prison.",
      "date": "1978-06-12"
    }
  ]
}

