{
  "timeline": [
    {
      "headline": "Founding of WikiLeaks",
      "text": "WikiLeaks was founded in 2006 by Julian Assange as a non-profit media organization and publisher of leaked documents.",
      "date": "2006"
    },
    {
      "headline": "First Major Publication",
      "text": "In 2007, WikiLeaks published its first major document, the standard operating procedures for Camp Delta, the US detention center at Guantanamo Bay.",
      "date": "2007"
    },
    {
      "headline": "Release of Collateral Murder Video",
      "text": "On April 5, 2010, WikiLeaks released the Collateral Murder video, showing a US helicopter attack in Baghdad that killed several people, including two Reuters journalists.",
      "date": "2010-04-05"
    },
    {
      "headline": "Publication of Afghan War Diary",
      "text": "On July 25, 2010, WikiLeaks published the Afghan War Diary, a collection of over 75,000 documents about the War in Afghanistan not previously available for public review.",
      "date": "2010-07-25"
    },
    {
      "headline": "Iraq War Logs Released",
      "text": "On October 22, 2010, WikiLeaks released the Iraq War Logs, a collection of 391,832 US Army field reports from the Iraq War covering the period from 2004 to 2009.",
      "date": "2010-10-22"
    },
    {
      "headline": "Cablegate",
      "text": "On November 28, 2010, WikiLeaks began releasing US State Department diplomatic cables, known as Cablegate, which included 251,287 cables from US embassies around the world.",
      "date": "2010-11-28"
    },
    {
      "headline": "Julian Assange Seeks Asylum",
      "text": "In June 2012, Julian Assange sought asylum in the Ecuadorian Embassy in London to avoid extradition to Sweden over allegations of sexual assault.",
      "date": "2012-06"
    },
    {
      "headline": "Vault 7 Release",
      "text": "On March 7, 2017, WikiLeaks began releasing Vault 7, a series of documents detailing the CIA's hacking capabilities.",
      "date": "2017-03-07"
    },
    {
      "headline": "Kristinn Hrafnsson Becomes Editor-in-Chief",
      "text": "In September 2018, Kristinn Hrafnsson was appointed as the editor-in-chief of WikiLeaks.",
      "date": "2018-09"
    },
    {
      "headline": "Last Original Document Publication",
      "text": "WikiLeaks' most recent publication of original documents was in 2019.",
      "date": "2019"
    },
    {
      "headline": "Most Recent Publication",
      "text": "WikiLeaks' most recent publication was in 2021.",
      "date": "2021"
    },
    {
      "headline": "Inaccessibility of Documents",
      "text": "From November 2022, numerous documents on WikiLeaks' website became inaccessible.",
      "date": "2022-11"
    },
    {
      "headline": "Julian Assange's Statement on Publishing",
      "text": "In 2023, Julian Assange stated that WikiLeaks is no longer able to publish due to his imprisonment and the effect of US government surveillance and funding restrictions on potential whistleblowers.",
      "date": "2023"
    }
  ]
}

