{
  "timeline": [
    {
      "headline": "eBay Founded",
      "text": "eBay was founded by Pierre Omidyar in September 1995 as AuctionWeb, a site dedicated to bringing buyers and sellers together in an honest and open marketplace.",
      "date": "1995-09"
    },
    {
      "headline": "First Item Sold",
      "text": "The first item sold on eBay was a broken laser pointer for $14.83, marking the beginning of the platform's auction-based sales model.",
      "date": "1995"
    },
    {
      "headline": "Company Name Change",
      "text": "In 1997, AuctionWeb officially changed its name to eBay, which was derived from Echo Bay Technology Group, Omidyar's consulting firm.",
      "date": "1997"
    },
    {
      "headline": "eBay Goes Public",
      "text": "eBay went public on September 21, 1998, with its initial public offering (IPO) on the NASDAQ stock exchange.",
      "date": "1998-09-21"
    },
    {
      "headline": "Acquisition of PayPal",
      "text": "In October 2002, eBay acquired PayPal, an online payment company, to facilitate easier transactions on its platform.",
      "date": "2002-10"
    },
    {
      "headline": "Skype Acquisition",
      "text": "eBay acquired Skype, a voice-over-IP service, in September 2005, expanding its reach into the communications sector.",
      "date": "2005-09"
    },
    {
      "headline": "Spin-off of PayPal",
      "text": "In July 2015, eBay spun off PayPal into a separate publicly traded company, allowing both companies to focus on their core businesses.",
      "date": "2015-07"
    },
    {
      "headline": "eBay's 25th Anniversary",
      "text": "In September 2020, eBay celebrated its 25th anniversary, marking a quarter-century of operations as a leading e-commerce platform.",
      "date": "2020-09"
    },
    {
      "headline": "2023 Financial Milestone",
      "text": "In 2023, eBay handled $73 billion in transactions, with 48% of these occurring in the United States. The company had a take rate of 13.81%.",
      "date": "2023"
    }
  ]
}

{
