    {
      "headline": "United Nations Conference on Sustainable Development",
      "text": "In June 2012, the United Nations Conference on Sustainable Development, also known as Rio+20, was held in Rio de Janeiro, Brazil. This conference led to the development of the Sustainable Development Goals (SDGs).",
      "date": "2012-06"
    },
    {
      "headline": "Proposal of the SDGs",
      "text": "In July 2014, the Open Working Group of the United Nations General Assembly proposed a set of 17 Sustainable Development Goals to succeed the Millennium Development Goals.",
      "date": "2014-07"
    },
    {
      "headline": "Adoption of the 2030 Agenda for Sustainable Development",
      "text": "On September 25, 2015, the United Nations General Assembly formally adopted the 2030 Agenda for Sustainable Development, which included the 17 Sustainable Development Goals.",
      "date": "2015-09-25"
    },
    {
      "headline": "Implementation of the SDGs",
      "text": "The Sustainable Development Goals officially came into force on January 1, 2016, marking the start of a 15-year plan to achieve the goals by 2030.",
      "date": "2016-01-01"
    },
    {
      "headline": "High-Level Political Forum on Sustainable Development",
      "text": "In July 2017, the High-Level Political Forum on Sustainable Development was held to review progress on the SDGs, focusing on specific goals each year.",
      "date": "2017-07"
    },
    {
      "headline": "SDG Summit",
      "text": "In September 2019, the first SDG Summit was held during the United Nations General Assembly to review progress and accelerate action towards achieving the SDGs.",
      "date": "2019-09"
    },
    {
      "headline": "Decade of Action",
      "text": "In January 2020, the United Nations launched the Decade of Action to deliver the Sustainable Development Goals by 2030, calling for accelerated solutions to global challenges.",
      "date": "2020-01"
    }
  ]
}

