    },
    {
      "headline": "Taliban Insurgency",
      "text": "After being overthrown, the Taliban regrouped and launched an insurgency against the Afghan government and coalition forces, lasting for two decades.",
      "date": "2001"
    },
    {
      "headline": "Recapture of Kabul",
      "text": "The Taliban recaptured Kabul on August 15, 2021, following the withdrawal of U.S. and NATO forces, effectively taking control of Afghanistan.",
      "date": "2021-08-15"
    },
    {
      "headline": "Establishment of New Government",
      "text": "After recapturing Kabul, the Taliban announced the formation of a new interim government in September 2021, although it remains unrecognized internationally.",
      "date": "2021-09"
    }
  ]
}

