    },
    {
      "headline": "Giles Corey's Death",
      "text": "On September 19, 1692, Giles Corey died under torture by pressing, after refusing to enter a plea.",
      "date": "1692-09-19"
    },
    {
      "headline": "Last Executions",
      "text": "On September 22, 1692, the last eight executions took place, marking the end of the executions during the Salem witch trials.",
      "date": "1692-09-22"
    },
    {
      "headline": "End of Trials",
      "text": "In May 1693, the Salem witch trials came to an end. Governor William Phips pardoned and released the remaining accused witches.",
