    {
      "headline": "Birth of Charles Darwin",
      "text": "Charles Robert Darwin was born on February 12, 1809, in Shrewsbury, Shropshire, England.",
      "date": "1809-02-12"
    },
    {
      "headline": "Education at the University of Edinburgh",
      "text": "In 1825, Darwin began studying medicine at the University of Edinburgh, but he found the lectures dull and surgery distressing.",
      "date": "1825"
