    {
      "headline": "Studies at Christ's College, Cambridge",
      "text": "In 1828, Darwin enrolled at Christ's College, Cambridge, to study for a Bachelor of Arts degree.",
      "date": "1828"
    },
    {
      "headline": "Graduation from Cambridge",
      "text": "Darwin graduated from Christ's College, Cambridge, with a Bachelor of Arts degree in 1831.",
      "date": "1831"
    },
    {
      "headline": "Voyage of the Beagle",
      "text": "Darwin embarked on the HMS Beagle on December 27, 1831, for a voyage that lasted nearly five years, during which he collected a vast amount of natural specimens.",
      "date": "1831-12-27"
    },
    {
      "headline": "Return from the Beagle Voyage",
      "text": "Darwin returned to England on October 2, 1836, after completing his voyage on the HMS Beagle.",
      "date": "1836-10-02"
    },
    {
      "headline": "Publication of 'On the Origin of Species'",
      "text": "On November 24, 1859, Darwin published 'On the Origin of Species', introducing his theory of evolution by natural selection.",
      "date": "1859-11-24"
    },
    {
      "headline": "Publication of 'The Descent of Man'",
      "text": "In 1871, Darwin published 'The Descent of Man, and Selection in Relation to Sex', which applied evolutionary theory to human evolution.",
      "date": "1871"
    },
    {
      "headline": "Death of Charles Darwin",
      "text": "Charles Darwin died on April 19, 1882, at his home, Down House, in Kent, England.",
      "date": "1882-04-19"
    },
    {
      "headline": "Burial in Westminster Abbey",
      "text": "Darwin was honoured with a burial in Westminster Abbey, London, on April 26, 1882.",
