{
  "timeline": [
    {
      "headline": "Greek Dark Ages Begin",
      "text": "The Greek Dark Ages began around the 12th century BC, following the collapse of the Mycenaean civilization.",
      "date": "-1200"
    },
    {
      "headline": "Archaic Period Begins",
      "text": "The Archaic period of Ancient Greece began around 800 BC, marked by the rise of city-states and the development of the Greek alphabet.",
      "date": "-0800"
    },
    {
      "headline": "First Olympic Games",
      "text": "The first Olympic Games were held in Olympia in 776 BC, marking a significant cultural event in Ancient Greece.",
      "date": "-0776"
    },
    {
      "headline": "Classical Period Begins",
      "text": "The Classical period of Ancient Greece began around 500 BC, characterized by great political and cultural achievements.",
      "date": "-0500"
    },
    {
      "headline": "Battle of Marathon",
      "text": "The Battle of Marathon took place in 490 BC, where the Athenians defeated the Persians, marking a pivotal moment in the Greco-Persian Wars.",
      "date": "-0490"
    },
    {
      "headline": "Battle of Thermopylae",
      "text": "In 480 BC, the famous Battle of Thermopylae occurred, where a small Greek force led by King Leonidas of Sparta resisted the much larger Persian army.",
      "date": "-0480"
    },
    {
      "headline": "Golden Age of Athens",
      "text": "The Golden Age of Athens, led by Pericles, began around 461 BC, marked by advancements in art, drama, philosophy, and the construction of the Parthenon.",
      "date": "-0461"
    },
    {
      "headline": "Peloponnesian War Begins",
      "text": "The Peloponnesian War between Athens and Sparta began in 431 BC, lasting until 404 BC and resulting in the downfall of Athens.",
      "date": "-0431"
    },
    {
      "headline": "Philip II of Macedon Unifies Greece",
      "text": "In 338 BC, Philip II of Macedon unified most of the Greek city-states under his rule after the Battle of Chaeronea.",
      "date": "-0338"
    },
    {
      "headline": "Alexander the Great's Conquests",
      "text": "Alexander the Great, son of Philip II, began his conquests in 334 BC, creating one of the largest empires in history by the time of his death in 323 BC.",
      "date": "-0334"
    },
    {
      "headline": "Hellenistic Period Begins",
      "text": "The Hellenistic period began in 323 BC following the death of Alexander the Great, characterized by the spread of Greek culture across the Mediterranean and Near East.",
      "date": "-0323"
    },
    {
      "headline": "Roman Conquest of Greece",
      "text": "In 146 BC, Greece fell under Roman control after the Roman victory at the Battle of Corinth, marking the end of Greek political independence.",
      "date": "-0146"
    }
  ]
}

