{
  "timeline": [
    {
      "headline": "Composition of the Hebrew Bible",
      "text": "The Hebrew Bible, also known as the Tanakh, is composed over several centuries. The earliest texts are believed to have been written around the 12th century BCE, with the final texts completed by the 2nd century BCE.",
      "date": "-1200"
    },
    {
      "headline": "Septuagint Translation",
      "text": "The Septuagint, a Greek translation of the Hebrew Bible, is completed. This translation is traditionally dated to the 3rd century BCE, with the work beginning around 285 BCE.",
      "date": "-0285"
    },
    {
      "headline": "Composition of the New Testament",
      "text": "The New Testament is composed between approximately 50 CE and 110 CE. It includes the Gospels, Acts, Epistles, and Revelation.",
      "date": "0050"
    },
    {
      "headline": "Council of Nicaea",
      "text": "In 325 CE, the First Council of Nicaea is convened by Emperor Constantine. While not directly about the Bible, it plays a significant role in the development of Christian doctrine and indirectly influences the formation of the biblical canon.",
      "date": "0325"
    },
    {
      "headline": "Vulgate Translation",
      "text": "In 382 CE, Pope Damasus I commissions Jerome to produce a Latin translation of the Bible, known as the Vulgate. This translation becomes the Catholic Church's officially promulgated Latin version of the Bible.",
      "date": "0382"
    },
    {
      "headline": "Council of Carthage",
      "text": "In 397 CE, the Council of Carthage confirms the canon of the New Testament, which is similar to the current canon used by most Christian denominations.",
      "date": "0397"
    },
    {
      "headline": "Gutenberg Bible Printed",
      "text": "In 1455, Johannes Gutenberg prints the Gutenberg Bible, the first major book printed using movable type in the West. This marks a significant moment in the history of the Bible's dissemination.",
      "date": "1455"
    },
    {
      "headline": "King James Version Published",
      "text": "In 1611, the King James Version of the Bible is published. Commissioned by King James I of England, it becomes one of the most popular and widely used translations in the English-speaking world.",
      "date": "1611"
    },
    {
      "headline": "Dead Sea Scrolls Discovered",
      "text": "In 1947, the Dead Sea Scrolls are discovered in the Qumran Caves near the Dead Sea. These ancient Jewish texts include some of the oldest known manuscripts of the Hebrew Bible.",
      "date": "1947"
    }
  ]
}

