    },
    {
      "headline": "Move to Kirtland, Ohio",
      "text": "In early 1831, Joseph Smith and his followers moved to Kirtland, Ohio, which became a center for the church.",
      "date": "1831"
    },
    {
      "headline": "Establishment of Zion in Missouri",
      "text": "In 1831, Joseph Smith identified Independence, Missouri, as the location for Zion, the New Jerusalem.",
      "date": "1831"
    },
    {
      "headline": "Kirtland Temple Dedication",
      "text": "The Kirtland Temple was dedicated on March 27, 1836, in Kirtland, Ohio.",
      "date": "1836-03-27"
    },
    {
      "headline": "Exodus to Far West, Missouri",
      "text": "In 1838, Joseph Smith and his followers moved to Far West, Missouri, due to increasing tensions in Kirtland.",
      "date": "1838"
    },
    {
      "headline": "Arrest and Imprisonment in Missouri",
      "text": "Joseph Smith was arrested and imprisoned in Liberty Jail in Missouri from December 1838 to April 1839.",
      "date": "1838-12"
    },
    {
      "headline": "Settlement in Nauvoo, Illinois",
      "text": "In 1839, Joseph Smith and his followers settled in Nauvoo, Illinois, where he became the mayor and leader of the community.",
