      "date": "1900"
    },
    {
      "headline": "Challenge Act at Scotland Yard",
      "text": "In 1904, Houdini performed a famous escape from special handcuffs commissioned by London's Daily Mirror, in front of a packed audience at the London Hippodrome.",
      "date": "1904"
    },
    {
      "headline": "Film Career",
      "text": "In 1919, Houdini began a film career, starring in silent films such as 'The Grim Game' and 'Terror Island.'",
      "date": "1919"
    },
    {
      "headline": "Anti-Spiritualism Campaign",
      "text": "In the 1920s, Houdini became an outspoken critic of spiritualists, exposing fraudulent mediums and writing the book 'A Magician Among the Spirits' in 1924.",
      "date": "1920"
    },
    {
      "headline": "Death of Harry Houdini",
      "text": "Harry Houdini died on October 31, 1926, in Detroit, Michigan, from peritonitis, secondary to a ruptured appendix.",
      "date": "1926-10-31"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Oda Nobunaga",
      "text": "Oda Nobunaga was born on June 23, 1534, in the Owari Province of Japan.",
      "date": "1534-06-23"
    },
    {
      "headline": "Becomes Head of the Oda Clan",
      "text": "In 1551, Oda Nobunaga became the head of the Oda clan after the death of his father, Oda Nobuhide.",
      "date": "1551"
    },
    {
      "headline": "Battle of Okehazama",
      "text": "In 1560, Oda Nobunaga defeated Imagawa Yoshimoto at the Battle of Okehazama, marking his rise to power.",
      "date": "1560"
    },
    {
      "headline": "Alliance with Tokugawa Ieyasu",
      "text": "In 1562, Oda Nobunaga formed an alliance with Tokugawa Ieyasu, which proved to be a pivotal moment in his campaign to unify Japan.",
      "date": "1562"
    },
    {
      "headline": "Capture of Kyoto",
      "text": "In 1568, Oda Nobunaga captured Kyoto and installed Ashikaga Yoshiaki as the shogun, effectively gaining control over the shogunate.",
      "date": "1568"
    },
    {
      "headline": "Battle of Nagashino",
      "text": "In 1575, Oda Nobunaga, along with Tokugawa Ieyasu, defeated the Takeda clan at the Battle of Nagashino, utilizing innovative tactics and firearms.",
      "date": "1575"
    },
    {
      "headline": "Destruction of the Enryaku-ji Monastery",
      "text": "In 1571, Oda Nobunaga ordered the destruction of the Enryaku-ji monastery on Mount Hiei, eliminating a significant threat to his power.",
      "date": "1571"
    },
    {
      "headline": "Death of Oda Nobunaga",
      "text": "Oda Nobunaga died on June 21, 1582, during the Incident at Honnō-ji, when he was betrayed by one of his generals, Akechi Mitsuhide.",
      "date": "1582-06-21"
    }
  ]
}

{
