{
  "timeline": [
    {
      "headline": "Formation of Mötley Crüe",
      "text": "Mötley Crüe was formed in Hollywood, California, in 1981 by bassist Nikki Sixx and drummer Tommy Lee. Guitarist Mick Mars and lead vocalist Vince Neil joined shortly after.",
      "date": "1981"
    },
    {
      "headline": "Release of Debut Album 'Too Fast for Love'",
      "text": "Mötley Crüe released their debut album 'Too Fast for Love' on November 10, 1981. Initially released on their own label, Leathür Records, it was later re-released by Elektra Records in 1982.",
      "date": "1981-11-10"
    },
    {
      "headline": "Release of 'Shout at the Devil'",
      "text": "The band's second album, 'Shout at the Devil', was released on September 26, 1983. It became a major commercial success and established Mötley Crüe as a prominent band in the heavy metal scene.",
      "date": "1983-09-26"
    },
    {
      "headline": "Release of 'Theatre of Pain'",
      "text": "Mötley Crüe released their third studio album, 'Theatre of Pain', on June 21, 1985. The album marked a stylistic shift for the band and included the hit single 'Home Sweet Home'.",
      "date": "1985-06-21"
    },
    {
      "headline": "Release of 'Girls, Girls, Girls'",
      "text": "On May 15, 1987, Mötley Crüe released their fourth studio album, 'Girls, Girls, Girls'. The album was a commercial success, reaching number two on the Billboard 200 chart.",
      "date": "1987-05-15"
    },
    {
      "headline": "Release of 'Dr. Feelgood'",
      "text": "The band's fifth studio album, 'Dr. Feelgood', was released on September 1, 1989. It became their most successful album, reaching number one on the Billboard 200 chart.",
      "date": "1989-09-01"
    },
    {
      "headline": "Vince Neil Leaves the Band",
      "text": "In February 1992, lead vocalist Vince Neil left Mötley Crüe. The band continued with a new singer, John Corabi.",
      "date": "1992-02"
    },
    {
      "headline": "Release of 'Mötley Crüe' with John Corabi",
      "text": "Mötley Crüe released a self-titled album with new vocalist John Corabi on March 15, 1994. The album marked a departure from their previous sound.",
      "date": "1994-03-15"
    },
    {
      "headline": "Vince Neil Rejoins Mötley Crüe",
      "text": "Vince Neil rejoined Mötley Crüe in 1997, leading to a reunion of the original lineup.",
      "date": "1997"
    },
    {
      "headline": "Release of 'Saints of Los Angeles'",
      "text": "On June 24, 2008, Mötley Crüe released 'Saints of Los Angeles', their ninth studio album. It was their first album in over a decade to feature the original lineup.",
      "date": "2008-06-24"
    },
    {
      "headline": "Final Tour Announcement",
      "text": "Mötley Crüe announced their final tour on January 28, 2014, signing a 'cessation of touring agreement' that would prevent them from touring again after 2015.",
      "date": "2014-01-28"
    },
    {
      "headline": "Final Show of the Farewell Tour",
      "text": "The band performed their final show of the farewell tour on December 31, 2015, at the Staples Center in Los Angeles, California.",
      "date": "2015-12-31"
    },
    {
      "headline": "Mötley Crüe Reunites",
      "text": "In 2019, Mötley Crüe announced their reunion and plans to tour again, nullifying their previous cessation of touring agreement.",
      "date": "2019"
    }
  ]
}

